window.__BAGUWEN_DATA__ = {"version":"1.0.0","generated":"2026-11-14","total":236,"plan":[{"day":1,"theme":"JS 语言核心","focus":"数据类型、原型链、闭包、this、GC","tip":"能默画原型链图、讲清 0.1+0.2","minutes":90},{"day":2,"theme":"异步与 ES6+","focus":"Event Loop、Promise、模块化、Proxy","tip":"推演混合输出题、手撕 Promise","minutes":90},{"day":3,"theme":"HTML / CSS / 渲染","focus":"渲染流水线、BFC、层叠上下文、布局","tip":"写出 6 种居中、说清重排重绘","minutes":80},{"day":4,"theme":"浏览器与网络","focus":"URL 全过程、HTTP 缓存、跨域、安全","tip":"一口气讲完 URL 到渲染的 8 步","minutes":90},{"day":5,"theme":"Vue / React 原理","focus":"响应式、diff、Fiber、Hooks、并发","tip":"对比两大框架的更新粒度","minutes":100},{"day":6,"theme":"工程化 / TS / 性能","focus":"Webpack、Vite、类型体操、Web Vitals","tip":"给出首屏优化的完整排查路径","minutes":90},{"day":7,"theme":"手写 + 场景题","focus":"30+ 手写实现、系统设计、模拟面试","tip":"不看答案写出 15 道手写题","minutes":120}],"chapters":[{"id":"day1","day":1,"title":"第 1 天｜JavaScript 语言核心（数据类型、原型、闭包、this）","short":"JavaScript 语言核心","note":"目标：把 JS 最容易被深挖的底层概念一次打穿。这部分是大厂面试的「必考区」，答不上来基本直接挂。建议早上背概念、晚上默写手写题要点。","sections":[{"id":"day1-s1","day":1,"title":"1.1 数据类型与内存模型","note":"","questions":[{"id":1,"num":"Q001","tag":"基础","title":"JavaScript 有哪些数据类型？基本类型和引用类型的区别是什么？","answers":["共 8 种：Undefined、Null、Boolean、Number、String、Symbol、BigInt 共 7 种原始类型（Primitive），以及 Object（引用类型，包含 Array、Function、Date、RegExp、Map、Set、Promise 等）。","原始类型按值访问、值不可变、赋值时复制一份值；引用类型的值存放在堆内存，变量里存的是指向堆的地址，赋值时复制地址，因此多个变量可能指向同一对象，修改属性会互相影响。","函数参数一律「按值传递」：传原始类型时复制值；传对象时复制的是地址，所以函数内修改对象属性会影响外部，但把参数整体重新赋值不会影响外部。"],"bullets":[],"code":[],"note":"追问：Symbol 用作唯一属性键、消除魔法字符串、模拟私有成员；BigInt 用于超出 Number.MAX_SAFE_INTEGER（2^53-1）的整数运算，如大额金额、雪花 ID。","text":"JavaScript 有哪些数据类型？基本类型和引用类型的区别是什么？ 共 8 种：Undefined、Null、Boolean、Number、String、Symbol、BigInt 共 7 种原始类型（Primitive），以及 Object（引用类型，包含 Array、Function、Date、RegExp、Map、Set、Promise 等）。 原始类型按值访问、值不可变、赋值时复制一份值；引用类型的值存放在堆内存，变量里存的是指向堆的地址，赋值时复制地址，因此多个变量可能指向同一对象，修改属性会互相影响。 函数参数一律「按值传递」：传原始类型时复制值；传对象时复制的是地址，所以函数内修改对象属性会影响外部，但把参数整体重新赋值不会影响外部。 追问：Symbol 用作唯一属性键、消除魔法字符串、模拟私有成员；BigInt 用于超出 Number.MAX_SAFE_INTEGER（2^53-1）的整数运算，如大额金额、雪花 ID。"},{"id":2,"num":"Q002","tag":"基础","title":"typeof 能判断哪些类型？为什么 typeof null === 'object'？","answers":["typeof 返回 'undefined'、'boolean'、'number'、'string'、'symbol'、'bigint'、'function'、'object' 八种字符串。数组、普通对象、null 都返回 'object'，无法细分。","typeof null === 'object' 是 JS 最初实现的历史 bug：值用低位类型标签存储，对象的标签是 000，而 null 的机器码全为 0，被误判为对象；为保持向后兼容一直没有修复。","typeof 对未声明的变量也返回 'undefined'（不报错），这是它唯一不会抛 ReferenceError 的场景；但对 let/const 暂时性死区中的变量仍会抛错。"],"bullets":[],"code":[],"note":"","text":"typeof 能判断哪些类型？为什么 typeof null === 'object'？ typeof 返回 'undefined'、'boolean'、'number'、'string'、'symbol'、'bigint'、'function'、'object' 八种字符串。数组、普通对象、null 都返回 'object'，无法细分。 typeof null === 'object' 是 JS 最初实现的历史 bug：值用低位类型标签存储，对象的标签是 000，而 null 的机器码全为 0，被误判为对象；为保持向后兼容一直没有修复。 typeof 对未声明的变量也返回 'undefined'（不报错），这是它唯一不会抛 ReferenceError 的场景；但对 let/const 暂时性死区中的变量仍会抛错。"},{"id":3,"num":"Q003","tag":"对比","title":"判断数据类型的几种方式及各自缺陷？","answers":["typeof：适合原始类型（除 null）与函数判断，无法区分数组、对象、null。","instanceof：沿原型链查找，适合判断自定义类实例；无法判断原始类型，跨 iframe / 多 realm 会失效（不同全局对象的原型不共享）。","Object.prototype.toString.call(x)：最通用，返回 '[object Array]'、'[object Null]' 等；注意 Symbol.toStringTag 可被改写，需谨慎。","Array.isArray(x)：判断数组最可靠，跨 realm 依然有效；constructor 判断不可靠（可被改写、null 无 constructor）。"],"bullets":[],"code":[["Object.prototype.toString.call(null)  // '[object Null]'","Object.prototype.toString.call([])    // '[object Array]'","Object.prototype.toString.call(()=>{}) // '[object Function]'"]],"note":"","text":"判断数据类型的几种方式及各自缺陷？ typeof：适合原始类型（除 null）与函数判断，无法区分数组、对象、null。 instanceof：沿原型链查找，适合判断自定义类实例；无法判断原始类型，跨 iframe / 多 realm 会失效（不同全局对象的原型不共享）。 Object.prototype.toString.call(x)：最通用，返回 '[object Array]'、'[object Null]' 等；注意 Symbol.toStringTag 可被改写，需谨慎。 Array.isArray(x)：判断数组最可靠，跨 realm 依然有效；constructor 判断不可靠（可被改写、null 无 constructor）。 Object.prototype.toString.call(null)  // '[object Null]' Object.prototype.toString.call([])    // '[object Array]' Object.prototype.toString.call(()=>{}) // '[object Function]'"},{"id":4,"num":"Q004","tag":"对比","title":"null 与 undefined 的区别？","answers":["undefined 表示「声明了但未赋值」，是变量未初始化、函数无返回值、对象属性不存在、函数形参未传时的默认值；null 表示「有意为空」，是一个需要显式赋值的对象空指针。","typeof undefined === 'undefined'，typeof null === 'object'；Number(undefined) 是 NaN，Number(null) 是 0；== 下两者相等（undefined == null 为 true），=== 下不等。","JSON.stringify 会忽略值为 undefined 的属性，但保留 null；undefined 不是合法 JSON 值。"],"bullets":[],"code":[],"note":"","text":"null 与 undefined 的区别？ undefined 表示「声明了但未赋值」，是变量未初始化、函数无返回值、对象属性不存在、函数形参未传时的默认值；null 表示「有意为空」，是一个需要显式赋值的对象空指针。 typeof undefined === 'undefined'，typeof null === 'object'；Number(undefined) 是 NaN，Number(null) 是 0；== 下两者相等（undefined == null 为 true），=== 下不等。 JSON.stringify 会忽略值为 undefined 的属性，但保留 null；undefined 不是合法 JSON 值。"},{"id":5,"num":"Q005","tag":"原理","title":"堆和栈有什么区别？闭包变量存在哪里？","answers":["栈内存连续、由系统自动分配释放、容量小、访问快，存放函数调用帧、局部变量与原始值；堆内存不连续、容量大、由垃圾回收器管理，存放对象等引用类型的值。","面试标准答法：原始类型存栈、引用类型的「地址」存栈而「值」存堆。补充加分点：V8 中原始类型也常被编码进堆或直接放寄存器，闭包捕获的变量会被提升到堆中的 Context 对象，因此闭包变量不会因为栈帧销毁而消失。"],"bullets":[],"code":[],"note":"","text":"堆和栈有什么区别？闭包变量存在哪里？ 栈内存连续、由系统自动分配释放、容量小、访问快，存放函数调用帧、局部变量与原始值；堆内存不连续、容量大、由垃圾回收器管理，存放对象等引用类型的值。 面试标准答法：原始类型存栈、引用类型的「地址」存栈而「值」存堆。补充加分点：V8 中原始类型也常被编码进堆或直接放寄存器，闭包捕获的变量会被提升到堆中的 Context 对象，因此闭包变量不会因为栈帧销毁而消失。"},{"id":6,"num":"Q006","tag":"高频","title":"为什么 0.1 + 0.2 !== 0.3？怎么解决？","answers":["JS 使用 IEEE 754 双精度浮点数（64 位：1 符号位 + 11 指数位 + 52 尾数位），0.1、0.2 的二进制是无限循环小数，存储时被截断产生精度误差，相加后误差放大，结果约为 0.30000000000000004。","解决办法：① 用 Number.EPSILON 比较：Math.abs(a-b) < Number.EPSILON；② 先放大为整数再运算后缩小，如 (0.1*100 + 0.2*100)/100；③ 用 toFixed(n) 后转 Number（注意四舍五入误差）；④ 金额计算用 BigInt 或 decimal.js / big.js 等库，不要直接用浮点。"],"bullets":[],"code":[["Number.EPSILON // 2.220446049250313e-16"]],"note":"追问：Number.MAX_SAFE_INTEGER 是 2^53-1，为什么？因为 52 位尾数加隐含的 1 位共 53 位有效二进制位。","text":"为什么 0.1 + 0.2 !== 0.3？怎么解决？ JS 使用 IEEE 754 双精度浮点数（64 位：1 符号位 + 11 指数位 + 52 尾数位），0.1、0.2 的二进制是无限循环小数，存储时被截断产生精度误差，相加后误差放大，结果约为 0.30000000000000004。 解决办法：① 用 Number.EPSILON 比较：Math.abs(a-b) < Number.EPSILON；② 先放大为整数再运算后缩小，如 (0.1*100 + 0.2*100)/100；③ 用 toFixed(n) 后转 Number（注意四舍五入误差）；④ 金额计算用 BigInt 或 decimal.js / big.js 等库，不要直接用浮点。 Number.EPSILON // 2.220446049250313e-16 追问：Number.MAX_SAFE_INTEGER 是 2^53-1，为什么？因为 52 位尾数加隐含的 1 位共 53 位有效二进制位。"},{"id":7,"num":"Q007","tag":"概念","title":"NaN 是什么？isNaN 与 Number.isNaN 的区别？","answers":["NaN 表示「不是一个数」，是全局唯一不等于自身的值（NaN !== NaN），typeof NaN === 'number'。它来自 0/0、parseInt 失败、无效数学运算等。","全局 isNaN 会先把参数强制转成数字再判断，因此 isNaN('abc') 为 true、isNaN([]) 为 false；Number.isNaN 不做类型转换，只有值本身是 NaN 才返回 true，更可靠。","判断 NaN 推荐 Number.isNaN(x) 或 x !== x；Object.is(NaN, NaN) 为 true。"],"bullets":[],"code":[],"note":"","text":"NaN 是什么？isNaN 与 Number.isNaN 的区别？ NaN 表示「不是一个数」，是全局唯一不等于自身的值（NaN !== NaN），typeof NaN === 'number'。它来自 0/0、parseInt 失败、无效数学运算等。 全局 isNaN 会先把参数强制转成数字再判断，因此 isNaN('abc') 为 true、isNaN([]) 为 false；Number.isNaN 不做类型转换，只有值本身是 NaN 才返回 true，更可靠。 判断 NaN 推荐 Number.isNaN(x) 或 x !== x；Object.is(NaN, NaN) 为 true。"},{"id":8,"num":"Q008","tag":"概念","title":"如何获取「安全的」 undefined？void 0 是什么？","answers":["void 是一元运算符，会对表达式求值但始终返回 undefined，void 0 是最常见的写法。因为在非严格模式下局部作用域可以声明一个叫 undefined 的变量并改写它（全局 undefined 不可写但可被遮蔽），用 void 0 可以保证拿到真正的 undefined。","现代代码中直接用 undefined 即可，但压缩器（如 Terser）会把 undefined 压缩成 void 0，因为更短。"],"bullets":[],"code":[],"note":"","text":"如何获取「安全的」 undefined？void 0 是什么？ void 是一元运算符，会对表达式求值但始终返回 undefined，void 0 是最常见的写法。因为在非严格模式下局部作用域可以声明一个叫 undefined 的变量并改写它（全局 undefined 不可写但可被遮蔽），用 void 0 可以保证拿到真正的 undefined。 现代代码中直接用 undefined 即可，但压缩器（如 Terser）会把 undefined 压缩成 void 0，因为更短。"},{"id":9,"num":"Q009","tag":"高频","title":"哪些值是假值？== 的隐式转换规则是什么？","answers":["假值共 8 个（ES2020 起）：false、0、-0、0n、''、null、undefined、NaN；其余对象（含 []、{}、new Boolean(false)）都是真值。","== 规则：① 类型相同按 === 比较；② null 与 undefined 相等且不与任何其它值相等；③ String 与 Number 比较，字符串转 Number；④ 有 Boolean 则布尔转 Number；⑤ 对象与原始值比较，对象先 ToPrimitive（先 valueOf 后 toString，可用 Symbol.toPrimitive 覆盖）；⑥ NaN 与任何值都不相等。","工程建议：一律用 ===，仅在 `x == null` 这种同时判 null/undefined 的惯用写法中可用 ==。"],"bullets":[],"code":[],"note":"","text":"哪些值是假值？== 的隐式转换规则是什么？ 假值共 8 个（ES2020 起）：false、0、-0、0n、''、null、undefined、NaN；其余对象（含 []、{}、new Boolean(false)）都是真值。 == 规则：① 类型相同按 === 比较；② null 与 undefined 相等且不与任何其它值相等；③ String 与 Number 比较，字符串转 Number；④ 有 Boolean 则布尔转 Number；⑤ 对象与原始值比较，对象先 ToPrimitive（先 valueOf 后 toString，可用 Symbol.toPrimitive 覆盖）；⑥ NaN 与任何值都不相等。 工程建议：一律用 ===，仅在 `x == null` 这种同时判 null/undefined 的惯用写法中可用 ==。"},{"id":10,"num":"Q010","tag":"输出题","title":"[] == ![] 为什么是 true？","answers":["拆解：![] 先把 [] 转布尔（对象恒为 true）再取反得到 false；于是表达式变成 [] == false；有布尔则转数字，false → 0；[] == 0 时对象 ToPrimitive，[].valueOf() 返回自身不是原始值，继续 [].toString() 得到 ''；'' == 0 时字符串转数字为 0；0 == 0 为 true。"],"bullets":[],"code":[],"note":"延伸：{} == !{} 为 false，因为 {} 转字符串是 '[object Object]'，转数字是 NaN。","text":"[] == ![] 为什么是 true？ 拆解：![] 先把 [] 转布尔（对象恒为 true）再取反得到 false；于是表达式变成 [] == false；有布尔则转数字，false → 0；[] == 0 时对象 ToPrimitive，[].valueOf() 返回自身不是原始值，继续 [].toString() 得到 ''；'' == 0 时字符串转数字为 0；0 == 0 为 true。 延伸：{} == !{} 为 false，因为 {} 转字符串是 '[object Object]'，转数字是 NaN。"},{"id":11,"num":"Q011","tag":"输出题","title":"['1','2','3'].map(parseInt) 的结果是什么？","answers":["结果是 [1, NaN, NaN]。map 回调接收 (item, index, array)，等价于 parseInt('1',0) → 1（radix 为 0 视为 10）、parseInt('2',1) → NaN（1 不是合法进制）、parseInt('3',2) → NaN（二进制里没有 3）。","修复：arr.map(Number) 或 arr.map(x => parseInt(x, 10))。"],"bullets":[],"code":[],"note":"追问：parseInt 的第二个参数 radix 合法范围是 2~36，为 0/undefined 时按 10 处理（字符串以 0x 开头按 16）。","text":"['1','2','3'].map(parseInt) 的结果是什么？ 结果是 [1, NaN, NaN]。map 回调接收 (item, index, array)，等价于 parseInt('1',0) → 1（radix 为 0 视为 10）、parseInt('2',1) → NaN（1 不是合法进制）、parseInt('3',2) → NaN（二进制里没有 3）。 修复：arr.map(Number) 或 arr.map(x => parseInt(x, 10))。 追问：parseInt 的第二个参数 radix 合法范围是 2~36，为 0/undefined 时按 10 处理（字符串以 0x 开头按 16）。"},{"id":12,"num":"Q012","tag":"原理","title":"对象转原始值（ToPrimitive）的完整流程？","answers":["① 若存在 Symbol.toPrimitive 方法，调用它并传入 hint（'number' / 'string' / 'default'），返回原始值则结束；② 否则按 hint 决定顺序：hint 为 'string' 时先 toString 后 valueOf，其它情况先 valueOf 后 toString；③ 依次调用，只要返回原始值就采用；④ 都返回对象则抛 TypeError。","Date 对象特殊：默认 hint 是 'string'，所以 Date 与数字相加走字符串拼接；普通对象默认 hint 是 'default'，先走 valueOf（返回自身）再走 toString 得 '[object Object]'。"],"bullets":[],"code":[["const obj = { [Symbol.toPrimitive](hint){ return hint === 'number' ? 42 : 'hi' } }","obj + 1      // 'hi1'","Number(obj)  // 42"]],"note":"","text":"对象转原始值（ToPrimitive）的完整流程？ ① 若存在 Symbol.toPrimitive 方法，调用它并传入 hint（'number' / 'string' / 'default'），返回原始值则结束；② 否则按 hint 决定顺序：hint 为 'string' 时先 toString 后 valueOf，其它情况先 valueOf 后 toString；③ 依次调用，只要返回原始值就采用；④ 都返回对象则抛 TypeError。 Date 对象特殊：默认 hint 是 'string'，所以 Date 与数字相加走字符串拼接；普通对象默认 hint 是 'default'，先走 valueOf（返回自身）再走 toString 得 '[object Object]'。 const obj = { [Symbol.toPrimitive](hint){ return hint === 'number' ? 42 : 'hi' } } obj + 1      // 'hi1' Number(obj)  // 42"},{"id":13,"num":"Q013","tag":"原理","title":"+ 运算符什么时候做字符串拼接？","answers":["一元 + 会做 ToNumber；二元 + 先把两边 ToPrimitive（hint 为 default），只要有一边结果是字符串就做拼接，否则都转数字做加法。","所以 [] + {} 是 '[object Object]'，{} + [] 在控制台常被解析成代码块 + 一元加号得到 0，1 + '2' 是 '12'，'1' + 2 + 3 是 '123'，1 + 2 + '3' 是 '33'。"],"bullets":[],"code":[],"note":"","text":"+ 运算符什么时候做字符串拼接？ 一元 + 会做 ToNumber；二元 + 先把两边 ToPrimitive（hint 为 default），只要有一边结果是字符串就做拼接，否则都转数字做加法。 所以 [] + {} 是 '[object Object]'，{} + [] 在控制台常被解析成代码块 + 一元加号得到 0，1 + '2' 是 '12'，'1' + 2 + 3 是 '123'，1 + 2 + '3' 是 '33'。"},{"id":14,"num":"Q014","tag":"手写见第 7 天","title":"如何判断一个对象是空对象？有哪些坑？","answers":["① Object.keys(obj).length === 0（只算自身可枚举属性，Symbol 键不算）；② Reflect.ownKeys(obj).length === 0（包含不可枚举与 Symbol）；③ JSON.stringify(obj) === '{}'（会忽略 undefined / 函数 / Symbol，且无法处理循环引用）。","坑：Object.keys 不含原型链上的属性、不含不可枚举属性、不含 Symbol；若要连原型链一起判断，需先 Object.getPrototypeOf(obj) === Object.prototype。"],"bullets":[],"code":[],"note":"","text":"如何判断一个对象是空对象？有哪些坑？ ① Object.keys(obj).length === 0（只算自身可枚举属性，Symbol 键不算）；② Reflect.ownKeys(obj).length === 0（包含不可枚举与 Symbol）；③ JSON.stringify(obj) === '{}'（会忽略 undefined / 函数 / Symbol，且无法处理循环引用）。 坑：Object.keys 不含原型链上的属性、不含不可枚举属性、不含 Symbol；若要连原型链一起判断，需先 Object.getPrototypeOf(obj) === Object.prototype。"},{"id":15,"num":"Q015","tag":"对比","title":"浅拷贝与深拷贝的区别？JSON 方式有哪些缺陷？","answers":["浅拷贝只复制第一层：基本类型复制值，嵌套对象仍共享地址（Object.assign、展开运算符、Array.prototype.slice、concat 都是浅拷贝）。深拷贝递归复制所有层级，新旧对象完全隔离。","JSON.parse(JSON.stringify(obj)) 的缺陷：忽略 undefined、函数、Symbol 键值；Date 变字符串；RegExp、Error、Map、Set 变 {}；Infinity/NaN 变 null；无法处理循环引用会抛错；会丢失原型链与不可枚举属性。","生产可用 structuredClone（浏览器/Node 17+，支持循环引用、Map/Set/Date，但不支持函数、DOM 节点、原型）。手写深拷贝见第 7 天。"],"bullets":[],"code":[],"note":"","text":"浅拷贝与深拷贝的区别？JSON 方式有哪些缺陷？ 浅拷贝只复制第一层：基本类型复制值，嵌套对象仍共享地址（Object.assign、展开运算符、Array.prototype.slice、concat 都是浅拷贝）。深拷贝递归复制所有层级，新旧对象完全隔离。 JSON.parse(JSON.stringify(obj)) 的缺陷：忽略 undefined、函数、Symbol 键值；Date 变字符串；RegExp、Error、Map、Set 变 {}；Infinity/NaN 变 null；无法处理循环引用会抛错；会丢失原型链与不可枚举属性。 生产可用 structuredClone（浏览器/Node 17+，支持循环引用、Map/Set/Date，但不支持函数、DOM 节点、原型）。手写深拷贝见第 7 天。"}]},{"id":"day1-s2","day":1,"title":"1.2 原型、原型链与继承","note":"","questions":[{"id":16,"num":"Q016","tag":"原理","title":"讲清楚 prototype、__proto__、constructor 三者的关系。","answers":["每个函数都有 prototype 属性，指向一个对象（原型对象），用于存放实例共享的方法；每个对象都有内部槽 [[Prototype]]（通过 __proto__ 访问，或 Object.getPrototypeOf），指向创建它的构造函数的 prototype；原型对象上有 constructor 属性，指回构造函数本身。","关系公式：实例.__proto__ === 构造函数.prototype；构造函数.prototype.constructor === 构造函数；构造函数.prototype.__proto__ === Object.prototype；Object.prototype.__proto__ === null（原型链终点）。","注意 __proto__ 是历史遗留的访问器（位于 Object.prototype），ES6 才标准化，现代代码请用 Object.getPrototypeOf / Object.setPrototypeOf / Object.create。"],"bullets":[],"code":[],"note":"","text":"讲清楚 prototype、__proto__、constructor 三者的关系。 每个函数都有 prototype 属性，指向一个对象（原型对象），用于存放实例共享的方法；每个对象都有内部槽 [[Prototype]]（通过 __proto__ 访问，或 Object.getPrototypeOf），指向创建它的构造函数的 prototype；原型对象上有 constructor 属性，指回构造函数本身。 关系公式：实例.__proto__ === 构造函数.prototype；构造函数.prototype.constructor === 构造函数；构造函数.prototype.__proto__ === Object.prototype；Object.prototype.__proto__ === null（原型链终点）。 注意 __proto__ 是历史遗留的访问器（位于 Object.prototype），ES6 才标准化，现代代码请用 Object.getPrototypeOf / Object.setPrototypeOf / Object.create。"},{"id":17,"num":"Q017","tag":"原理","title":"什么是原型链？属性查找过程是怎样的？","answers":["访问对象属性时，先查对象自身（OwnProperty）；没有则沿 [[Prototype]] 逐层向上查找，直到 Object.prototype，再到 null 停止；这条链就是原型链。找到就返回，全链没有则返回 undefined。","写入属性不受原型链影响（只会写自身，除非原型上有 setter 或属性是只读的，严格模式下会抛错）。这也是「实例共享方法、独享数据」的实现基础。"],"bullets":[],"code":[],"note":"","text":"什么是原型链？属性查找过程是怎样的？ 访问对象属性时，先查对象自身（OwnProperty）；没有则沿 [[Prototype]] 逐层向上查找，直到 Object.prototype，再到 null 停止；这条链就是原型链。找到就返回，全链没有则返回 undefined。 写入属性不受原型链影响（只会写自身，除非原型上有 setter 或属性是只读的，严格模式下会抛错）。这也是「实例共享方法、独享数据」的实现基础。"},{"id":18,"num":"Q018","tag":"基础","title":"获取对象原型的方法有哪些？","answers":["obj.__proto__（不推荐）、Object.getPrototypeOf(obj)（推荐）、obj.constructor.prototype（constructor 可被篡改，不可靠）、Reflect.getPrototypeOf(obj)。","判断原型关系：Object.prototype.isPrototypeOf(obj)、instanceof、Object.getPrototypeOf(obj) === Ctor.prototype。"],"bullets":[],"code":[],"note":"","text":"获取对象原型的方法有哪些？ obj.__proto__（不推荐）、Object.getPrototypeOf(obj)（推荐）、obj.constructor.prototype（constructor 可被篡改，不可靠）、Reflect.getPrototypeOf(obj)。 判断原型关系：Object.prototype.isPrototypeOf(obj)、instanceof、Object.getPrototypeOf(obj) === Ctor.prototype。"},{"id":19,"num":"Q019","tag":"高频","title":"new 操作符到底做了什么？","answers":["① 创建一个新空对象；② 把该对象的 [[Prototype]] 指向构造函数的 prototype；③ 以该对象为 this 执行构造函数；④ 若构造函数显式返回一个对象，则返回该对象；若返回原始值则忽略，返回新创建的对象。","手写实现要点见第 7 天（含「返回对象时覆盖」和「原型指向」两个易漏点）。"],"bullets":[],"code":[],"note":"","text":"new 操作符到底做了什么？ ① 创建一个新空对象；② 把该对象的 [[Prototype]] 指向构造函数的 prototype；③ 以该对象为 this 执行构造函数；④ 若构造函数显式返回一个对象，则返回该对象；若返回原始值则忽略，返回新创建的对象。 手写实现要点见第 7 天（含「返回对象时覆盖」和「原型指向」两个易漏点）。"},{"id":20,"num":"Q020","tag":"原理","title":"instanceof 的原理？手写的注意点？","answers":["沿左值的原型链逐层查找，判断右值.prototype 是否出现在链上，直到 null。本质是原型链比对，不是类型判断。","缺陷：原始类型恒为 false（1 instanceof Number 为 false）；跨 iframe 失效；右值 prototype 可被改写导致结果不稳定。Symbol.hasInstance 可自定义 instanceof 行为。","实现要点：while (obj = Object.getPrototypeOf(obj)) 逐一比对，注意处理左边是原始值、右边不是函数的情况。"],"bullets":[],"code":[],"note":"","text":"instanceof 的原理？手写的注意点？ 沿左值的原型链逐层查找，判断右值.prototype 是否出现在链上，直到 null。本质是原型链比对，不是类型判断。 缺陷：原始类型恒为 false（1 instanceof Number 为 false）；跨 iframe 失效；右值 prototype 可被改写导致结果不稳定。Symbol.hasInstance 可自定义 instanceof 行为。 实现要点：while (obj = Object.getPrototypeOf(obj)) 逐一比对，注意处理左边是原始值、右边不是函数的情况。"},{"id":21,"num":"Q021","tag":"对比","title":"JavaScript 实现继承有哪几种方式？各自缺点？","answers":["① 原型链继承：Child.prototype = new Parent()，缺点是无法向父构造函数传参、父类引用类型属性被所有实例共享。","② 借用构造函数（call/apply）：在子构造函数里 Parent.call(this)，能传参且属性独立，但无法继承原型上的方法，方法无法复用。","③ 组合继承：①+②，最常用，但父构造函数会被调用两次，实例与原型上都有一份父属性。","④ 原型式继承：Object.create(parent)，类似浅拷贝一个对象，引用属性仍共享。","⑤ 寄生式继承：在④基础上包一层函数添加方法，方法无法复用。","⑥ 寄生组合继承：用 Object.create(Parent.prototype) 设置原型并修正 constructor，只调用一次父构造函数，是 ES5 时代最优解。","⑦ ES6 class extends：语法糖，底层仍基于原型；子类必须在 constructor 中先 super() 才能用 this，因为派生类的 this 由父类构造创建。"],"bullets":[],"code":[],"note":"","text":"JavaScript 实现继承有哪几种方式？各自缺点？ ① 原型链继承：Child.prototype = new Parent()，缺点是无法向父构造函数传参、父类引用类型属性被所有实例共享。 ② 借用构造函数（call/apply）：在子构造函数里 Parent.call(this)，能传参且属性独立，但无法继承原型上的方法，方法无法复用。 ③ 组合继承：①+②，最常用，但父构造函数会被调用两次，实例与原型上都有一份父属性。 ④ 原型式继承：Object.create(parent)，类似浅拷贝一个对象，引用属性仍共享。 ⑤ 寄生式继承：在④基础上包一层函数添加方法，方法无法复用。 ⑥ 寄生组合继承：用 Object.create(Parent.prototype) 设置原型并修正 constructor，只调用一次父构造函数，是 ES5 时代最优解。 ⑦ ES6 class extends：语法糖，底层仍基于原型；子类必须在 constructor 中先 super() 才能用 this，因为派生类的 this 由父类构造创建。"},{"id":22,"num":"Q022","tag":"高频","title":"寄生组合继承为什么是最优解？核心代码思路？","answers":["组合继承的问题是父构造函数执行两次：一次 new Parent() 挂原型时，一次 Parent.call(this) 初始化属性时，导致子类原型上有多余的父实例属性。","寄生组合继承改为「不 new Parent，而是用 Object.create(Parent.prototype) 造一个只继承原型方法的空对象」，再用 Object.setPrototypeOf / 修正 constructor，这样父构造函数只在子类 constructor 里被调用一次。"],"bullets":[],"code":[["function Child(...args) { Parent.apply(this, args) }","Child.prototype = Object.create(Parent.prototype)","Child.prototype.constructor = Child"]],"note":"","text":"寄生组合继承为什么是最优解？核心代码思路？ 组合继承的问题是父构造函数执行两次：一次 new Parent() 挂原型时，一次 Parent.call(this) 初始化属性时，导致子类原型上有多余的父实例属性。 寄生组合继承改为「不 new Parent，而是用 Object.create(Parent.prototype) 造一个只继承原型方法的空对象」，再用 Object.setPrototypeOf / 修正 constructor，这样父构造函数只在子类 constructor 里被调用一次。 function Child(...args) { Parent.apply(this, args) } Child.prototype = Object.create(Parent.prototype) Child.prototype.constructor = Child"},{"id":23,"num":"Q023","tag":"对比","title":"ES6 class 与 ES5 构造函数有什么区别？","answers":["class 本质仍是原型继承的语法糖，但有 5 个差异：① class 不存在变量提升（有暂时性死区），必须先定义后使用；② class 内部默认严格模式；③ class 的方法定义在原型上且不可枚举（Object.keys 取不到）；④ 必须用 new 调用，直接调用会抛 TypeError；⑤ 支持 extends / super / static / 私有字段 #x，且派生类必须 super() 后才能访问 this。","另：class 的静态方法可被子类继承（子类.__proto__ 指向父类），这是 ES6 特有的「双链」结构。"],"bullets":[],"code":[],"note":"","text":"ES6 class 与 ES5 构造函数有什么区别？ class 本质仍是原型继承的语法糖，但有 5 个差异：① class 不存在变量提升（有暂时性死区），必须先定义后使用；② class 内部默认严格模式；③ class 的方法定义在原型上且不可枚举（Object.keys 取不到）；④ 必须用 new 调用，直接调用会抛 TypeError；⑤ 支持 extends / super / static / 私有字段 #x，且派生类必须 super() 后才能访问 this。 另：class 的静态方法可被子类继承（子类.__proto__ 指向父类），这是 ES6 特有的「双链」结构。"},{"id":24,"num":"Q024","tag":"场景","title":"Object.create(null) 有什么用？","answers":["创建一个没有原型（[[Prototype]] 为 null）的纯净对象，没有 toString / hasOwnProperty / constructor 等继承属性。","用途：① 实现字典 / Map 时避免键名与原型属性冲突（如用户输入 'toString'、'__proto__' 造成原型污染）；② 减少原型链查找开销。注意它无法直接调用 obj.toString()，要用 Object.prototype.toString.call(obj)。"],"bullets":[],"code":[],"note":"","text":"Object.create(null) 有什么用？ 创建一个没有原型（[[Prototype]] 为 null）的纯净对象，没有 toString / hasOwnProperty / constructor 等继承属性。 用途：① 实现字典 / Map 时避免键名与原型属性冲突（如用户输入 'toString'、'__proto__' 造成原型污染）；② 减少原型链查找开销。注意它无法直接调用 obj.toString()，要用 Object.prototype.toString.call(obj)。"}]},{"id":"day1-s3","day":1,"title":"1.3 作用域、闭包与 this","note":"","questions":[{"id":25,"num":"Q025","tag":"原理","title":"什么是作用域、词法作用域和作用域链？","answers":["作用域是变量与函数的可访问范围，JS 采用词法（静态）作用域：作用域在函数「定义时」就确定，而不是调用时。ES6 后有全局、函数、块级（{} + let/const）三级作用域。","作用域链是查找变量时由内向外的一系列变量对象（VO/AO 或词法环境 Environment Record）构成的链条，最外层是全局对象；查找沿链向上，找到即停止，找不到抛 ReferenceError。","延伸：闭包之所以能「记住」定义时的变量，正是词法作用域 + 外部词法环境引用的结果，与调用位置无关。"],"bullets":[],"code":[],"note":"","text":"什么是作用域、词法作用域和作用域链？ 作用域是变量与函数的可访问范围，JS 采用词法（静态）作用域：作用域在函数「定义时」就确定，而不是调用时。ES6 后有全局、函数、块级（{} + let/const）三级作用域。 作用域链是查找变量时由内向外的一系列变量对象（VO/AO 或词法环境 Environment Record）构成的链条，最外层是全局对象；查找沿链向上，找到即停止，找不到抛 ReferenceError。 延伸：闭包之所以能「记住」定义时的变量，正是词法作用域 + 外部词法环境引用的结果，与调用位置无关。"},{"id":26,"num":"Q026","tag":"高频","title":"var / let / const 的区别？什么是暂时性死区？","answers":["var：函数作用域、存在变量提升（声明提升到顶部并初始化为 undefined）、可重复声明、可重新赋值、全局 var 会成为 window 属性。","let/const：块级作用域、有暂时性死区（TDZ，声明前访问抛 ReferenceError，虽然引擎已为其分配空间但未初始化）、同一作用域不可重复声明、不会挂到 window 上。const 声明时必须初始化，且绑定不可重新赋值（对象内部属性仍可改，需 Object.freeze 才能冻结）。"],"bullets":[],"code":[["console.log(a) // undefined（var 提升）","console.log(b) // ReferenceError（TDZ）","var a = 1; let b = 2"]],"note":"","text":"var / let / const 的区别？什么是暂时性死区？ var：函数作用域、存在变量提升（声明提升到顶部并初始化为 undefined）、可重复声明、可重新赋值、全局 var 会成为 window 属性。 let/const：块级作用域、有暂时性死区（TDZ，声明前访问抛 ReferenceError，虽然引擎已为其分配空间但未初始化）、同一作用域不可重复声明、不会挂到 window 上。const 声明时必须初始化，且绑定不可重新赋值（对象内部属性仍可改，需 Object.freeze 才能冻结）。 console.log(a) // undefined（var 提升） console.log(b) // ReferenceError（TDZ） var a = 1; let b = 2"},{"id":27,"num":"Q027","tag":"原理","title":"变量提升与函数提升的优先级？","answers":["同一作用域内，函数声明整体提升（包含函数体），var 声明只提升声明不提升赋值；函数提升优先于 var 提升。同名的函数声明与 var 声明，最终以函数为准（除非后续有赋值覆盖）。","函数表达式（var f = function(){}）只提升 var 声明，调用时是 undefined 会报 TypeError。let/const/class 也存在提升，但因 TDZ 表现为「不可访问」。"],"bullets":[],"code":[],"note":"","text":"变量提升与函数提升的优先级？ 同一作用域内，函数声明整体提升（包含函数体），var 声明只提升声明不提升赋值；函数提升优先于 var 提升。同名的函数声明与 var 声明，最终以函数为准（除非后续有赋值覆盖）。 函数表达式（var f = function(){}）只提升 var 声明，调用时是 undefined 会报 TypeError。let/const/class 也存在提升，但因 TDZ 表现为「不可访问」。"},{"id":28,"num":"Q028","tag":"必考","title":"什么是闭包？原理、用途与缺点？","answers":["定义：函数与其定义时所在词法环境的组合；当一个函数在其定义的作用域之外被调用，仍能访问该作用域的变量，就产生了闭包（更严谨的说法：所有函数都有 [[Environment]] 引用外层词法环境，只是内部函数被外部保留时最明显）。","原理：外层函数执行完毕后，其词法环境因为仍被内部函数引用而无法被 GC 回收，变量被保存在堆中的 Context 里。","用途：① 数据私有化 / 模块模式（IIFE、单例）；② 柯里化与函数工厂；③ 防抖节流保存定时器；④ 缓存 / memoize；⑤ 循环中的变量保存；⑥ React Hooks 的状态保存。","缺点：变量常驻内存，使用不当会造成内存泄漏；比直接访问略慢。处理办法：不再使用时把引用置为 null。"],"bullets":[],"code":[],"note":"追问：闭包一定导致内存泄漏吗？不一定，V8 会分析未被内部函数引用的变量并回收，只有被引用的变量才保留；真正的泄漏多来自未清理的定时器、事件监听、DOM 引用与全局变量。","text":"什么是闭包？原理、用途与缺点？ 定义：函数与其定义时所在词法环境的组合；当一个函数在其定义的作用域之外被调用，仍能访问该作用域的变量，就产生了闭包（更严谨的说法：所有函数都有 [[Environment]] 引用外层词法环境，只是内部函数被外部保留时最明显）。 原理：外层函数执行完毕后，其词法环境因为仍被内部函数引用而无法被 GC 回收，变量被保存在堆中的 Context 里。 用途：① 数据私有化 / 模块模式（IIFE、单例）；② 柯里化与函数工厂；③ 防抖节流保存定时器；④ 缓存 / memoize；⑤ 循环中的变量保存；⑥ React Hooks 的状态保存。 缺点：变量常驻内存，使用不当会造成内存泄漏；比直接访问略慢。处理办法：不再使用时把引用置为 null。 追问：闭包一定导致内存泄漏吗？不一定，V8 会分析未被内部函数引用的变量并回收，只有被引用的变量才保留；真正的泄漏多来自未清理的定时器、事件监听、DOM 引用与全局变量。"},{"id":29,"num":"Q029","tag":"输出题","title":"经典循环打印问题：为什么全是 5？怎么修？","answers":["原因：var 是函数作用域，整个循环共享同一个 i；setTimeout 回调在同步循环结束后才执行，此时 i 已经是 5。箭头函数捕获的是同一个词法环境里的 i 的引用，不是当时的值。","修复方案：① 把 var 改成 let（每次迭代创建新的块级绑定，最简）；② 用 IIFE 把 i 作为参数传进去形成新闭包；③ setTimeout 第三个参数传参；④ 用 forEach 等自带函数作用域的迭代。"],"bullets":[],"code":[["for (var i = 0; i < 5; i++) { setTimeout(() => console.log(i), 1000) }"],["for (let i = 0; i < 5; i++) setTimeout(() => console.log(i), 1000) // 0 1 2 3 4"]],"note":"","text":"经典循环打印问题：为什么全是 5？怎么修？ 原因：var 是函数作用域，整个循环共享同一个 i；setTimeout 回调在同步循环结束后才执行，此时 i 已经是 5。箭头函数捕获的是同一个词法环境里的 i 的引用，不是当时的值。 修复方案：① 把 var 改成 let（每次迭代创建新的块级绑定，最简）；② 用 IIFE 把 i 作为参数传进去形成新闭包；③ setTimeout 第三个参数传参；④ 用 forEach 等自带函数作用域的迭代。 for (var i = 0; i < 5; i++) { setTimeout(() => console.log(i), 1000) } for (let i = 0; i < 5; i++) setTimeout(() => console.log(i), 1000) // 0 1 2 3 4"},{"id":30,"num":"Q030","tag":"必考","title":"this 的绑定规则与优先级？","answers":["优先级从高到低：① new 绑定（this 指向新创建的实例）；② 显式绑定 call / apply / bind（指向传入对象，传 null/undefined 在非严格模式退化为全局）；③ 隐式绑定（作为对象方法调用，指向该对象，注意赋值给变量后丢失）；④ 默认绑定（普通函数调用，非严格模式指向全局 window，严格模式为 undefined）。","箭头函数不适用以上规则：它没有自己的 this，沿作用域链继承外层（定义时）的 this，且无法被 call/apply/bind 改变，不能作为构造函数，没有 arguments、super、new.target。"],"bullets":[],"code":[],"note":"追问：`obj.fn()` 与 `(obj.fn)()` 相同，但 `(obj.fn = obj.fn)()` 会丢失 this，因为赋值表达式返回值是函数本身。","text":"this 的绑定规则与优先级？ 优先级从高到低：① new 绑定（this 指向新创建的实例）；② 显式绑定 call / apply / bind（指向传入对象，传 null/undefined 在非严格模式退化为全局）；③ 隐式绑定（作为对象方法调用，指向该对象，注意赋值给变量后丢失）；④ 默认绑定（普通函数调用，非严格模式指向全局 window，严格模式为 undefined）。 箭头函数不适用以上规则：它没有自己的 this，沿作用域链继承外层（定义时）的 this，且无法被 call/apply/bind 改变，不能作为构造函数，没有 arguments、super、new.target。 追问：`obj.fn()` 与 `(obj.fn)()` 相同，但 `(obj.fn = obj.fn)()` 会丢失 this，因为赋值表达式返回值是函数本身。"},{"id":31,"num":"Q031","tag":"对比","title":"call、apply、bind 的区别与实现要点？","answers":["三者都用于改变 this：call(thisArg, a, b) 立即执行、参数逐个传；apply(thisArg, [a,b]) 立即执行、参数用数组（类数组也可）；bind(thisArg, a) 返回一个 permanently 绑定 this 的新函数，不立即执行，支持柯里化式分步传参，且返回的函数被 new 调用时绑定的 this 会被忽略（但预设参数仍生效）。","手写要点：把函数临时挂到 context 上用 `context.fn()` 触发隐式绑定，调用后 delete；call/apply 用 Symbol 作临时键避免覆盖；bind 要处理原型继承（fBound.prototype = Object.create(this.prototype)）与 new 时 this instanceof fBound 的判断。完整实现见第 7 天。"],"bullets":[],"code":[],"note":"","text":"call、apply、bind 的区别与实现要点？ 三者都用于改变 this：call(thisArg, a, b) 立即执行、参数逐个传；apply(thisArg, [a,b]) 立即执行、参数用数组（类数组也可）；bind(thisArg, a) 返回一个 permanently 绑定 this 的新函数，不立即执行，支持柯里化式分步传参，且返回的函数被 new 调用时绑定的 this 会被忽略（但预设参数仍生效）。 手写要点：把函数临时挂到 context 上用 `context.fn()` 触发隐式绑定，调用后 delete；call/apply 用 Symbol 作临时键避免覆盖；bind 要处理原型继承（fBound.prototype = Object.create(this.prototype)）与 new 时 this instanceof fBound 的判断。完整实现见第 7 天。"},{"id":32,"num":"Q032","tag":"概念","title":"严格模式 'use strict' 有哪些限制？","answers":["① 未声明变量赋值不再隐式创建全局变量，直接抛 ReferenceError；② 默认绑定的 this 为 undefined 而非 window；③ 禁止 with、禁止给只读属性/不可扩展对象赋值（静默失败变抛错）；④ 函数参数不能重名，禁止八进制字面量；⑤ eval 有独立作用域，不再污染外层；⑥ 禁止删除不可删除属性、arguments.callee/caller 被禁用；⑦ 对象字面量属性重复会报错（ES6 后已放宽）。","ES6 模块与 class 内部默认就是严格模式，无需手写。"],"bullets":[],"code":[],"note":"","text":"严格模式 'use strict' 有哪些限制？ ① 未声明变量赋值不再隐式创建全局变量，直接抛 ReferenceError；② 默认绑定的 this 为 undefined 而非 window；③ 禁止 with、禁止给只读属性/不可扩展对象赋值（静默失败变抛错）；④ 函数参数不能重名，禁止八进制字面量；⑤ eval 有独立作用域，不再污染外层；⑥ 禁止删除不可删除属性、arguments.callee/caller 被禁用；⑦ 对象字面量属性重复会报错（ES6 后已放宽）。 ES6 模块与 class 内部默认就是严格模式，无需手写。"},{"id":33,"num":"Q033","tag":"概念","title":"eval 和 with 为什么被禁止？","answers":["eval 把字符串当代码执行，会破坏词法作用域的静态可分析性，导致引擎无法做优化（去优化、内联缓存失效），且有代码注入安全风险；非严格模式下还会污染外层作用域。with 会动态改变作用域链，同样让引擎无法在编译期确定变量归属。","替代方案：用 JSON.parse 解析数据、用对象解构 / 属性访问代替 with，用 Function 构造器也要谨慎（只在全局作用域执行，比 eval 稍可控）。"],"bullets":[],"code":[],"note":"","text":"eval 和 with 为什么被禁止？ eval 把字符串当代码执行，会破坏词法作用域的静态可分析性，导致引擎无法做优化（去优化、内联缓存失效），且有代码注入安全风险；非严格模式下还会污染外层作用域。with 会动态改变作用域链，同样让引擎无法在编译期确定变量归属。 替代方案：用 JSON.parse 解析数据、用对象解构 / 属性访问代替 with，用 Function 构造器也要谨慎（只在全局作用域执行，比 eval 稍可控）。"},{"id":34,"num":"Q034","tag":"原理","title":"V8 的垃圾回收机制？","answers":["主流是「标记-清除」（Mark-Sweep）：从根对象（全局、当前调用栈、活动闭包等 GC Roots）出发标记可达对象，清除未标记的。配合标记-整理（Mark-Compact）解决内存碎片。","V8 采用分代回收：新生代用 Scavenge（Cheney 算法，From/To 两个 semispace 复制存活对象，晋升条件是经历过一次回收或 To 空间超过 25%）；老生代用 Mark-Sweep + Mark-Compact。","为减少全停顿（Stop-The-World），还有增量标记、惰性清理、并发标记、三色标记法与写屏障。加分点：引用计数因循环引用问题已不作为主算法（IE 旧时代 COM 对象用过）。"],"bullets":[],"code":[],"note":"","text":"V8 的垃圾回收机制？ 主流是「标记-清除」（Mark-Sweep）：从根对象（全局、当前调用栈、活动闭包等 GC Roots）出发标记可达对象，清除未标记的。配合标记-整理（Mark-Compact）解决内存碎片。 V8 采用分代回收：新生代用 Scavenge（Cheney 算法，From/To 两个 semispace 复制存活对象，晋升条件是经历过一次回收或 To 空间超过 25%）；老生代用 Mark-Sweep + Mark-Compact。 为减少全停顿（Stop-The-World），还有增量标记、惰性清理、并发标记、三色标记法与写屏障。加分点：引用计数因循环引用问题已不作为主算法（IE 旧时代 COM 对象用过）。"},{"id":35,"num":"Q035","tag":"高频","title":"哪些操作会造成内存泄漏？如何排查？","answers":["① 意外的全局变量（未声明变量、this 指向 window）；② 忘记 clearInterval / clearTimeout / cancelAnimationFrame；③ 移除 DOM 前未解绑事件监听（尤其闭包引用了 DOM）；④ 闭包长期持有大对象；⑤ 脱离 DOM 的引用（把节点存在数组/Map 里，节点从页面移除但引用还在）；⑥ 未清理的观察者、订阅、WebSocket；⑦ console.log 持有大对象引用；⑧ 缓存无淘汰策略（用 WeakMap / LRU 解决）。","排查：Chrome DevTools Memory 面板拍 Heap Snapshot 对比（三次 GC 后对比 retained size）、Allocation instrumentation on timeline 看分配栈、Performance 看 JS Heap 曲线是否阶梯上升。"],"bullets":[],"code":[],"note":"加分：WeakMap / WeakSet 的键是弱引用，不阻止 GC，适合给 DOM 节点挂元数据；WeakRef + FinalizationRegistry（ES2021）可做更细的生命周期管理。","text":"哪些操作会造成内存泄漏？如何排查？ ① 意外的全局变量（未声明变量、this 指向 window）；② 忘记 clearInterval / clearTimeout / cancelAnimationFrame；③ 移除 DOM 前未解绑事件监听（尤其闭包引用了 DOM）；④ 闭包长期持有大对象；⑤ 脱离 DOM 的引用（把节点存在数组/Map 里，节点从页面移除但引用还在）；⑥ 未清理的观察者、订阅、WebSocket；⑦ console.log 持有大对象引用；⑧ 缓存无淘汰策略（用 WeakMap / LRU 解决）。 排查：Chrome DevTools Memory 面板拍 Heap Snapshot 对比（三次 GC 后对比 retained size）、Allocation instrumentation on timeline 看分配栈、Performance 看 JS Heap 曲线是否阶梯上升。 加分：WeakMap / WeakSet 的键是弱引用，不阻止 GC，适合给 DOM 节点挂元数据；WeakRef + FinalizationRegistry（ES2021）可做更细的生命周期管理。"}]},{"id":"day1-s4","day":1,"title":"1.4 对象、数组与常用 API","note":"","questions":[{"id":36,"num":"Q036","tag":"对比","title":"Object.is、===、== 的区别？","answers":["== 会做隐式类型转换；=== 不做转换但有两个特例：NaN !== NaN、+0 === -0；Object.is 与 === 基本一致，但修正这两点：Object.is(NaN, NaN) 为 true，Object.is(+0, -0) 为 false（底层用 SameValue 算法）。","Object.is 常用于 polyfill 与框架内部做精确比较，React 的 useState / useEffect 依赖比较用的就是 Object.is（Object.is 语义）。"],"bullets":[],"code":[],"note":"","text":"Object.is、===、== 的区别？ == 会做隐式类型转换；=== 不做转换但有两个特例：NaN !== NaN、+0 === -0；Object.is 与 === 基本一致，但修正这两点：Object.is(NaN, NaN) 为 true，Object.is(+0, -0) 为 false（底层用 SameValue 算法）。 Object.is 常用于 polyfill 与框架内部做精确比较，React 的 useState / useEffect 依赖比较用的就是 Object.is（Object.is 语义）。"},{"id":37,"num":"Q037","tag":"基础","title":"数组哪些方法会改变原数组？哪些不会？","answers":["会改变（变异方法，共 9 个）：push、pop、shift、unshift、splice、sort、reverse、fill、copyWithin。","不改变：map、filter、reduce、forEach、slice、concat、join、find、findIndex、some、every、includes、indexOf、flat、flatMap、at、toSorted/toReversed/toSpliced（ES2023 新增的非变异版本）。","注意：map/filter 返回新数组，但元素是引用类型时仍共享对象地址；forEach 无法 break（用 some/every 或 for...of 替代）；sort 默认按字符串 Unicode 排序，需传比较函数 (a,b)=>a-b。"],"bullets":[],"code":[],"note":"","text":"数组哪些方法会改变原数组？哪些不会？ 会改变（变异方法，共 9 个）：push、pop、shift、unshift、splice、sort、reverse、fill、copyWithin。 不改变：map、filter、reduce、forEach、slice、concat、join、find、findIndex、some、every、includes、indexOf、flat、flatMap、at、toSorted/toReversed/toSpliced（ES2023 新增的非变异版本）。 注意：map/filter 返回新数组，但元素是引用类型时仍共享对象地址；forEach 无法 break（用 some/every 或 for...of 替代）；sort 默认按字符串 Unicode 排序，需传比较函数 (a,b)=>a-b。"},{"id":38,"num":"Q038","tag":"对比","title":"for...in、for...of、forEach 有什么区别？","answers":["for...in 遍历对象自身 + 原型链上的可枚举属性（键名，含字符串键，不含 Symbol），顺序不保证，适合遍历普通对象但需 hasOwnProperty 过滤。","for...of 遍历可迭代对象（实现了 Symbol.iterator，如数组、字符串、Set、Map、NodeList、arguments、生成器），拿到的是值，支持 break/continue/return 与 await。普通对象不可直接 for...of（需 Symbol.iterator 或 Object.keys 包装）。","forEach 是数组方法，遍历索引与值，无法中断（抛异常才能停），会跳过稀疏数组的空位；for 循环最灵活且性能最好。"],"bullets":[],"code":[],"note":"","text":"for...in、for...of、forEach 有什么区别？ for...in 遍历对象自身 + 原型链上的可枚举属性（键名，含字符串键，不含 Symbol），顺序不保证，适合遍历普通对象但需 hasOwnProperty 过滤。 for...of 遍历可迭代对象（实现了 Symbol.iterator，如数组、字符串、Set、Map、NodeList、arguments、生成器），拿到的是值，支持 break/continue/return 与 await。普通对象不可直接 for...of（需 Symbol.iterator 或 Object.keys 包装）。 forEach 是数组方法，遍历索引与值，无法中断（抛异常才能停），会跳过稀疏数组的空位；for 循环最灵活且性能最好。"},{"id":39,"num":"Q039","tag":"概念","title":"类数组对象是什么？如何转成真数组？","answers":["有 length 属性和数字索引、但没有数组方法（如 arguments、NodeList、HTMLCollection、字符串、{0:'a',1:'b',length:2}）。","转换方式：Array.from(x)（还能传 mapFn，且能处理可迭代对象）、展开运算符 [...x]（要求有 Symbol.iterator）、Array.prototype.slice.call(x)、Array.prototype.concat.apply([], x)、Array.from(new Set(x)) 顺带去重。"],"bullets":[],"code":[],"note":"追问：Array.from({length: 3}, (_, i) => i) 是快速生成 0/1/2 的常用技巧。","text":"类数组对象是什么？如何转成真数组？ 有 length 属性和数字索引、但没有数组方法（如 arguments、NodeList、HTMLCollection、字符串、{0:'a',1:'b',length:2}）。 转换方式：Array.from(x)（还能传 mapFn，且能处理可迭代对象）、展开运算符 [...x]（要求有 Symbol.iterator）、Array.prototype.slice.call(x)、Array.prototype.concat.apply([], x)、Array.from(new Set(x)) 顺带去重。 追问：Array.from({length: 3}, (_, i) => i) 是快速生成 0/1/2 的常用技巧。"},{"id":40,"num":"Q040","tag":"对比","title":"Object.assign 与对象展开运算符的异同？深浅拷贝问题？","answers":["两者都是浅拷贝，Object.assign(target, ...sources) 会修改并返回 target；展开 `{...a, ...b}` 创建新对象。两者都只复制自身可枚举属性（含 Symbol），都不复制原型与不可枚举属性。","区别：Object.assign 会触发目标对象上的 setter，展开不会；同名属性都是后者覆盖前者；Object.assign 的第一个参数为 null/undefined 会抛错。"],"bullets":[],"code":[],"note":"","text":"Object.assign 与对象展开运算符的异同？深浅拷贝问题？ 两者都是浅拷贝，Object.assign(target, ...sources) 会修改并返回 target；展开 `{...a, ...b}` 创建新对象。两者都只复制自身可枚举属性（含 Symbol），都不复制原型与不可枚举属性。 区别：Object.assign 会触发目标对象上的 setter，展开不会；同名属性都是后者覆盖前者；Object.assign 的第一个参数为 null/undefined 会抛错。"},{"id":41,"num":"Q041","tag":"概念","title":"函数柯里化、偏函数与 compose/pipe 是什么？","answers":["柯里化（curry）：把 f(a,b,c) 变成 f(a)(b)(c)，每次只接收部分参数并返回新函数，参数凑齐再执行。用途：参数复用、延迟执行、函数组合（如 add(1)(2)(3)）。","偏函数（partial）：固定部分参数生成一个新函数，但剩余参数一次性传入（bind 就是典型偏函数应用）。","compose 从右到左组合函数（compose(f,g,h)(x) === f(g(h(x)))），pipe 从左到右。实现都基于 reduce / reduceRight。完整手写见第 7 天。"],"bullets":[],"code":[],"note":"","text":"函数柯里化、偏函数与 compose/pipe 是什么？ 柯里化（curry）：把 f(a,b,c) 变成 f(a)(b)(c)，每次只接收部分参数并返回新函数，参数凑齐再执行。用途：参数复用、延迟执行、函数组合（如 add(1)(2)(3)）。 偏函数（partial）：固定部分参数生成一个新函数，但剩余参数一次性传入（bind 就是典型偏函数应用）。 compose 从右到左组合函数（compose(f,g,h)(x) === f(g(h(x)))），pipe 从左到右。实现都基于 reduce / reduceRight。完整手写见第 7 天。"},{"id":42,"num":"Q042","tag":"场景","title":"['1','2','3'] 求和、数组去重、数组扁平化各有几种写法？","answers":["求和：reduce((s, x) => s + Number(x), 0)；去重：[...new Set(arr)]（NaN 也能去重）、filter + indexOf、reduce + includes；对象数组按 key 去重可用 Map。","扁平化：arr.flat(Infinity)、arr.reduce + concat + 递归、JSON.stringify 正则替换（不推荐）、生成器 yield*。手写 flatten 见第 7 天。"],"bullets":[],"code":[],"note":"追问：flat 默认深度 1，会跳过空位；flatMap 等价于 map + flat(1)，但只能展一层。","text":"['1','2','3'] 求和、数组去重、数组扁平化各有几种写法？ 求和：reduce((s, x) => s + Number(x), 0)；去重：[...new Set(arr)]（NaN 也能去重）、filter + indexOf、reduce + includes；对象数组按 key 去重可用 Map。 扁平化：arr.flat(Infinity)、arr.reduce + concat + 递归、JSON.stringify 正则替换（不推荐）、生成器 yield*。手写 flatten 见第 7 天。 追问：flat 默认深度 1，会跳过空位；flatMap 等价于 map + flat(1)，但只能展一层。"}]}]},{"id":"day2","day":2,"title":"第 2 天｜异步编程、Event Loop 与 ES6+","short":"异步编程、Event Loop 与 ES6+","note":"目标：把「同步/异步 + Promise + 事件循环」这一组连问题一次打通。面试官最爱在这里出代码输出题，务必按「同步 → 微任务 → 宏任务」的顺序动手推演，不要凭感觉。","sections":[{"id":"day2-s1","day":2,"title":"2.1 事件循环（Event Loop）","note":"","questions":[{"id":43,"num":"Q043","tag":"必考","title":"讲清楚浏览器的事件循环机制。","answers":["JS 是单线程，靠「调用栈 + 任务队列 + 事件循环」实现异步：同步代码进调用栈依次执行；遇到异步 API 交给浏览器/运行时其他线程（定时器线程、网络线程等）处理，完成后把回调放入对应任务队列；调用栈清空后，事件循环先清空全部微任务队列，再取一个宏任务执行，如此反复。","宏任务（Macrotask）：script 整体代码、setTimeout/setInterval、I/O、UI 渲染、postMessage、MessageChannel、requestAnimationFrame（严格说 rAF 在渲染阶段）、setImmediate（Node）。","微任务（Microtask）：Promise.then/catch/finally、MutationObserver、queueMicrotask、process.nextTick（Node，优先级最高）、await 后面的代码。","关键规则：每次「一个宏任务 → 清空整个微任务队列 → 必要时渲染 → 下一个宏任务」。微任务里新产生的微任务会在本轮继续执行完（可能饿死宏任务）。"],"bullets":[],"code":[],"note":"","text":"讲清楚浏览器的事件循环机制。 JS 是单线程，靠「调用栈 + 任务队列 + 事件循环」实现异步：同步代码进调用栈依次执行；遇到异步 API 交给浏览器/运行时其他线程（定时器线程、网络线程等）处理，完成后把回调放入对应任务队列；调用栈清空后，事件循环先清空全部微任务队列，再取一个宏任务执行，如此反复。 宏任务（Macrotask）：script 整体代码、setTimeout/setInterval、I/O、UI 渲染、postMessage、MessageChannel、requestAnimationFrame（严格说 rAF 在渲染阶段）、setImmediate（Node）。 微任务（Microtask）：Promise.then/catch/finally、MutationObserver、queueMicrotask、process.nextTick（Node，优先级最高）、await 后面的代码。 关键规则：每次「一个宏任务 → 清空整个微任务队列 → 必要时渲染 → 下一个宏任务」。微任务里新产生的微任务会在本轮继续执行完（可能饿死宏任务）。"},{"id":44,"num":"Q044","tag":"输出题","title":"请写出下面代码的输出顺序并解释。","answers":["输出：1 → 4 → 3 → 2。同步代码先输出 1、4；同步代码执行完后清空微任务，输出 3；最后取宏任务 setTimeout，输出 2。","注意：setTimeout(fn, 0) 不是立刻执行，HTML 规范规定嵌套定时器最小延迟约 4ms，且要等当前宏任务与所有微任务结束。"],"bullets":[],"code":[["console.log('1')","setTimeout(() => console.log('2'), 0)","Promise.resolve().then(() => console.log('3'))","console.log('4')"]],"note":"","text":"请写出下面代码的输出顺序并解释。 输出：1 → 4 → 3 → 2。同步代码先输出 1、4；同步代码执行完后清空微任务，输出 3；最后取宏任务 setTimeout，输出 2。 注意：setTimeout(fn, 0) 不是立刻执行，HTML 规范规定嵌套定时器最小延迟约 4ms，且要等当前宏任务与所有微任务结束。 console.log('1') setTimeout(() => console.log('2'), 0) Promise.resolve().then(() => console.log('3')) console.log('4')"},{"id":45,"num":"Q045","tag":"输出题","title":"async / await 与 Promise 混用的执行顺序。","answers":["输出：A → D → B → C。await 之前的代码（含 await 表达式求值）是同步的，输出 A；await 之后的代码等价于放进 Promise.then 微任务；于是同步输出 D；微任务队列按入队顺序为 B 再 C。","加分：await 一个非 Promise 值会被 Promise.resolve 包装；await 后面的代码总是在微任务里执行，哪怕 await 的是已决议的 Promise。"],"bullets":[],"code":[["async function f() { console.log('A'); await null; console.log('B') }","f(); Promise.resolve().then(() => console.log('C')); console.log('D')"]],"note":"","text":"async / await 与 Promise 混用的执行顺序。 输出：A → D → B → C。await 之前的代码（含 await 表达式求值）是同步的，输出 A；await 之后的代码等价于放进 Promise.then 微任务；于是同步输出 D；微任务队列按入队顺序为 B 再 C。 加分：await 一个非 Promise 值会被 Promise.resolve 包装；await 后面的代码总是在微任务里执行，哪怕 await 的是已决议的 Promise。 async function f() { console.log('A'); await null; console.log('B') } f(); Promise.resolve().then(() => console.log('C')); console.log('D')"},{"id":46,"num":"Q046","tag":"输出题","title":"嵌套 Promise + 定时器的完整推演。","answers":["输出：5 → 3 → 1 → 2 → 4。同步 5；首轮微任务 3（并把 4 的定时器排入宏任务）；下一个宏任务是第一个 setTimeout 输出 1，其回调内产生的微任务 2 立刻在本轮清空；再下一个宏任务输出 4。"],"bullets":[],"code":[["setTimeout(() => { console.log(1); Promise.resolve().then(() => console.log(2)) }, 0)","Promise.resolve().then(() => { console.log(3); setTimeout(() => console.log(4), 0) })","console.log(5)"]],"note":"口诀：一轮只取一个宏任务，但微任务要「清空到见底」，且宏任务回调里新产生的微任务在本轮末尾就执行。","text":"嵌套 Promise + 定时器的完整推演。 输出：5 → 3 → 1 → 2 → 4。同步 5；首轮微任务 3（并把 4 的定时器排入宏任务）；下一个宏任务是第一个 setTimeout 输出 1，其回调内产生的微任务 2 立刻在本轮清空；再下一个宏任务输出 4。 setTimeout(() => { console.log(1); Promise.resolve().then(() => console.log(2)) }, 0) Promise.resolve().then(() => { console.log(3); setTimeout(() => console.log(4), 0) }) console.log(5) 口诀：一轮只取一个宏任务，但微任务要「清空到见底」，且宏任务回调里新产生的微任务在本轮末尾就执行。"},{"id":47,"num":"Q047","tag":"对比","title":"浏览器与 Node.js 的事件循环有什么区别？","answers":["浏览器：宏任务队列 → 微任务队列 → 渲染，循环。Node（libuv）分 6 个阶段：timers → pending callbacks → idle/prepare → poll → check → close callbacks；每个阶段执行完（以及各阶段之间）清空微任务。","Node 特有：setImmediate 在 check 阶段执行，process.nextTick 队列优先级高于 Promise 微任务，会在当前操作结束后立即清空（可能先于所有微任务）。","Node v11 之后行为与浏览器趋同：每个定时器/Immediate 执行后都会清空微任务，不再像旧版本那样先清空整个 timers 队列。","注意：setTimeout(fn,0) 与 setImmediate 在顶层代码里执行顺序不保证（受进程启动耗时影响），在 I/O 回调内则 setImmediate 一定先于 setTimeout。"],"bullets":[],"code":[],"note":"","text":"浏览器与 Node.js 的事件循环有什么区别？ 浏览器：宏任务队列 → 微任务队列 → 渲染，循环。Node（libuv）分 6 个阶段：timers → pending callbacks → idle/prepare → poll → check → close callbacks；每个阶段执行完（以及各阶段之间）清空微任务。 Node 特有：setImmediate 在 check 阶段执行，process.nextTick 队列优先级高于 Promise 微任务，会在当前操作结束后立即清空（可能先于所有微任务）。 Node v11 之后行为与浏览器趋同：每个定时器/Immediate 执行后都会清空微任务，不再像旧版本那样先清空整个 timers 队列。 注意：setTimeout(fn,0) 与 setImmediate 在顶层代码里执行顺序不保证（受进程启动耗时影响），在 I/O 回调内则 setImmediate 一定先于 setTimeout。"},{"id":48,"num":"Q048","tag":"原理","title":"为什么要有微任务？MutationObserver 为什么是微任务？","answers":["微任务用于「在当前任务结束后、下一次渲染/宏任务前」立即执行高优先级、需要原子化的工作，避免中间状态被用户看到，也避免多一次宏任务调度带来的延迟。","MutationObserver 需在 DOM 变化后、浏览器渲染前批量回调，若做成宏任务会导致多次渲染之间状态不一致；做成同步又可能在一次 DOM 批量修改中触发无数次回调，所以微任务最合适。"],"bullets":[],"code":[],"note":"","text":"为什么要有微任务？MutationObserver 为什么是微任务？ 微任务用于「在当前任务结束后、下一次渲染/宏任务前」立即执行高优先级、需要原子化的工作，避免中间状态被用户看到，也避免多一次宏任务调度带来的延迟。 MutationObserver 需在 DOM 变化后、浏览器渲染前批量回调，若做成宏任务会导致多次渲染之间状态不一致；做成同步又可能在一次 DOM 批量修改中触发无数次回调，所以微任务最合适。"},{"id":49,"num":"Q049","tag":"场景","title":"requestAnimationFrame、requestIdleCallback 分别适合做什么？","answers":["rAF 在浏览器每次重绘前执行（约 16.7ms 一次，后台标签页暂停），适合做动画、逐帧 DOM 读写，能避免丢帧与布局抖动；不要再在 rAF 里做耗时计算。","requestIdleCallback 在浏览器空闲时执行，适合埋点上报、非关键预加载、低优先级数据处理；有 deadline.timeRemaining() 与 timeout 参数，不能保证一定执行，不适合关键逻辑。"],"bullets":[],"code":[],"note":"","text":"requestAnimationFrame、requestIdleCallback 分别适合做什么？ rAF 在浏览器每次重绘前执行（约 16.7ms 一次，后台标签页暂停），适合做动画、逐帧 DOM 读写，能避免丢帧与布局抖动；不要再在 rAF 里做耗时计算。 requestIdleCallback 在浏览器空闲时执行，适合埋点上报、非关键预加载、低优先级数据处理；有 deadline.timeRemaining() 与 timeout 参数，不能保证一定执行，不适合关键逻辑。"}]},{"id":"day2-s2","day":2,"title":"2.2 Promise 与 async / await","note":"","questions":[{"id":50,"num":"Q050","tag":"原理","title":"Promise 是什么？解决了什么问题？A+ 规范要点？","answers":["Promise 是异步结果的占位对象，有 pending / fulfilled / rejected 三种状态，状态一旦改变不可逆（pending → fulfilled 或 pending → rejected），且只能改变一次。","解决回调地狱、提供统一的错误捕获（catch）与链式组合能力，让异步流程可写、可读、可组合。","Promises/A+ 要点：① then 必须返回新的 Promise（因此可链式）；② then 接收 onFulfilled / onRejected，回调返回值 x 要走 [[Resolve]]（Promise Resolution Procedure），若 x 是 thenable 会递归展开并吸收其状态；③ 回调必须异步执行（微任务）；④ 错误冒泡到最近的 catch；⑤ 值穿透（then 里没传函数时向后传值）。"],"bullets":[],"code":[],"note":"","text":"Promise 是什么？解决了什么问题？A+ 规范要点？ Promise 是异步结果的占位对象，有 pending / fulfilled / rejected 三种状态，状态一旦改变不可逆（pending → fulfilled 或 pending → rejected），且只能改变一次。 解决回调地狱、提供统一的错误捕获（catch）与链式组合能力，让异步流程可写、可读、可组合。 Promises/A+ 要点：① then 必须返回新的 Promise（因此可链式）；② then 接收 onFulfilled / onRejected，回调返回值 x 要走 [[Resolve]]（Promise Resolution Procedure），若 x 是 thenable 会递归展开并吸收其状态；③ 回调必须异步执行（微任务）；④ 错误冒泡到最近的 catch；⑤ 值穿透（then 里没传函数时向后传值）。"},{"id":51,"num":"Q051","tag":"高频","title":"Promise 的静态方法有哪些？区别与适用场景？","answers":["Promise.all：全部成功才 resolve，结果数组按输入顺序（不是完成顺序）；任一 reject 立即 reject（其余仍会继续执行，只是结果被丢弃）。适合互相依赖的并发请求。","Promise.allSettled（ES2020）：等所有都结束，返回 [{status, value/reason}]，永不 reject。适合批量任务需要逐个看结果。","Promise.race：第一个「敲定」的就返回（无论成功失败）。适合超时控制、多源竞速。","Promise.any（ES2021）：第一个成功的就 resolve；全部失败才 reject 一个 AggregateError。适合多 CDN 兜底。","Promise.resolve / Promise.reject：快速创建已决议 Promise；Promise.withResolvers（ES2024）可一次性拿到 promise / resolve / reject。"],"bullets":[],"code":[],"note":"","text":"Promise 的静态方法有哪些？区别与适用场景？ Promise.all：全部成功才 resolve，结果数组按输入顺序（不是完成顺序）；任一 reject 立即 reject（其余仍会继续执行，只是结果被丢弃）。适合互相依赖的并发请求。 Promise.allSettled（ES2020）：等所有都结束，返回 [{status, value/reason}]，永不 reject。适合批量任务需要逐个看结果。 Promise.race：第一个「敲定」的就返回（无论成功失败）。适合超时控制、多源竞速。 Promise.any（ES2021）：第一个成功的就 resolve；全部失败才 reject 一个 AggregateError。适合多 CDN 兜底。 Promise.resolve / Promise.reject：快速创建已决议 Promise；Promise.withResolvers（ES2024）可一次性拿到 promise / resolve / reject。"},{"id":52,"num":"Q052","tag":"场景","title":"如何给 Promise 加超时控制？如何做并发限制？","answers":["超时：Promise.race([task, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))])，记得在 finally 里 clearTimeout 并考虑用 AbortController 真正取消请求（race 只是忽略结果，请求仍在跑）。","并发限制：维护一个执行池，用「递归补位」或 Promise.race 池化：启动 limit 个 worker，每个 worker 完成后从队列取下一个任务继续，直到队列空；最后 Promise.all(workers)。完整实现见第 7 天。"],"bullets":[],"code":[],"note":"","text":"如何给 Promise 加超时控制？如何做并发限制？ 超时：Promise.race([task, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))])，记得在 finally 里 clearTimeout 并考虑用 AbortController 真正取消请求（race 只是忽略结果，请求仍在跑）。 并发限制：维护一个执行池，用「递归补位」或 Promise.race 池化：启动 limit 个 worker，每个 worker 完成后从队列取下一个任务继续，直到队列空；最后 Promise.all(workers)。完整实现见第 7 天。"},{"id":53,"num":"Q053","tag":"对比","title":"Promise 链式调用中 then / catch / finally 的细节。","answers":["then 返回新 Promise；回调 return 普通值 → 下一个 then 收到该值；return Promise → 等待其决议；throw 或返回 rejected Promise → 跳到最近的 catch；没有对应处理函数时错误会继续向后冒泡。","catch 本质就是 then(null, onRejected)，catch 之后仍可继续 then（错误已被「处理」），所以 catch 放末尾还是中间影响后续链路。","finally 无论成败都执行，回调不接收参数，且返回的 Promise 会「透传」原结果；若 finally 里抛错或返回 rejected Promise，会覆盖原结果。"],"bullets":[],"code":[],"note":"","text":"Promise 链式调用中 then / catch / finally 的细节。 then 返回新 Promise；回调 return 普通值 → 下一个 then 收到该值；return Promise → 等待其决议；throw 或返回 rejected Promise → 跳到最近的 catch；没有对应处理函数时错误会继续向后冒泡。 catch 本质就是 then(null, onRejected)，catch 之后仍可继续 then（错误已被「处理」），所以 catch 放末尾还是中间影响后续链路。 finally 无论成败都执行，回调不接收参数，且返回的 Promise 会「透传」原结果；若 finally 里抛错或返回 rejected Promise，会覆盖原结果。"},{"id":54,"num":"Q054","tag":"高频","title":"async / await 的原理、错误处理与陷阱？","answers":["async 函数永远返回 Promise；await 会暂停当前 async 函数的执行（不阻塞整个线程），把后续代码注册为微任务，等 Promise 决议后恢复。生成器 + 自动执行器（如 co）是其语法糖等价实现。","错误处理：try...catch 包住 await，或 await p.catch(...)，或统一在调用处 .catch；多个 await 可以包在同一个 try 里，也可用 Promise.allSettled 收集。","陷阱：① 无依赖的多个请求顺序 await 会串行变慢，应改用 Promise.all；② 在 forEach / map 里直接 await 不会按预期串行，map 配合 Promise.all 才能并发；③ 循环里 await 要注意是否需要串行；④ await 的错误若未捕获会造成 unhandledrejection。"],"bullets":[],"code":[],"note":"","text":"async / await 的原理、错误处理与陷阱？ async 函数永远返回 Promise；await 会暂停当前 async 函数的执行（不阻塞整个线程），把后续代码注册为微任务，等 Promise 决议后恢复。生成器 + 自动执行器（如 co）是其语法糖等价实现。 错误处理：try...catch 包住 await，或 await p.catch(...)，或统一在调用处 .catch；多个 await 可以包在同一个 try 里，也可用 Promise.allSettled 收集。 陷阱：① 无依赖的多个请求顺序 await 会串行变慢，应改用 Promise.all；② 在 forEach / map 里直接 await 不会按预期串行，map 配合 Promise.all 才能并发；③ 循环里 await 要注意是否需要串行；④ await 的错误若未捕获会造成 unhandledrejection。"},{"id":55,"num":"Q055","tag":"对比","title":"异步编程的演进：回调 → Promise → Generator → async/await。","answers":["回调：简单但易形成回调地狱、无法用 try/catch 捕获异步错误、控制反转（信任问题）。","Promise：链式、错误冒泡、状态不可逆，但仍有大量 then 样板与「Promise 化」改造成本。","Generator + co：用 yield 暂停/恢复，可写出看起来同步的异步流程，但需要额外执行器。","async/await：语言级支持，同步写法 + 原生错误捕获 + 与 Promise 完全互通，是当前标准；缺点是容易误写成串行、顶层 await 需 ESM 环境支持。"],"bullets":[],"code":[],"note":"","text":"异步编程的演进：回调 → Promise → Generator → async/await。 回调：简单但易形成回调地狱、无法用 try/catch 捕获异步错误、控制反转（信任问题）。 Promise：链式、错误冒泡、状态不可逆，但仍有大量 then 样板与「Promise 化」改造成本。 Generator + co：用 yield 暂停/恢复，可写出看起来同步的异步流程，但需要额外执行器。 async/await：语言级支持，同步写法 + 原生错误捕获 + 与 Promise 完全互通，是当前标准；缺点是容易误写成串行、顶层 await 需 ESM 环境支持。"},{"id":56,"num":"Q056","tag":"概念","title":"什么是 Promise 穿透、值吸收与 thenable？","answers":["值穿透：then() 不传回调时，Promise 会把上一个结果原样传给下一个 then（规范里 onFulfilled 缺省时替换为 v => v）。","thenable：任何带 then 方法的对象或函数；Promise Resolution Procedure 会尝试调用它的 then 并把决议权交给它，因此可以实现与第三方 Promise 库互通，也带来「then 被反复读取」的安全风险（规范规定只取一次并加锁）。","Promise.resolve(thenable) 会展开它；Promise.reject(thenable) 不会展开，直接把 thenable 当 reason。"],"bullets":[],"code":[],"note":"","text":"什么是 Promise 穿透、值吸收与 thenable？ 值穿透：then() 不传回调时，Promise 会把上一个结果原样传给下一个 then（规范里 onFulfilled 缺省时替换为 v => v）。 thenable：任何带 then 方法的对象或函数；Promise Resolution Procedure 会尝试调用它的 then 并把决议权交给它，因此可以实现与第三方 Promise 库互通，也带来「then 被反复读取」的安全风险（规范规定只取一次并加锁）。 Promise.resolve(thenable) 会展开它；Promise.reject(thenable) 不会展开，直接把 thenable 当 reason。"},{"id":57,"num":"Q057","tag":"场景","title":"unhandledrejection 与全局错误如何处理？","answers":["浏览器监听 window.addEventListener('unhandledrejection', e => ...) 与 'error' 事件；Node 用 process.on('unhandledRejection') / 'uncaughtException'。","线上应接入前端监控 SDK：捕获 JS 运行时错误、资源加载错误（capture 阶段监听）、未处理 Promise 拒绝、接口异常，配合 sourcemap 还原堆栈与用户行为面包屑。"],"bullets":[],"code":[],"note":"","text":"unhandledrejection 与全局错误如何处理？ 浏览器监听 window.addEventListener('unhandledrejection', e => ...) 与 'error' 事件；Node 用 process.on('unhandledRejection') / 'uncaughtException'。 线上应接入前端监控 SDK：捕获 JS 运行时错误、资源加载错误（capture 阶段监听）、未处理 Promise 拒绝、接口异常，配合 sourcemap 还原堆栈与用户行为面包屑。"}]},{"id":"day2-s3","day":2,"title":"2.3 ES6+ 语法与特性","note":"","questions":[{"id":58,"num":"Q058","tag":"对比","title":"箭头函数与普通函数的区别？","answers":["① 没有自己的 this / arguments / super / new.target，沿词法作用域继承外层；② 不能作为构造函数（无 prototype，new 会抛 TypeError）；③ 不能用 yield（不能做生成器）；④ 语法更简洁，单表达式可隐式返回，返回对象字面量要加括号；⑤ call/apply/bind 无法改变其 this（但能传参）。","适用场景：回调、数组方法、需要固定 this 的简短函数；不适用场景：对象方法（需要 this 指向对象）、构造函数、需要 arguments、原型方法、事件处理里需要 this 指向 DOM 元素时。"],"bullets":[],"code":[],"note":"","text":"箭头函数与普通函数的区别？ ① 没有自己的 this / arguments / super / new.target，沿词法作用域继承外层；② 不能作为构造函数（无 prototype，new 会抛 TypeError）；③ 不能用 yield（不能做生成器）；④ 语法更简洁，单表达式可隐式返回，返回对象字面量要加括号；⑤ call/apply/bind 无法改变其 this（但能传参）。 适用场景：回调、数组方法、需要固定 this 的简短函数；不适用场景：对象方法（需要 this 指向对象）、构造函数、需要 arguments、原型方法、事件处理里需要 this 指向 DOM 元素时。"},{"id":59,"num":"Q059","tag":"基础","title":"解构赋值、模板字符串、展开/剩余运算符的用法与坑？","answers":["解构支持数组按位置、对象按属性名，可设默认值、别名、嵌套解构、剩余收集；默认值只在值为 undefined 时生效（null 不触发）。","模板字符串支持多行、插值 ${}、标签模板（tagged template，可用于 styled-components、防 XSS 转义、国际化）。","展开运算符 ... 用于数组/对象浅拷贝与合并（要求可迭代 / 可枚举），剩余参数必须放最后且只能有一个；对象展开不复制原型与不可枚举属性。"],"bullets":[],"code":[],"note":"","text":"解构赋值、模板字符串、展开/剩余运算符的用法与坑？ 解构支持数组按位置、对象按属性名，可设默认值、别名、嵌套解构、剩余收集；默认值只在值为 undefined 时生效（null 不触发）。 模板字符串支持多行、插值 ${}、标签模板（tagged template，可用于 styled-components、防 XSS 转义、国际化）。 展开运算符 ... 用于数组/对象浅拷贝与合并（要求可迭代 / 可枚举），剩余参数必须放最后且只能有一个；对象展开不复制原型与不可枚举属性。"},{"id":60,"num":"Q060","tag":"概念","title":"可选链 ?.、空值合并 ??、逻辑赋值运算符的区别？","answers":["?. 在引用为 null/undefined 时短路返回 undefined，不抛错（obj?.a?.b、fn?.()、arr?.[0]）；不能用于赋值左侧。","?? 只在左侧为 null 或 undefined 时返回右侧，与 || 不同（|| 会把 0、''、false 也当作假值），因此配置默认值、保留 0 更应该用 ??。","逻辑赋值：??=、||=、&&=；?? 与 ||/&& 不能无括号混用（语法错误）。"],"bullets":[],"code":[],"note":"","text":"可选链 ?.、空值合并 ??、逻辑赋值运算符的区别？ ?. 在引用为 null/undefined 时短路返回 undefined，不抛错（obj?.a?.b、fn?.()、arr?.[0]）；不能用于赋值左侧。 ?? 只在左侧为 null 或 undefined 时返回右侧，与 || 不同（|| 会把 0、''、false 也当作假值），因此配置默认值、保留 0 更应该用 ??。 逻辑赋值：??=、||=、&&=；?? 与 ||/&& 不能无括号混用（语法错误）。"},{"id":61,"num":"Q061","tag":"原理","title":"Symbol 的特性与内置 Symbol？","answers":["Symbol 是唯一且不可变的原始值，主要作为对象属性键（不参与 for...in / Object.keys，需用 Reflect.ownKeys 或 Object.getOwnPropertySymbols 获取），可避免属性名冲突。","Symbol.for(key) 会在全局注册表复用同一 Symbol，Symbol() 每次都新建；Symbol.keyFor 可反查全局注册的 key。","常用内置 well-known Symbol：Symbol.iterator（可迭代协议）、Symbol.toPrimitive（类型转换）、Symbol.toStringTag（影响 Object.prototype.toString）、Symbol.hasInstance（自定义 instanceof）、Symbol.species、Symbol.asyncIterator、Symbol.match/replace/search/split。"],"bullets":[],"code":[],"note":"","text":"Symbol 的特性与内置 Symbol？ Symbol 是唯一且不可变的原始值，主要作为对象属性键（不参与 for...in / Object.keys，需用 Reflect.ownKeys 或 Object.getOwnPropertySymbols 获取），可避免属性名冲突。 Symbol.for(key) 会在全局注册表复用同一 Symbol，Symbol() 每次都新建；Symbol.keyFor 可反查全局注册的 key。 常用内置 well-known Symbol：Symbol.iterator（可迭代协议）、Symbol.toPrimitive（类型转换）、Symbol.toStringTag（影响 Object.prototype.toString）、Symbol.hasInstance（自定义 instanceof）、Symbol.species、Symbol.asyncIterator、Symbol.match/replace/search/split。"},{"id":62,"num":"Q062","tag":"对比","title":"Set / Map / WeakSet / WeakMap 的区别与场景？","answers":["Set：值唯一集合（SameValueZero 比较，NaN 等于自身），有 add/delete/has/size，可迭代，常用于去重。","Map：键值对集合，键可以是任意类型（对象、函数、NaN），保持插入顺序，有 get/set/has/delete/size，可迭代；比普通对象更适合做字典（无原型污染、键类型不限、size 直接可用、频繁增删性能更好）。","WeakSet / WeakMap：键（或元素）必须是对象且为弱引用，不阻止 GC，因此不可遍历、没有 size；适合给 DOM 节点/对象挂私有元数据、缓存计算结果、避免内存泄漏。","注意：WeakMap 的 key 必须是对象，value 可以是任意值；弱的是 key，不是 value。"],"bullets":[],"code":[],"note":"","text":"Set / Map / WeakSet / WeakMap 的区别与场景？ Set：值唯一集合（SameValueZero 比较，NaN 等于自身），有 add/delete/has/size，可迭代，常用于去重。 Map：键值对集合，键可以是任意类型（对象、函数、NaN），保持插入顺序，有 get/set/has/delete/size，可迭代；比普通对象更适合做字典（无原型污染、键类型不限、size 直接可用、频繁增删性能更好）。 WeakSet / WeakMap：键（或元素）必须是对象且为弱引用，不阻止 GC，因此不可遍历、没有 size；适合给 DOM 节点/对象挂私有元数据、缓存计算结果、避免内存泄漏。 注意：WeakMap 的 key 必须是对象，value 可以是任意值；弱的是 key，不是 value。"},{"id":63,"num":"Q063","tag":"原理","title":"Proxy 与 Reflect 是什么？Object.defineProperty 为什么不够用？","answers":["Proxy 创建一个对象代理，可拦截 13 种基本操作（get/set/has/deleteProperty/ownKeys/getOwnPropertyDescriptor/defineProperty/preventExtensions/getPrototypeOf/setPrototypeOf/isExtensible/apply/construct），是真正的「元编程」能力。","Object.defineProperty 只能拦截单个属性的 get/set，无法感知属性新增/删除、数组 push/length 变化、in 操作符、Object.keys 等；Vue2 因此需要重写数组 7 个变异方法并额外提供 $set/$delete。","Reflect 提供与 Proxy trap 一一对应的默认行为方法，统一了原本散落在 Object 上的内部方法，且返回值更合理（如 Reflect.set 返回布尔而非抛错），配合 receiver 参数可正确修正 this 指向（Vue3 响应式的关键）。"],"bullets":[],"code":[],"note":"追问：Proxy 的缺点？兼容性（IE 不支持、无法 polyfill）、代理对象与原始对象 !==、需要配合 Reflect 保证 receiver 正确、对性能有轻微开销。","text":"Proxy 与 Reflect 是什么？Object.defineProperty 为什么不够用？ Proxy 创建一个对象代理，可拦截 13 种基本操作（get/set/has/deleteProperty/ownKeys/getOwnPropertyDescriptor/defineProperty/preventExtensions/getPrototypeOf/setPrototypeOf/isExtensible/apply/construct），是真正的「元编程」能力。 Object.defineProperty 只能拦截单个属性的 get/set，无法感知属性新增/删除、数组 push/length 变化、in 操作符、Object.keys 等；Vue2 因此需要重写数组 7 个变异方法并额外提供 $set/$delete。 Reflect 提供与 Proxy trap 一一对应的默认行为方法，统一了原本散落在 Object 上的内部方法，且返回值更合理（如 Reflect.set 返回布尔而非抛错），配合 receiver 参数可正确修正 this 指向（Vue3 响应式的关键）。 追问：Proxy 的缺点？兼容性（IE 不支持、无法 polyfill）、代理对象与原始对象 !==、需要配合 Reflect 保证 receiver 正确、对性能有轻微开销。"},{"id":64,"num":"Q064","tag":"原理","title":"迭代器（Iterator）与生成器（Generator）？","answers":["可迭代协议：对象实现 [Symbol.iterator]() 返回一个迭代器；迭代器协议：有 next() 返回 {value, done}。数组、字符串、Set、Map、arguments、NodeList 原生可迭代。","生成器 function* 用 yield 暂停/恢复执行，返回的是迭代器对象（同时也是可迭代的）；next(v) 可向内部传值，throw 可向内部抛错，return 可提前结束；yield* 可委托给另一个可迭代对象。","应用：自定义遍历、惰性计算/无限序列、异步流程控制（co / async-await 雏形）、大数据分批处理、redux-saga。"],"bullets":[],"code":[],"note":"","text":"迭代器（Iterator）与生成器（Generator）？ 可迭代协议：对象实现 [Symbol.iterator]() 返回一个迭代器；迭代器协议：有 next() 返回 {value, done}。数组、字符串、Set、Map、arguments、NodeList 原生可迭代。 生成器 function* 用 yield 暂停/恢复执行，返回的是迭代器对象（同时也是可迭代的）；next(v) 可向内部传值，throw 可向内部抛错，return 可提前结束；yield* 可委托给另一个可迭代对象。 应用：自定义遍历、惰性计算/无限序列、异步流程控制（co / async-await 雏形）、大数据分批处理、redux-saga。"},{"id":65,"num":"Q065","tag":"对比","title":"CommonJS、AMD、CMD、UMD、ESM 的区别？","answers":["CommonJS（Node）：require / module.exports，运行时同步加载，输出的是值的「拷贝」（原始类型拷贝、对象浅拷贝引用），模块首次加载后缓存，支持动态任意位置 require。","AMD（RequireJS）：define/require，依赖前置、异步加载，浏览器端；CMD（SeaJS）：就近依赖、延迟执行，更贴近 CommonJS 书写习惯。UMD 是兼容 CJS/AMD/全局变量的包装格式。","ESM（ES Module）：import/export，编译时静态分析（顶层、不能动态写在条件里，可用 import() 动态导入），输出「值的只读引用/绑定」——模块内部变量变化会反映到所有导入方；自动严格模式；支持 Tree Shaking、循环依赖更安全、支持 top-level await。","循环依赖：CJS 可能拿到不完整的 exports（因为按执行顺序取拷贝）；ESM 因为是 live binding，只要不在初始化阶段读取就不会出错（可能报 TDZ）。"],"bullets":[],"code":[],"note":"","text":"CommonJS、AMD、CMD、UMD、ESM 的区别？ CommonJS（Node）：require / module.exports，运行时同步加载，输出的是值的「拷贝」（原始类型拷贝、对象浅拷贝引用），模块首次加载后缓存，支持动态任意位置 require。 AMD（RequireJS）：define/require，依赖前置、异步加载，浏览器端；CMD（SeaJS）：就近依赖、延迟执行，更贴近 CommonJS 书写习惯。UMD 是兼容 CJS/AMD/全局变量的包装格式。 ESM（ES Module）：import/export，编译时静态分析（顶层、不能动态写在条件里，可用 import() 动态导入），输出「值的只读引用/绑定」——模块内部变量变化会反映到所有导入方；自动严格模式；支持 Tree Shaking、循环依赖更安全、支持 top-level await。 循环依赖：CJS 可能拿到不完整的 exports（因为按执行顺序取拷贝）；ESM 因为是 live binding，只要不在初始化阶段读取就不会出错（可能报 TDZ）。"},{"id":66,"num":"Q066","tag":"高频","title":"为什么 Tree Shaking 只对 ESM 有效？","answers":["Tree Shaking 依赖「静态分析」：ESM 的 import/export 是编译时确定的静态结构，打包器能在不执行代码的情况下判断哪些导出未被引用并剔除；CommonJS 的 require 可以是变量、可以写在条件/函数里，还可能在运行时给 exports 动态挂属性，无法静态推断。","生效前提：① 使用 ESM；② 打包器开启 production 优化；③ package.json 设 sideEffects: false 或数组标注有副作用的文件；④ 避免把整个模块赋值成对象再取属性（会阻碍分析）；⑤ Babel/TS 不要先把 ESM 转成 CJS。"],"bullets":[],"code":[],"note":"","text":"为什么 Tree Shaking 只对 ESM 有效？ Tree Shaking 依赖「静态分析」：ESM 的 import/export 是编译时确定的静态结构，打包器能在不执行代码的情况下判断哪些导出未被引用并剔除；CommonJS 的 require 可以是变量、可以写在条件/函数里，还可能在运行时给 exports 动态挂属性，无法静态推断。 生效前提：① 使用 ESM；② 打包器开启 production 优化；③ package.json 设 sideEffects: false 或数组标注有副作用的文件；④ 避免把整个模块赋值成对象再取属性（会阻碍分析）；⑤ Babel/TS 不要先把 ESM 转成 CJS。"},{"id":67,"num":"Q067","tag":"基础","title":"let/const 的暂时性死区、块级作用域在循环中的表现？","answers":["let 在 for 循环头部每次迭代都会创建一个新的绑定，并把上一轮的值复制过来，所以 setTimeout 里能拿到各自的值；这是「每次迭代新环境」而不是简单的块级作用域。","TDZ 存在于从块开始到声明语句之间的区域，typeof 一个 TDZ 中的变量也会抛 ReferenceError（与未声明变量不同）。"],"bullets":[],"code":[],"note":"","text":"let/const 的暂时性死区、块级作用域在循环中的表现？ let 在 for 循环头部每次迭代都会创建一个新的绑定，并把上一轮的值复制过来，所以 setTimeout 里能拿到各自的值；这是「每次迭代新环境」而不是简单的块级作用域。 TDZ 存在于从块开始到声明语句之间的区域，typeof 一个 TDZ 中的变量也会抛 ReferenceError（与未声明变量不同）。"},{"id":68,"num":"Q068","tag":"概念","title":"ES6 之后还有哪些高频新特性值得说？","answers":["ES2016：** 指数运算符、Array.includes；ES2017：Object.values/entries、padStart/padEnd、async/await、共享内存；ES2018：异步迭代、对象展开、Promise.finally；ES2019：flat/flatMap、Object.fromEntries、trimStart；ES2020：可选链、??、BigInt、Promise.allSettled、globalThis；ES2021：Promise.any、WeakRef、逻辑赋值、数字分隔符 1_000_000；ES2022：顶层 await、class 私有字段 #x、静态块、Array.at、Object.hasOwn、Error cause；ES2023：toSorted/toReversed/toSpliced/findLast、Array.fromAsync（后续）；ES2024：Promise.withResolvers、Object.groupBy、Map.groupBy、正则 v 标志。"],"bullets":[],"code":[],"note":"面试加分：能说出「ES 现在是按年份发布、TC39 四阶段流程（Stage 0~3 提案 → Stage 4 纳入标准）」会显得体系完整。","text":"ES6 之后还有哪些高频新特性值得说？ ES2016：** 指数运算符、Array.includes；ES2017：Object.values/entries、padStart/padEnd、async/await、共享内存；ES2018：异步迭代、对象展开、Promise.finally；ES2019：flat/flatMap、Object.fromEntries、trimStart；ES2020：可选链、??、BigInt、Promise.allSettled、globalThis；ES2021：Promise.any、WeakRef、逻辑赋值、数字分隔符 1_000_000；ES2022：顶层 await、class 私有字段 #x、静态块、Array.at、Object.hasOwn、Error cause；ES2023：toSorted/toReversed/toSpliced/findLast、Array.fromAsync（后续）；ES2024：Promise.withResolvers、Object.groupBy、Map.groupBy、正则 v 标志。 面试加分：能说出「ES 现在是按年份发布、TC39 四阶段流程（Stage 0~3 提案 → Stage 4 纳入标准）」会显得体系完整。"}]},{"id":"day2-s4","day":2,"title":"2.4 DOM 事件与异步常见场景","note":"","questions":[{"id":69,"num":"Q069","tag":"原理","title":"DOM 事件流三个阶段？事件委托的原理与好处？","answers":["捕获阶段（window → document → ... → 目标父级）→ 目标阶段 → 冒泡阶段（目标 → 父级 → window）。addEventListener 第三个参数 useCapture 为 true 时在捕获阶段触发；{capture, once, passive} 是更现代的配置。","事件委托：利用事件冒泡，把监听器绑在父元素上，通过 event.target 判断实际触发元素（配合 closest / matches）。好处：减少监听器数量与内存占用、动态新增子元素无需重新绑定；坏处：不冒泡的事件（focus/blur/mouseenter/mouseleave）不适用，需要额外判断层数。","阻止：stopPropagation 阻止继续传播、stopImmediatePropagation 还阻止同元素剩余监听器、preventDefault 阻止默认行为（passive: true 时 preventDefault 无效）。"],"bullets":[],"code":[],"note":"","text":"DOM 事件流三个阶段？事件委托的原理与好处？ 捕获阶段（window → document → ... → 目标父级）→ 目标阶段 → 冒泡阶段（目标 → 父级 → window）。addEventListener 第三个参数 useCapture 为 true 时在捕获阶段触发；{capture, once, passive} 是更现代的配置。 事件委托：利用事件冒泡，把监听器绑在父元素上，通过 event.target 判断实际触发元素（配合 closest / matches）。好处：减少监听器数量与内存占用、动态新增子元素无需重新绑定；坏处：不冒泡的事件（focus/blur/mouseenter/mouseleave）不适用，需要额外判断层数。 阻止：stopPropagation 阻止继续传播、stopImmediatePropagation 还阻止同元素剩余监听器、preventDefault 阻止默认行为（passive: true 时 preventDefault 无效）。"},{"id":70,"num":"Q070","tag":"对比","title":"mouseover 与 mouseenter、target 与 currentTarget 的区别？","answers":["mouseover/mouseout 会冒泡，移到子元素时也会触发；mouseenter/mouseleave 不冒泡，只在进出元素边界时触发一次，性能更好。同理有 mouseover→mouseenter 的一一对应关系。","event.target 是实际触发事件的最深层元素；event.currentTarget 是绑定监听器的那个元素（等于监听器内的 this，箭头函数除外）。"],"bullets":[],"code":[],"note":"","text":"mouseover 与 mouseenter、target 与 currentTarget 的区别？ mouseover/mouseout 会冒泡，移到子元素时也会触发；mouseenter/mouseleave 不冒泡，只在进出元素边界时触发一次，性能更好。同理有 mouseover→mouseenter 的一一对应关系。 event.target 是实际触发事件的最深层元素；event.currentTarget 是绑定监听器的那个元素（等于监听器内的 this，箭头函数除外）。"},{"id":71,"num":"Q071","tag":"场景","title":"Ajax / fetch / axios 的区别？fetch 有哪些坑？","answers":["XMLHttpRequest 是老式回调 API；fetch 是浏览器原生 Promise API，语义更现代；axios 基于 XHR（浏览器）/http（Node）封装，提供拦截器、自动 JSON 转换、取消、超时、进度、统一错误处理。","fetch 的坑：① 只有网络错误才 reject，HTTP 4xx/5xx 仍会 resolve，需手动检查 res.ok；② 默认不带 cookie，需 credentials: 'include'；③ 没有原生超时（用 AbortController）与上传进度；④ 响应体只能读一次（body 是流，需要 clone()）；⑤ 不支持请求/响应拦截，需自己封装。"],"bullets":[],"code":[],"note":"","text":"Ajax / fetch / axios 的区别？fetch 有哪些坑？ XMLHttpRequest 是老式回调 API；fetch 是浏览器原生 Promise API，语义更现代；axios 基于 XHR（浏览器）/http（Node）封装，提供拦截器、自动 JSON 转换、取消、超时、进度、统一错误处理。 fetch 的坑：① 只有网络错误才 reject，HTTP 4xx/5xx 仍会 resolve，需手动检查 res.ok；② 默认不带 cookie，需 credentials: 'include'；③ 没有原生超时（用 AbortController）与上传进度；④ 响应体只能读一次（body 是流，需要 clone()）；⑤ 不支持请求/响应拦截，需自己封装。"},{"id":72,"num":"Q072","tag":"场景","title":"防抖与节流的区别与应用场景？","answers":["防抖 debounce：事件停止触发 n 毫秒后才执行一次，中途再次触发则重新计时；适合搜索框联想、输入校验、窗口 resize 结束后重排、按钮防重复提交（立即执行版）。","节流 throttle：n 毫秒内最多执行一次，适合 scroll 加载、拖拽、鼠标移动、高频点击、滚动位置上报。","实现要点：防抖用闭包保存 timer 并 clearTimeout；节流可用时间戳或定时器实现，需要处理首次立即执行、末次补发、this 与参数透传、cancel 方法。完整代码见第 7 天。"],"bullets":[],"code":[],"note":"","text":"防抖与节流的区别与应用场景？ 防抖 debounce：事件停止触发 n 毫秒后才执行一次，中途再次触发则重新计时；适合搜索框联想、输入校验、窗口 resize 结束后重排、按钮防重复提交（立即执行版）。 节流 throttle：n 毫秒内最多执行一次，适合 scroll 加载、拖拽、鼠标移动、高频点击、滚动位置上报。 实现要点：防抖用闭包保存 timer 并 clearTimeout；节流可用时间戳或定时器实现，需要处理首次立即执行、末次补发、this 与参数透传、cancel 方法。完整代码见第 7 天。"},{"id":73,"num":"Q073","tag":"场景","title":"页面中有 10 万条数据如何渲染不卡顿？","answers":["① 虚拟列表（只渲染可视区 + 缓冲区的少量 DOM，通过滚动位置计算 startIndex 与 translateY 偏移，需要固定/可估算行高，不定高需缓存测量值）；② 时间分片（requestAnimationFrame / requestIdleCallback 分批插入，或 setTimeout 分片）；③ DocumentFragment 批量插入减少回流；④ 分页 / 无限滚动 + 数据懒加载；⑤ 用 canvas 渲染超大规模表格；⑥ 避免每条数据都挂事件监听，用事件委托。"],"bullets":[],"code":[],"note":"追问：虚拟列表如何处理不定高？维护一个位置缓存数组 + 二分查找定位，滚动时用预估高度先渲染再异步测量并修正偏移。","text":"页面中有 10 万条数据如何渲染不卡顿？ ① 虚拟列表（只渲染可视区 + 缓冲区的少量 DOM，通过滚动位置计算 startIndex 与 translateY 偏移，需要固定/可估算行高，不定高需缓存测量值）；② 时间分片（requestAnimationFrame / requestIdleCallback 分批插入，或 setTimeout 分片）；③ DocumentFragment 批量插入减少回流；④ 分页 / 无限滚动 + 数据懒加载；⑤ 用 canvas 渲染超大规模表格；⑥ 避免每条数据都挂事件监听，用事件委托。 追问：虚拟列表如何处理不定高？维护一个位置缓存数组 + 二分查找定位，滚动时用预估高度先渲染再异步测量并修正偏移。"}]}]},{"id":"day3","day":3,"title":"第 3 天｜HTML、CSS 与浏览器渲染","short":"HTML、CSS 与浏览器渲染","note":"目标：HTML/CSS 题看似简单，但「渲染流程 + BFC + 层叠上下文 + 居中方案」是区分度最高的四块。CSS 题一定要能边说边写出代码，光背概念不够。","sections":[{"id":"day3-s1","day":3,"title":"3.1 HTML 基础与语义化","note":"","questions":[{"id":74,"num":"Q074","tag":"基础","title":"DOCTYPE 的作用？标准模式与怪异模式有什么区别？","answers":["<!DOCTYPE html> 告诉浏览器使用哪个 HTML 规范解析文档，决定是否触发标准模式（Standards Mode）。HTML5 之前需要引用 DTD（如 HTML 4.01 Strict/Transitional），HTML5 不再基于 SGML，所以只需写 <!DOCTYPE html>。","怪异模式（Quirks Mode）为兼容老页面而存在，差异包括：盒模型默认 border-box 计算方式不同（IE 旧盒模型 width 含 padding+border）、行内元素垂直对齐、table 中字体继承、百分比高度解析、margin 塌陷处理、document.documentElement.clientWidth 取值等。","判断方式：document.compatMode 返回 'CSS1Compat'（标准）或 'BackCompat'（怪异）。"],"bullets":[],"code":[],"note":"","text":"DOCTYPE 的作用？标准模式与怪异模式有什么区别？ <!DOCTYPE html> 告诉浏览器使用哪个 HTML 规范解析文档，决定是否触发标准模式（Standards Mode）。HTML5 之前需要引用 DTD（如 HTML 4.01 Strict/Transitional），HTML5 不再基于 SGML，所以只需写 <!DOCTYPE html>。 怪异模式（Quirks Mode）为兼容老页面而存在，差异包括：盒模型默认 border-box 计算方式不同（IE 旧盒模型 width 含 padding+border）、行内元素垂直对齐、table 中字体继承、百分比高度解析、margin 塌陷处理、document.documentElement.clientWidth 取值等。 判断方式：document.compatMode 返回 'CSS1Compat'（标准）或 'BackCompat'（怪异）。"},{"id":75,"num":"Q075","tag":"概念","title":"什么是 HTML 语义化？好处是什么？","answers":["用正确的标签表达正确的内容结构：header/nav/main/article/section/aside/footer/h1~h6/p/ul/li/figure/time/strong/em 等，而不是全用 div + span。","好处：① 无障碍（屏幕阅读器、键盘导航可理解结构）；② SEO（爬虫更容易抓取权重与内容层级）；③ 可维护性与团队协作；④ 无 CSS/JS 时仍可读；⑤ 移动端/阅读模式适配更好。"],"bullets":[],"code":[],"note":"易考点：b 与 strong（strong 有语义强调）、i 与 em（em 强调语气）、title 与 h1（title 是浏览器标签/收藏标题与 SEO，h1 是页面内容主标题）、img 的 alt（图片失效时的替代文本、无障碍与 SEO）与 title（悬停提示）。","text":"什么是 HTML 语义化？好处是什么？ 用正确的标签表达正确的内容结构：header/nav/main/article/section/aside/footer/h1~h6/p/ul/li/figure/time/strong/em 等，而不是全用 div + span。 好处：① 无障碍（屏幕阅读器、键盘导航可理解结构）；② SEO（爬虫更容易抓取权重与内容层级）；③ 可维护性与团队协作；④ 无 CSS/JS 时仍可读；⑤ 移动端/阅读模式适配更好。 易考点：b 与 strong（strong 有语义强调）、i 与 em（em 强调语气）、title 与 h1（title 是浏览器标签/收藏标题与 SEO，h1 是页面内容主标题）、img 的 alt（图片失效时的替代文本、无障碍与 SEO）与 title（悬停提示）。"},{"id":76,"num":"Q076","tag":"对比","title":"link 与 @import 引入 CSS 的区别？","answers":["link 是 HTML 标签，属于 DOM 元素，页面加载时并行下载，权重与顺序可控，可被 JS 动态插入，兼容性好；@import 是 CSS 规则，必须写在样式表最前面，会等包含它的 CSS 下载解析完后才发起请求（串行），可能造成 FOUC 与渲染阻塞，且无法用 JS 动态控制。","结论：一律用 link；@import 只在 CSS 预处理器/组件化按需合并时内部使用（构建后会被打平）。"],"bullets":[],"code":[],"note":"","text":"link 与 @import 引入 CSS 的区别？ link 是 HTML 标签，属于 DOM 元素，页面加载时并行下载，权重与顺序可控，可被 JS 动态插入，兼容性好；@import 是 CSS 规则，必须写在样式表最前面，会等包含它的 CSS 下载解析完后才发起请求（串行），可能造成 FOUC 与渲染阻塞，且无法用 JS 动态控制。 结论：一律用 link；@import 只在 CSS 预处理器/组件化按需合并时内部使用（构建后会被打平）。"},{"id":77,"num":"Q077","tag":"高频","title":"script 的 defer 与 async 有什么区别？","answers":["普通 <script>：下载与执行都会阻塞 HTML 解析，执行完才继续解析，所以一般放 body 末尾。","defer：异步下载、不阻塞解析，等 HTML 解析完成、DOMContentLoaded 之前按文档顺序执行；适合有依赖顺序、需要操作 DOM 的脚本。","async：异步下载、下载完立即执行，执行时仍会阻塞解析，且多个 async 脚本执行顺序不确定；适合完全独立、不操作 DOM 的脚本（统计、广告）。","两者都只对外部脚本有效（有 src），且 async 优先级高于 defer（同时写时以 async 为准）；type=\"module\" 默认具备 defer 行为。"],"bullets":[],"code":[],"note":"","text":"script 的 defer 与 async 有什么区别？ 普通 <script>：下载与执行都会阻塞 HTML 解析，执行完才继续解析，所以一般放 body 末尾。 defer：异步下载、不阻塞解析，等 HTML 解析完成、DOMContentLoaded 之前按文档顺序执行；适合有依赖顺序、需要操作 DOM 的脚本。 async：异步下载、下载完立即执行，执行时仍会阻塞解析，且多个 async 脚本执行顺序不确定；适合完全独立、不操作 DOM 的脚本（统计、广告）。 两者都只对外部脚本有效（有 src），且 async 优先级高于 defer（同时写时以 async 为准）；type=\"module\" 默认具备 defer 行为。"},{"id":78,"num":"Q078","tag":"基础","title":"HTML5 新增了哪些特性？移除了哪些元素？","answers":["新增：语义化标签、canvas/svg、video/audio、localStorage/sessionStorage、IndexedDB、Web Workers、WebSocket、Geolocation、拖放 API、History API（pushState）、表单新类型（email/date/range/number/color）与属性（placeholder/required/autocomplete/pattern）、web SQL 废弃、contenteditable、data-* 自定义属性、拖放、SVG 内联、WebRTC、requestAnimationFrame 等。","移除/废弃：纯表现层标签 font/center/big/strike/u/s、frame/frameset/noframes、acronym/applet/basefont/dir 等；用 CSS 与语义标签替代。"],"bullets":[],"code":[],"note":"","text":"HTML5 新增了哪些特性？移除了哪些元素？ 新增：语义化标签、canvas/svg、video/audio、localStorage/sessionStorage、IndexedDB、Web Workers、WebSocket、Geolocation、拖放 API、History API（pushState）、表单新类型（email/date/range/number/color）与属性（placeholder/required/autocomplete/pattern）、web SQL 废弃、contenteditable、data-* 自定义属性、拖放、SVG 内联、WebRTC、requestAnimationFrame 等。 移除/废弃：纯表现层标签 font/center/big/strike/u/s、frame/frameset/noframes、acronym/applet/basefont/dir 等；用 CSS 与语义标签替代。"},{"id":79,"num":"Q079","tag":"对比","title":"Cookie、localStorage、sessionStorage、IndexedDB 的区别？","answers":["Cookie：4KB 左右，随每次同源 HTTP 请求自动携带（浪费带宽），可设 expires/max-age、domain/path、HttpOnly（防 JS 读取）、Secure、SameSite；适合会话标识，不适合存大量数据。","localStorage：约 5MB，同源持久存储，除非手动清除否则永不过期，跨标签页共享（storage 事件可通信），只存字符串。","sessionStorage：约 5MB，仅当前标签页/会话有效，关闭标签页即清除，刷新保留，新开标签页不共享（从当前页 window.open 的会复制一份独立副本）。","IndexedDB：浏览器端事务型 NoSQL 数据库，容量大（通常为磁盘配额的比例），支持索引、异步、结构化克隆，适合离线缓存、大量结构化数据。","共同点：都受同源策略限制；都不宜存敏感信息（XSS 可读 localStorage），敏感令牌优先放 HttpOnly + Secure Cookie。"],"bullets":[],"code":[],"note":"","text":"Cookie、localStorage、sessionStorage、IndexedDB 的区别？ Cookie：4KB 左右，随每次同源 HTTP 请求自动携带（浪费带宽），可设 expires/max-age、domain/path、HttpOnly（防 JS 读取）、Secure、SameSite；适合会话标识，不适合存大量数据。 localStorage：约 5MB，同源持久存储，除非手动清除否则永不过期，跨标签页共享（storage 事件可通信），只存字符串。 sessionStorage：约 5MB，仅当前标签页/会话有效，关闭标签页即清除，刷新保留，新开标签页不共享（从当前页 window.open 的会复制一份独立副本）。 IndexedDB：浏览器端事务型 NoSQL 数据库，容量大（通常为磁盘配额的比例），支持索引、异步、结构化克隆，适合离线缓存、大量结构化数据。 共同点：都受同源策略限制；都不宜存敏感信息（XSS 可读 localStorage），敏感令牌优先放 HttpOnly + Secure Cookie。"},{"id":80,"num":"Q080","tag":"场景","title":"如何实现浏览器多个标签页之间通信？","answers":["① localStorage 的 storage 事件（同域、当前页不触发、其他标签页触发，最常用）；② BroadcastChannel API（同源，语义最清晰）；③ SharedWorker（同源，可维护共享状态与长连接）；④ WebSocket / SSE 经由服务端转发；⑤ IndexedDB 轮询或 postMessage + window.open 引用；⑥ cookie 轮询（已少用）。","注意 storage 事件只在同一浏览器同一源、且值真正发生变化时触发；BroadcastChannel 需要显式 close 避免泄漏。"],"bullets":[],"code":[],"note":"","text":"如何实现浏览器多个标签页之间通信？ ① localStorage 的 storage 事件（同域、当前页不触发、其他标签页触发，最常用）；② BroadcastChannel API（同源，语义最清晰）；③ SharedWorker（同源，可维护共享状态与长连接）；④ WebSocket / SSE 经由服务端转发；⑤ IndexedDB 轮询或 postMessage + window.open 引用；⑥ cookie 轮询（已少用）。 注意 storage 事件只在同一浏览器同一源、且值真正发生变化时触发；BroadcastChannel 需要显式 close 避免泄漏。"},{"id":81,"num":"Q081","tag":"对比","title":"Canvas 与 SVG 的区别？","answers":["Canvas 是位图、基于像素的立即模式绘图 API，通过 JS 逐帧绘制，绘制后不保留图形对象，放大失真；适合大量对象、游戏、图表大数据量、图像处理、像素级操作。","SVG 是矢量、基于 XML 的保留模式，每个图形都是 DOM 节点，可用 CSS 设置样式、绑定事件、支持缩放不失真、可被搜索引擎索引、方便无障碍；适合图标、地图、中小规模交互图表、需要动画与响应式缩放的场景。","性能分界：对象数量少（数百）用 SVG 更方便，上千上万个对象或高频重绘用 Canvas / WebGL。"],"bullets":[],"code":[],"note":"","text":"Canvas 与 SVG 的区别？ Canvas 是位图、基于像素的立即模式绘图 API，通过 JS 逐帧绘制，绘制后不保留图形对象，放大失真；适合大量对象、游戏、图表大数据量、图像处理、像素级操作。 SVG 是矢量、基于 XML 的保留模式，每个图形都是 DOM 节点，可用 CSS 设置样式、绑定事件、支持缩放不失真、可被搜索引擎索引、方便无障碍；适合图标、地图、中小规模交互图表、需要动画与响应式缩放的场景。 性能分界：对象数量少（数百）用 SVG 更方便，上千上万个对象或高频重绘用 Canvas / WebGL。"},{"id":82,"num":"Q082","tag":"场景","title":"前端 SEO 需要注意什么？","answers":["① 服务端渲染 / 预渲染（SSR、SSG、Prerender），因为纯 CSR 的初始 HTML 空壳不利于抓取；② 语义化标签与合理的 h1~h6 层级（一个页面一个 h1）；③ title / description / keywords（后者已基本无效）/ canonical / Open Graph；④ 图片加 alt、给链接用真实 href；⑤ 合理的 URL、sitemap.xml、robots.txt；⑥ 首屏性能（Core Web Vitals 已纳入排名因素）；⑦ 结构化数据 JSON-LD（Schema.org）；⑧ 避免大量 iframe、避免重要内容靠 JS 异步注入；⑨ 移动端适配与 HTTPS。"],"bullets":[],"code":[],"note":"","text":"前端 SEO 需要注意什么？ ① 服务端渲染 / 预渲染（SSR、SSG、Prerender），因为纯 CSR 的初始 HTML 空壳不利于抓取；② 语义化标签与合理的 h1~h6 层级（一个页面一个 h1）；③ title / description / keywords（后者已基本无效）/ canonical / Open Graph；④ 图片加 alt、给链接用真实 href；⑤ 合理的 URL、sitemap.xml、robots.txt；⑥ 首屏性能（Core Web Vitals 已纳入排名因素）；⑦ 结构化数据 JSON-LD（Schema.org）；⑧ 避免大量 iframe、避免重要内容靠 JS 异步注入；⑨ 移动端适配与 HTTPS。"},{"id":83,"num":"Q083","tag":"概念","title":"attribute 与 property 的区别？disabled 与 readonly？","answers":["attribute 是 HTML 标签上的字符串属性（getAttribute/setAttribute），property 是 DOM 对象上的 JS 属性；多数 attribute 与 property 一一对应（id、class→className），但 value/checked/selected 特殊：property 反映当前实时状态，attribute 反映初始 HTML 值。","disabled：表单元素禁用、不参与校验、不随表单提交、值不被提交；readonly：只读但值会提交，且只对 input/textarea 有效，用户仍可聚焦复制。"],"bullets":[],"code":[],"note":"","text":"attribute 与 property 的区别？disabled 与 readonly？ attribute 是 HTML 标签上的字符串属性（getAttribute/setAttribute），property 是 DOM 对象上的 JS 属性；多数 attribute 与 property 一一对应（id、class→className），但 value/checked/selected 特殊：property 反映当前实时状态，attribute 反映初始 HTML 值。 disabled：表单元素禁用、不参与校验、不随表单提交、值不被提交；readonly：只读但值会提交，且只对 input/textarea 有效，用户仍可聚焦复制。"}]},{"id":"day3-s2","day":3,"title":"3.2 浏览器渲染原理","note":"","questions":[{"id":84,"num":"Q084","tag":"必考","title":"浏览器从拿到 HTML 到页面显示，中间发生了什么？","answers":["① 解析 HTML 构建 DOM 树（遇到 CSS 并行下载并构建 CSSOM，遇到 JS 会阻塞/暂停解析）；② DOM + CSSOM 合成渲染树 Render Tree（不含 display:none、head 等不可见节点）；③ 布局 Layout/Reflow：计算每个节点的几何位置与尺寸；④ 绘制 Paint：生成绘制记录，填充像素（背景、文字、边框等）；⑤ 合成 Composite：按层（Layer）栅格化，由合成线程合成并输出到屏幕。","随后还有交互阶段的回流/重绘与 JS 执行；首屏相关事件：DOMContentLoaded（HTML 解析完、defer 脚本执行完，不等待图片等资源）、load（所有资源加载完）。"],"bullets":[],"code":[],"note":"加分：现代浏览器是多进程架构（Browser / Renderer / GPU / Network / Plugin 进程），渲染进程内有主线程、合成线程、光栅化线程；CSS 是「渲染阻塞资源」，JS 是「解析阻塞资源」。","text":"浏览器从拿到 HTML 到页面显示，中间发生了什么？ ① 解析 HTML 构建 DOM 树（遇到 CSS 并行下载并构建 CSSOM，遇到 JS 会阻塞/暂停解析）；② DOM + CSSOM 合成渲染树 Render Tree（不含 display:none、head 等不可见节点）；③ 布局 Layout/Reflow：计算每个节点的几何位置与尺寸；④ 绘制 Paint：生成绘制记录，填充像素（背景、文字、边框等）；⑤ 合成 Composite：按层（Layer）栅格化，由合成线程合成并输出到屏幕。 随后还有交互阶段的回流/重绘与 JS 执行；首屏相关事件：DOMContentLoaded（HTML 解析完、defer 脚本执行完，不等待图片等资源）、load（所有资源加载完）。 加分：现代浏览器是多进程架构（Browser / Renderer / GPU / Network / Plugin 进程），渲染进程内有主线程、合成线程、光栅化线程；CSS 是「渲染阻塞资源」，JS 是「解析阻塞资源」。"},{"id":85,"num":"Q085","tag":"原理","title":"CSS 和 JS 分别是如何阻塞渲染的？","answers":["CSS 不阻塞 DOM 解析，但阻塞渲染（Render Tree 需要 CSSOM）与 JS 执行（JS 可能要读样式，所以浏览器会等前面的 CSS 加载完再执行 JS）。因此 CSS 放 head 里尽早加载，避免 FOUC。","JS 默认阻塞 HTML 解析（因为可能 document.write 改 DOM）；加 defer/async 可解除下载阻塞。CSS 放最前面、JS 放最后或加 defer，是优化关键渲染路径的核心。","浏览器有预解析（Preload Scanner）：主线程被阻塞时，后台线程仍会扫描后续 HTML 提前发起资源请求；<link rel=preload/prefetch/preconnect/dns-prefetch> 可主动提示优先级。"],"bullets":[],"code":[],"note":"","text":"CSS 和 JS 分别是如何阻塞渲染的？ CSS 不阻塞 DOM 解析，但阻塞渲染（Render Tree 需要 CSSOM）与 JS 执行（JS 可能要读样式，所以浏览器会等前面的 CSS 加载完再执行 JS）。因此 CSS 放 head 里尽早加载，避免 FOUC。 JS 默认阻塞 HTML 解析（因为可能 document.write 改 DOM）；加 defer/async 可解除下载阻塞。CSS 放最前面、JS 放最后或加 defer，是优化关键渲染路径的核心。 浏览器有预解析（Preload Scanner）：主线程被阻塞时，后台线程仍会扫描后续 HTML 提前发起资源请求；<link rel=preload/prefetch/preconnect/dns-prefetch> 可主动提示优先级。"},{"id":86,"num":"Q086","tag":"高频","title":"什么是重排（回流）、重绘与合成？如何减少？","answers":["重排 Reflow：几何属性变化（宽高、位置、字体大小、增删 DOM、窗口 resize、读取 offset/scroll/client 系列或 getComputedStyle 触发强制同步布局），需要重新计算布局，代价最大，且会波及子元素与后续兄弟节点。","重绘 Repaint：外观变化但不影响布局（color、background、visibility、box-shadow），跳过布局只重画像素。","合成 Composite：只改 transform / opacity（且元素在独立合成层）时，跳过布局与绘制，由 GPU 合成，代价最小。","优化：① 批量修改样式（用 class 切换、cssText、先 display:none 再改再显示、DocumentFragment）；② 避免循环中交替读写布局属性（读写分离，缓存 offsetWidth）；③ 用 transform/top 替代 top/left 做动画；④ 对频繁动画元素用 will-change / translateZ(0) 提升合成层（勿滥用，占显存）；⑤ 用 requestAnimationFrame 合并帧内变更；⑥ 避免在布局抖动时频繁 getBoundingClientRect。"],"bullets":[],"code":[],"note":"","text":"什么是重排（回流）、重绘与合成？如何减少？ 重排 Reflow：几何属性变化（宽高、位置、字体大小、增删 DOM、窗口 resize、读取 offset/scroll/client 系列或 getComputedStyle 触发强制同步布局），需要重新计算布局，代价最大，且会波及子元素与后续兄弟节点。 重绘 Repaint：外观变化但不影响布局（color、background、visibility、box-shadow），跳过布局只重画像素。 合成 Composite：只改 transform / opacity（且元素在独立合成层）时，跳过布局与绘制，由 GPU 合成，代价最小。 优化：① 批量修改样式（用 class 切换、cssText、先 display:none 再改再显示、DocumentFragment）；② 避免循环中交替读写布局属性（读写分离，缓存 offsetWidth）；③ 用 transform/top 替代 top/left 做动画；④ 对频繁动画元素用 will-change / translateZ(0) 提升合成层（勿滥用，占显存）；⑤ 用 requestAnimationFrame 合并帧内变更；⑥ 避免在布局抖动时频繁 getBoundingClientRect。"},{"id":87,"num":"Q087","tag":"概念","title":"为什么操作 DOM 很慢？","answers":["DOM 不是纯 JS 对象，而是渲染引擎与 JS 引擎之间的跨语言/跨进程桥梁（JS 在 V8，DOM 在渲染引擎），每次访问都有桥接成本；更关键的是 DOM 修改会触发样式计算、布局、绘制、合成整条渲染流水线，频繁修改会造成大量重排重绘。","优化思路：减少 DOM 操作次数（批量、模板字符串一次性 innerHTML、DocumentFragment、虚拟 DOM 做差异合并）、缓存查询结果、事件委托减少监听器、动画用 CSS/transform。"],"bullets":[],"code":[],"note":"","text":"为什么操作 DOM 很慢？ DOM 不是纯 JS 对象，而是渲染引擎与 JS 引擎之间的跨语言/跨进程桥梁（JS 在 V8，DOM 在渲染引擎），每次访问都有桥接成本；更关键的是 DOM 修改会触发样式计算、布局、绘制、合成整条渲染流水线，频繁修改会造成大量重排重绘。 优化思路：减少 DOM 操作次数（批量、模板字符串一次性 innerHTML、DocumentFragment、虚拟 DOM 做差异合并）、缓存查询结果、事件委托减少监听器、动画用 CSS/transform。"},{"id":88,"num":"Q088","tag":"场景","title":"如何优化关键渲染路径（CRP）？","answers":["目标：最小化关键资源数量、字节数与关键路径长度。做法：① CSS 内联首屏关键样式、其余异步加载（media/print、preload + onload 切换）；② JS 加 defer/async、代码分割按需加载；③ 资源压缩（gzip/brotli）、minify、图片压缩与 WebP/AVIF；④ preconnect / dns-prefetch / preload 关键字体与 LCP 图片；⑤ 服务端 HTTP/2、CDN、缓存；⑥ 字体 font-display: swap 避免 FOIT；⑦ SSR/SSG 让首屏 HTML 直接可见；⑧ 减少第三方脚本。"],"bullets":[],"code":[],"note":"","text":"如何优化关键渲染路径（CRP）？ 目标：最小化关键资源数量、字节数与关键路径长度。做法：① CSS 内联首屏关键样式、其余异步加载（media/print、preload + onload 切换）；② JS 加 defer/async、代码分割按需加载；③ 资源压缩（gzip/brotli）、minify、图片压缩与 WebP/AVIF；④ preconnect / dns-prefetch / preload 关键字体与 LCP 图片；⑤ 服务端 HTTP/2、CDN、缓存；⑥ 字体 font-display: swap 避免 FOIT；⑦ SSR/SSG 让首屏 HTML 直接可见；⑧ 减少第三方脚本。"},{"id":89,"num":"Q089","tag":"概念","title":"CSS 选择器为什么从右往左解析？","answers":["浏览器用「从右向左」匹配：先找出所有最右侧选择器命中的候选元素，再向上验证祖先条件，能快速过滤掉绝大多数节点（若从左往右，需要遍历所有元素再逐个往下找后代，候选集几乎不缩小）。","优化：避免通配符与深层后代选择器、少用属性选择器与复杂伪类、给关键元素加类、控制选择器长度；现代浏览器的 Bloom Filter / 样式共享等技术已大幅降低开销，但保持选择器简洁仍是好习惯。"],"bullets":[],"code":[],"note":"","text":"CSS 选择器为什么从右往左解析？ 浏览器用「从右向左」匹配：先找出所有最右侧选择器命中的候选元素，再向上验证祖先条件，能快速过滤掉绝大多数节点（若从左往右，需要遍历所有元素再逐个往下找后代，候选集几乎不缩小）。 优化：避免通配符与深层后代选择器、少用属性选择器与复杂伪类、给关键元素加类、控制选择器长度；现代浏览器的 Bloom Filter / 样式共享等技术已大幅降低开销，但保持选择器简洁仍是好习惯。"}]},{"id":"day3-s3","day":3,"title":"3.3 CSS 核心概念","note":"","questions":[{"id":90,"num":"Q090","tag":"基础","title":"标准盒模型与 IE 盒模型的区别？box-sizing 怎么用？","answers":["标准盒模型（content-box）：width 只含 content，实际占宽 = width + padding + border + margin；IE/怪异盒模型（border-box）：width 已包含 content + padding + border，实际占宽 = width + margin。","全局设置 `*, *::before, *::after { box-sizing: border-box }` 是现代标准做法，布局计算更直观；注意 border-box 下 content 宽度会被压缩，padding 过大时内容区可能变 0。"],"bullets":[],"code":[],"note":"","text":"标准盒模型与 IE 盒模型的区别？box-sizing 怎么用？ 标准盒模型（content-box）：width 只含 content，实际占宽 = width + padding + border + margin；IE/怪异盒模型（border-box）：width 已包含 content + padding + border，实际占宽 = width + margin。 全局设置 `*, *::before, *::after { box-sizing: border-box }` 是现代标准做法，布局计算更直观；注意 border-box 下 content 宽度会被压缩，padding 过大时内容区可能变 0。"},{"id":91,"num":"Q091","tag":"必考","title":"CSS 选择器优先级如何计算？","answers":["按 (a, b, c, d) 四元组逐位比较：a = 内联 style（1,0,0,0）；b = ID 选择器个数；c = 类/属性/伪类个数；d = 元素/伪元素个数。从左到右逐位比大小，某位大者胜出，胜出后不再比较低位（所以「11 个类」也压不过 1 个 ID 是常见误区——实际上按位比较时 b 位不同已定胜负）。","特殊规则：!important 优先级最高（同层级比较时，作者 !important > 内联 !important 需看来源；用户 !important > 作者 !important）；同优先级后者覆盖前者；继承来的样式优先级最低（低于通配符）；:where() 权重为 0，:is()/:has()/否定伪类取参数中最高权重；!important 不参与层叠层（@layer）比较时按层顺序反转。","来源优先级（从低到高）：浏览器默认 < 用户普通 < 作者普通 < 动画 < 作者 !important < 用户 !important < 过渡。"],"bullets":[],"code":[],"note":"","text":"CSS 选择器优先级如何计算？ 按 (a, b, c, d) 四元组逐位比较：a = 内联 style（1,0,0,0）；b = ID 选择器个数；c = 类/属性/伪类个数；d = 元素/伪元素个数。从左到右逐位比大小，某位大者胜出，胜出后不再比较低位（所以「11 个类」也压不过 1 个 ID 是常见误区——实际上按位比较时 b 位不同已定胜负）。 特殊规则：!important 优先级最高（同层级比较时，作者 !important > 内联 !important 需看来源；用户 !important > 作者 !important）；同优先级后者覆盖前者；继承来的样式优先级最低（低于通配符）；:where() 权重为 0，:is()/:has()/否定伪类取参数中最高权重；!important 不参与层叠层（@layer）比较时按层顺序反转。 来源优先级（从低到高）：浏览器默认 < 用户普通 < 作者普通 < 动画 < 作者 !important < 用户 !important < 过渡。"},{"id":92,"num":"Q092","tag":"对比","title":"伪类与伪元素的区别？::before 与 :before？","answers":["伪类（单冒号，如 :hover/:focus/:nth-child/:not）表示元素的某种状态或位置，不创建新元素；伪元素（双冒号，如 ::before/::after/::first-line/::selection/::placeholder）创建或选中抽象的子部分，不在 DOM 树中。","CSS3 规定伪元素用双冒号以区分伪类，:before 是 CSS2 遗留写法，浏览器仍兼容；伪元素必须有 content 属性才渲染，默认是 inline 元素，不能用于替换元素（img、input）内部。"],"bullets":[],"code":[],"note":"","text":"伪类与伪元素的区别？::before 与 :before？ 伪类（单冒号，如 :hover/:focus/:nth-child/:not）表示元素的某种状态或位置，不创建新元素；伪元素（双冒号，如 ::before/::after/::first-line/::selection/::placeholder）创建或选中抽象的子部分，不在 DOM 树中。 CSS3 规定伪元素用双冒号以区分伪类，:before 是 CSS2 遗留写法，浏览器仍兼容；伪元素必须有 content 属性才渲染，默认是 inline 元素，不能用于替换元素（img、input）内部。"},{"id":93,"num":"Q093","tag":"基础","title":"哪些 CSS 属性可继承？","answers":["可继承：字体相关（font-family/size/weight/style/line-height）、文本相关（color、text-align、text-indent、letter-spacing、word-spacing、white-space、text-transform、direction）、visibility、cursor、list-style、quotes、border-collapse 等。","不可继承：盒模型（width/height/margin/padding/border）、display、position/float、background、opacity、transform、overflow（多数）等。","强制继承用 inherit；重置用 initial / unset / revert / revert-layer。"],"bullets":[],"code":[],"note":"","text":"哪些 CSS 属性可继承？ 可继承：字体相关（font-family/size/weight/style/line-height）、文本相关（color、text-align、text-indent、letter-spacing、word-spacing、white-space、text-transform、direction）、visibility、cursor、list-style、quotes、border-collapse 等。 不可继承：盒模型（width/height/margin/padding/border）、display、position/float、background、opacity、transform、overflow（多数）等。 强制继承用 inherit；重置用 initial / unset / revert / revert-layer。"},{"id":94,"num":"Q094","tag":"对比","title":"隐藏元素的几种方式及差异？","answers":["display:none：不占位、不渲染、不响应事件、不可被无障碍读取，会触发重排；visibility:hidden：占位、不可见、不响应事件、子元素可用 visibility:visible 覆盖，只触发重绘；opacity:0：占位、透明、仍响应事件、可被屏幕阅读器读取、会创建合成层；position:absolute + left:-9999px 或 clip-path：视觉隐藏但保留可访问性（屏幕阅读器方案）；content-visibility:hidden 跳过子树渲染但保留布局与可访问性。","追问：display:none 元素的 background-image 会不会加载？主流浏览器中一般不加载（Chrome 会跳过），但 img 的 src 在 DOM 解析阶段通常仍会发起请求。"],"bullets":[],"code":[],"note":"","text":"隐藏元素的几种方式及差异？ display:none：不占位、不渲染、不响应事件、不可被无障碍读取，会触发重排；visibility:hidden：占位、不可见、不响应事件、子元素可用 visibility:visible 覆盖，只触发重绘；opacity:0：占位、透明、仍响应事件、可被屏幕阅读器读取、会创建合成层；position:absolute + left:-9999px 或 clip-path：视觉隐藏但保留可访问性（屏幕阅读器方案）；content-visibility:hidden 跳过子树渲染但保留布局与可访问性。 追问：display:none 元素的 background-image 会不会加载？主流浏览器中一般不加载（Chrome 会跳过），但 img 的 src 在 DOM 解析阶段通常仍会发起请求。"},{"id":95,"num":"Q095","tag":"高频","title":"水平垂直居中有哪些方案？（至少说出 6 种）","answers":["① Flex：父 `display:flex; justify-content:center; align-items:center`（最常用）；② Grid：父 `display:grid; place-items:center` 或子 `margin:auto`；③ 绝对定位 + transform：`position:absolute; top:50%; left:50%; transform:translate(-50%,-50%)`（无需知道尺寸）；④ 绝对定位 + margin:auto：`top/right/bottom/left:0; margin:auto`（需固定宽高）；⑤ 绝对定位 + 负 margin（需知道宽高）；⑥ 父 `display:table-cell; vertical-align:middle; text-align:center` + 子 inline-block；⑦ line-height = height + text-align:center（单行文字）；⑧ 伪元素 + vertical-align 幽灵节点方案。","加分：Flex/Grid 方案天然支持内容尺寸自适应；transform 方案可能触发新的合成层且文字发虚（可用 translate3d 或整数像素规避）。"],"bullets":[],"code":[],"note":"","text":"水平垂直居中有哪些方案？（至少说出 6 种） ① Flex：父 `display:flex; justify-content:center; align-items:center`（最常用）；② Grid：父 `display:grid; place-items:center` 或子 `margin:auto`；③ 绝对定位 + transform：`position:absolute; top:50%; left:50%; transform:translate(-50%,-50%)`（无需知道尺寸）；④ 绝对定位 + margin:auto：`top/right/bottom/left:0; margin:auto`（需固定宽高）；⑤ 绝对定位 + 负 margin（需知道宽高）；⑥ 父 `display:table-cell; vertical-align:middle; text-align:center` + 子 inline-block；⑦ line-height = height + text-align:center（单行文字）；⑧ 伪元素 + vertical-align 幽灵节点方案。 加分：Flex/Grid 方案天然支持内容尺寸自适应；transform 方案可能触发新的合成层且文字发虚（可用 translate3d 或整数像素规避）。"},{"id":96,"num":"Q096","tag":"必考","title":"BFC 是什么？如何触发？能解决什么问题？","answers":["BFC（Block Formatting Context，块级格式化上下文）是一个独立的渲染区域，内部块级盒子按普通流垂直排列，内部布局不影响外部，外部也不影响内部。","触发条件：根元素 html；float 不为 none；position 为 absolute/fixed；display 为 inline-block / table-cell / table-caption / flex / grid / flow-root；overflow 不为 visible（hidden/auto/scroll）；contain: layout/content/paint。","作用：① 清除浮动（父元素触发 BFC 后高度会包含浮动子元素）；② 阻止上下相邻 margin 合并（塌陷）；③ 阻止元素被浮动元素覆盖，实现自适应两栏布局（右侧 overflow:hidden）。","推荐用 `display: flow-root` 触发，语义最干净、无 overflow 副作用。"],"bullets":[],"code":[],"note":"","text":"BFC 是什么？如何触发？能解决什么问题？ BFC（Block Formatting Context，块级格式化上下文）是一个独立的渲染区域，内部块级盒子按普通流垂直排列，内部布局不影响外部，外部也不影响内部。 触发条件：根元素 html；float 不为 none；position 为 absolute/fixed；display 为 inline-block / table-cell / table-caption / flex / grid / flow-root；overflow 不为 visible（hidden/auto/scroll）；contain: layout/content/paint。 作用：① 清除浮动（父元素触发 BFC 后高度会包含浮动子元素）；② 阻止上下相邻 margin 合并（塌陷）；③ 阻止元素被浮动元素覆盖，实现自适应两栏布局（右侧 overflow:hidden）。 推荐用 `display: flow-root` 触发，语义最干净、无 overflow 副作用。"},{"id":97,"num":"Q097","tag":"原理","title":"外边距塌陷（margin collapsing）的规则？","answers":["相邻兄弟元素的上下 margin 会合并，取两者较大值（同为正取最大，同为负取绝对值最大，一正一负取和）；父元素与第一个/最后一个子元素之间，若父没有 border/padding/inline 内容/BFC 隔离，上下 margin 会合并并「溢出」到父元素外侧；空块级元素自身上下 margin 也会合并。","避免：给父触发 BFC（overflow:hidden、flow-root）、加 border/padding、用 flex/grid 容器、改用 padding 或 gap。注意水平方向 margin 不会合并，行内元素与绝对定位元素不合并。"],"bullets":[],"code":[],"note":"","text":"外边距塌陷（margin collapsing）的规则？ 相邻兄弟元素的上下 margin 会合并，取两者较大值（同为正取最大，同为负取绝对值最大，一正一负取和）；父元素与第一个/最后一个子元素之间，若父没有 border/padding/inline 内容/BFC 隔离，上下 margin 会合并并「溢出」到父元素外侧；空块级元素自身上下 margin 也会合并。 避免：给父触发 BFC（overflow:hidden、flow-root）、加 border/padding、用 flex/grid 容器、改用 padding 或 gap。注意水平方向 margin 不会合并，行内元素与绝对定位元素不合并。"},{"id":98,"num":"Q098","tag":"原理","title":"清除浮动的方法与 clear 的原理？","answers":["方法：① 父元素触发 BFC（overflow:hidden / display:flow-root）；② 末尾加空元素 `clear:both`（多余标签，不推荐）；③ 伪元素 clearfix（推荐）：","④ 父元素也浮动或绝对定位（有副作用）。clear 的原理：给元素添加额外的「清除空间」，使其上边框边界下移到指定方向所有浮动元素的下边缘之下，从而撑开父容器高度。","zoom:1 是 IE 私有属性，用来触发 hasLayout 达到类似 BFC 的效果，属于历史 hack。"],"bullets":[],"code":[[".clearfix::after { content: ''; display: block; clear: both }"]],"note":"","text":"清除浮动的方法与 clear 的原理？ 方法：① 父元素触发 BFC（overflow:hidden / display:flow-root）；② 末尾加空元素 `clear:both`（多余标签，不推荐）；③ 伪元素 clearfix（推荐）： ④ 父元素也浮动或绝对定位（有副作用）。clear 的原理：给元素添加额外的「清除空间」，使其上边框边界下移到指定方向所有浮动元素的下边缘之下，从而撑开父容器高度。 zoom:1 是 IE 私有属性，用来触发 hasLayout 达到类似 BFC 的效果，属于历史 hack。 .clearfix::after { content: ''; display: block; clear: both }"},{"id":99,"num":"Q099","tag":"概念","title":"什么是层叠上下文（Stacking Context）？层叠顺序如何？","answers":["层叠上下文是元素在 z 轴上的独立渲染单元，内部子元素的 z-index 只在该上下文内比较，无法越过父级与外部元素比较。","触发条件：根元素；position 为 relative/absolute 且 z-index 不为 auto（flex/grid 子项 z-index 不为 auto 即可）；opacity < 1；transform / filter / backdrop-filter / perspective / clip-path / mask 不为 none；will-change 指定上述属性；isolation: isolate；contain: paint；mix-blend-mode 不为 normal。","同一层叠上下文内从底到顶大致顺序：背景/边框 → 负 z-index → 块级盒 → 浮动盒 → 行内/行内块 → z-index:0/auto 的定位元素 → 正 z-index。z-index 只在定位元素（或 flex/grid 子项）上生效。"],"bullets":[],"code":[],"note":"","text":"什么是层叠上下文（Stacking Context）？层叠顺序如何？ 层叠上下文是元素在 z 轴上的独立渲染单元，内部子元素的 z-index 只在该上下文内比较，无法越过父级与外部元素比较。 触发条件：根元素；position 为 relative/absolute 且 z-index 不为 auto（flex/grid 子项 z-index 不为 auto 即可）；opacity < 1；transform / filter / backdrop-filter / perspective / clip-path / mask 不为 none；will-change 指定上述属性；isolation: isolate；contain: paint；mix-blend-mode 不为 normal。 同一层叠上下文内从底到顶大致顺序：背景/边框 → 负 z-index → 块级盒 → 浮动盒 → 行内/行内块 → z-index:0/auto 的定位元素 → 正 z-index。z-index 只在定位元素（或 flex/grid 子项）上生效。"},{"id":100,"num":"Q100","tag":"对比","title":"Flex 布局常用属性与经典场景？","answers":["容器：display:flex、flex-direction、flex-wrap、justify-content（主轴）、align-items（交叉轴单行）、align-content（多行）、gap、flex-flow。","项目：flex: grow shrink basis（推荐简写 flex:1 = 1 1 0%）、align-self、order、flex-basis。","注意：`flex: 1` 的 basis 是 0% 而不是 auto，因此按内容均分会失败（等分内容不等宽），要按内容比例可用 flex:auto；flex 子项默认 min-width:auto 导致内容撑破不收缩，需设 min-width:0 才能触发文本省略。","经典场景：水平垂直居中、两栏/三栏自适应（侧栏固定 flex:0 0 200px + 主区 flex:1）、等高布局（align-items:stretch 默认）、粘性底部（margin-top:auto）、均分导航。"],"bullets":[],"code":[],"note":"","text":"Flex 布局常用属性与经典场景？ 容器：display:flex、flex-direction、flex-wrap、justify-content（主轴）、align-items（交叉轴单行）、align-content（多行）、gap、flex-flow。 项目：flex: grow shrink basis（推荐简写 flex:1 = 1 1 0%）、align-self、order、flex-basis。 注意：`flex: 1` 的 basis 是 0% 而不是 auto，因此按内容均分会失败（等分内容不等宽），要按内容比例可用 flex:auto；flex 子项默认 min-width:auto 导致内容撑破不收缩，需设 min-width:0 才能触发文本省略。 经典场景：水平垂直居中、两栏/三栏自适应（侧栏固定 flex:0 0 200px + 主区 flex:1）、等高布局（align-items:stretch 默认）、粘性底部（margin-top:auto）、均分导航。"},{"id":101,"num":"Q101","tag":"对比","title":"Grid 布局相比 Flex 的优势？","answers":["Flex 是一维（一行或一列），Grid 是二维（同时控制行列）。Grid 用 grid-template-columns/rows、fr、repeat(auto-fit, minmax(200px, 1fr))、gap、grid-area / grid-template-areas、auto-flow、place-items 等。","优势：二维对齐无需嵌套、自适应卡片布局一行代码 `repeat(auto-fill, minmax(240px, 1fr))`、可命名区域做整页骨架、行列间距 gap 不产生 margin 塌陷、支持隐式网格与 dense 填充。","实践建议：整体页面骨架 / 卡片墙用 Grid，组件内部一维排列用 Flex，两者常组合使用。"],"bullets":[],"code":[],"note":"","text":"Grid 布局相比 Flex 的优势？ Flex 是一维（一行或一列），Grid 是二维（同时控制行列）。Grid 用 grid-template-columns/rows、fr、repeat(auto-fit, minmax(200px, 1fr))、gap、grid-area / grid-template-areas、auto-flow、place-items 等。 优势：二维对齐无需嵌套、自适应卡片布局一行代码 `repeat(auto-fill, minmax(240px, 1fr))`、可命名区域做整页骨架、行列间距 gap 不产生 margin 塌陷、支持隐式网格与 dense 填充。 实践建议：整体页面骨架 / 卡片墙用 Grid，组件内部一维排列用 Flex，两者常组合使用。"},{"id":102,"num":"Q102","tag":"对比","title":"常见 CSS 布局实现：两栏、三栏、圣杯与双飞翼。","answers":["两栏（左固定右自适应）：Flex（左 flex:0 0 200px，右 flex:1）、BFC（左 float:left，右 overflow:hidden）、Grid（grid-template-columns: 200px 1fr）、绝对定位 + margin-left。","三栏（左右固定中间自适应）：Flex 最简；Grid 一行；圣杯布局用「全部左浮动 + 父 padding 留白 + 左负 margin + relative 定位」，中间栏优先渲染（DOM 顺序主内容在前，利于 SEO 与首屏）；双飞翼在中间栏内再嵌一层 div 用 margin 留白，避免相对定位。","等高：Flex align-items:stretch、Grid 默认拉伸、table-cell、padding-bottom 大值 + margin-bottom 负值 hack。"],"bullets":[],"code":[],"note":"","text":"常见 CSS 布局实现：两栏、三栏、圣杯与双飞翼。 两栏（左固定右自适应）：Flex（左 flex:0 0 200px，右 flex:1）、BFC（左 float:left，右 overflow:hidden）、Grid（grid-template-columns: 200px 1fr）、绝对定位 + margin-left。 三栏（左右固定中间自适应）：Flex 最简；Grid 一行；圣杯布局用「全部左浮动 + 父 padding 留白 + 左负 margin + relative 定位」，中间栏优先渲染（DOM 顺序主内容在前，利于 SEO 与首屏）；双飞翼在中间栏内再嵌一层 div 用 margin 留白，避免相对定位。 等高：Flex align-items:stretch、Grid 默认拉伸、table-cell、padding-bottom 大值 + margin-bottom 负值 hack。"},{"id":103,"num":"Q103","tag":"场景","title":"移动端 1px 问题与适配方案？","answers":["原因：高清屏 dpr=2/3 时，1 个 CSS 像素对应 2/3 个物理像素，直接写 border:1px 看起来偏粗。","方案：① 伪元素 + transform: scaleY(0.5)（最通用，配合 @media (-webkit-min-device-pixel-ratio: 2) 按 dpr 缩放）；② box-shadow: 0 0.5px 0；③ 直接写 0.5px（部分 iOS 支持，Android 不保证）；④ 用 border-image 或 SVG 画线；⑤ viewport 设 initial-scale=1/dpr（会造成整体适配复杂，已少用）。","适配方案：rem（配合 flexible / postcss-pxtorem，根据根字体大小换算）、vw/vh（1vw = 视口宽 1%，配合 postcss-px-to-viewport，注意与 rem 二选一）、Flex/Grid 弹性布局 + 媒体查询、响应式断点、容器查询 @container。"],"bullets":[],"code":[],"note":"","text":"移动端 1px 问题与适配方案？ 原因：高清屏 dpr=2/3 时，1 个 CSS 像素对应 2/3 个物理像素，直接写 border:1px 看起来偏粗。 方案：① 伪元素 + transform: scaleY(0.5)（最通用，配合 @media (-webkit-min-device-pixel-ratio: 2) 按 dpr 缩放）；② box-shadow: 0 0.5px 0；③ 直接写 0.5px（部分 iOS 支持，Android 不保证）；④ 用 border-image 或 SVG 画线；⑤ viewport 设 initial-scale=1/dpr（会造成整体适配复杂，已少用）。 适配方案：rem（配合 flexible / postcss-pxtorem，根据根字体大小换算）、vw/vh（1vw = 视口宽 1%，配合 postcss-px-to-viewport，注意与 rem 二选一）、Flex/Grid 弹性布局 + 媒体查询、响应式断点、容器查询 @container。"},{"id":104,"num":"Q104","tag":"对比","title":"transition、animation、transform 的区别与性能？","answers":["transition：需要触发条件（:hover、class 变化），只有起止两个状态，一次性、不可循环、不需要关键帧。","animation：用 @keyframes 定义多关键帧，可自动播放、循环（iteration-count）、alternate、延时、控制播放状态（animation-play-state），无需触发条件。","transform（translate/scale/rotate/skew）与 opacity 的动画只走合成阶段（跳过 Layout/Paint），性能最好；改变 top/left/width/height 触发布局，代价高。用 will-change 提前提升图层，但滥用会导致显存暴涨与图层爆炸。","JS 动画（setTimeout/rAF）灵活可做复杂物理效果，但主线程繁忙易掉帧；CSS 动画由合成线程驱动更流畅。rAF 的最小间隔 ≈ 1000/60 ≈ 16.7ms（高刷屏更小）。"],"bullets":[],"code":[],"note":"","text":"transition、animation、transform 的区别与性能？ transition：需要触发条件（:hover、class 变化），只有起止两个状态，一次性、不可循环、不需要关键帧。 animation：用 @keyframes 定义多关键帧，可自动播放、循环（iteration-count）、alternate、延时、控制播放状态（animation-play-state），无需触发条件。 transform（translate/scale/rotate/skew）与 opacity 的动画只走合成阶段（跳过 Layout/Paint），性能最好；改变 top/left/width/height 触发布局，代价高。用 will-change 提前提升图层，但滥用会导致显存暴涨与图层爆炸。 JS 动画（setTimeout/rAF）灵活可做复杂物理效果，但主线程繁忙易掉帧；CSS 动画由合成线程驱动更流畅。rAF 的最小间隔 ≈ 1000/60 ≈ 16.7ms（高刷屏更小）。"},{"id":105,"num":"Q105","tag":"概念","title":"设备像素、CSS 像素、DPR、PPI 与三种 viewport？","answers":["设备像素（物理像素）是屏幕实际发光点；CSS 像素是逻辑像素，1 CSS px 在 dpr=2 的屏上占 2×2 物理像素；DPR = 设备像素 / CSS 像素（window.devicePixelRatio）；PPI 是每英寸物理像素密度。","layout viewport（布局视口，文档宽度，移动端默认约 980px）、visual viewport（用户当前可见区域，可缩放/滚动）、ideal viewport（理想视口 = 设备宽度，通过 `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">` 让 layout viewport 等于它）。"],"bullets":[],"code":[],"note":"","text":"设备像素、CSS 像素、DPR、PPI 与三种 viewport？ 设备像素（物理像素）是屏幕实际发光点；CSS 像素是逻辑像素，1 CSS px 在 dpr=2 的屏上占 2×2 物理像素；DPR = 设备像素 / CSS 像素（window.devicePixelRatio）；PPI 是每英寸物理像素密度。 layout viewport（布局视口，文档宽度，移动端默认约 980px）、visual viewport（用户当前可见区域，可缩放/滚动）、ideal viewport（理想视口 = 设备宽度，通过 `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">` 让 layout viewport 等于它）。"},{"id":106,"num":"Q106","tag":"基础","title":"图片格式怎么选？CSS Sprites、base64 的利弊？","answers":["JPG：有损、体积小、不支持透明，适合照片；PNG：无损、支持 alpha 透明，体积大，适合图标/需要透明；GIF：256 色、支持简单动画；WebP：同时支持有损/无损/透明/动画，体积比 JPG/PNG 小约 25~35%；AVIF 压缩率更高但编码慢、兼容性略差；SVG：矢量、无损缩放、可被 CSS 控制，适合图标与简单图形。","CSS Sprites：把小图合并到一张大图用 background-position 定位，减少 HTTP 请求（HTTP/1.1 时代价值大）；缺点：维护成本高、单图失败影响全部、无法单独懒加载、放大模糊。HTTP/2 多路复用后收益下降，图标优先用 SVG / iconfont / 内联 SVG。","base64：内联减少请求，但体积增大约 1/3、无法独立缓存、阻塞 CSS/HTML 解析、无法懒加载；只适合极小且复用度高的图片（构建工具通常 <4KB 自动内联）。"],"bullets":[],"code":[],"note":"","text":"图片格式怎么选？CSS Sprites、base64 的利弊？ JPG：有损、体积小、不支持透明，适合照片；PNG：无损、支持 alpha 透明，体积大，适合图标/需要透明；GIF：256 色、支持简单动画；WebP：同时支持有损/无损/透明/动画，体积比 JPG/PNG 小约 25~35%；AVIF 压缩率更高但编码慢、兼容性略差；SVG：矢量、无损缩放、可被 CSS 控制，适合图标与简单图形。 CSS Sprites：把小图合并到一张大图用 background-position 定位，减少 HTTP 请求（HTTP/1.1 时代价值大）；缺点：维护成本高、单图失败影响全部、无法单独懒加载、放大模糊。HTTP/2 多路复用后收益下降，图标优先用 SVG / iconfont / 内联 SVG。 base64：内联减少请求，但体积增大约 1/3、无法独立缓存、阻塞 CSS/HTML 解析、无法懒加载；只适合极小且复用度高的图片（构建工具通常 <4KB 自动内联）。"},{"id":107,"num":"Q107","tag":"基础","title":"单行/多行文本溢出省略怎么写？","answers":["注意多行方案依赖 -webkit- 前缀（现代 Chrome/Safari/Firefox 已广泛支持 line-clamp），且必须配合 flex 子项 min-width:0 才能在 Flex 布局里生效。"],"bullets":[],"code":[["/* 单行 */",".ellipsis { overflow:hidden; text-overflow:ellipsis; white-space:nowrap }","/* 多行（WebKit 内核） */",".ellipsis2 { display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden }"]],"note":"","text":"单行/多行文本溢出省略怎么写？ 注意多行方案依赖 -webkit- 前缀（现代 Chrome/Safari/Firefox 已广泛支持 line-clamp），且必须配合 flex 子项 min-width:0 才能在 Flex 布局里生效。 /* 单行 */ .ellipsis { overflow:hidden; text-overflow:ellipsis; white-space:nowrap } /* 多行（WebKit 内核） */ .ellipsis2 { display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden }"},{"id":108,"num":"Q108","tag":"概念","title":"响应式设计、媒体查询、容器查询与 CSS 新特性？","answers":["响应式：一套代码适配多端，核心是流体网格（%/fr/vw）、弹性图片（max-width:100%）、媒体查询断点（@media (min-width: 768px)）与移动优先。","媒体查询基于「视口/设备」尺寸，容器查询 @container 基于「父容器」尺寸，组件级复用更合理：先给父 `container-type: inline-size`，再 `@container (min-width: 400px) { ... }`。","其它高频新特性：:has()（父选择器 / 「根据子元素选父元素」）、:is()/:where()（选择器列表简化、权重差异）、@layer（层叠层，控制优先级）、subgrid、color-mix()、CSS 变量 --var + var()、逻辑属性 margin-inline/padding-block、aspect-ratio、gap、scroll-snap、backdrop-filter。"],"bullets":[],"code":[],"note":"","text":"响应式设计、媒体查询、容器查询与 CSS 新特性？ 响应式：一套代码适配多端，核心是流体网格（%/fr/vw）、弹性图片（max-width:100%）、媒体查询断点（@media (min-width: 768px)）与移动优先。 媒体查询基于「视口/设备」尺寸，容器查询 @container 基于「父容器」尺寸，组件级复用更合理：先给父 `container-type: inline-size`，再 `@container (min-width: 400px) { ... }`。 其它高频新特性：:has()（父选择器 / 「根据子元素选父元素」）、:is()/:where()（选择器列表简化、权重差异）、@layer（层叠层，控制优先级）、subgrid、color-mix()、CSS 变量 --var + var()、逻辑属性 margin-inline/padding-block、aspect-ratio、gap、scroll-snap、backdrop-filter。"}]}]},{"id":"day4","day":4,"title":"第 4 天｜浏览器、网络协议与前端安全","short":"浏览器、网络协议与前端安全","note":"目标：把「输入 URL 发生了什么」这条主线拉通，它能一题带出 DNS、TCP、TLS、HTTP、缓存、渲染、跨域、安全十余个考点，是最值得准备的一条「串题」。","sections":[{"id":"day4-s1","day":4,"title":"4.1 从输入 URL 到页面显示（超级串题）","note":"","questions":[{"id":109,"num":"Q109","tag":"必考","title":"在浏览器地址栏输入 URL 并回车，到页面显示，发生了什么？","answers":["① 解析 URL：补全协议（https）、分析域名/端口/路径/参数/片段标识符（# 后的片段不会发给服务器）。","② DNS 解析：依次查浏览器缓存 → 系统缓存 / hosts → 本地 DNS 服务器（递归）→ 根域 → 顶级域 → 权威域名服务器，拿到 IP；期间可用 DNS 预取（dns-prefetch）与 CDN 调度。","③ 建立连接：TCP 三次握手（SYN → SYN+ACK → ACK），若是 HTTPS 还要进行 TLS 握手协商对称密钥；HTTP/3 则用 QUIC over UDP，把传输与加密握手合并，0/1-RTT 建连。","④ 发送请求：构造请求行、请求头（含 Cookie、UA、Accept、缓存相关字段）、请求体；强缓存命中则直接返回本地副本，跳过网络。","⑤ 服务端处理：负载均衡 / 反向代理 / 网关 → 应用服务 → 可能命中 CDN 边缘缓存或服务端缓存 → 返回响应（状态码、响应头、响应体）。","⑥ 浏览器接收：若 301/302 则重新发起请求；若 304 则用本地缓存；解析响应体并按第 3 天讲的渲染流水线构建 DOM/CSSOM/Render Tree → Layout → Paint → Composite。","⑦ 加载子资源：解析到 img/script/link 等继续发起请求， DOMContentLoaded 在 HTML 解析完成后触发，load 在所有资源加载完成后触发。","⑧ 连接复用：HTTP/1.1 keep-alive 或 HTTP/2 多路复用保持连接；断开时 TCP 四次挥手。"],"bullets":[],"code":[],"note":"高分答法：不要平铺直叙，主动分「网络层 / 协议层 / 浏览器渲染层」三段，并在每段抛出可量化优化点（preconnect、CDN、缓存策略、关键渲染路径），最后补一句 Core Web Vitals 指标验证。","text":"在浏览器地址栏输入 URL 并回车，到页面显示，发生了什么？ ① 解析 URL：补全协议（https）、分析域名/端口/路径/参数/片段标识符（# 后的片段不会发给服务器）。 ② DNS 解析：依次查浏览器缓存 → 系统缓存 / hosts → 本地 DNS 服务器（递归）→ 根域 → 顶级域 → 权威域名服务器，拿到 IP；期间可用 DNS 预取（dns-prefetch）与 CDN 调度。 ③ 建立连接：TCP 三次握手（SYN → SYN+ACK → ACK），若是 HTTPS 还要进行 TLS 握手协商对称密钥；HTTP/3 则用 QUIC over UDP，把传输与加密握手合并，0/1-RTT 建连。 ④ 发送请求：构造请求行、请求头（含 Cookie、UA、Accept、缓存相关字段）、请求体；强缓存命中则直接返回本地副本，跳过网络。 ⑤ 服务端处理：负载均衡 / 反向代理 / 网关 → 应用服务 → 可能命中 CDN 边缘缓存或服务端缓存 → 返回响应（状态码、响应头、响应体）。 ⑥ 浏览器接收：若 301/302 则重新发起请求；若 304 则用本地缓存；解析响应体并按第 3 天讲的渲染流水线构建 DOM/CSSOM/Render Tree → Layout → Paint → Composite。 ⑦ 加载子资源：解析到 img/script/link 等继续发起请求， DOMContentLoaded 在 HTML 解析完成后触发，load 在所有资源加载完成后触发。 ⑧ 连接复用：HTTP/1.1 keep-alive 或 HTTP/2 多路复用保持连接；断开时 TCP 四次挥手。 高分答法：不要平铺直叙，主动分「网络层 / 协议层 / 浏览器渲染层」三段，并在每段抛出可量化优化点（preconnect、CDN、缓存策略、关键渲染路径），最后补一句 Core Web Vitals 指标验证。"},{"id":110,"num":"Q110","tag":"原理","title":"DNS 为什么用 UDP？DNS 查询过程？","answers":["DNS 主要用 UDP 53 端口：单次查询/响应数据量小（<512 字节），UDP 无需握手、开销低、延迟小，服务器能支撑极高并发；若响应超过 512 字节（含 DNSSEC、大量记录）或做区域传送（AXFR），则改用 TCP。","查询过程：先查各级缓存（浏览器、操作系统、hosts、本地 DNS 缓存），未命中则本地 DNS 服务器递归查询：根服务器返回 TLD 地址 → TLD 服务器返回权威 DNS 地址 → 权威 DNS 返回最终 IP，沿途结果按 TTL 缓存。","相关优化：DNS 预解析 <link rel=\"dns-prefetch\">、preconnect 提前完成 DNS+TCP+TLS、CDN 通过 CNAME 与智能调度把用户导向最近边缘节点。"],"bullets":[],"code":[],"note":"","text":"DNS 为什么用 UDP？DNS 查询过程？ DNS 主要用 UDP 53 端口：单次查询/响应数据量小（<512 字节），UDP 无需握手、开销低、延迟小，服务器能支撑极高并发；若响应超过 512 字节（含 DNSSEC、大量记录）或做区域传送（AXFR），则改用 TCP。 查询过程：先查各级缓存（浏览器、操作系统、hosts、本地 DNS 缓存），未命中则本地 DNS 服务器递归查询：根服务器返回 TLD 地址 → TLD 服务器返回权威 DNS 地址 → 权威 DNS 返回最终 IP，沿途结果按 TTL 缓存。 相关优化：DNS 预解析 <link rel=\"dns-prefetch\">、preconnect 提前完成 DNS+TCP+TLS、CDN 通过 CNAME 与智能调度把用户导向最近边缘节点。"},{"id":111,"num":"Q111","tag":"原理","title":"TCP 三次握手与四次挥手，为什么是三次/四次？","answers":["三次握手：客户端 SYN(seq=x) → 服务端 SYN+ACK(seq=y, ack=x+1) → 客户端 ACK(ack=y+1)。三次是为了双方都确认「自己的发送与接收能力、对方的发送与接收能力」正常，并同步初始序列号；两次无法确认客户端的接收能力，也防止已失效的 SYN 突然到达造成错误连接。","四次挥手：主动方 FIN → 被动方 ACK（此时被动方可能还有数据要发，进入 CLOSE_WAIT）→ 被动方 FIN → 主动方 ACK（进入 TIME_WAIT，等待 2MSL 才关闭）。多出来的一次是因为 TCP 是全双工，被动方收到 FIN 后不能立刻把「自己的 FIN」合并发出，要先 ACK 再等数据发完。","TIME_WAIT 等 2MSL 的原因：① 保证最后一个 ACK 能到达对端（若丢失，对端会重发 FIN）；② 让本次连接的残余报文在网络中消散，避免污染新连接。"],"bullets":[],"code":[],"note":"","text":"TCP 三次握手与四次挥手，为什么是三次/四次？ 三次握手：客户端 SYN(seq=x) → 服务端 SYN+ACK(seq=y, ack=x+1) → 客户端 ACK(ack=y+1)。三次是为了双方都确认「自己的发送与接收能力、对方的发送与接收能力」正常，并同步初始序列号；两次无法确认客户端的接收能力，也防止已失效的 SYN 突然到达造成错误连接。 四次挥手：主动方 FIN → 被动方 ACK（此时被动方可能还有数据要发，进入 CLOSE_WAIT）→ 被动方 FIN → 主动方 ACK（进入 TIME_WAIT，等待 2MSL 才关闭）。多出来的一次是因为 TCP 是全双工，被动方收到 FIN 后不能立刻把「自己的 FIN」合并发出，要先 ACK 再等数据发完。 TIME_WAIT 等 2MSL 的原因：① 保证最后一个 ACK 能到达对端（若丢失，对端会重发 FIN）；② 让本次连接的残余报文在网络中消散，避免污染新连接。"},{"id":112,"num":"Q112","tag":"对比","title":"TCP 与 UDP 的区别？","answers":["TCP：面向连接、可靠（确认重传、序号、流量控制、拥塞控制）、有序、字节流、头部 20 字节起、有队头阻塞，适合 HTTP/1.1、文件传输、邮件。","UDP：无连接、不保证可靠与顺序、无拥塞控制、面向报文、头部 8 字节、低延迟，适合 DNS、视频通话、直播、QUIC/HTTP3、实时游戏。","加分：HTTP/2 虽用多路复用解决了「应用层队头阻塞」，但底层仍是单条 TCP，丢包时仍会触发 TCP 层队头阻塞；HTTP/3 基于 QUIC（UDP 上实现可靠传输 + TLS 1.3），每个流独立，才彻底解决。"],"bullets":[],"code":[],"note":"","text":"TCP 与 UDP 的区别？ TCP：面向连接、可靠（确认重传、序号、流量控制、拥塞控制）、有序、字节流、头部 20 字节起、有队头阻塞，适合 HTTP/1.1、文件传输、邮件。 UDP：无连接、不保证可靠与顺序、无拥塞控制、面向报文、头部 8 字节、低延迟，适合 DNS、视频通话、直播、QUIC/HTTP3、实时游戏。 加分：HTTP/2 虽用多路复用解决了「应用层队头阻塞」，但底层仍是单条 TCP，丢包时仍会触发 TCP 层队头阻塞；HTTP/3 基于 QUIC（UDP 上实现可靠传输 + TLS 1.3），每个流独立，才彻底解决。"},{"id":113,"num":"Q113","tag":"原理","title":"HTTPS 的加密过程？对称加密与非对称加密如何配合？","answers":["HTTP 明文传输，存在窃听、篡改、冒充三大风险；HTTPS = HTTP + TLS（SSL 是前身），提供加密、身份认证、完整性校验。","流程（TLS 1.2 经典）：① 客户端 ClientHello（支持的版本、加密套件、随机数 A）；② 服务端 ServerHello（选定套件、随机数 B）+ 数字证书（含公钥、域名、CA 签名）；③ 客户端验证证书链（CA 公信、域名匹配、有效期、是否吊销 OCSP/CRL）；④ 客户端生成随机数 C（pre-master），用服务端公钥加密发送；⑤ 双方用 A+B+C 通过 PRF 生成相同的会话密钥（对称密钥）；⑥ 之后用对称加密通信，用 MAC/HMAC 保证完整性。","为什么用三个随机数：让密钥不依赖单方的随机性，防止某一方伪随机数被预测，同时每次会话密钥不同（前向安全的一部分）；更现代的做法是 ECDHE 密钥交换，客户端与服务端各生成临时椭圆曲线公私钥，直接协商出会话密钥，天然具备前向安全（即使私钥泄露，历史会话也无法解密），TLS 1.3 已只保留这种 DH 类套件并把握手压缩到 1-RTT（会话恢复可 0-RTT）。","为什么不全程非对称：非对称加密计算慢、且有长度限制，只适合在握手阶段做身份认证与密钥交换；对称加密（AES-GCM/ChaCha20）适合高速加密大量数据。"],"bullets":[],"code":[],"note":"追问：中间人攻击为什么被证书挡住？因为证书由受信任 CA 用私钥签名，浏览器内置 CA 公钥可验签，攻击者无法伪造被信任的域名证书；除非用户安装了恶意根证书或遭遇证书误签发。","text":"HTTPS 的加密过程？对称加密与非对称加密如何配合？ HTTP 明文传输，存在窃听、篡改、冒充三大风险；HTTPS = HTTP + TLS（SSL 是前身），提供加密、身份认证、完整性校验。 流程（TLS 1.2 经典）：① 客户端 ClientHello（支持的版本、加密套件、随机数 A）；② 服务端 ServerHello（选定套件、随机数 B）+ 数字证书（含公钥、域名、CA 签名）；③ 客户端验证证书链（CA 公信、域名匹配、有效期、是否吊销 OCSP/CRL）；④ 客户端生成随机数 C（pre-master），用服务端公钥加密发送；⑤ 双方用 A+B+C 通过 PRF 生成相同的会话密钥（对称密钥）；⑥ 之后用对称加密通信，用 MAC/HMAC 保证完整性。 为什么用三个随机数：让密钥不依赖单方的随机性，防止某一方伪随机数被预测，同时每次会话密钥不同（前向安全的一部分）；更现代的做法是 ECDHE 密钥交换，客户端与服务端各生成临时椭圆曲线公私钥，直接协商出会话密钥，天然具备前向安全（即使私钥泄露，历史会话也无法解密），TLS 1.3 已只保留这种 DH 类套件并把握手压缩到 1-RTT（会话恢复可 0-RTT）。 为什么不全程非对称：非对称加密计算慢、且有长度限制，只适合在握手阶段做身份认证与密钥交换；对称加密（AES-GCM/ChaCha20）适合高速加密大量数据。 追问：中间人攻击为什么被证书挡住？因为证书由受信任 CA 用私钥签名，浏览器内置 CA 公钥可验签，攻击者无法伪造被信任的域名证书；除非用户安装了恶意根证书或遭遇证书误签发。"},{"id":114,"num":"Q114","tag":"场景","title":"CDN 的作用与原理？","answers":["CDN 把静态资源缓存到全球边缘节点，用户请求被 DNS 调度到就近节点，减少 RTT、降低源站压力、提升可用性与抗攻击能力。","关键机制：CNAME 解析到 CDN 域名 + 智能调度（基于地理位置、运营商、节点负载、健康检查）；缓存策略（Cache-Control / s-maxage / 边缘规则）；回源（未命中或过期时回源站拉取）；缓存刷新（主动 purge / 版本号文件名 hash 是更稳妥的做法）；动静分离与边缘计算。","注意：Cookie 隔离，静态资源用独立无 Cookie 域名，避免每个请求都带上一大坨 Cookie 浪费带宽。"],"bullets":[],"code":[],"note":"","text":"CDN 的作用与原理？ CDN 把静态资源缓存到全球边缘节点，用户请求被 DNS 调度到就近节点，减少 RTT、降低源站压力、提升可用性与抗攻击能力。 关键机制：CNAME 解析到 CDN 域名 + 智能调度（基于地理位置、运营商、节点负载、健康检查）；缓存策略（Cache-Control / s-maxage / 边缘规则）；回源（未命中或过期时回源站拉取）；缓存刷新（主动 purge / 版本号文件名 hash 是更稳妥的做法）；动静分离与边缘计算。 注意：Cookie 隔离，静态资源用独立无 Cookie 域名，避免每个请求都带上一大坨 Cookie 浪费带宽。"}]},{"id":"day4-s2","day":4,"title":"4.2 HTTP 协议与缓存","note":"","questions":[{"id":115,"num":"Q115","tag":"对比","title":"GET 与 POST 的区别？（别只背表面的 4 条）","answers":["语义（RFC 最重要的一条）：GET 是安全且幂等的「获取资源」，POST 是「提交/创建资源」，非幂等、不安全。","工程差异：GET 参数在 URL（长度受浏览器/服务器限制，通常 2KB~8KB 不等，不是协议限制）、会被浏览器缓存与保留在历史记录/日志中、只支持 ASCII 且会被 URL 编码、可收藏；POST 参数在 body（支持多种编码，大小由服务端配置限制）、默认不缓存、刷新会提示重新提交、更适合传敏感或大量数据。","常见误区纠正：GET 也可以有 body（规范没禁止，只是多数实现会忽略）；POST 也不比 GET「更安全」（都不加密，需 HTTPS）；GET 传参长度限制来自浏览器/服务器实现而非 HTTP 协议；GET 请求并非一定只发一个 TCP 包。","其它方法：PUT（整体替换，幂等）、PATCH（部分更新）、DELETE（幂等）、HEAD（只取响应头）、OPTIONS（预检 / 查询支持的方法）、TRACE、CONNECT。"],"bullets":[],"code":[],"note":"","text":"GET 与 POST 的区别？（别只背表面的 4 条） 语义（RFC 最重要的一条）：GET 是安全且幂等的「获取资源」，POST 是「提交/创建资源」，非幂等、不安全。 工程差异：GET 参数在 URL（长度受浏览器/服务器限制，通常 2KB~8KB 不等，不是协议限制）、会被浏览器缓存与保留在历史记录/日志中、只支持 ASCII 且会被 URL 编码、可收藏；POST 参数在 body（支持多种编码，大小由服务端配置限制）、默认不缓存、刷新会提示重新提交、更适合传敏感或大量数据。 常见误区纠正：GET 也可以有 body（规范没禁止，只是多数实现会忽略）；POST 也不比 GET「更安全」（都不加密，需 HTTPS）；GET 传参长度限制来自浏览器/服务器实现而非 HTTP 协议；GET 请求并非一定只发一个 TCP 包。 其它方法：PUT（整体替换，幂等）、PATCH（部分更新）、DELETE（幂等）、HEAD（只取响应头）、OPTIONS（预检 / 查询支持的方法）、TRACE、CONNECT。"},{"id":116,"num":"Q116","tag":"基础","title":"常见 HTTP 状态码？","answers":["1xx 信息：100 Continue（大请求体前先问服务端是否接受）、101 Switching Protocols（WebSocket 升级）、103 Early Hints。","2xx 成功：200 OK、201 Created、204 No Content（无响应体，常用于 DELETE / OPTIONS 预检）、206 Partial Content（断点续传 / Range 分片）。","3xx 重定向：301 永久（可被浏览器/搜索引擎缓存，换域名要谨慎）、302 临时、303 See Other、304 Not Modified（协商缓存命中）、307/308 保留方法与请求体的重定向（307 临时 / 308 永久，比 302/301 更严格）。","4xx 客户端错误：400 参数错误、401 未认证（需登录）、403 已认证但无权限、404 不存在、405 方法不允许、409 冲突、413 请求体过大、415 不支持的媒体类型、429 请求过多（限流）。","5xx 服务端错误：500 内部错误、502 网关收到上游无效响应、503 服务不可用（过载/维护）、504 网关超时。"],"bullets":[],"code":[],"note":"","text":"常见 HTTP 状态码？ 1xx 信息：100 Continue（大请求体前先问服务端是否接受）、101 Switching Protocols（WebSocket 升级）、103 Early Hints。 2xx 成功：200 OK、201 Created、204 No Content（无响应体，常用于 DELETE / OPTIONS 预检）、206 Partial Content（断点续传 / Range 分片）。 3xx 重定向：301 永久（可被浏览器/搜索引擎缓存，换域名要谨慎）、302 临时、303 See Other、304 Not Modified（协商缓存命中）、307/308 保留方法与请求体的重定向（307 临时 / 308 永久，比 302/301 更严格）。 4xx 客户端错误：400 参数错误、401 未认证（需登录）、403 已认证但无权限、404 不存在、405 方法不允许、409 冲突、413 请求体过大、415 不支持的媒体类型、429 请求过多（限流）。 5xx 服务端错误：500 内部错误、502 网关收到上游无效响应、503 服务不可用（过载/维护）、504 网关超时。"},{"id":117,"num":"Q117","tag":"必考","title":"HTTP/1.0、1.1、2.0、3.0 的演进？","answers":["HTTP/1.0：默认短连接，每个请求一次 TCP 握手；不支持 Host 头（无法虚拟主机）；缓存用 Expires / Last-Modified。","HTTP/1.1：默认长连接 keep-alive（Connection: keep-alive）、管线化 pipelining（因队头阻塞基本废弃）、Host 头必需、支持分块传输 chunked、断点续传 Range、新增 Cache-Control / ETag、OPTIONS、更多状态码；但同一域名浏览器仍有 6~8 个并发连接限制，且存在队头阻塞。","HTTP/2：二进制分帧（不再是文本）、多路复用（一个连接上并行多个 Stream，解决应用层队头阻塞）、HPACK 头部压缩（静态表 + 动态表 + Huffman）、服务端推送 Server Push（实践中效果不佳，已被多数浏览器弃用）、流优先级、要求 HTTPS（事实标准）。遗留问题：TCP 层丢包队头阻塞、握手延迟。","HTTP/3：基于 QUIC（UDP 之上实现可靠传输、拥塞控制与内置 TLS 1.3），0/1-RTT 建连、连接迁移（用 Connection ID，切 Wi-Fi/4G 不断线）、每个流独立无队头阻塞；缺点：UDP 在部分网络被限速/阻断、服务端与中间件改造成本。"],"bullets":[],"code":[],"note":"高频追问：HTTP/2 还需要合并资源（雪碧图、域名分片、合并 JS）吗？不需要，反而有害——域名分片会破坏多路复用，合并大文件会降低缓存命中率与粒度；正确做法是按路由细粒度分包 + 长缓存 + hash 文件名。","text":"HTTP/1.0、1.1、2.0、3.0 的演进？ HTTP/1.0：默认短连接，每个请求一次 TCP 握手；不支持 Host 头（无法虚拟主机）；缓存用 Expires / Last-Modified。 HTTP/1.1：默认长连接 keep-alive（Connection: keep-alive）、管线化 pipelining（因队头阻塞基本废弃）、Host 头必需、支持分块传输 chunked、断点续传 Range、新增 Cache-Control / ETag、OPTIONS、更多状态码；但同一域名浏览器仍有 6~8 个并发连接限制，且存在队头阻塞。 HTTP/2：二进制分帧（不再是文本）、多路复用（一个连接上并行多个 Stream，解决应用层队头阻塞）、HPACK 头部压缩（静态表 + 动态表 + Huffman）、服务端推送 Server Push（实践中效果不佳，已被多数浏览器弃用）、流优先级、要求 HTTPS（事实标准）。遗留问题：TCP 层丢包队头阻塞、握手延迟。 HTTP/3：基于 QUIC（UDP 之上实现可靠传输、拥塞控制与内置 TLS 1.3），0/1-RTT 建连、连接迁移（用 Connection ID，切 Wi-Fi/4G 不断线）、每个流独立无队头阻塞；缺点：UDP 在部分网络被限速/阻断、服务端与中间件改造成本。 高频追问：HTTP/2 还需要合并资源（雪碧图、域名分片、合并 JS）吗？不需要，反而有害——域名分片会破坏多路复用，合并大文件会降低缓存命中率与粒度；正确做法是按路由细粒度分包 + 长缓存 + hash 文件名。"},{"id":118,"num":"Q118","tag":"必考","title":"强缓存与协商缓存的完整流程？","answers":["强缓存：浏览器直接用本地副本，不发网络请求，状态码显示 200 (from disk cache / memory cache)。字段：Cache-Control（HTTP/1.1，优先级高，max-age=秒数、no-cache、no-store、private、public、s-maxage、immutable）、Expires（HTTP/1.0，绝对时间，依赖客户端时钟，已淘汰）。","协商缓存：强缓存失效后，浏览器带条件字段发请求，服务端判断资源未变则返回 304 Not Modified（无响应体），浏览器复用本地副本；变了返回 200 + 新资源。","字段配对：Last-Modified（服务端响应，秒级精度）↔ If-Modified-Since（请求）；ETag（资源唯一标识，精度更高、可处理秒级内多次修改与内容不变的场景）↔ If-None-Match（请求）。ETag 优先级高于 Last-Modified。","Cache-Control: no-cache 不是「不缓存」，而是「每次都必须向服务端协商验证」；no-store 才是真正不缓存（用于含敏感信息的响应）。","最佳实践：带内容 hash 的静态资源用 `Cache-Control: max-age=31536000, immutable`；HTML 入口用 `no-cache` 或短 max-age，保证发版后能拿到新的资源引用；API 响应按业务设置 private/no-store。"],"bullets":[],"code":[],"note":"","text":"强缓存与协商缓存的完整流程？ 强缓存：浏览器直接用本地副本，不发网络请求，状态码显示 200 (from disk cache / memory cache)。字段：Cache-Control（HTTP/1.1，优先级高，max-age=秒数、no-cache、no-store、private、public、s-maxage、immutable）、Expires（HTTP/1.0，绝对时间，依赖客户端时钟，已淘汰）。 协商缓存：强缓存失效后，浏览器带条件字段发请求，服务端判断资源未变则返回 304 Not Modified（无响应体），浏览器复用本地副本；变了返回 200 + 新资源。 字段配对：Last-Modified（服务端响应，秒级精度）↔ If-Modified-Since（请求）；ETag（资源唯一标识，精度更高、可处理秒级内多次修改与内容不变的场景）↔ If-None-Match（请求）。ETag 优先级高于 Last-Modified。 Cache-Control: no-cache 不是「不缓存」，而是「每次都必须向服务端协商验证」；no-store 才是真正不缓存（用于含敏感信息的响应）。 最佳实践：带内容 hash 的静态资源用 `Cache-Control: max-age=31536000, immutable`；HTML 入口用 `no-cache` 或短 max-age，保证发版后能拿到新的资源引用；API 响应按业务设置 private/no-store。"},{"id":119,"num":"Q119","tag":"场景","title":"用户刷新 / 强制刷新时缓存行为如何？","answers":["正常地址栏回车：强缓存优先，命中直接用；F5 刷新：请求带上 Cache-Control: max-age=0（或 no-cache 语义），强缓存失效但协商缓存仍可能命中 304；Ctrl+F5 强制刷新：带 Cache-Control: no-cache 且不带 If-None-Match / If-Modified-Since（或带 Pragma: no-cache），绕过全部缓存重新拉取。","开发调试用 DevTools 勾选 Disable cache；线上排查优先看 Response Headers 的 Cache-Control、Age、ETag 与 Size 列是否显示 from cache。"],"bullets":[],"code":[],"note":"","text":"用户刷新 / 强制刷新时缓存行为如何？ 正常地址栏回车：强缓存优先，命中直接用；F5 刷新：请求带上 Cache-Control: max-age=0（或 no-cache 语义），强缓存失效但协商缓存仍可能命中 304；Ctrl+F5 强制刷新：带 Cache-Control: no-cache 且不带 If-None-Match / If-Modified-Since（或带 Pragma: no-cache），绕过全部缓存重新拉取。 开发调试用 DevTools 勾选 Disable cache；线上排查优先看 Response Headers 的 Cache-Control、Age、ETag 与 Size 列是否显示 from cache。"},{"id":120,"num":"Q120","tag":"必考","title":"什么是同源策略？跨域有哪些解决方案？","answers":["同源 = 协议 + 域名 + 端口三者完全相同。同源策略限制：① XMLHttpRequest/fetch 读取跨域响应；② Cookie / localStorage / IndexedDB 读取；③ DOM（iframe 跨源）访问。注意 `<script>/<img>/<link>/<video>` 等标签加载跨域资源是允许的（只是 JS 无法读取内容，这正是 JSONP 的基础）。","① CORS（标准方案）：服务端返回 Access-Control-Allow-Origin（具体源或 *，带凭证时不能为 *）、Allow-Methods、Allow-Headers、Allow-Credentials: true、Max-Age、Expose-Headers。简单请求直接发；非简单请求（自定义头、application/json 等）先发 OPTIONS 预检。","② 开发环境代理：Webpack devServer.proxy / Vite server.proxy / Nginx 反向代理，让浏览器请求同源，由服务端转发（同源策略只约束浏览器）。","③ JSONP：利用 script 标签不受限，回调名传参、服务端返回 `callback(data)`；只支持 GET、安全性差（需校验回调名防 XSS）、无法捕获 HTTP 错误，已基本淘汰。","④ Nginx 反向代理 / 网关统一配置 CORS 是最常见的生产做法。","⑤ 其它：postMessage + iframe（跨窗口通信）、window.name / document.domain（历史方案，document.domain 已被现代浏览器弃用）、WebSocket（不受同源策略限制，但服务端可校验 Origin）、Chrome 扩展 / --disable-web-security 仅本地调试。"],"bullets":[],"code":[],"note":"","text":"什么是同源策略？跨域有哪些解决方案？ 同源 = 协议 + 域名 + 端口三者完全相同。同源策略限制：① XMLHttpRequest/fetch 读取跨域响应；② Cookie / localStorage / IndexedDB 读取；③ DOM（iframe 跨源）访问。注意 `<script>/<img>/<link>/<video>` 等标签加载跨域资源是允许的（只是 JS 无法读取内容，这正是 JSONP 的基础）。 ① CORS（标准方案）：服务端返回 Access-Control-Allow-Origin（具体源或 *，带凭证时不能为 *）、Allow-Methods、Allow-Headers、Allow-Credentials: true、Max-Age、Expose-Headers。简单请求直接发；非简单请求（自定义头、application/json 等）先发 OPTIONS 预检。 ② 开发环境代理：Webpack devServer.proxy / Vite server.proxy / Nginx 反向代理，让浏览器请求同源，由服务端转发（同源策略只约束浏览器）。 ③ JSONP：利用 script 标签不受限，回调名传参、服务端返回 `callback(data)`；只支持 GET、安全性差（需校验回调名防 XSS）、无法捕获 HTTP 错误，已基本淘汰。 ④ Nginx 反向代理 / 网关统一配置 CORS 是最常见的生产做法。 ⑤ 其它：postMessage + iframe（跨窗口通信）、window.name / document.domain（历史方案，document.domain 已被现代浏览器弃用）、WebSocket（不受同源策略限制，但服务端可校验 Origin）、Chrome 扩展 / --disable-web-security 仅本地调试。"},{"id":121,"num":"Q121","tag":"原理","title":"CORS 简单请求与预检请求的判定？","answers":["同时满足才是简单请求：方法是 GET/HEAD/POST 之一；头字段仅包含 Accept、Accept-Language、Content-Language、Content-Type（且值仅限 application/x-www-form-urlencoded、multipart/form-data、text/plain）、DPR/Downlink/Save-Data/Viewport-Width/Width 等安全头；请求中没有自定义头、没有使用 ReadableStream、XMLHttpRequest 未注册 upload 事件之外的高级监听器。","预检 OPTIONS 带 Origin、Access-Control-Request-Method、Access-Control-Request-Headers；服务端响应 Access-Control-Allow-Origin / Methods / Headers / Max-Age（缓存预检结果，减少往返），通过后才发真实请求。","带 Cookie 需三处配合：前端 credentials: 'include'（fetch）/ withCredentials: true（XHR），服务端 Allow-Credentials: true，且 Allow-Origin 必须是具体源（不能 *），Cookie 的 SameSite 属性也要允许跨站携带。"],"bullets":[],"code":[],"note":"","text":"CORS 简单请求与预检请求的判定？ 同时满足才是简单请求：方法是 GET/HEAD/POST 之一；头字段仅包含 Accept、Accept-Language、Content-Language、Content-Type（且值仅限 application/x-www-form-urlencoded、multipart/form-data、text/plain）、DPR/Downlink/Save-Data/Viewport-Width/Width 等安全头；请求中没有自定义头、没有使用 ReadableStream、XMLHttpRequest 未注册 upload 事件之外的高级监听器。 预检 OPTIONS 带 Origin、Access-Control-Request-Method、Access-Control-Request-Headers；服务端响应 Access-Control-Allow-Origin / Methods / Headers / Max-Age（缓存预检结果，减少往返），通过后才发真实请求。 带 Cookie 需三处配合：前端 credentials: 'include'（fetch）/ withCredentials: true（XHR），服务端 Allow-Credentials: true，且 Allow-Origin 必须是具体源（不能 *），Cookie 的 SameSite 属性也要允许跨站携带。"},{"id":122,"num":"Q122","tag":"基础","title":"常见请求/响应头与 Content-Type？","answers":["请求头：Host、User-Agent、Accept / Accept-Encoding / Accept-Language、Content-Type、Authorization（Bearer/JWT）、Cookie、Origin、Referer、If-None-Match / If-Modified-Since、Range、Cache-Control、Connection、X-Requested-With、Sec-Fetch-*。","响应头：Content-Type / Content-Length / Content-Encoding（gzip/br）、Cache-Control / ETag / Last-Modified、Set-Cookie、Access-Control-*、Location（重定向）、Content-Disposition（下载）、Strict-Transport-Security（HSTS）、Content-Security-Policy、X-Content-Type-Options、Transfer-Encoding: chunked、Vary。","常见 Content-Type：application/json、application/x-www-form-urlencoded（普通表单）、multipart/form-data（文件上传）、text/plain、text/html、application/octet-stream（二进制下载）、application/javascript、image/webp。"],"bullets":[],"code":[],"note":"加分：Vary: Accept-Encoding / Origin 决定缓存键是否区分这些头，配错会导致 CDN 缓存串内容。","text":"常见请求/响应头与 Content-Type？ 请求头：Host、User-Agent、Accept / Accept-Encoding / Accept-Language、Content-Type、Authorization（Bearer/JWT）、Cookie、Origin、Referer、If-None-Match / If-Modified-Since、Range、Cache-Control、Connection、X-Requested-With、Sec-Fetch-*。 响应头：Content-Type / Content-Length / Content-Encoding（gzip/br）、Cache-Control / ETag / Last-Modified、Set-Cookie、Access-Control-*、Location（重定向）、Content-Disposition（下载）、Strict-Transport-Security（HSTS）、Content-Security-Policy、X-Content-Type-Options、Transfer-Encoding: chunked、Vary。 常见 Content-Type：application/json、application/x-www-form-urlencoded（普通表单）、multipart/form-data（文件上传）、text/plain、text/html、application/octet-stream（二进制下载）、application/javascript、image/webp。 加分：Vary: Accept-Encoding / Origin 决定缓存键是否区分这些头，配错会导致 CDN 缓存串内容。"},{"id":123,"num":"Q123","tag":"概念","title":"Cookie 的属性有哪些？SameSite 的三个值？","answers":["属性：Name/Value、Domain（可作用域名，不能跨顶级域）、Path、Expires/Max-Age（不设则为会话 Cookie，关浏览器失效）、Size（约 4KB）、HttpOnly（禁止 JS 读取，防 XSS 窃取）、Secure（仅 HTTPS 发送）、SameSite、Priority、Partitioned（第三方 Cookie 分区，CHIPS）。","SameSite=Strict：完全禁止跨站请求携带（最严，但从外链跳回会丢登录态）；Lax（现代浏览器默认值）：允许顶级导航的 GET 等安全方法携带，禁止跨站 POST / iframe / img / fetch 携带；None：跨站也携带，但必须同时设 Secure（否则被拒绝）。","「跨站」与「跨域」不同：同站（same-site）看的是 eTLD+1（有效顶级域 + 一级域），如 a.example.com 与 b.example.com 是同站、但不同源。"],"bullets":[],"code":[],"note":"","text":"Cookie 的属性有哪些？SameSite 的三个值？ 属性：Name/Value、Domain（可作用域名，不能跨顶级域）、Path、Expires/Max-Age（不设则为会话 Cookie，关浏览器失效）、Size（约 4KB）、HttpOnly（禁止 JS 读取，防 XSS 窃取）、Secure（仅 HTTPS 发送）、SameSite、Priority、Partitioned（第三方 Cookie 分区，CHIPS）。 SameSite=Strict：完全禁止跨站请求携带（最严，但从外链跳回会丢登录态）；Lax（现代浏览器默认值）：允许顶级导航的 GET 等安全方法携带，禁止跨站 POST / iframe / img / fetch 携带；None：跨站也携带，但必须同时设 Secure（否则被拒绝）。 「跨站」与「跨域」不同：同站（same-site）看的是 eTLD+1（有效顶级域 + 一级域），如 a.example.com 与 b.example.com 是同站、但不同源。"}]},{"id":"day4-s3","day":4,"title":"4.3 前端安全","note":"","questions":[{"id":124,"num":"Q124","tag":"必考","title":"什么是 XSS？有哪些类型？如何防御？","answers":["XSS（跨站脚本）：攻击者把恶意脚本注入到页面中被执行，可窃取 Cookie/token、篡改页面、发起钓鱼、做蠕虫传播。","类型：① 存储型（恶意代码存进数据库，如评论区，所有访问者中招，危害最大）；② 反射型（恶意代码在 URL 参数里，服务端拼进 HTML 立即返回，需诱导点击）；③ DOM 型（纯前端 JS 把不可信数据写入 innerHTML/eval/document.write/location，不经过服务端）；④ 突变型（mXSS，浏览器解析修正导致转义被绕过）。","防御：① 输出编码 / 转义（按上下文区分 HTML、属性、JS、URL、CSS 编码），优先用 textContent 而非 innerHTML；② 框架默认转义（React/Vue 的 {{ }}），警惕 v-html / dangerouslySetInnerHTML；③ CSP（Content-Security-Policy）限制可执行脚本来源，禁止 inline-script / eval，配合 nonce/hash；④ Cookie 设 HttpOnly + Secure + SameSite，让 XSS 拿不到会话凭证；⑤ 输入校验与白名单富文本过滤（DOMPurify）；⑥ 避免把不可信数据拼进 eval / setTimeout 字符串 / javascript: 伪协议 / innerHTML / JSONP 回调名；⑦ Trusted Types（Chrome）从 API 层面强制安全 sink。"],"bullets":[],"code":[],"note":"追问：CSP 为什么能防 XSS？它通过 script-src 'self' 等指令限制脚本只能从可信源加载，且默认禁止内联脚本与 eval，即使攻击者注入了 <script> 标签也无法执行；但注意 JSONP 回调、unsafe-inline、宽松的 CDN 白名单都可能被绕过。","text":"什么是 XSS？有哪些类型？如何防御？ XSS（跨站脚本）：攻击者把恶意脚本注入到页面中被执行，可窃取 Cookie/token、篡改页面、发起钓鱼、做蠕虫传播。 类型：① 存储型（恶意代码存进数据库，如评论区，所有访问者中招，危害最大）；② 反射型（恶意代码在 URL 参数里，服务端拼进 HTML 立即返回，需诱导点击）；③ DOM 型（纯前端 JS 把不可信数据写入 innerHTML/eval/document.write/location，不经过服务端）；④ 突变型（mXSS，浏览器解析修正导致转义被绕过）。 防御：① 输出编码 / 转义（按上下文区分 HTML、属性、JS、URL、CSS 编码），优先用 textContent 而非 innerHTML；② 框架默认转义（React/Vue 的 {{ }}），警惕 v-html / dangerouslySetInnerHTML；③ CSP（Content-Security-Policy）限制可执行脚本来源，禁止 inline-script / eval，配合 nonce/hash；④ Cookie 设 HttpOnly + Secure + SameSite，让 XSS 拿不到会话凭证；⑤ 输入校验与白名单富文本过滤（DOMPurify）；⑥ 避免把不可信数据拼进 eval / setTimeout 字符串 / javascript: 伪协议 / innerHTML / JSONP 回调名；⑦ Trusted Types（Chrome）从 API 层面强制安全 sink。 追问：CSP 为什么能防 XSS？它通过 script-src 'self' 等指令限制脚本只能从可信源加载，且默认禁止内联脚本与 eval，即使攻击者注入了 <script> 标签也无法执行；但注意 JSONP 回调、unsafe-inline、宽松的 CDN 白名单都可能被绕过。"},{"id":125,"num":"Q125","tag":"必考","title":"什么是 CSRF？如何防御？和 XSS 有什么区别？","answers":["CSRF（跨站请求伪造）：用户已登录 A 站，攻击者诱导其访问 B 站，B 站发出对 A 站的请求（img/form/fetch），浏览器会自动带上 A 站的 Cookie，服务端误认为是用户本人操作。","防御：① CSRF Token（服务端下发随机 token，请求带在 body/自定义头里，攻击者拿不到同源 token；注意 token 不要放 Cookie）；② SameSite=Lax/Strict Cookie（现代浏览器默认值已能挡住大部分跨站 POST）；③ 校验 Origin / Referer 白名单；④ 关键操作二次验证（短信/密码/验证码）；⑤ 对状态变更接口统一用 POST + 自定义头（触发 CORS 预检，跨域无法带自定义头通过）；⑥ 双重 Cookie 校验（把 token 同时放 Cookie 和请求参数，服务端比对，注意子域可被注入 Cookie 的风险）。","区别：XSS 是「注入并执行脚本」，攻击者能在受害站点内做任何事，拿到凭证；CSRF 是「借用户的凭证发请求」，攻击者拿不到 Cookie 内容也读不到响应，只能「冒用身份做事」。XSS 可绕过大部分 CSRF 防御（因为能读页面里的 token），所以防 XSS 是前提。"],"bullets":[],"code":[],"note":"","text":"什么是 CSRF？如何防御？和 XSS 有什么区别？ CSRF（跨站请求伪造）：用户已登录 A 站，攻击者诱导其访问 B 站，B 站发出对 A 站的请求（img/form/fetch），浏览器会自动带上 A 站的 Cookie，服务端误认为是用户本人操作。 防御：① CSRF Token（服务端下发随机 token，请求带在 body/自定义头里，攻击者拿不到同源 token；注意 token 不要放 Cookie）；② SameSite=Lax/Strict Cookie（现代浏览器默认值已能挡住大部分跨站 POST）；③ 校验 Origin / Referer 白名单；④ 关键操作二次验证（短信/密码/验证码）；⑤ 对状态变更接口统一用 POST + 自定义头（触发 CORS 预检，跨域无法带自定义头通过）；⑥ 双重 Cookie 校验（把 token 同时放 Cookie 和请求参数，服务端比对，注意子域可被注入 Cookie 的风险）。 区别：XSS 是「注入并执行脚本」，攻击者能在受害站点内做任何事，拿到凭证；CSRF 是「借用户的凭证发请求」，攻击者拿不到 Cookie 内容也读不到响应，只能「冒用身份做事」。XSS 可绕过大部分 CSRF 防御（因为能读页面里的 token），所以防 XSS 是前提。"},{"id":126,"num":"Q126","tag":"概念","title":"点击劫持、SQL 注入、中间人攻击如何防？","answers":["点击劫持（Clickjacking）：用透明 iframe 覆盖在诱导按钮上，用户以为点的是 A 实际点的是 B。防御：响应头 `X-Frame-Options: DENY/SAMEORIGIN`、`CSP: frame-ancestors 'none'/'self'`（更现代），以及 JS 的 frame busting（可被 sandbox 绕过，仅兜底）。","SQL 注入：后端责任，前端只做基础校验；根本解法是参数化查询/预编译语句、ORM、最小权限、输入白名单，绝不拼接 SQL 字符串。","中间人：全站 HTTPS + HSTS（Strict-Transport-Security 强制浏览器只用 HTTPS，防止首次 HTTP 被降级）、证书校验 / 证书固定（Certificate Pinning）、公共 Wi-Fi 提示。","其它：CORS 配置过宽（Allow-Origin: * 且 Allow-Credentials 组合）、JWT 存 localStorage 被 XSS 读取、敏感信息写在 URL 被日志/Referer 泄露、第三方 SDK 供应链风险（SRI 子资源完整性 + 锁定版本）。"],"bullets":[],"code":[],"note":"","text":"点击劫持、SQL 注入、中间人攻击如何防？ 点击劫持（Clickjacking）：用透明 iframe 覆盖在诱导按钮上，用户以为点的是 A 实际点的是 B。防御：响应头 `X-Frame-Options: DENY/SAMEORIGIN`、`CSP: frame-ancestors 'none'/'self'`（更现代），以及 JS 的 frame busting（可被 sandbox 绕过，仅兜底）。 SQL 注入：后端责任，前端只做基础校验；根本解法是参数化查询/预编译语句、ORM、最小权限、输入白名单，绝不拼接 SQL 字符串。 中间人：全站 HTTPS + HSTS（Strict-Transport-Security 强制浏览器只用 HTTPS，防止首次 HTTP 被降级）、证书校验 / 证书固定（Certificate Pinning）、公共 Wi-Fi 提示。 其它：CORS 配置过宽（Allow-Origin: * 且 Allow-Credentials 组合）、JWT 存 localStorage 被 XSS 读取、敏感信息写在 URL 被日志/Referer 泄露、第三方 SDK 供应链风险（SRI 子资源完整性 + 锁定版本）。"},{"id":127,"num":"Q127","tag":"对比","title":"Cookie vs Token（JWT）做会话管理，怎么选？","answers":["Cookie-Session：服务端有状态，天然可主动失效/踢人，配合 HttpOnly + Secure + SameSite 可较好防 XSS 窃取，但存在 CSRF 风险、跨域/多端不友好、服务端需要存储与共享 session（Redis）。","JWT：无状态、自包含、适合微服务/多端/跨域，服务端不存储；但无法主动失效（需黑名单/短过期 + Refresh Token 折中）、payload 只是 Base64 编码不是加密、体积大、存 localStorage 易被 XSS 窃取、存 Cookie 又有 CSRF 问题。","实践建议：传统 Web 应用优先用「HttpOnly + SameSite=Lax 的 Session Cookie」；BFF / 移动跨端场景用 Access Token（短时，内存或 HttpOnly Cookie）+ Refresh Token（长时，HttpOnly Cookie、可轮换、可撤销）。"],"bullets":[],"code":[],"note":"高分补充：不要说「JWT 更安全」，要说 trade-off；能讲出「无状态换来的代价是不可撤销」和「存哪决定面对 XSS 还是 CSRF」才到位。","text":"Cookie vs Token（JWT）做会话管理，怎么选？ Cookie-Session：服务端有状态，天然可主动失效/踢人，配合 HttpOnly + Secure + SameSite 可较好防 XSS 窃取，但存在 CSRF 风险、跨域/多端不友好、服务端需要存储与共享 session（Redis）。 JWT：无状态、自包含、适合微服务/多端/跨域，服务端不存储；但无法主动失效（需黑名单/短过期 + Refresh Token 折中）、payload 只是 Base64 编码不是加密、体积大、存 localStorage 易被 XSS 窃取、存 Cookie 又有 CSRF 问题。 实践建议：传统 Web 应用优先用「HttpOnly + SameSite=Lax 的 Session Cookie」；BFF / 移动跨端场景用 Access Token（短时，内存或 HttpOnly Cookie）+ Refresh Token（长时，HttpOnly Cookie、可轮换、可撤销）。 高分补充：不要说「JWT 更安全」，要说 trade-off；能讲出「无状态换来的代价是不可撤销」和「存哪决定面对 XSS 还是 CSRF」才到位。"}]},{"id":"day4-s4","day":4,"title":"4.4 实时通信、性能监控与浏览器能力","note":"","questions":[{"id":128,"num":"Q128","tag":"对比","title":"短轮询、长轮询、SSE、WebSocket 的区别？","answers":["短轮询：客户端定时发请求，实现简单、浪费请求与带宽、实时性差。","长轮询（Comet）：服务端 hold 住请求直到有数据或超时，返回后客户端立刻再发；减少无效请求，但每次仍要建 HTTP 连接，服务端连接占用高。","SSE（Server-Sent Events）：基于 HTTP 的单向（服务端 → 客户端）长连接，text/event-stream，浏览器原生 EventSource 支持自动重连、Last-Event-ID 断点续传；适合通知、日志流、股价推送；只能单向、默认受同源与连接数限制（HTTP/1.1 下 6 个）、只支持文本。","WebSocket：基于 HTTP Upgrade 握手（101 Switching Protocols）后建立全双工 TCP 长连接，双向、低延迟、开销小；需自己实现心跳（ping/pong）、重连、消息去重与离线补偿；适合 IM、协同编辑、游戏、实时看板。","HTTP/2 Server Push / WebRTC / MQTT 也是可选方案，按场景取舍。"],"bullets":[],"code":[],"note":"","text":"短轮询、长轮询、SSE、WebSocket 的区别？ 短轮询：客户端定时发请求，实现简单、浪费请求与带宽、实时性差。 长轮询（Comet）：服务端 hold 住请求直到有数据或超时，返回后客户端立刻再发；减少无效请求，但每次仍要建 HTTP 连接，服务端连接占用高。 SSE（Server-Sent Events）：基于 HTTP 的单向（服务端 → 客户端）长连接，text/event-stream，浏览器原生 EventSource 支持自动重连、Last-Event-ID 断点续传；适合通知、日志流、股价推送；只能单向、默认受同源与连接数限制（HTTP/1.1 下 6 个）、只支持文本。 WebSocket：基于 HTTP Upgrade 握手（101 Switching Protocols）后建立全双工 TCP 长连接，双向、低延迟、开销小；需自己实现心跳（ping/pong）、重连、消息去重与离线补偿；适合 IM、协同编辑、游戏、实时看板。 HTTP/2 Server Push / WebRTC / MQTT 也是可选方案，按场景取舍。"},{"id":129,"num":"Q129","tag":"场景","title":"WebSocket 的心跳、重连与消息可靠性怎么设计？","answers":["心跳：客户端定时（如 30s）发 ping，服务端回 pong；连续 N 次未收到 pong 判定断连，避免「半开连接」（TCP 断线两端感知不到）。","重连：指数退避 + 随机抖动（避免服务端被同时重连打爆），设置最大重试次数；重连成功后用最后一条消息 ID / 序列号向服务端补拉离线消息。","可靠性：每条消息带唯一 msgId + 递增 seq，客户端去重；服务端做 ACK 确认与超时重发；未确认消息本地持久化；断网期间用本地队列暂存，恢复后批量补发。"],"bullets":[],"code":[],"note":"","text":"WebSocket 的心跳、重连与消息可靠性怎么设计？ 心跳：客户端定时（如 30s）发 ping，服务端回 pong；连续 N 次未收到 pong 判定断连，避免「半开连接」（TCP 断线两端感知不到）。 重连：指数退避 + 随机抖动（避免服务端被同时重连打爆），设置最大重试次数；重连成功后用最后一条消息 ID / 序列号向服务端补拉离线消息。 可靠性：每条消息带唯一 msgId + 递增 seq，客户端去重；服务端做 ACK 确认与超时重发；未确认消息本地持久化；断网期间用本地队列暂存，恢复后批量补发。"},{"id":130,"num":"Q130","tag":"原理","title":"浏览器架构：多进程与线程模型？","answers":["现代 Chrome 是多进程架构：Browser 进程（UI、地址栏、网络调度、子进程管理）、Renderer 进程（每站点/每标签页一个或多个，负责 HTML/CSS/JS 解析执行、布局绘制，运行在沙箱中）、GPU 进程（合成与栅格化）、Network Service 进程、Storage/Utility 进程、插件进程。","Renderer 内有主线程（JS 执行、DOM 构建、样式计算、布局、部分绘制）、合成线程（图层合成、滚动）、光栅化线程、Worker 线程（Web Worker 独立于主线程）。站点隔离（Site Isolation）让跨站 iframe 用独立进程，缓解 Spectre 类攻击。","意义：一个标签页崩溃不会拖垮整个浏览器、沙箱提升安全性、多进程可利用多核；代价是内存占用更高（Chrome 有进程合并策略）。"],"bullets":[],"code":[],"note":"","text":"浏览器架构：多进程与线程模型？ 现代 Chrome 是多进程架构：Browser 进程（UI、地址栏、网络调度、子进程管理）、Renderer 进程（每站点/每标签页一个或多个，负责 HTML/CSS/JS 解析执行、布局绘制，运行在沙箱中）、GPU 进程（合成与栅格化）、Network Service 进程、Storage/Utility 进程、插件进程。 Renderer 内有主线程（JS 执行、DOM 构建、样式计算、布局、部分绘制）、合成线程（图层合成、滚动）、光栅化线程、Worker 线程（Web Worker 独立于主线程）。站点隔离（Site Isolation）让跨站 iframe 用独立进程，缓解 Spectre 类攻击。 意义：一个标签页崩溃不会拖垮整个浏览器、沙箱提升安全性、多进程可利用多核；代价是内存占用更高（Chrome 有进程合并策略）。"},{"id":131,"num":"Q131","tag":"概念","title":"Performance API 与常见前端性能指标？","answers":["Performance API：performance.now()（高精度单调时钟）、performance.timing（已废弃）/ Navigation Timing Level 2 的 performance.getEntriesByType('navigation')、Resource Timing（资源各阶段耗时）、performance.mark / measure 自定义打点、PerformanceObserver 监听 longtask / layout-shift / largest-contentful-paint / event 等条目。","关键时间：TTFB（首字节）、FP（首次绘制）、FCP（首次内容绘制）、LCP（最大内容绘制，≤2.5s 为优）、FID（首次输入延迟，已被 INP 取代）、INP（交互到下一帧绘制，≤200ms）、CLS（累积布局偏移，≤0.1）、TTI（可交互时间）、TBT（总阻塞时间）、SI（速度指数）。","排查工具链：Lighthouse / PageSpeed Insights 给实验室数据 → Chrome DevTools Performance 火焰图找长任务 → Web Vitals / web-vitals 库 + 监控 SDK 采集真实用户数据（RUM）→ 按 P75/P95 分位数评估优化效果。"],"bullets":[],"code":[],"note":"","text":"Performance API 与常见前端性能指标？ Performance API：performance.now()（高精度单调时钟）、performance.timing（已废弃）/ Navigation Timing Level 2 的 performance.getEntriesByType('navigation')、Resource Timing（资源各阶段耗时）、performance.mark / measure 自定义打点、PerformanceObserver 监听 longtask / layout-shift / largest-contentful-paint / event 等条目。 关键时间：TTFB（首字节）、FP（首次绘制）、FCP（首次内容绘制）、LCP（最大内容绘制，≤2.5s 为优）、FID（首次输入延迟，已被 INP 取代）、INP（交互到下一帧绘制，≤200ms）、CLS（累积布局偏移，≤0.1）、TTI（可交互时间）、TBT（总阻塞时间）、SI（速度指数）。 排查工具链：Lighthouse / PageSpeed Insights 给实验室数据 → Chrome DevTools Performance 火焰图找长任务 → Web Vitals / web-vitals 库 + 监控 SDK 采集真实用户数据（RUM）→ 按 P75/P95 分位数评估优化效果。"},{"id":132,"num":"Q132","tag":"场景","title":"前端监控 SDK 需要采集哪些数据？","answers":["① JS 错误：window.onerror + unhandledrejection + 资源加载错误（document 上 capture 阶段监听）+ Vue/React errorHandler，堆栈配合 sourcemap 还原；② 性能：Navigation/Resource Timing、Web Vitals、Long Task、首屏时间、接口耗时；③ 接口请求：拦截 XHR/fetch 记录状态码、耗时、错误；④ 用户行为面包屑：点击、路由跳转、console、输入（脱敏）；⑤ 环境信息：UA、设备、网络（navigator.connection）、版本、用户标识、会话 ID；⑥ 白屏/卡顿检测：MutationObserver + 采样、longtask 阈值。","上报策略：批量合并、空闲/卸载时发送（sendBeacon 或 fetch keepalive）、采样率可配置、失败重试、限流降级，避免监控自身拖垮页面。"],"bullets":[],"code":[],"note":"","text":"前端监控 SDK 需要采集哪些数据？ ① JS 错误：window.onerror + unhandledrejection + 资源加载错误（document 上 capture 阶段监听）+ Vue/React errorHandler，堆栈配合 sourcemap 还原；② 性能：Navigation/Resource Timing、Web Vitals、Long Task、首屏时间、接口耗时；③ 接口请求：拦截 XHR/fetch 记录状态码、耗时、错误；④ 用户行为面包屑：点击、路由跳转、console、输入（脱敏）；⑤ 环境信息：UA、设备、网络（navigator.connection）、版本、用户标识、会话 ID；⑥ 白屏/卡顿检测：MutationObserver + 采样、longtask 阈值。 上报策略：批量合并、空闲/卸载时发送（sendBeacon 或 fetch keepalive）、采样率可配置、失败重试、限流降级，避免监控自身拖垮页面。"},{"id":133,"num":"Q133","tag":"概念","title":"什么是 Service Worker、PWA 与离线缓存？","answers":["Service Worker 是运行在浏览器后台、独立于页面的脚本（只能 HTTPS / localhost），可拦截并代理网络请求（fetch 事件）、做离线缓存、推送通知、后台同步；生命周期为 install → activate → fetch，通过 Cache Storage / IndexedDB 存储。","常见缓存策略：Cache First（静态资源）、Network First（HTML/API 及时性）、Stale-While-Revalidate（先返缓存再后台更新）、Network Only / Cache Only。","注意：更新需要 skipWaiting + clients.claim 或等所有页面关闭；它是 PWA 的核心，但调试时容易被旧 SW 缓存坑到。"],"bullets":[],"code":[],"note":"","text":"什么是 Service Worker、PWA 与离线缓存？ Service Worker 是运行在浏览器后台、独立于页面的脚本（只能 HTTPS / localhost），可拦截并代理网络请求（fetch 事件）、做离线缓存、推送通知、后台同步；生命周期为 install → activate → fetch，通过 Cache Storage / IndexedDB 存储。 常见缓存策略：Cache First（静态资源）、Network First（HTML/API 及时性）、Stale-While-Revalidate（先返缓存再后台更新）、Network Only / Cache Only。 注意：更新需要 skipWaiting + clients.claim 或等所有页面关闭；它是 PWA 的核心，但调试时容易被旧 SW 缓存坑到。"},{"id":134,"num":"Q134","tag":"对比","title":"Web Worker / SharedWorker / Service Worker 的区别？","answers":["Web Worker：在后台线程执行 JS，不能操作 DOM，通过 postMessage 与主线程通信，适合大计算、加密、图像处理、大文件分片 hash，避免阻塞 UI。","SharedWorker：多个同源标签页/iframe 共享同一个 worker 实例，可做跨标签页状态共享与通信（用 port）。","Service Worker：不服务于单个页面，是网络代理 + 事件驱动的持久层，用于离线缓存与推送，页面关闭后仍可被事件唤醒。","限制：都不能直接访问 DOM、localStorage（Service Worker 可用 IndexedDB / Cache API），传输数据用结构化克隆（大 ArrayBuffer 用 transferable 可零拷贝转移所有权）。"],"bullets":[],"code":[],"note":"","text":"Web Worker / SharedWorker / Service Worker 的区别？ Web Worker：在后台线程执行 JS，不能操作 DOM，通过 postMessage 与主线程通信，适合大计算、加密、图像处理、大文件分片 hash，避免阻塞 UI。 SharedWorker：多个同源标签页/iframe 共享同一个 worker 实例，可做跨标签页状态共享与通信（用 port）。 Service Worker：不服务于单个页面，是网络代理 + 事件驱动的持久层，用于离线缓存与推送，页面关闭后仍可被事件唤醒。 限制：都不能直接访问 DOM、localStorage（Service Worker 可用 IndexedDB / Cache API），传输数据用结构化克隆（大 ArrayBuffer 用 transferable 可零拷贝转移所有权）。"}]}]},{"id":"day5","day":5,"title":"第 5 天｜Vue 与 React 框架原理","short":"Vue 与 React 框架原理","note":"目标：框架题的评分标准是「能不能讲清原理 + 能不能落到项目问题」。建议每个原理都准备一句「我在项目里遇到过什么问题、怎么解决的」，比如 key 用 index 导致表单错位、useEffect 闭包陷阱拿到旧值。","sections":[{"id":"day5-s1","day":5,"title":"5.1 Vue2 / Vue3 响应式原理","note":"","questions":[{"id":135,"num":"Q135","tag":"必考","title":"Vue2 的响应式原理？为什么需要 $set 和重写数组方法？","answers":["Vue2 用 Object.defineProperty 递归遍历 data 的每个属性，把属性转成 getter/setter：getter 里做依赖收集（Dep 收集当前 Watcher），setter 里触发 dep.notify() 通知所有 Watcher 更新；每个组件对应一个渲染 Watcher，组件渲染时读取的数据会被收集为依赖。","整体链路：Observer（劫持数据）→ Dep（依赖管理）→ Watcher（观察者）→ 调度队列（异步批量更新，nextTick）→ 虚拟 DOM patch。","缺陷：① 只能劫持「已经存在」的属性，新增/删除属性无法侦测，需要 Vue.set / this.$set（内部手动调用 defineReactive + dep.notify）或 Vue.delete；② 数组通过下标赋值、修改 length 不会被拦截，因此需要重写 push/pop/shift/unshift/splice/sort/reverse 这 7 个变异方法（用原型拦截：Object.create(Array.prototype) 造一层 arrayMethods，在方法里调用原始方法后手动通知，并对新增元素再做 observe）；③ 初始化时要递归遍历整个对象，数据层级深时性能开销大；④ 不支持 Map/Set 等集合类型。"],"bullets":[],"code":[],"note":"","text":"Vue2 的响应式原理？为什么需要 $set 和重写数组方法？ Vue2 用 Object.defineProperty 递归遍历 data 的每个属性，把属性转成 getter/setter：getter 里做依赖收集（Dep 收集当前 Watcher），setter 里触发 dep.notify() 通知所有 Watcher 更新；每个组件对应一个渲染 Watcher，组件渲染时读取的数据会被收集为依赖。 整体链路：Observer（劫持数据）→ Dep（依赖管理）→ Watcher（观察者）→ 调度队列（异步批量更新，nextTick）→ 虚拟 DOM patch。 缺陷：① 只能劫持「已经存在」的属性，新增/删除属性无法侦测，需要 Vue.set / this.$set（内部手动调用 defineReactive + dep.notify）或 Vue.delete；② 数组通过下标赋值、修改 length 不会被拦截，因此需要重写 push/pop/shift/unshift/splice/sort/reverse 这 7 个变异方法（用原型拦截：Object.create(Array.prototype) 造一层 arrayMethods，在方法里调用原始方法后手动通知，并对新增元素再做 observe）；③ 初始化时要递归遍历整个对象，数据层级深时性能开销大；④ 不支持 Map/Set 等集合类型。"},{"id":136,"num":"Q136","tag":"必考","title":"Vue3 的响应式原理？Proxy + Reflect 好在哪？","answers":["Vue3 用 Proxy 代理整个对象，拦截 get / set / deleteProperty / has / ownKeys 等 13 种操作：get 时 track（把当前 activeEffect 收集进 target 的依赖 Map），set / delete 时 trigger（取出依赖执行），依赖存储在全局 WeakMap<target, Map<key, Set<effect>>> 结构中。","优势：① 代理整个对象而非逐个属性，能侦测属性新增、删除、in、Object.keys；② 数组下标赋值与 length 修改天然可侦测，不再需要重写 7 个方法；③ 支持 Map/Set/WeakMap/WeakSet（通过集合类型的 instrumented 方法）；④ 惰性递归——只有真正被访问到的嵌套对象才被包装成响应式，初始化性能更好；⑤ 通过 Reflect 配合 receiver 保证属性访问器里的 this 指向代理对象，避免原型链上 getter 收集错依赖。","代价：IE 不支持且无法 polyfill（所以 Vue3 不支持 IE11）；代理对象 !== 原对象（用 toRaw 可拿回原始对象）；每次访问都会产生新代理需要缓存（Vue3 用 reactiveMap 缓存）。"],"bullets":[],"code":[],"note":"高分补充：ref 是对基本类型的包装（.value + Object.defineProperty 的 get/set），reactive 只能用于对象；toRefs 解构 reactive 时保持响应性；computed 是带缓存的 effect（dirty 标记 + scheduler）；watch 是 effect 的调度器实现。","text":"Vue3 的响应式原理？Proxy + Reflect 好在哪？ Vue3 用 Proxy 代理整个对象，拦截 get / set / deleteProperty / has / ownKeys 等 13 种操作：get 时 track（把当前 activeEffect 收集进 target 的依赖 Map），set / delete 时 trigger（取出依赖执行），依赖存储在全局 WeakMap<target, Map<key, Set<effect>>> 结构中。 优势：① 代理整个对象而非逐个属性，能侦测属性新增、删除、in、Object.keys；② 数组下标赋值与 length 修改天然可侦测，不再需要重写 7 个方法；③ 支持 Map/Set/WeakMap/WeakSet（通过集合类型的 instrumented 方法）；④ 惰性递归——只有真正被访问到的嵌套对象才被包装成响应式，初始化性能更好；⑤ 通过 Reflect 配合 receiver 保证属性访问器里的 this 指向代理对象，避免原型链上 getter 收集错依赖。 代价：IE 不支持且无法 polyfill（所以 Vue3 不支持 IE11）；代理对象 !== 原对象（用 toRaw 可拿回原始对象）；每次访问都会产生新代理需要缓存（Vue3 用 reactiveMap 缓存）。 高分补充：ref 是对基本类型的包装（.value + Object.defineProperty 的 get/set），reactive 只能用于对象；toRefs 解构 reactive 时保持响应性；computed 是带缓存的 effect（dirty 标记 + scheduler）；watch 是 effect 的调度器实现。"},{"id":137,"num":"Q137","tag":"对比","title":"Vue2 与 Vue3 的区别？Vue3 为什么更快？","answers":["响应式：defineProperty → Proxy（见上两题）；API：Options API → Composition API（逻辑复用更灵活、无 this 混淆、TS 友好、按功能组织代码）；生命周期：beforeDestroy/destroyed → beforeUnmount/unmounted，新增 onActivated 等组合式 API；Fragment / Teleport / Suspense 支持；多根节点模板；v-model 可带参数且可多个；v-if 优先级高于 v-for（与 Vue2 相反）；全局 API 改为 app 实例（createApp）避免污染；Tree-shaking 支持按需引入，体积更小。","性能提升：① 编译期 PatchFlag 标记动态节点，diff 时只比对动态部分（静态节点跳过）；② hoistStatic 静态提升，静态节点只创建一次并被复用；③ cacheHandler 缓存事件处理函数，避免每次渲染生成新函数；④ Block Tree / dynamicChildren 把 diff 从整棵树递归降为「只遍历动态子节点数组」；⑤ SSR 与 Tree-shaking 优化。","其它：TypeScript 重写、更好的类型推导；Vite 官方配套；Pinia 取代 Vuex 成为官方推荐。"],"bullets":[],"code":[],"note":"","text":"Vue2 与 Vue3 的区别？Vue3 为什么更快？ 响应式：defineProperty → Proxy（见上两题）；API：Options API → Composition API（逻辑复用更灵活、无 this 混淆、TS 友好、按功能组织代码）；生命周期：beforeDestroy/destroyed → beforeUnmount/unmounted，新增 onActivated 等组合式 API；Fragment / Teleport / Suspense 支持；多根节点模板；v-model 可带参数且可多个；v-if 优先级高于 v-for（与 Vue2 相反）；全局 API 改为 app 实例（createApp）避免污染；Tree-shaking 支持按需引入，体积更小。 性能提升：① 编译期 PatchFlag 标记动态节点，diff 时只比对动态部分（静态节点跳过）；② hoistStatic 静态提升，静态节点只创建一次并被复用；③ cacheHandler 缓存事件处理函数，避免每次渲染生成新函数；④ Block Tree / dynamicChildren 把 diff 从整棵树递归降为「只遍历动态子节点数组」；⑤ SSR 与 Tree-shaking 优化。 其它：TypeScript 重写、更好的类型推导；Vite 官方配套；Pinia 取代 Vuex 成为官方推荐。"},{"id":138,"num":"Q138","tag":"必考","title":"Vue 的虚拟 DOM 与 diff 算法？key 的作用？","answers":["虚拟 DOM 是用 JS 对象描述真实 DOM 的轻量抽象，状态变化时生成新的 VNode 树，通过 diff 找出最小变更再 patch 到真实 DOM，避免全量重绘，同时提供跨平台能力（SSR、Weex、小程序）。","Vue 的 diff 采用「同层比较 + 双端指针」（Vue2）：只比较同一层级，不跨层移动；用 oldStartIdx/oldEndIdx/newStartIdx/newEndIdx 四个指针做头头、尾尾、头尾、尾头四种命中判断，命中则复用并移动指针，否则用 key 建立 oldVNode 的 map 查找可复用节点，最后处理新增与删除。Vue3 在此基础上用「最长递增子序列（LIS）」优化乱序移动，使需要 move 的节点数最少。","key 的作用：作为 VNode 的唯一标识，让 diff 能判断「同一个节点」从而复用真实 DOM 与组件实例（含内部状态）。用 index 作 key 在列表插入/删除/排序时会造成错误复用（输入框内容错位、组件状态串位、动画异常），也会让本可复用的节点被销毁重建；不写 key 时 Vue 会默认用索引，即「就地复用」策略。","key 应该用稳定的业务唯一 ID（如 item.id）；用 Math.random() 作 key 会导致每次渲染全部重建，是常见反模式。"],"bullets":[],"code":[],"note":"","text":"Vue 的虚拟 DOM 与 diff 算法？key 的作用？ 虚拟 DOM 是用 JS 对象描述真实 DOM 的轻量抽象，状态变化时生成新的 VNode 树，通过 diff 找出最小变更再 patch 到真实 DOM，避免全量重绘，同时提供跨平台能力（SSR、Weex、小程序）。 Vue 的 diff 采用「同层比较 + 双端指针」（Vue2）：只比较同一层级，不跨层移动；用 oldStartIdx/oldEndIdx/newStartIdx/newEndIdx 四个指针做头头、尾尾、头尾、尾头四种命中判断，命中则复用并移动指针，否则用 key 建立 oldVNode 的 map 查找可复用节点，最后处理新增与删除。Vue3 在此基础上用「最长递增子序列（LIS）」优化乱序移动，使需要 move 的节点数最少。 key 的作用：作为 VNode 的唯一标识，让 diff 能判断「同一个节点」从而复用真实 DOM 与组件实例（含内部状态）。用 index 作 key 在列表插入/删除/排序时会造成错误复用（输入框内容错位、组件状态串位、动画异常），也会让本可复用的节点被销毁重建；不写 key 时 Vue 会默认用索引，即「就地复用」策略。 key 应该用稳定的业务唯一 ID（如 item.id）；用 Math.random() 作 key 会导致每次渲染全部重建，是常见反模式。"},{"id":139,"num":"Q139","tag":"高频","title":"nextTick 的原理？为什么 Vue 的 DOM 更新是异步的？","answers":["Vue 检测到数据变化后不会立刻更新 DOM，而是把 Watcher 推入一个队列并去重（同一 Watcher 多次变更只入队一次），在下一个微任务周期统一 flush，这样无论改多少次数据都只做一次渲染，避免不必要的重排重绘。","nextTick(cb) 就是把回调也放进这个异步队列（或 flush 之后的微任务），因此能在 DOM 更新完成后拿到最新 DOM。","实现降级链：Promise.then（微任务）→ MutationObserver → setImmediate → setTimeout（宏任务）；Vue3 直接用 Promise.resolve().then。"],"bullets":[],"code":[],"note":"追问：为什么用微任务而不是宏任务？微任务在当前事件循环结束前执行，比 setTimeout 更早，且不会插入一次浏览器渲染，用户看不到中间态；但宏任务在 UI 事件、跨标签通信等场景也有其调度价值。","text":"nextTick 的原理？为什么 Vue 的 DOM 更新是异步的？ Vue 检测到数据变化后不会立刻更新 DOM，而是把 Watcher 推入一个队列并去重（同一 Watcher 多次变更只入队一次），在下一个微任务周期统一 flush，这样无论改多少次数据都只做一次渲染，避免不必要的重排重绘。 nextTick(cb) 就是把回调也放进这个异步队列（或 flush 之后的微任务），因此能在 DOM 更新完成后拿到最新 DOM。 实现降级链：Promise.then（微任务）→ MutationObserver → setImmediate → setTimeout（宏任务）；Vue3 直接用 Promise.resolve().then。 追问：为什么用微任务而不是宏任务？微任务在当前事件循环结束前执行，比 setTimeout 更早，且不会插入一次浏览器渲染，用户看不到中间态；但宏任务在 UI 事件、跨标签通信等场景也有其调度价值。"},{"id":140,"num":"Q140","tag":"对比","title":"computed 与 watch / watchEffect 的区别？","answers":["computed：有缓存，只有依赖的响应式数据变化才重新计算，依赖不变时多次读取直接返回缓存值；必须有返回值；适合由其它数据派生出新数据（如过滤列表、总价）。computed 默认惰性求值（用到才算），本质是一个带 dirty 标记的 effect。","watch：侦听指定数据源，数据变化时执行副作用（请求、日志、手动操作 DOM），无返回值；可拿到 oldValue/newValue、支持 deep、immediate、flush（pre/post/sync）、可停止（返回 stop 函数）；适合「数据变化后做一件事」。","watchEffect（Vue3）：自动收集回调里用到的所有依赖，立即执行一次，依赖变化时重跑，无法拿到旧值；适合依赖不固定的灵活场景。","常见坑：watch 侦听 reactive 对象时默认已开启 deep，但侦听 `() => props.obj` 这类 getter 时若对象引用不变则不会触发，需 deep: true。"],"bullets":[],"code":[],"note":"","text":"computed 与 watch / watchEffect 的区别？ computed：有缓存，只有依赖的响应式数据变化才重新计算，依赖不变时多次读取直接返回缓存值；必须有返回值；适合由其它数据派生出新数据（如过滤列表、总价）。computed 默认惰性求值（用到才算），本质是一个带 dirty 标记的 effect。 watch：侦听指定数据源，数据变化时执行副作用（请求、日志、手动操作 DOM），无返回值；可拿到 oldValue/newValue、支持 deep、immediate、flush（pre/post/sync）、可停止（返回 stop 函数）；适合「数据变化后做一件事」。 watchEffect（Vue3）：自动收集回调里用到的所有依赖，立即执行一次，依赖变化时重跑，无法拿到旧值；适合依赖不固定的灵活场景。 常见坑：watch 侦听 reactive 对象时默认已开启 deep，但侦听 `() => props.obj` 这类 getter 时若对象引用不变则不会触发，需 deep: true。"},{"id":141,"num":"Q141","tag":"基础","title":"Vue 的生命周期与父子组件执行顺序？","answers":["Vue3（组合式）：setup（最先，替代 beforeCreate/created）→ onBeforeMount → onMounted → onBeforeUpdate → onUpdated → onBeforeUnmount → onUnmounted；keep-alive 额外有 onActivated / onDeactivated；还有 onErrorCaptured、onRenderTracked / onRenderTriggered（调试用）。","父子顺序：父 setup → 父 beforeMount → 子 setup → 子 beforeMount → 子 mounted → 父 mounted；更新同理「父 beforeUpdate → 子 beforeUpdate → 子 updated → 父 updated」；销毁是「父 beforeUnmount → 子 beforeUnmount → 子 unmounted → 父 unmounted」。","常见用途：mounted 里拿 DOM / 初始化第三方库 / 发请求；beforeUnmount 里清理定时器、事件监听、取消订阅与未完成的请求；updated 里不要再改依赖数据（死循环）。","注意：Vue2 的 beforeCreate 阶段还拿不到 data/methods，created 已可访问数据但还没挂载 DOM；异步请求放 created 还是 mounted 取决于是否要尽早发起，二者差别不大，但 SSR 下 mounted 不会执行。"],"bullets":[],"code":[],"note":"","text":"Vue 的生命周期与父子组件执行顺序？ Vue3（组合式）：setup（最先，替代 beforeCreate/created）→ onBeforeMount → onMounted → onBeforeUpdate → onUpdated → onBeforeUnmount → onUnmounted；keep-alive 额外有 onActivated / onDeactivated；还有 onErrorCaptured、onRenderTracked / onRenderTriggered（调试用）。 父子顺序：父 setup → 父 beforeMount → 子 setup → 子 beforeMount → 子 mounted → 父 mounted；更新同理「父 beforeUpdate → 子 beforeUpdate → 子 updated → 父 updated」；销毁是「父 beforeUnmount → 子 beforeUnmount → 子 unmounted → 父 unmounted」。 常见用途：mounted 里拿 DOM / 初始化第三方库 / 发请求；beforeUnmount 里清理定时器、事件监听、取消订阅与未完成的请求；updated 里不要再改依赖数据（死循环）。 注意：Vue2 的 beforeCreate 阶段还拿不到 data/methods，created 已可访问数据但还没挂载 DOM；异步请求放 created 还是 mounted 取决于是否要尽早发起，二者差别不大，但 SSR 下 mounted 不会执行。"},{"id":142,"num":"Q142","tag":"基础","title":"Vue 组件通信方式有哪些？（说全 + 说场景）","answers":["① props / $emit（父子，最基础，props 单向数据流，子组件不要直接改 props）；② v-model / .sync / defineModel（父子双向语法糖，Vue3 组件可用多个 v-model）；③ ref / $refs + defineExpose（父调子方法）；④ $parent / $children（Vue2，强耦合不推荐）；⑤ provide / inject（跨层级依赖注入，适合主题、配置、全局状态，注意默认非响应式需传 ref/reactive）；⑥ 事件总线 EventBus / mitt（任意组件，Vue3 移除了 $on，需第三方库或自己写）；⑦ Vuex / Pinia（全局状态）；⑧ $attrs / $listeners（透传属性与事件，封装高阶组件）；⑨ slot 作用域插槽（父拿子的数据）；⑩ 路由参数 / query、localStorage、URL 状态、全局 window 事件。","加分：能说出「单向数据流 + 状态提升」的设计原则，以及为什么大项目要收敛到 Pinia 而不是满天飞的事件总线（难追踪、难调试、内存泄漏）。"],"bullets":[],"code":[],"note":"","text":"Vue 组件通信方式有哪些？（说全 + 说场景） ① props / $emit（父子，最基础，props 单向数据流，子组件不要直接改 props）；② v-model / .sync / defineModel（父子双向语法糖，Vue3 组件可用多个 v-model）；③ ref / $refs + defineExpose（父调子方法）；④ $parent / $children（Vue2，强耦合不推荐）；⑤ provide / inject（跨层级依赖注入，适合主题、配置、全局状态，注意默认非响应式需传 ref/reactive）；⑥ 事件总线 EventBus / mitt（任意组件，Vue3 移除了 $on，需第三方库或自己写）；⑦ Vuex / Pinia（全局状态）；⑧ $attrs / $listeners（透传属性与事件，封装高阶组件）；⑨ slot 作用域插槽（父拿子的数据）；⑩ 路由参数 / query、localStorage、URL 状态、全局 window 事件。 加分：能说出「单向数据流 + 状态提升」的设计原则，以及为什么大项目要收敛到 Pinia 而不是满天飞的事件总线（难追踪、难调试、内存泄漏）。"},{"id":143,"num":"Q143","tag":"对比","title":"v-if 与 v-show、v-for 与 v-if 的优先级？","answers":["v-if 是「真」的条件渲染：条件为假时根本不创建/销毁 DOM 与组件实例（会触发生命周期与重新渲染），切换开销大、初始渲染开销小；v-show 始终渲染，只切换 CSS display:none，初始开销大、频繁切换开销小。频繁显隐用 v-show，运行时很少改变或涉及权限/重逻辑用 v-if。","Vue2 中 v-for 优先级高于 v-if（同一元素上会先循环再判断，浪费性能且 v-if 拿不到循环变量）；Vue3 中 v-if 优先级高于 v-for（此时 v-if 里访问不到 v-for 的变量）。正确做法：把 v-if 提到外层 template，或先用 computed 过滤列表。","补充：v-for 必须加稳定 key；不要和 v-if 写在同一元素；遍历对象时顺序是 Object.keys 的顺序；v-for 支持解构与 (item, index) 以及 of/in。"],"bullets":[],"code":[],"note":"","text":"v-if 与 v-show、v-for 与 v-if 的优先级？ v-if 是「真」的条件渲染：条件为假时根本不创建/销毁 DOM 与组件实例（会触发生命周期与重新渲染），切换开销大、初始渲染开销小；v-show 始终渲染，只切换 CSS display:none，初始开销大、频繁切换开销小。频繁显隐用 v-show，运行时很少改变或涉及权限/重逻辑用 v-if。 Vue2 中 v-for 优先级高于 v-if（同一元素上会先循环再判断，浪费性能且 v-if 拿不到循环变量）；Vue3 中 v-if 优先级高于 v-for（此时 v-if 里访问不到 v-for 的变量）。正确做法：把 v-if 提到外层 template，或先用 computed 过滤列表。 补充：v-for 必须加稳定 key；不要和 v-if 写在同一元素；遍历对象时顺序是 Object.keys 的顺序；v-for 支持解构与 (item, index) 以及 of/in。"},{"id":144,"num":"Q144","tag":"概念","title":"Vue 的指令、修饰符与插槽？","answers":["常用指令：v-bind / v-on / v-model / v-if / v-show / v-for / v-slot / v-pre（跳过编译）/ v-cloak（防闪烁）/ v-once（只渲染一次）/ v-memo（Vue3.2 缓存子树）/ v-html（有 XSS 风险，必须配合 DOMPurify）。","常用修饰符：事件 .stop / .prevent / .capture / .self / .once / .passive / .left / .middle；按键 .enter / .esc / .space / .ctrl；v-model .lazy / .number / .trim；鼠标 .native（Vue2）。","插槽：默认插槽、具名插槽（v-slot:name，简写 #name）、作用域插槽（子组件用 <slot :row=\"row\"> 把数据传给父组件模板，父用 #default=\"{ row }\" 接收），是实现「可配置组件」与表格组件列模板的核心。Vue3 中 slot 编译为函数，作用域插槽性能更好。"],"bullets":[],"code":[],"note":"","text":"Vue 的指令、修饰符与插槽？ 常用指令：v-bind / v-on / v-model / v-if / v-show / v-for / v-slot / v-pre（跳过编译）/ v-cloak（防闪烁）/ v-once（只渲染一次）/ v-memo（Vue3.2 缓存子树）/ v-html（有 XSS 风险，必须配合 DOMPurify）。 常用修饰符：事件 .stop / .prevent / .capture / .self / .once / .passive / .left / .middle；按键 .enter / .esc / .space / .ctrl；v-model .lazy / .number / .trim；鼠标 .native（Vue2）。 插槽：默认插槽、具名插槽（v-slot:name，简写 #name）、作用域插槽（子组件用 <slot :row=\"row\"> 把数据传给父组件模板，父用 #default=\"{ row }\" 接收），是实现「可配置组件」与表格组件列模板的核心。Vue3 中 slot 编译为函数，作用域插槽性能更好。"},{"id":145,"num":"Q145","tag":"对比","title":"Vuex 与 Pinia 的区别？","answers":["Vuex（Vue2 时代）：有 state / getters / mutations（必须同步）/ actions（可异步）/ modules 五件套，需要通过 commit → mutation 修改状态，样板代码多、TS 支持弱、模块嵌套复杂。","Pinia：去掉 mutations，直接 this.xxx = 或 store.$patch 修改；天然 TypeScript 类型推导；每个 store 独立定义、可组合、支持多个 store 实例、无需命名空间嵌套；支持插件扩展、devtools、SSR；体积更小，是 Vue3 官方推荐。","加分：能讲清「为什么去掉 mutations」——它最初的初衷是让 devtools 追踪状态变更，但 Pinia 通过 $patch / 订阅机制同样可追踪，同步限制反而增加心智负担。"],"bullets":[],"code":[],"note":"","text":"Vuex 与 Pinia 的区别？ Vuex（Vue2 时代）：有 state / getters / mutations（必须同步）/ actions（可异步）/ modules 五件套，需要通过 commit → mutation 修改状态，样板代码多、TS 支持弱、模块嵌套复杂。 Pinia：去掉 mutations，直接 this.xxx = 或 store.$patch 修改；天然 TypeScript 类型推导；每个 store 独立定义、可组合、支持多个 store 实例、无需命名空间嵌套；支持插件扩展、devtools、SSR；体积更小，是 Vue3 官方推荐。 加分：能讲清「为什么去掉 mutations」——它最初的初衷是让 devtools 追踪状态变更，但 Pinia 通过 $patch / 订阅机制同样可追踪，同步限制反而增加心智负担。"},{"id":146,"num":"Q146","tag":"场景","title":"vue-router 的原理与两种模式、导航守卫？","answers":["hash 模式：用 URL 中 # 后面的部分，监听 hashchange，改变 hash 不向服务器发请求，兼容性好但 URL 不美观、SEO 差。","history 模式：基于 HTML5 History API（pushState / replaceState），监听 popstate，URL 干净；需要服务端配置「所有路径回退到 index.html」，否则刷新 404。","abstract 模式：非浏览器环境（SSR / 测试）用内存数组模拟。","守卫：全局 beforeEach / beforeResolve / afterEach，路由独享 beforeEnter，组件内 beforeRouteEnter / beforeRouteUpdate / beforeRouteLeave；典型应用是登录鉴权（beforeEach + 白名单 + 重定向 + 动态路由 addRoute）、权限校验、页面离开确认、滚动行为 scrollBehavior。","加分：beforeRouteEnter 里拿不到 this（组件还没创建），需要通过 next(vm => ...) 访问实例；next 必须且只能调用一次。"],"bullets":[],"code":[],"note":"","text":"vue-router 的原理与两种模式、导航守卫？ hash 模式：用 URL 中 # 后面的部分，监听 hashchange，改变 hash 不向服务器发请求，兼容性好但 URL 不美观、SEO 差。 history 模式：基于 HTML5 History API（pushState / replaceState），监听 popstate，URL 干净；需要服务端配置「所有路径回退到 index.html」，否则刷新 404。 abstract 模式：非浏览器环境（SSR / 测试）用内存数组模拟。 守卫：全局 beforeEach / beforeResolve / afterEach，路由独享 beforeEnter，组件内 beforeRouteEnter / beforeRouteUpdate / beforeRouteLeave；典型应用是登录鉴权（beforeEach + 白名单 + 重定向 + 动态路由 addRoute）、权限校验、页面离开确认、滚动行为 scrollBehavior。 加分：beforeRouteEnter 里拿不到 this（组件还没创建），需要通过 next(vm => ...) 访问实例；next 必须且只能调用一次。"},{"id":147,"num":"Q147","tag":"概念","title":"keep-alive 的原理与 LRU？","answers":["keep-alive 是抽象组件（不渲染 DOM、不出现在父链中），缓存已渲染的组件 VNode 与实例，切换时不销毁而是 deactivate/activate，触发 activated / deactivated 钩子，保留表单输入、滚动位置等状态。","支持 include / exclude（按组件 name 匹配正则/字符串/数组）与 max（最大缓存数）；超出 max 时用 LRU 策略淘汰最久未访问的 key（Vue 内部用 keys 数组 + cache 对象实现：访问时把 key 移到队尾，淘汰时删队首）。","坑：被缓存组件不会再触发 mounted / unmounted，清理逻辑要放 deactivated 或用 onActivated 重新初始化；include 依赖组件 name，匿名组件/动态组件要注意命名。"],"bullets":[],"code":[],"note":"","text":"keep-alive 的原理与 LRU？ keep-alive 是抽象组件（不渲染 DOM、不出现在父链中），缓存已渲染的组件 VNode 与实例，切换时不销毁而是 deactivate/activate，触发 activated / deactivated 钩子，保留表单输入、滚动位置等状态。 支持 include / exclude（按组件 name 匹配正则/字符串/数组）与 max（最大缓存数）；超出 max 时用 LRU 策略淘汰最久未访问的 key（Vue 内部用 keys 数组 + cache 对象实现：访问时把 key 移到队尾，淘汰时删队首）。 坑：被缓存组件不会再触发 mounted / unmounted，清理逻辑要放 deactivated 或用 onActivated 重新初始化；include 依赖组件 name，匿名组件/动态组件要注意命名。"},{"id":148,"num":"Q148","tag":"场景","title":"mixins 的问题？Composition API 如何解决？","answers":["mixins 的问题：① 命名冲突（同名选项合并规则隐晦，容易互相覆盖）；② 来源不清晰（组件里突然出现一个 data/method，不知道来自哪个 mixin）；③ 多个 mixin 之间可隐式耦合、难以复用与抽取；④ TS 类型推导差。","Composition API 用「组合函数 composable」解决：函数显式返回 ref / computed / 方法，调用处解构命名（可重命名），依赖关系与数据来源一目了然，天然支持 TS 类型推导，逻辑可跨组件复用且可嵌套组合。","加分：Vue3 仍保留 mixins 只为兼容，新代码应优先用 composables（类似 React 自定义 Hook）。"],"bullets":[],"code":[],"note":"","text":"mixins 的问题？Composition API 如何解决？ mixins 的问题：① 命名冲突（同名选项合并规则隐晦，容易互相覆盖）；② 来源不清晰（组件里突然出现一个 data/method，不知道来自哪个 mixin）；③ 多个 mixin 之间可隐式耦合、难以复用与抽取；④ TS 类型推导差。 Composition API 用「组合函数 composable」解决：函数显式返回 ref / computed / 方法，调用处解构命名（可重命名），依赖关系与数据来源一目了然，天然支持 TS 类型推导，逻辑可跨组件复用且可嵌套组合。 加分：Vue3 仍保留 mixins 只为兼容，新代码应优先用 composables（类似 React 自定义 Hook）。"}]},{"id":"day5-s2","day":5,"title":"5.2 React 核心与 Hooks","note":"","questions":[{"id":149,"num":"Q149","tag":"原理","title":"React 的渲染流程与 Fiber 架构？","answers":["Fiber 是 React 16 引入的重写后的协调（Reconciliation）引擎，把原本递归、不可中断的同步 diff 改造成「可中断、可恢复、可设优先级」的工作单元链表结构（每个 FiberNode 对应一个组件/元素，含 child / sibling / return 指针）。","流程：JSX → React Element → beginWork（render 阶段，可中断，构建 workInProgress 树并打 effect 标记）→ completeWork → commit 阶段（不可中断，一次性把变更应用到真实 DOM，执行生命周期/useLayoutEffect/useEffect）。","双缓存机制：current 树（当前屏幕上显示的）与 workInProgress 树（正在构建的）通过 alternate 指针互相引用，构建完成后一次性切换 fiberRoot.current，保证用户不会看到半渲染的 UI。","调度：Scheduler 按优先级（Immediate / UserBlocking / Normal / Low / Idle）分配任务，用时间切片（默认 5ms）在浏览器空闲时执行，配合 lane 模型标记更新优先级，实现并发渲染（Concurrent Rendering）与可中断更新。"],"bullets":[],"code":[],"note":"","text":"React 的渲染流程与 Fiber 架构？ Fiber 是 React 16 引入的重写后的协调（Reconciliation）引擎，把原本递归、不可中断的同步 diff 改造成「可中断、可恢复、可设优先级」的工作单元链表结构（每个 FiberNode 对应一个组件/元素，含 child / sibling / return 指针）。 流程：JSX → React Element → beginWork（render 阶段，可中断，构建 workInProgress 树并打 effect 标记）→ completeWork → commit 阶段（不可中断，一次性把变更应用到真实 DOM，执行生命周期/useLayoutEffect/useEffect）。 双缓存机制：current 树（当前屏幕上显示的）与 workInProgress 树（正在构建的）通过 alternate 指针互相引用，构建完成后一次性切换 fiberRoot.current，保证用户不会看到半渲染的 UI。 调度：Scheduler 按优先级（Immediate / UserBlocking / Normal / Low / Idle）分配任务，用时间切片（默认 5ms）在浏览器空闲时执行，配合 lane 模型标记更新优先级，实现并发渲染（Concurrent Rendering）与可中断更新。"},{"id":150,"num":"Q150","tag":"必考","title":"setState 是同步还是异步？React 18 的变化？","answers":["React 18 之前：在合成事件与生命周期中是「批量更新」（表现为异步，拿不到新值），在 setTimeout / 原生事件 / Promise 回调中是同步立即更新；因为是否批处理取决于是否处于 React 的 batchedUpdates 上下文中。","React 18 起默认开启 automatic batching：无论 setTimeout、原生事件、Promise、async/await 里，多次 setState 都会自动合并为一次渲染。需要立即同步刷新可用 flushSync（谨慎使用，会破坏批处理）。","要点：setState 本身不是「异步 API」，而是「状态更新被调度/批处理」，状态对象在本次渲染中保持不变；函数式更新 setState(prev => prev + 1) 能拿到最新的 prev，适合连续多次更新；类组件 setState 第二参数回调与 componentDidUpdate 可拿到更新后的值。","useState 的 setter 用 Object.is 比较，值相同时会跳过重渲染（bail out）；对象/数组必须换引用才会更新。"],"bullets":[],"code":[],"note":"","text":"setState 是同步还是异步？React 18 的变化？ React 18 之前：在合成事件与生命周期中是「批量更新」（表现为异步，拿不到新值），在 setTimeout / 原生事件 / Promise 回调中是同步立即更新；因为是否批处理取决于是否处于 React 的 batchedUpdates 上下文中。 React 18 起默认开启 automatic batching：无论 setTimeout、原生事件、Promise、async/await 里，多次 setState 都会自动合并为一次渲染。需要立即同步刷新可用 flushSync（谨慎使用，会破坏批处理）。 要点：setState 本身不是「异步 API」，而是「状态更新被调度/批处理」，状态对象在本次渲染中保持不变；函数式更新 setState(prev => prev + 1) 能拿到最新的 prev，适合连续多次更新；类组件 setState 第二参数回调与 componentDidUpdate 可拿到更新后的值。 useState 的 setter 用 Object.is 比较，值相同时会跳过重渲染（bail out）；对象/数组必须换引用才会更新。"},{"id":151,"num":"Q151","tag":"高频","title":"Hooks 的规则与原理？为什么不能在条件/循环里调用？","answers":["规则：只在函数组件/自定义 Hook 的顶层调用，不能在条件、循环、嵌套函数里调用；只能在 React 函数中调用（自定义 Hook 以 use 开头）。","原理：函数组件的 Hook 状态以「链表/数组」形式挂在 FiberNode 的 memoizedState 上，每次渲染按调用顺序依次读取；如果顺序或数量变化（条件分支跳过某个 Hook），就会把 A Hook 的状态读到 B 上，导致状态错乱。ESLint 的 eslint-plugin-react-hooks 会静态检查这一点。","组件首次渲染走 mountXxx（创建 Hook 对象并挂链），更新走 updateXxx（复用链表节点）；useEffect 的 effect 也组成链表，靠 deps 数组决定是否重新执行。"],"bullets":[],"code":[],"note":"","text":"Hooks 的规则与原理？为什么不能在条件/循环里调用？ 规则：只在函数组件/自定义 Hook 的顶层调用，不能在条件、循环、嵌套函数里调用；只能在 React 函数中调用（自定义 Hook 以 use 开头）。 原理：函数组件的 Hook 状态以「链表/数组」形式挂在 FiberNode 的 memoizedState 上，每次渲染按调用顺序依次读取；如果顺序或数量变化（条件分支跳过某个 Hook），就会把 A Hook 的状态读到 B 上，导致状态错乱。ESLint 的 eslint-plugin-react-hooks 会静态检查这一点。 组件首次渲染走 mountXxx（创建 Hook 对象并挂链），更新走 updateXxx（复用链表节点）；useEffect 的 effect 也组成链表，靠 deps 数组决定是否重新执行。"},{"id":152,"num":"Q152","tag":"必考","title":"useEffect 的闭包陷阱？怎么解决？","answers":["原因：每次渲染都会创建一个新的函数闭包，effect 回调捕获的是「那一次渲染」的 props/state。如果 deps 为空或漏写依赖，回调里读到的永远是首次渲染的旧值（典型：定时器里 count 一直是 0）。","解决：① 依赖数组写全（ESLint exhaustive-deps）；② 用函数式更新 setCount(c => c + 1) 绕开对 count 的读取；③ 用 useRef 保存最新值（useLatest 模式：ref.current = value，回调读 ref.current）；④ 用 useReducer 把逻辑收敛；⑤ 在 useEffect 里正确 return 清理函数（清定时器、取消订阅、AbortController 取消请求）。","高频追问：useEffect 里请求数据为什么会有竞态？快速切换 tab 时旧请求后返回会覆盖新数据；用 cleanup 里的 canceled 标记或 AbortController.signal 取消，或直接上 TanStack Query / SWR。"],"bullets":[],"code":[],"note":"","text":"useEffect 的闭包陷阱？怎么解决？ 原因：每次渲染都会创建一个新的函数闭包，effect 回调捕获的是「那一次渲染」的 props/state。如果 deps 为空或漏写依赖，回调里读到的永远是首次渲染的旧值（典型：定时器里 count 一直是 0）。 解决：① 依赖数组写全（ESLint exhaustive-deps）；② 用函数式更新 setCount(c => c + 1) 绕开对 count 的读取；③ 用 useRef 保存最新值（useLatest 模式：ref.current = value，回调读 ref.current）；④ 用 useReducer 把逻辑收敛；⑤ 在 useEffect 里正确 return 清理函数（清定时器、取消订阅、AbortController 取消请求）。 高频追问：useEffect 里请求数据为什么会有竞态？快速切换 tab 时旧请求后返回会覆盖新数据；用 cleanup 里的 canceled 标记或 AbortController.signal 取消，或直接上 TanStack Query / SWR。"},{"id":153,"num":"Q153","tag":"对比","title":"useEffect、useLayoutEffect、useInsertionEffect 的区别？","answers":["useEffect：在浏览器完成绘制之后异步执行，不阻塞渲染，适合数据请求、订阅、埋点等大多数副作用。","useLayoutEffect：在 DOM 变更完成后、浏览器绘制之前同步执行，会阻塞绘制；适合读取 DOM 尺寸并同步调整布局、避免闪烁（如先测量再定位 tooltip）；SSR 下会告警（服务端无 DOM）。","useInsertionEffect：在布局副作用之前执行，专为 CSS-in-JS 库在渲染时注入 <style> 设计，业务代码基本不用。","执行顺序（一次更新）：DOM 变更 → useLayoutEffect（同步）→ 浏览器绘制 → useEffect（异步）；清理函数按同样时机先执行。"],"bullets":[],"code":[],"note":"","text":"useEffect、useLayoutEffect、useInsertionEffect 的区别？ useEffect：在浏览器完成绘制之后异步执行，不阻塞渲染，适合数据请求、订阅、埋点等大多数副作用。 useLayoutEffect：在 DOM 变更完成后、浏览器绘制之前同步执行，会阻塞绘制；适合读取 DOM 尺寸并同步调整布局、避免闪烁（如先测量再定位 tooltip）；SSR 下会告警（服务端无 DOM）。 useInsertionEffect：在布局副作用之前执行，专为 CSS-in-JS 库在渲染时注入 <style> 设计，业务代码基本不用。 执行顺序（一次更新）：DOM 变更 → useLayoutEffect（同步）→ 浏览器绘制 → useEffect（异步）；清理函数按同样时机先执行。"},{"id":154,"num":"Q154","tag":"对比","title":"useMemo、useCallback、React.memo 的区别与滥用问题？","answers":["React.memo：高阶组件，对 props 做浅比较，props 不变时跳过整个组件重渲染（组件级缓存）。","useMemo：缓存「计算结果」，依赖不变时复用值（值级缓存），适合昂贵计算或需要稳定引用的对象/数组（避免子组件因引用变化重渲染）。","useCallback：缓存「函数引用」，等价于 useMemo(() => fn, deps)，主要为了配合 React.memo 与作为 effect 依赖时保持引用稳定。","注意三者都是「缓存 + 依赖比较」，不是「性能优化万能药」：缓存本身有比较与内存成本，组件很轻或 props 每次都变时反而更慢；正确做法是先测量（React DevTools Profiler）再优化；且必须保证 deps 正确，否则会拿到旧值。","加分：React 19 的 React Compiler（原 Forget）可自动做记忆化，未来手写 memo 的必要性会下降。"],"bullets":[],"code":[],"note":"","text":"useMemo、useCallback、React.memo 的区别与滥用问题？ React.memo：高阶组件，对 props 做浅比较，props 不变时跳过整个组件重渲染（组件级缓存）。 useMemo：缓存「计算结果」，依赖不变时复用值（值级缓存），适合昂贵计算或需要稳定引用的对象/数组（避免子组件因引用变化重渲染）。 useCallback：缓存「函数引用」，等价于 useMemo(() => fn, deps)，主要为了配合 React.memo 与作为 effect 依赖时保持引用稳定。 注意三者都是「缓存 + 依赖比较」，不是「性能优化万能药」：缓存本身有比较与内存成本，组件很轻或 props 每次都变时反而更慢；正确做法是先测量（React DevTools Profiler）再优化；且必须保证 deps 正确，否则会拿到旧值。 加分：React 19 的 React Compiler（原 Forget）可自动做记忆化，未来手写 memo 的必要性会下降。"},{"id":155,"num":"Q155","tag":"高频","title":"useState / useReducer / useContext / useRef 各自适用什么？","answers":["useState：简单独立状态；useReducer：多个子值互相依赖、状态转移逻辑复杂（用 dispatch + reducer 更可测、可预测），或需要把更新逻辑下传给深层组件（传 dispatch 比传多个 setter 稳定）；useContext：跨层级共享「低频变化」的全局数据（主题、locale、登录态），但 context 变化会让所有消费组件重渲染，高频状态应拆 context / 配合状态库 / 用 useSyncExternalStore；useRef：保存不触发渲染的可变值（DOM 引用、定时器 ID、上一次的值、最新值），修改 .ref.current 不会重渲染。","forwardRef + useImperativeHandle 用于父组件调用子组件暴露的方法（Vue 里对应 defineExpose）。"],"bullets":[],"code":[],"note":"","text":"useState / useReducer / useContext / useRef 各自适用什么？ useState：简单独立状态；useReducer：多个子值互相依赖、状态转移逻辑复杂（用 dispatch + reducer 更可测、可预测），或需要把更新逻辑下传给深层组件（传 dispatch 比传多个 setter 稳定）；useContext：跨层级共享「低频变化」的全局数据（主题、locale、登录态），但 context 变化会让所有消费组件重渲染，高频状态应拆 context / 配合状态库 / 用 useSyncExternalStore；useRef：保存不触发渲染的可变值（DOM 引用、定时器 ID、上一次的值、最新值），修改 .ref.current 不会重渲染。 forwardRef + useImperativeHandle 用于父组件调用子组件暴露的方法（Vue 里对应 defineExpose）。"},{"id":156,"num":"Q156","tag":"必考","title":"React 18/19 并发特性有哪些？解决什么问题？","answers":["startTransition / useTransition：把更新标记为「非紧急」（如输入时过滤大列表），React 可中断它去优先响应输入，isPending 可显示 loading；解决「输入卡顿」与「渲染阻塞交互」。","useDeferredValue：延迟某个值的更新（类似防抖但由 React 调度，可中断、不丢中间态），适合搜索结果列表。","Suspense：让组件在「等待数据/代码」时声明式展示 fallback，配合 lazy 做代码分割、配合支持 Suspense 的数据源做流式渲染。","React 19 新增：Actions（useActionState / useOptimistic / form action，处理表单提交与乐观更新、自动处理 pending 与错误）、use()（可在渲染中读取 Promise 或 Context，甚至可在条件里调用）、ref 作为 prop（不再需要 forwardRef）、服务端组件 RSC 与 Server Actions、改进的水合错误与资源预加载 API。","核心心智：并发不是「并行计算」，而是「可中断、可丢弃、可重来、带优先级的渲染」，让高优先级交互不被低优先级渲染卡住。"],"bullets":[],"code":[],"note":"","text":"React 18/19 并发特性有哪些？解决什么问题？ startTransition / useTransition：把更新标记为「非紧急」（如输入时过滤大列表），React 可中断它去优先响应输入，isPending 可显示 loading；解决「输入卡顿」与「渲染阻塞交互」。 useDeferredValue：延迟某个值的更新（类似防抖但由 React 调度，可中断、不丢中间态），适合搜索结果列表。 Suspense：让组件在「等待数据/代码」时声明式展示 fallback，配合 lazy 做代码分割、配合支持 Suspense 的数据源做流式渲染。 React 19 新增：Actions（useActionState / useOptimistic / form action，处理表单提交与乐观更新、自动处理 pending 与错误）、use()（可在渲染中读取 Promise 或 Context，甚至可在条件里调用）、ref 作为 prop（不再需要 forwardRef）、服务端组件 RSC 与 Server Actions、改进的水合错误与资源预加载 API。 核心心智：并发不是「并行计算」，而是「可中断、可丢弃、可重来、带优先级的渲染」，让高优先级交互不被低优先级渲染卡住。"},{"id":157,"num":"Q157","tag":"原理","title":"React 合成事件（SyntheticEvent）机制？与原生事件区别？","answers":["React 把事件委托到根节点（React 17 起是 root container，16 及之前是 document），用统一插件系统把原生事件包装成 SyntheticEvent，抹平浏览器差异，并按组件树模拟捕获/冒泡。","区别：① 命名用小驼峰 onClick；② 传函数而非字符串；③ 阻止默认行为用 preventDefault（不能 return false）；④ SyntheticEvent 是池化对象（React 16 及之前事件回调后会被复用，异步读取需 e.persist()，React 17 已移除事件池）；⑤ 执行时机与原生事件顺序不同（React 17 后更贴近原生）；⑥ 想阻止原生监听器要用 e.nativeEvent.stopImmediatePropagation()。"],"bullets":[],"code":[],"note":"追问：为什么事件委托到 root 而不是 document？避免多版本 React 共存、嵌套独立应用时事件串扰，也让事件与所属 root 对应，利于 Suspense / 微前端。","text":"React 合成事件（SyntheticEvent）机制？与原生事件区别？ React 把事件委托到根节点（React 17 起是 root container，16 及之前是 document），用统一插件系统把原生事件包装成 SyntheticEvent，抹平浏览器差异，并按组件树模拟捕获/冒泡。 区别：① 命名用小驼峰 onClick；② 传函数而非字符串；③ 阻止默认行为用 preventDefault（不能 return false）；④ SyntheticEvent 是池化对象（React 16 及之前事件回调后会被复用，异步读取需 e.persist()，React 17 已移除事件池）；⑤ 执行时机与原生事件顺序不同（React 17 后更贴近原生）；⑥ 想阻止原生监听器要用 e.nativeEvent.stopImmediatePropagation()。 追问：为什么事件委托到 root 而不是 document？避免多版本 React 共存、嵌套独立应用时事件串扰，也让事件与所属 root 对应，利于 Suspense / 微前端。"},{"id":158,"num":"Q158","tag":"对比","title":"受控组件与非受控组件？","answers":["受控组件：表单值由 React state 驱动（value + onChange），单一数据源、便于即时校验、联动、提交前处理、动态设值；但每次输入都触发重渲染，大表单有性能成本。","非受控组件：值由 DOM 自己维护，通过 ref / defaultValue 读取，代码少、性能好、便于集成第三方 DOM 库；但难以实时校验与联动。","实践：绝大多数场景用受控；文件上传 <input type=file> 只能非受控；超大表单可用非受控 + FormData，或用 react-hook-form（基于非受控 + 订阅，减少重渲染）。"],"bullets":[],"code":[],"note":"","text":"受控组件与非受控组件？ 受控组件：表单值由 React state 驱动（value + onChange），单一数据源、便于即时校验、联动、提交前处理、动态设值；但每次输入都触发重渲染，大表单有性能成本。 非受控组件：值由 DOM 自己维护，通过 ref / defaultValue 读取，代码少、性能好、便于集成第三方 DOM 库；但难以实时校验与联动。 实践：绝大多数场景用受控；文件上传 <input type=file> 只能非受控；超大表单可用非受控 + FormData，或用 react-hook-form（基于非受控 + 订阅，减少重渲染）。"},{"id":159,"num":"Q159","tag":"原理","title":"React 的 diff 算法与 key？","answers":["React 采用三大启发式策略把 O(n³) 降到近似 O(n)：① 只做同层比较，跨层移动直接删除旧子树并重建；② 不同类型元素生成不同树，直接替换；③ 用 key 标识同层子节点的稳定性。","单节点 diff：key 与 type 都相同则复用 Fiber 并更新属性；key 相同 type 不同则删除重建；key 不同直接视为不同节点。","数组 diff：React 会把老节点按 key 存 Map（或按顺序线性比对），遍历新数组，用 lastPlacedIndex 判断是否需要移动——只往后移动、不往前搬（这也是「把最后一项移到最前面性能差」的原因）。","key 必须是稳定、唯一、在兄弟节点间不重复的值；用 index 作 key 在列表头插入/排序时会导致状态错位与不必要的重建。"],"bullets":[],"code":[],"note":"","text":"React 的 diff 算法与 key？ React 采用三大启发式策略把 O(n³) 降到近似 O(n)：① 只做同层比较，跨层移动直接删除旧子树并重建；② 不同类型元素生成不同树，直接替换；③ 用 key 标识同层子节点的稳定性。 单节点 diff：key 与 type 都相同则复用 Fiber 并更新属性；key 相同 type 不同则删除重建；key 不同直接视为不同节点。 数组 diff：React 会把老节点按 key 存 Map（或按顺序线性比对），遍历新数组，用 lastPlacedIndex 判断是否需要移动——只往后移动、不往前搬（这也是「把最后一项移到最前面性能差」的原因）。 key 必须是稳定、唯一、在兄弟节点间不重复的值；用 index 作 key 在列表头插入/排序时会导致状态错位与不必要的重建。"},{"id":160,"num":"Q160","tag":"原理","title":"虚拟 DOM 一定比直接操作 DOM 快吗？","answers":["不一定。虚拟 DOM 的价值不是「绝对更快」，而是「提供一个可声明、可批处理、可跨平台、可自动做最小更新的抽象层」，让开发者不必手动管理 DOM；在复杂频繁更新的场景，diff + 批量提交通常优于手写全量重排；但单次精确 DOM 操作（如只改一个文本节点）原生更快。","现代框架的差异化在于「更新粒度」：React 每次状态变更从组件根重新 render 再 diff；Vue 通过响应式依赖收集能精确知道哪个组件需要更新（组件级细粒度），Vue3 进一步用 PatchFlag 做到节点内动态属性级；Svelte / Solid 走编译期无虚拟 DOM 路线，直接生成精确更新代码。","加分：能讲出「虚拟 DOM 的开销 = 创建 VNode + diff + patch」，以及为什么 React 需要 memo 而 Vue 常常不需要。"],"bullets":[],"code":[],"note":"","text":"虚拟 DOM 一定比直接操作 DOM 快吗？ 不一定。虚拟 DOM 的价值不是「绝对更快」，而是「提供一个可声明、可批处理、可跨平台、可自动做最小更新的抽象层」，让开发者不必手动管理 DOM；在复杂频繁更新的场景，diff + 批量提交通常优于手写全量重排；但单次精确 DOM 操作（如只改一个文本节点）原生更快。 现代框架的差异化在于「更新粒度」：React 每次状态变更从组件根重新 render 再 diff；Vue 通过响应式依赖收集能精确知道哪个组件需要更新（组件级细粒度），Vue3 进一步用 PatchFlag 做到节点内动态属性级；Svelte / Solid 走编译期无虚拟 DOM 路线，直接生成精确更新代码。 加分：能讲出「虚拟 DOM 的开销 = 创建 VNode + diff + patch」，以及为什么 React 需要 memo 而 Vue 常常不需要。"},{"id":161,"num":"Q161","tag":"场景","title":"useState 的实现原理？为什么函数组件能保存状态？","answers":["状态并不存在函数里，而是挂在 FiberNode.memoizedState 的 Hook 链表上；组件函数每次渲染只是重新执行，useState 读取当前 Hook 节点的值并返回 [state, dispatch]；dispatch 把更新对象（update）加入该 Hook 的 queue，并调度一次重新渲染，下次渲染时 reducer 依次计算 queue 得到新 state。","因为链表按调用顺序对应，所以 Hook 必须稳定顺序调用；多个 useState 就是多个链表节点。手写极简 useState / useEffect 见第 7 天。"],"bullets":[],"code":[],"note":"","text":"useState 的实现原理？为什么函数组件能保存状态？ 状态并不存在函数里，而是挂在 FiberNode.memoizedState 的 Hook 链表上；组件函数每次渲染只是重新执行，useState 读取当前 Hook 节点的值并返回 [state, dispatch]；dispatch 把更新对象（update）加入该 Hook 的 queue，并调度一次重新渲染，下次渲染时 reducer 依次计算 queue 得到新 state。 因为链表按调用顺序对应，所以 Hook 必须稳定顺序调用；多个 useState 就是多个链表节点。手写极简 useState / useEffect 见第 7 天。"},{"id":162,"num":"Q162","tag":"场景","title":"React 性能优化清单？","answers":["① 先测量：React DevTools Profiler / Lighthouse 定位真正慢的组件与 commit 耗时；② 减少不必要的重渲染：React.memo + 稳定 props（useCallback/useMemo）、状态下沉、组件拆分、把大 Context 拆小或用 useSyncExternalStore；③ 列表用稳定 key、大数据用虚拟滚动（react-window / react-virtual）；④ 代码分割 React.lazy + Suspense / 路由级懒加载；⑤ 昂贵计算 useMemo、长任务用 useTransition / useDeferredValue 让位给交互；⑥ 避免在 render 里创建新对象/函数直接传给 memo 子组件；⑦ 图片懒加载与尺寸占位（减少 CLS）；⑧ 用生产构建（dev 模式慢数倍）。","加分：能说出「优化前先确认是 CPU 密集还是渲染量过大」——前者拆任务/Worker，后者减少渲染节点数。"],"bullets":[],"code":[],"note":"","text":"React 性能优化清单？ ① 先测量：React DevTools Profiler / Lighthouse 定位真正慢的组件与 commit 耗时；② 减少不必要的重渲染：React.memo + 稳定 props（useCallback/useMemo）、状态下沉、组件拆分、把大 Context 拆小或用 useSyncExternalStore；③ 列表用稳定 key、大数据用虚拟滚动（react-window / react-virtual）；④ 代码分割 React.lazy + Suspense / 路由级懒加载；⑤ 昂贵计算 useMemo、长任务用 useTransition / useDeferredValue 让位给交互；⑥ 避免在 render 里创建新对象/函数直接传给 memo 子组件；⑦ 图片懒加载与尺寸占位（减少 CLS）；⑧ 用生产构建（dev 模式慢数倍）。 加分：能说出「优化前先确认是 CPU 密集还是渲染量过大」——前者拆任务/Worker，后者减少渲染节点数。"}]},{"id":"day5-s3","day":5,"title":"5.3 框架对比、状态管理与渲染模式","note":"","questions":[{"id":163,"num":"Q163","tag":"高频","title":"Vue 与 React 的本质区别？","answers":["更新粒度：Vue 基于响应式依赖收集，数据变化时精确知道哪些组件/节点要更新，默认「细粒度」；React 基于不可变数据与自顶向下重新渲染，靠 diff 与 memo 控制范围，默认「粗粒度但可预测」。","模板 vs JSX：Vue 用模板（编译期可做静态分析、PatchFlag、静态提升，优化空间大、上手容易）；React 用 JSX（JS 全表达能力、灵活，但编译期优化信息少）。","心智模型：Vue 可变数据 + 自动追踪（写起来像改对象）；React 不可变 + 显式 setState / 函数式更新（更容易推理与时间旅行调试）。","API 演进：Vue Options API → Composition API；React class → Hooks → 并发 / RSC。生态：Vue 官方全家桶统一（Router/Pinia），React 社区方案百花齐放（Router/Redux/TanStack Query/Next.js）。","结论：没有优劣，选型看团队、生态、SSR 需求与人员熟悉度；面试切忌「踩一捧一」，讲设计取舍更容易拿高分。"],"bullets":[],"code":[],"note":"","text":"Vue 与 React 的本质区别？ 更新粒度：Vue 基于响应式依赖收集，数据变化时精确知道哪些组件/节点要更新，默认「细粒度」；React 基于不可变数据与自顶向下重新渲染，靠 diff 与 memo 控制范围，默认「粗粒度但可预测」。 模板 vs JSX：Vue 用模板（编译期可做静态分析、PatchFlag、静态提升，优化空间大、上手容易）；React 用 JSX（JS 全表达能力、灵活，但编译期优化信息少）。 心智模型：Vue 可变数据 + 自动追踪（写起来像改对象）；React 不可变 + 显式 setState / 函数式更新（更容易推理与时间旅行调试）。 API 演进：Vue Options API → Composition API；React class → Hooks → 并发 / RSC。生态：Vue 官方全家桶统一（Router/Pinia），React 社区方案百花齐放（Router/Redux/TanStack Query/Next.js）。 结论：没有优劣，选型看团队、生态、SSR 需求与人员熟悉度；面试切忌「踩一捧一」，讲设计取舍更容易拿高分。"},{"id":164,"num":"Q164","tag":"对比","title":"CSR、SSR、SSG、ISR、RSC 分别是什么？","answers":["CSR（客户端渲染）：首屏 HTML 空壳，JS 下载执行后才渲染，首屏慢、SEO 差，但前后端分离、交互切换快、服务器压力小。","SSR（服务端渲染）：每次请求在服务端生成完整 HTML，首屏快、SEO 好，但服务器有渲染压力、TTFB 变长、需要 hydration（水合）且存在双端代码约束（window/document 不可用）。","SSG（静态站点生成）：构建时预生成 HTML，可直接 CDN 托管，性能与 SEO 最佳，适合内容型站点（文档、博客、官网），缺点是数据更新要重新构建。","ISR（增量静态再生）：SSG + 按时间间隔/按需重新生成指定页面，兼顾静态性能与数据新鲜度（Next.js）。","RSC（React Server Components）：组件分服务端/客户端两类，服务端组件只在服务端执行、不进入 JS bundle、可直接访问数据库，输出一种可流式传输的中间表示；客户端组件带 'use client' 标记负责交互。收益是包体积更小、数据获取更近、减少客户端瀑布请求；代价是心智模型与边界约束复杂。","加分：hydration 的坑——服务端与客户端渲染结果不一致会报错/重渲染，避免在渲染中读 Date.now()/Math.random()/window；流式 SSR + 选择性水合可改善 TTI。"],"bullets":[],"code":[],"note":"","text":"CSR、SSR、SSG、ISR、RSC 分别是什么？ CSR（客户端渲染）：首屏 HTML 空壳，JS 下载执行后才渲染，首屏慢、SEO 差，但前后端分离、交互切换快、服务器压力小。 SSR（服务端渲染）：每次请求在服务端生成完整 HTML，首屏快、SEO 好，但服务器有渲染压力、TTFB 变长、需要 hydration（水合）且存在双端代码约束（window/document 不可用）。 SSG（静态站点生成）：构建时预生成 HTML，可直接 CDN 托管，性能与 SEO 最佳，适合内容型站点（文档、博客、官网），缺点是数据更新要重新构建。 ISR（增量静态再生）：SSG + 按时间间隔/按需重新生成指定页面，兼顾静态性能与数据新鲜度（Next.js）。 RSC（React Server Components）：组件分服务端/客户端两类，服务端组件只在服务端执行、不进入 JS bundle、可直接访问数据库，输出一种可流式传输的中间表示；客户端组件带 'use client' 标记负责交互。收益是包体积更小、数据获取更近、减少客户端瀑布请求；代价是心智模型与边界约束复杂。 加分：hydration 的坑——服务端与客户端渲染结果不一致会报错/重渲染，避免在渲染中读 Date.now()/Math.random()/window；流式 SSR + 选择性水合可改善 TTI。"},{"id":165,"num":"Q165","tag":"对比","title":"Redux、Zustand、MobX、Context 的选型？","answers":["Redux（含 Redux Toolkit）：单一 store、不可变状态、action → reducer 纯函数、可预测、devtools 时间旅行、中间件生态成熟；样板代码多（RTK 已大幅简化），适合大型团队协作与复杂状态流转。","Zustand：轻量 hooks API、基于 useSyncExternalStore 的外部 store、无 Provider、支持选择器粒度订阅与中间件，样板极少，中小型项目首选。","MobX：响应式/可变状态、自动追踪依赖，写法最简洁，但「魔法」较多、调试与可预测性弱于 Redux。","Context：适合低频全局配置（主题、locale、用户信息），不适合高频更新的业务状态（所有消费者重渲染 + 无细粒度订阅）。","加分：把「服务端状态」与「客户端状态」分开——接口数据优先用 TanStack Query / SWR（缓存、失效、重试、竞态、分页），别把接口响应一股脑塞进 Redux，这是现代 React 状态管理最重要的实践变化。"],"bullets":[],"code":[],"note":"","text":"Redux、Zustand、MobX、Context 的选型？ Redux（含 Redux Toolkit）：单一 store、不可变状态、action → reducer 纯函数、可预测、devtools 时间旅行、中间件生态成熟；样板代码多（RTK 已大幅简化），适合大型团队协作与复杂状态流转。 Zustand：轻量 hooks API、基于 useSyncExternalStore 的外部 store、无 Provider、支持选择器粒度订阅与中间件，样板极少，中小型项目首选。 MobX：响应式/可变状态、自动追踪依赖，写法最简洁，但「魔法」较多、调试与可预测性弱于 Redux。 Context：适合低频全局配置（主题、locale、用户信息），不适合高频更新的业务状态（所有消费者重渲染 + 无细粒度订阅）。 加分：把「服务端状态」与「客户端状态」分开——接口数据优先用 TanStack Query / SWR（缓存、失效、重试、竞态、分页），别把接口响应一股脑塞进 Redux，这是现代 React 状态管理最重要的实践变化。"},{"id":166,"num":"Q166","tag":"概念","title":"微前端解决了什么问题？常见方案与隔离手段？","answers":["解决：巨石应用拆分为多个可独立开发、独立构建、独立部署、技术栈可异构的子应用，实现团队自治与渐进式重构；同时带来运行时集成复杂度。","方案：iframe（隔离最彻底但体验差、通信与路由困难）、single-spa（路由调度层）、qiankun（基于 single-spa + import-html-entry，提供 JS 沙箱与样式隔离）、Module Federation（Webpack 5 / Vite 插件，构建期共享模块，运行时动态加载 remote）、Web Components / 无界（iframe + Shadow DOM 改良）。","隔离：JS 沙箱（Proxy 快照沙箱 / with + 代理 window，防止全局污染）、样式隔离（Shadow DOM 最彻底但弹窗穿透等有坑 / scoped CSS 前缀 / 动态样式表卸载）、路由与状态（主应用统一路由分发、应用间用自定义事件或全局 store 通信）、公共依赖（externals / shared 避免重复打包 React）。","风险：版本冲突、重复依赖体积、样式污染、子应用生命周期管理、监控与错误归因复杂、SEO 与首屏耗时。"],"bullets":[],"code":[],"note":"","text":"微前端解决了什么问题？常见方案与隔离手段？ 解决：巨石应用拆分为多个可独立开发、独立构建、独立部署、技术栈可异构的子应用，实现团队自治与渐进式重构；同时带来运行时集成复杂度。 方案：iframe（隔离最彻底但体验差、通信与路由困难）、single-spa（路由调度层）、qiankun（基于 single-spa + import-html-entry，提供 JS 沙箱与样式隔离）、Module Federation（Webpack 5 / Vite 插件，构建期共享模块，运行时动态加载 remote）、Web Components / 无界（iframe + Shadow DOM 改良）。 隔离：JS 沙箱（Proxy 快照沙箱 / with + 代理 window，防止全局污染）、样式隔离（Shadow DOM 最彻底但弹窗穿透等有坑 / scoped CSS 前缀 / 动态样式表卸载）、路由与状态（主应用统一路由分发、应用间用自定义事件或全局 store 通信）、公共依赖（externals / shared 避免重复打包 React）。 风险：版本冲突、重复依赖体积、样式污染、子应用生命周期管理、监控与错误归因复杂、SEO 与首屏耗时。"},{"id":167,"num":"Q167","tag":"场景","title":"Next.js / Nuxt 的核心能力？","answers":["Next.js：文件系统路由（App Router / Pages Router）、SSR/SSG/ISR/RSC、API Routes / Route Handlers、Server Actions、图片优化 next/image、字体优化、代码分割、middleware、增量水合与流式渲染。","Nuxt（Vue）：约定式目录、SSR/SSG/混合渲染、Nitro 服务端引擎（可部署到 Serverless/Edge）、auto-imports、useFetch/useAsyncData 处理 SSR 数据双端一致、模块生态与 layers。","共同价值：把渲染模式、路由、数据获取、构建部署这些「框架之上的框架」问题标准化，降低全栈门槛。"],"bullets":[],"code":[],"note":"","text":"Next.js / Nuxt 的核心能力？ Next.js：文件系统路由（App Router / Pages Router）、SSR/SSG/ISR/RSC、API Routes / Route Handlers、Server Actions、图片优化 next/image、字体优化、代码分割、middleware、增量水合与流式渲染。 Nuxt（Vue）：约定式目录、SSR/SSG/混合渲染、Nitro 服务端引擎（可部署到 Serverless/Edge）、auto-imports、useFetch/useAsyncData 处理 SSR 数据双端一致、模块生态与 layers。 共同价值：把渲染模式、路由、数据获取、构建部署这些「框架之上的框架」问题标准化，降低全栈门槛。"},{"id":168,"num":"Q168","tag":"场景","title":"项目里遇到过最难的框架问题是什么？（开放题答题模板）","answers":["答题结构：背景（什么场景、量级）→ 现象与量化指标（卡顿 X ms / 内存 X MB / LCP X s）→ 定位过程（用什么工具、排除了什么）→ 根因 → 方案（含取舍与备选方案）→ 结果与验证数据 → 沉淀（规范/工具/复盘）。","可用素材：长列表虚拟滚动、大表单受控重渲染、useEffect 竞态、key 用 index 导致表单错位、Context 过大导致全树重渲染、Pinia/Vuex 状态设计不合理、路由懒加载与预加载策略、SSR 水合不一致、打包体积过大（分析工具 + 分包 + 按需引入）。"],"bullets":[],"code":[],"note":"面试官真正想听的是「你怎么发现问题、怎么验证有效」，一定要带上具体数字与工具名，不要只说「我做了性能优化」。","text":"项目里遇到过最难的框架问题是什么？（开放题答题模板） 答题结构：背景（什么场景、量级）→ 现象与量化指标（卡顿 X ms / 内存 X MB / LCP X s）→ 定位过程（用什么工具、排除了什么）→ 根因 → 方案（含取舍与备选方案）→ 结果与验证数据 → 沉淀（规范/工具/复盘）。 可用素材：长列表虚拟滚动、大表单受控重渲染、useEffect 竞态、key 用 index 导致表单错位、Context 过大导致全树重渲染、Pinia/Vuex 状态设计不合理、路由懒加载与预加载策略、SSR 水合不一致、打包体积过大（分析工具 + 分包 + 按需引入）。 面试官真正想听的是「你怎么发现问题、怎么验证有效」，一定要带上具体数字与工具名，不要只说「我做了性能优化」。"}]}]},{"id":"day6","day":6,"title":"第 6 天｜工程化、TypeScript 与性能优化","short":"工程化、TypeScript 与性能优化","note":"目标：2026 年工程化已经从「加分项」变成「必考项」。答题从「会配置」升级到「会决策」：为什么选它、代价是什么、怎么量化效果。今天也补上 TypeScript 与 Node/Git 的常考八股。","sections":[{"id":"day6-s1","day":6,"title":"6.1 构建工具：Webpack 与 Vite","note":"","questions":[{"id":169,"num":"Q169","tag":"必考","title":"Webpack 的构建流程？Loader 与 Plugin 的区别？","answers":["流程：① 读取配置与 CLI 参数合并；② 从 entry 出发创建 Compiler，调用 run → compile，创建 Compilation；③ 用 resolver 解析模块路径，递归构建依赖图；④ 对匹配的文件调用对应 Loader 链（从右到左、从下到上）把非 JS 资源转成 JS 模块；⑤ 生成 AST 分析依赖与导出，包装成模块函数；⑥ 按 chunk 分组、生成 runtime 与 manifest；⑦ 输出 assets 到 output.path（emitAssets），全程通过 Tapable 的钩子广播生命周期事件。","Loader 是「文件转换器」：输入源码字符串、输出处理后的 JS 字符串（或 sourcemap），运行在模块加载阶段，专注单文件转换（babel-loader、css-loader、ts-loader、file-loader、vue-loader）。可链式、可同步/异步、可通过 pitch 阶段提前返回。","Plugin 是「构建生命周期扩展器」：通过 compiler.hooks.xxx.tap / tapAsync 接入任意钩子，能访问整个编译过程与资源，做打包优化、资源生成、环境变量注入、HTML 生成（HtmlWebpackPlugin）、清理（旧版 CleanPlugin）、分析（BundleAnalyzer）等。Plugin 能力覆盖 Loader，但 Loader 更专一。","加分：Loader 本质是函数（this 上有 context、可 emitFile），Plugin 是带 apply(compiler) 方法的类；Tapable 提供 SyncHook / AsyncSeriesHook 等钩子类型。"],"bullets":[],"code":[],"note":"","text":"Webpack 的构建流程？Loader 与 Plugin 的区别？ 流程：① 读取配置与 CLI 参数合并；② 从 entry 出发创建 Compiler，调用 run → compile，创建 Compilation；③ 用 resolver 解析模块路径，递归构建依赖图；④ 对匹配的文件调用对应 Loader 链（从右到左、从下到上）把非 JS 资源转成 JS 模块；⑤ 生成 AST 分析依赖与导出，包装成模块函数；⑥ 按 chunk 分组、生成 runtime 与 manifest；⑦ 输出 assets 到 output.path（emitAssets），全程通过 Tapable 的钩子广播生命周期事件。 Loader 是「文件转换器」：输入源码字符串、输出处理后的 JS 字符串（或 sourcemap），运行在模块加载阶段，专注单文件转换（babel-loader、css-loader、ts-loader、file-loader、vue-loader）。可链式、可同步/异步、可通过 pitch 阶段提前返回。 Plugin 是「构建生命周期扩展器」：通过 compiler.hooks.xxx.tap / tapAsync 接入任意钩子，能访问整个编译过程与资源，做打包优化、资源生成、环境变量注入、HTML 生成（HtmlWebpackPlugin）、清理（旧版 CleanPlugin）、分析（BundleAnalyzer）等。Plugin 能力覆盖 Loader，但 Loader 更专一。 加分：Loader 本质是函数（this 上有 context、可 emitFile），Plugin 是带 apply(compiler) 方法的类；Tapable 提供 SyncHook / AsyncSeriesHook 等钩子类型。"},{"id":170,"num":"Q170","tag":"高频","title":"Webpack 的优化手段有哪些？","answers":["构建速度：① 持久化缓存 cache: { type: 'filesystem' }（Webpack 5）；② babel-loader / ts-loader 开启缓存与 include/exclude 精确范围；③ 用 esbuild / swc 替代 Babel 做转译；④ thread-loader / parallel-webpack 并行（进程开销需权衡）；⑤ 缩小 resolve.modules / extensions / alias；⑥ module.noParse 跳过已打包的大库；⑦ externals 排除 CDN 引入的依赖；⑧ DllPlugin（旧方案，Webpack 5 已被持久缓存替代）；⑨ 升级到 Rspack / Vite / Turbopack。","产物体积：① Tree Shaking（ESM + production + sideEffects）；② splitChunks 拆 vendor / 公共模块 / 运行时；③ 动态 import() 路由级懒加载；④ 压缩 TerserPlugin / CssMinimizerPlugin、gzip/brotli 预压缩；⑤ 图片压缩与 WebP/AVIF、内联小图；⑥ Moment.js 等大库按需引入（babel-plugin-import、dayjs 替换）；⑦ browserslist 精准目标减少 polyfill。","运行性能：contenthash 长缓存、runtimeChunk 单独抽离避免 hash 连锁失效、prefetch/preload 提示、module federation 共享依赖。"],"bullets":[],"code":[],"note":"","text":"Webpack 的优化手段有哪些？ 构建速度：① 持久化缓存 cache: { type: 'filesystem' }（Webpack 5）；② babel-loader / ts-loader 开启缓存与 include/exclude 精确范围；③ 用 esbuild / swc 替代 Babel 做转译；④ thread-loader / parallel-webpack 并行（进程开销需权衡）；⑤ 缩小 resolve.modules / extensions / alias；⑥ module.noParse 跳过已打包的大库；⑦ externals 排除 CDN 引入的依赖；⑧ DllPlugin（旧方案，Webpack 5 已被持久缓存替代）；⑨ 升级到 Rspack / Vite / Turbopack。 产物体积：① Tree Shaking（ESM + production + sideEffects）；② splitChunks 拆 vendor / 公共模块 / 运行时；③ 动态 import() 路由级懒加载；④ 压缩 TerserPlugin / CssMinimizerPlugin、gzip/brotli 预压缩；⑤ 图片压缩与 WebP/AVIF、内联小图；⑥ Moment.js 等大库按需引入（babel-plugin-import、dayjs 替换）；⑦ browserslist 精准目标减少 polyfill。 运行性能：contenthash 长缓存、runtimeChunk 单独抽离避免 hash 连锁失效、prefetch/preload 提示、module federation 共享依赖。"},{"id":171,"num":"Q171","tag":"原理","title":"Webpack HMR（热更新）原理？","answers":["① 开发服务器启动，向浏览器注入 HMR runtime 客户端，与 dev-server 建立 WebSocket 长连接；② 文件变更触发重新编译，Webpack 生成「本次变更的模块清单 + 新模块代码（hot-update.json / hot-update.js）」并计算新的 hash；③ 服务端通过 WebSocket 推送 hash 与更新清单；④ 客户端 runtime 用 JSONP/动态 script 拉取增量 chunk；⑤ 调用 module.hot.accept 注册的回调，替换旧模块并重新执行受影响模块，若没有 accept 处理函数则冒泡到上层直到刷新整页。","对比 Vite 的 HMR：Vite 基于原生 ESM，直接让浏览器重新请求变更模块（带时间戳失效缓存），精度到模块级、无需重新打包整个 bundle，因此项目越大差距越明显。"],"bullets":[],"code":[],"note":"","text":"Webpack HMR（热更新）原理？ ① 开发服务器启动，向浏览器注入 HMR runtime 客户端，与 dev-server 建立 WebSocket 长连接；② 文件变更触发重新编译，Webpack 生成「本次变更的模块清单 + 新模块代码（hot-update.json / hot-update.js）」并计算新的 hash；③ 服务端通过 WebSocket 推送 hash 与更新清单；④ 客户端 runtime 用 JSONP/动态 script 拉取增量 chunk；⑤ 调用 module.hot.accept 注册的回调，替换旧模块并重新执行受影响模块，若没有 accept 处理函数则冒泡到上层直到刷新整页。 对比 Vite 的 HMR：Vite 基于原生 ESM，直接让浏览器重新请求变更模块（带时间戳失效缓存），精度到模块级、无需重新打包整个 bundle，因此项目越大差距越明显。"},{"id":172,"num":"Q172","tag":"必考","title":"Vite 为什么快？依赖预构建做了什么？","answers":["开发期快的原因：① 浏览器原生支持 ESM，Vite 只做「按需编译 + 单文件转换」，不做整包 bundle，冷启动时只处理入口与首屏需要的模块；② 依赖预构建：用 esbuild（Go 编写、并行、比 JS 工具快 10~100 倍）把 node_modules 里的第三方依赖提前转成 ESM 并合并成少数几个文件，解决两个问题——CommonJS/UMD 转 ESM、把 lodash 这类「一个包几百个模块」合并成单文件减少请求瀑布；③ 预构建结果缓存在 node_modules/.vite，依赖不变时秒启；④ HMR 基于 ESM 边界，只失效变更模块；⑤ 按需编译，源码用原生 ESM 交给浏览器，只在请求时做 TS/JSX/Vue SFC 转换。","生产构建仍用 Rollup（打包、Tree Shaking、代码分割、静态资源处理更成熟），因为原生 ESM 在生产环境会有大量请求、无法做细粒度优化；Vite 通过 build.rollupOptions 暴露配置。","局限：首屏大量模块请求时的「请求瀑布」、SSR/库模式配置更复杂、部分 CommonJS 生态兼容问题、老浏览器需 legacy 插件。"],"bullets":[],"code":[],"note":"","text":"Vite 为什么快？依赖预构建做了什么？ 开发期快的原因：① 浏览器原生支持 ESM，Vite 只做「按需编译 + 单文件转换」，不做整包 bundle，冷启动时只处理入口与首屏需要的模块；② 依赖预构建：用 esbuild（Go 编写、并行、比 JS 工具快 10~100 倍）把 node_modules 里的第三方依赖提前转成 ESM 并合并成少数几个文件，解决两个问题——CommonJS/UMD 转 ESM、把 lodash 这类「一个包几百个模块」合并成单文件减少请求瀑布；③ 预构建结果缓存在 node_modules/.vite，依赖不变时秒启；④ HMR 基于 ESM 边界，只失效变更模块；⑤ 按需编译，源码用原生 ESM 交给浏览器，只在请求时做 TS/JSX/Vue SFC 转换。 生产构建仍用 Rollup（打包、Tree Shaking、代码分割、静态资源处理更成熟），因为原生 ESM 在生产环境会有大量请求、无法做细粒度优化；Vite 通过 build.rollupOptions 暴露配置。 局限：首屏大量模块请求时的「请求瀑布」、SSR/库模式配置更复杂、部分 CommonJS 生态兼容问题、老浏览器需 legacy 插件。"},{"id":173,"num":"Q173","tag":"对比","title":"Vite 与 Webpack 怎么选？","answers":["Webpack：生态最全、loader/plugin 海量、对复杂场景（微前端 Module Federation、非标准资源、老项目、精细 chunk 控制）支持成熟； but 冷启动与 HMR 随项目增大线性变慢。","Vite：开发体验（冷启动、HMR）碾压，配置简洁，适合现代浏览器、Vue/React 新项目、SSR/库模式也基本够用；生产用 Rollup，超大型项目的构建产物优化能力略弱于 Webpack 的可控度。","决策口径：新项目默认 Vite；已有巨型 Webpack 项目迁移要评估插件替代成本，可先上 Rspack / esbuild-loader 渐进提速；需要 Module Federation 或极其定制化的构建流程时 Webpack 更稳。"],"bullets":[],"code":[],"note":"加分：能说出 esbuild（Go，快但不支持 AST 级插件/产物体量大）、SWC（Rust，转译 + 压缩，可替代 Babel）、Rspack（Rust，兼容 Webpack 生态）、Turbopack（Next.js，Rust 增量）的定位差异。","text":"Vite 与 Webpack 怎么选？ Webpack：生态最全、loader/plugin 海量、对复杂场景（微前端 Module Federation、非标准资源、老项目、精细 chunk 控制）支持成熟； but 冷启动与 HMR 随项目增大线性变慢。 Vite：开发体验（冷启动、HMR）碾压，配置简洁，适合现代浏览器、Vue/React 新项目、SSR/库模式也基本够用；生产用 Rollup，超大型项目的构建产物优化能力略弱于 Webpack 的可控度。 决策口径：新项目默认 Vite；已有巨型 Webpack 项目迁移要评估插件替代成本，可先上 Rspack / esbuild-loader 渐进提速；需要 Module Federation 或极其定制化的构建流程时 Webpack 更稳。 加分：能说出 esbuild（Go，快但不支持 AST 级插件/产物体量大）、SWC（Rust，转译 + 压缩，可替代 Babel）、Rspack（Rust，兼容 Webpack 生态）、Turbopack（Next.js，Rust 增量）的定位差异。"},{"id":174,"num":"Q174","tag":"原理","title":"Babel 的工作流程？polyfill 怎么打？","answers":["三阶段：解析 Parse（@babel/parser 生成 AST）→ 转换 Transform（@babel/traverse 遍历 AST，插件对节点增删改）→ 生成 Generate（@babel/generator 输出代码 + sourcemap）。","@babel/preset-env 根据 browserslist / targets 决定要转哪些语法；语法转换（箭头函数、解构）靠 transform 插件，新增 API（Promise、Array.includes、Object.fromEntries）需要 polyfill。","polyfill 方案：① @babel/polyfill（已废弃，全局污染）；② useBuiltIns: 'usage' + core-js（按用到的 API 按需引入，仍污染全局但体积可控）；③ @babel/plugin-transform-runtime + @babel/runtime-corejs3（沙箱化、不污染全局，适合库开发）；④ 现代做法：不再为老浏览器打包大量 polyfill，用 differential serving（module/nomodule 双产物）或只按 targets 精准注入。","加分：构建工具链里 Babel 只负责「降级语法」，模块打包与 Tree Shaking 由 Webpack/Rollup 负责；TS 用 babel 的 @babel/preset-typescript 只做类型擦除、不做类型检查（检查交给 tsc --noEmit 或 fork-ts-checker）。"],"bullets":[],"code":[],"note":"","text":"Babel 的工作流程？polyfill 怎么打？ 三阶段：解析 Parse（@babel/parser 生成 AST）→ 转换 Transform（@babel/traverse 遍历 AST，插件对节点增删改）→ 生成 Generate（@babel/generator 输出代码 + sourcemap）。 @babel/preset-env 根据 browserslist / targets 决定要转哪些语法；语法转换（箭头函数、解构）靠 transform 插件，新增 API（Promise、Array.includes、Object.fromEntries）需要 polyfill。 polyfill 方案：① @babel/polyfill（已废弃，全局污染）；② useBuiltIns: 'usage' + core-js（按用到的 API 按需引入，仍污染全局但体积可控）；③ @babel/plugin-transform-runtime + @babel/runtime-corejs3（沙箱化、不污染全局，适合库开发）；④ 现代做法：不再为老浏览器打包大量 polyfill，用 differential serving（module/nomodule 双产物）或只按 targets 精准注入。 加分：构建工具链里 Babel 只负责「降级语法」，模块打包与 Tree Shaking 由 Webpack/Rollup 负责；TS 用 babel 的 @babel/preset-typescript 只做类型擦除、不做类型检查（检查交给 tsc --noEmit 或 fork-ts-checker）。"},{"id":175,"num":"Q175","tag":"概念","title":"contenthash、hash、chunkhash 的区别？为什么长缓存要用 contenthash？","answers":["hash 是整次编译的全局哈希，任一文件变化会让所有产物文件名都变，缓存全部失效；chunkhash 按 chunk 计算，某个入口变化只影响该 chunk（但 CSS 与 JS 同 chunk 时会互相牵连）；contenthash 按「文件内容」计算，内容不变文件名就不变，最精确。","配套做法：① 输出文件名带 [name].[contenthash:8].js；② runtimeChunk: 'single' 把模块清单单独抽出，避免 runtime 变化引起所有 chunk hash 变化；③ splitChunks 抽 vendor，业务代码改动不影响第三方依赖的长缓存；④ HTML 入口用 no-cache，静态资源用 max-age=31536000, immutable；⑤ 保证 moduleIds/chunkIds 稳定（Webpack 5 默认 deterministic）。"],"bullets":[],"code":[],"note":"","text":"contenthash、hash、chunkhash 的区别？为什么长缓存要用 contenthash？ hash 是整次编译的全局哈希，任一文件变化会让所有产物文件名都变，缓存全部失效；chunkhash 按 chunk 计算，某个入口变化只影响该 chunk（但 CSS 与 JS 同 chunk 时会互相牵连）；contenthash 按「文件内容」计算，内容不变文件名就不变，最精确。 配套做法：① 输出文件名带 [name].[contenthash:8].js；② runtimeChunk: 'single' 把模块清单单独抽出，避免 runtime 变化引起所有 chunk hash 变化；③ splitChunks 抽 vendor，业务代码改动不影响第三方依赖的长缓存；④ HTML 入口用 no-cache，静态资源用 max-age=31536000, immutable；⑤ 保证 moduleIds/chunkIds 稳定（Webpack 5 默认 deterministic）。"}]},{"id":"day6-s2","day":6,"title":"6.2 包管理、Monorepo 与工程规范","note":"","questions":[{"id":176,"num":"Q176","tag":"高频","title":"pnpm 为什么比 npm / yarn 快、省空间？","answers":["① 全局内容寻址存储（content-addressable store）：所有包只在本机存一份，项目里用硬链接指向 store，多个项目/多版本复用同一份文件，避免 npm 的重复拷贝；② 符号链接 + 严格 node_modules 结构：只有直接依赖出现在顶层 node_modules，间接依赖放在 .pnpm 里通过软链访问，天然防止「幽灵依赖」（phantom dependency，代码能引用到未声明的包）与「依赖分身」；③ 并行安装与更快的解析算法；④ 原生支持 workspace / Monorepo，filter 命令可按包执行脚本。","代价：符号链接对某些工具（老版本 Webpack、部分 Node 原生模块、Electron 打包）兼容性需验证，可用 node-linker=hoisted 降级回扁平结构。","对比：npm v3+ 扁平化（带来幽灵依赖与分身问题）、yarn v1 扁平 + yarn.lock、yarn Berry PnP（无 node_modules，用 .pnp.cjs 映射，最严格但兼容性挑战大）。"],"bullets":[],"code":[],"note":"","text":"pnpm 为什么比 npm / yarn 快、省空间？ ① 全局内容寻址存储（content-addressable store）：所有包只在本机存一份，项目里用硬链接指向 store，多个项目/多版本复用同一份文件，避免 npm 的重复拷贝；② 符号链接 + 严格 node_modules 结构：只有直接依赖出现在顶层 node_modules，间接依赖放在 .pnpm 里通过软链访问，天然防止「幽灵依赖」（phantom dependency，代码能引用到未声明的包）与「依赖分身」；③ 并行安装与更快的解析算法；④ 原生支持 workspace / Monorepo，filter 命令可按包执行脚本。 代价：符号链接对某些工具（老版本 Webpack、部分 Node 原生模块、Electron 打包）兼容性需验证，可用 node-linker=hoisted 降级回扁平结构。 对比：npm v3+ 扁平化（带来幽灵依赖与分身问题）、yarn v1 扁平 + yarn.lock、yarn Berry PnP（无 node_modules，用 .pnp.cjs 映射，最严格但兼容性挑战大）。"},{"id":177,"num":"Q177","tag":"概念","title":"Monorepo 的价值与常见工具？","answers":["价值：多个包/应用共用一个仓库与统一依赖版本、原子化提交与跨包改动、共享配置与组件库、统一 CI/CD、便于重构；代价是仓库体积、构建与权限复杂度提升。","工具：pnpm workspace / yarn workspace / npm workspaces（依赖层）；Lerna（发布与版本管理，现多与 Nx 配合）；Turborepo / Nx（任务编排、增量构建与远程缓存，靠哈希跳过未变化的任务）；Changesets（语义化版本与 CHANGELOG）；Rush（超大规模）。","关键实践：只构建受影响包（--filter ...[origin/main]）、远程缓存复用、统一 lint/test/typecheck 流水线、避免所有包共用一份无边界的 tsconfig。"],"bullets":[],"code":[],"note":"","text":"Monorepo 的价值与常见工具？ 价值：多个包/应用共用一个仓库与统一依赖版本、原子化提交与跨包改动、共享配置与组件库、统一 CI/CD、便于重构；代价是仓库体积、构建与权限复杂度提升。 工具：pnpm workspace / yarn workspace / npm workspaces（依赖层）；Lerna（发布与版本管理，现多与 Nx 配合）；Turborepo / Nx（任务编排、增量构建与远程缓存，靠哈希跳过未变化的任务）；Changesets（语义化版本与 CHANGELOG）；Rush（超大规模）。 关键实践：只构建受影响包（--filter ...[origin/main]）、远程缓存复用、统一 lint/test/typecheck 流水线、避免所有包共用一份无边界的 tsconfig。"},{"id":178,"num":"Q178","tag":"基础","title":"Git 常考命令与工作流？","answers":["概念：工作区 → 暂存区（index）→ 本地仓库 → 远程仓库；三个区对应 add / commit / push。HEAD 指向当前分支最新提交，^ 与 ~ 表示父提交。","常考：merge vs rebase（merge 保留真实历史产生合并节点；rebase 变基使历史线性但改写提交，已 push 的公共分支禁止 rebase）；revert（生成一个反向新提交，安全）vs reset（移动 HEAD，--soft/--mixed/--hard 逐级危险）；cherry-pick 摘取单个提交；stash 暂存工作区；reflog 找回误删提交；bisect 二分定位引入 bug 的提交；tag 打版本。","分支模型：Git Flow（master/develop/feature/release/hotfix，偏重）、GitHub Flow / Trunk-Based（主干 + 短生命周期分支 + PR + CI，现代主流），配合 squash merge 保持主干整洁。"],"bullets":[],"code":[],"note":"追问：merge 冲突怎么解？看懂 <<<<<<< / ======= / >>>>>>> 三段，手动保留正确内容后 git add + commit；冲突多的功能分支可先 rebase 主分支再逐提交解冲突。","text":"Git 常考命令与工作流？ 概念：工作区 → 暂存区（index）→ 本地仓库 → 远程仓库；三个区对应 add / commit / push。HEAD 指向当前分支最新提交，^ 与 ~ 表示父提交。 常考：merge vs rebase（merge 保留真实历史产生合并节点；rebase 变基使历史线性但改写提交，已 push 的公共分支禁止 rebase）；revert（生成一个反向新提交，安全）vs reset（移动 HEAD，--soft/--mixed/--hard 逐级危险）；cherry-pick 摘取单个提交；stash 暂存工作区；reflog 找回误删提交；bisect 二分定位引入 bug 的提交；tag 打版本。 分支模型：Git Flow（master/develop/feature/release/hotfix，偏重）、GitHub Flow / Trunk-Based（主干 + 短生命周期分支 + PR + CI，现代主流），配合 squash merge 保持主干整洁。 追问：merge 冲突怎么解？看懂 <<<<<<< / ======= / >>>>>>> 三段，手动保留正确内容后 git add + commit；冲突多的功能分支可先 rebase 主分支再逐提交解冲突。"},{"id":179,"num":"Q179","tag":"基础","title":"前端代码规范与质量保障怎么做？","answers":["工具链：ESLint（代码质量）+ Prettier（格式）+ Stylelint（CSS）+ TypeScript（类型）+ EditorConfig（编辑器一致）+ husky / lint-staged（提交前只检查暂存文件）+ commitlint（约定式提交）+ CI 里跑 lint / typecheck / test / build。","测试：单元测试（Vitest / Jest，函数与 Hook）、组件测试（Testing Library / Vue Test Utils，测行为而非实现细节）、E2E（Playwright / Cypress，测关键业务流程）、覆盖率与快照（谨慎用快照，容易变成无意义变更）；TDD（先写测试）与 BDD（用业务语言描述行为）。","加分：能讲出「规范要自动化且卡在 CI，而不是靠人肉 review」，以及 lint-staged 为什么只对暂存文件跑（速度与避免历史债务阻塞）。"],"bullets":[],"code":[],"note":"","text":"前端代码规范与质量保障怎么做？ 工具链：ESLint（代码质量）+ Prettier（格式）+ Stylelint（CSS）+ TypeScript（类型）+ EditorConfig（编辑器一致）+ husky / lint-staged（提交前只检查暂存文件）+ commitlint（约定式提交）+ CI 里跑 lint / typecheck / test / build。 测试：单元测试（Vitest / Jest，函数与 Hook）、组件测试（Testing Library / Vue Test Utils，测行为而非实现细节）、E2E（Playwright / Cypress，测关键业务流程）、覆盖率与快照（谨慎用快照，容易变成无意义变更）；TDD（先写测试）与 BDD（用业务语言描述行为）。 加分：能讲出「规范要自动化且卡在 CI，而不是靠人肉 review」，以及 lint-staged 为什么只对暂存文件跑（速度与避免历史债务阻塞）。"},{"id":180,"num":"Q180","tag":"场景","title":"CI/CD 流水线怎么设计？灰度与回滚？","answers":["流程：PR 触发 lint / typecheck / unit test / build 预览环境 → 合并主干后构建产物（Docker 镜像或静态资源 + 内容 hash）→ 部署到测试/预发 → 自动化 E2E / 冒烟 → 灰度发布（按用户 ID/地域/百分比/白名单分流，或金丝雀）→ 观测指标（错误率、性能、转化）→ 全量。","回滚：静态资源保留历史版本 + HTML 入口可切换（秒级回滚）、镜像保留上一版本 tag、feature flag 一键关停；数据库变更要做向前兼容的双写/迁移。","加分：能说出「灰度看什么指标」（JS 错误率、接口 5xx、LCP/INP、核心转化漏斗）与「为什么静态资源用 hash 文件名 + HTML 不缓存」（回滚只需换 HTML 引用）。"],"bullets":[],"code":[],"note":"","text":"CI/CD 流水线怎么设计？灰度与回滚？ 流程：PR 触发 lint / typecheck / unit test / build 预览环境 → 合并主干后构建产物（Docker 镜像或静态资源 + 内容 hash）→ 部署到测试/预发 → 自动化 E2E / 冒烟 → 灰度发布（按用户 ID/地域/百分比/白名单分流，或金丝雀）→ 观测指标（错误率、性能、转化）→ 全量。 回滚：静态资源保留历史版本 + HTML 入口可切换（秒级回滚）、镜像保留上一版本 tag、feature flag 一键关停；数据库变更要做向前兼容的双写/迁移。 加分：能说出「灰度看什么指标」（JS 错误率、接口 5xx、LCP/INP、核心转化漏斗）与「为什么静态资源用 hash 文件名 + HTML 不缓存」（回滚只需换 HTML 引用）。"}]},{"id":"day6-s3","day":6,"title":"6.3 TypeScript","note":"","questions":[{"id":181,"num":"Q181","tag":"对比","title":"interface 与 type 的区别？","answers":["相同点：都能描述对象/函数形状、都可扩展、都能被实现。","差异：① interface 可被多次声明并自动合并（declaration merging，适合扩展第三方库类型），type 重复声明会报错；② interface 只能描述对象/函数/类结构，type 可描述任意类型（联合、交叉、原始类型别名、元组、映射类型、条件类型、模板字面量类型）；③ interface 可被 extends / implements，type 用 & 交叉实现扩展；④ type 支持 typeof / keyof / infer 等类型运算，interface 更适合对外暴露的公共 API（错误提示更友好、可合并）。","实践建议：描述对象/类结构优先 interface，需要联合/工具类型/类型运算时用 type；团队保持一致即可。"],"bullets":[],"code":[],"note":"","text":"interface 与 type 的区别？ 相同点：都能描述对象/函数形状、都可扩展、都能被实现。 差异：① interface 可被多次声明并自动合并（declaration merging，适合扩展第三方库类型），type 重复声明会报错；② interface 只能描述对象/函数/类结构，type 可描述任意类型（联合、交叉、原始类型别名、元组、映射类型、条件类型、模板字面量类型）；③ interface 可被 extends / implements，type 用 & 交叉实现扩展；④ type 支持 typeof / keyof / infer 等类型运算，interface 更适合对外暴露的公共 API（错误提示更友好、可合并）。 实践建议：描述对象/类结构优先 interface，需要联合/工具类型/类型运算时用 type；团队保持一致即可。"},{"id":182,"num":"Q182","tag":"必考","title":"any、unknown、never、void 的区别？","answers":["any：关闭类型检查，可赋任意值、可任意访问属性与调用，等价于退回 JS，具有「传染性」，应严格禁用（noImplicitAny / eslint no-explicit-any）。","unknown：类型安全的顶层类型，任何值都能赋给它，但使用前必须收窄（typeof / instanceof / 类型断言 / 类型保护），不能随便取属性或调用；适合替代 any 处理外部输入。","never：永不存在的值的类型，是底部类型；用于「永远抛错/死循环的函数返回值」、穷尽性检查（exhaustive check，switch default 里 const _: never = x）、以及条件类型里过滤（T extends never ? ...）。","void：函数没有返回值（与 undefined 不同：void 表示「不关心返回值」，所以返回 void 的函数可以返回任意值给回调使用）；undefined 是一个具体值类型。"],"bullets":[],"code":[],"note":"","text":"any、unknown、never、void 的区别？ any：关闭类型检查，可赋任意值、可任意访问属性与调用，等价于退回 JS，具有「传染性」，应严格禁用（noImplicitAny / eslint no-explicit-any）。 unknown：类型安全的顶层类型，任何值都能赋给它，但使用前必须收窄（typeof / instanceof / 类型断言 / 类型保护），不能随便取属性或调用；适合替代 any 处理外部输入。 never：永不存在的值的类型，是底部类型；用于「永远抛错/死循环的函数返回值」、穷尽性检查（exhaustive check，switch default 里 const _: never = x）、以及条件类型里过滤（T extends never ? ...）。 void：函数没有返回值（与 undefined 不同：void 表示「不关心返回值」，所以返回 void 的函数可以返回任意值给回调使用）；undefined 是一个具体值类型。"},{"id":183,"num":"Q183","tag":"必考","title":"泛型是什么？常见内置工具类型有哪些？","answers":["泛型是「类型参数化」，把类型当参数传入，让函数/类/接口在保持类型信息的同时复用（function identity<T>(arg: T): T；约束用 T extends Constraint；默认值 <T = string>）。","内置工具类型：Partial / Required / Readonly、Pick<T,K> / Omit<T,K>、Record<K,V>、Exclude<T,U> / Extract<T,U> / NonNullable<T>、ReturnType<F> / Parameters<F> / ConstructorParameters / InstanceType、Awaited<T>、Uppercase/Lowercase/Capitalize/Uncapitalize（模板字面量）、ThisParameterType / OmitThisParameter。","加分：能说出关键类型的底层实现——映射类型 `[K in keyof T]?: T[K]`、条件类型 `T extends U ? X : Y`、infer 推断、keyof 索引查询、分布式条件类型（裸类型参数 + 联合类型会逐个分发）；以及为什么判断两个类型完全相等要用 `(<T>() => T extends X ? 1 : 2) extends (<T>() => T extends Y ? 1 : 2) ? true : false` 这种技巧（避免分发与 any 干扰）。"],"bullets":[],"code":[],"note":"","text":"泛型是什么？常见内置工具类型有哪些？ 泛型是「类型参数化」，把类型当参数传入，让函数/类/接口在保持类型信息的同时复用（function identity<T>(arg: T): T；约束用 T extends Constraint；默认值 <T = string>）。 内置工具类型：Partial / Required / Readonly、Pick<T,K> / Omit<T,K>、Record<K,V>、Exclude<T,U> / Extract<T,U> / NonNullable<T>、ReturnType<F> / Parameters<F> / ConstructorParameters / InstanceType、Awaited<T>、Uppercase/Lowercase/Capitalize/Uncapitalize（模板字面量）、ThisParameterType / OmitThisParameter。 加分：能说出关键类型的底层实现——映射类型 `[K in keyof T]?: T[K]`、条件类型 `T extends U ? X : Y`、infer 推断、keyof 索引查询、分布式条件类型（裸类型参数 + 联合类型会逐个分发）；以及为什么判断两个类型完全相等要用 `(<T>() => T extends X ? 1 : 2) extends (<T>() => T extends Y ? 1 : 2) ? true : false` 这种技巧（避免分发与 any 干扰）。"},{"id":184,"num":"Q184","tag":"概念","title":"类型体操常见题：联合转交叉、DeepReadonly、获取路径类型？","answers":["联合转交叉：`type UnionToIntersection<U> = (U extends any ? (x: U) => void : never) extends (x: infer I) => void ? I : never`，利用函数参数位置的逆变与 infer 推导。","DeepReadonly：`type DeepReadonly<T> = T extends Function ? T : T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T`（注意处理数组、Map/Set、内置对象与循环引用，生产可直接用 type-fest）。","路径类型：`type Path<T> = ...` 用递归映射 + 模板字面量 `${K}.${Path<T[K]>}` 生成 'user.address.city' 这样的字符串联合。","面试策略：类型体操题先看「是否真的要手写」，能讲清映射类型 / 条件类型 / infer / 递归 / 分发这几个原语就够，不必死记答案。"],"bullets":[],"code":[],"note":"","text":"类型体操常见题：联合转交叉、DeepReadonly、获取路径类型？ 联合转交叉：`type UnionToIntersection<U> = (U extends any ? (x: U) => void : never) extends (x: infer I) => void ? I : never`，利用函数参数位置的逆变与 infer 推导。 DeepReadonly：`type DeepReadonly<T> = T extends Function ? T : T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T`（注意处理数组、Map/Set、内置对象与循环引用，生产可直接用 type-fest）。 路径类型：`type Path<T> = ...` 用递归映射 + 模板字面量 `${K}.${Path<T[K]>}` 生成 'user.address.city' 这样的字符串联合。 面试策略：类型体操题先看「是否真的要手写」，能讲清映射类型 / 条件类型 / infer / 递归 / 分发这几个原语就够，不必死记答案。"},{"id":185,"num":"Q185","tag":"概念","title":"类型保护、断言与声明文件？","answers":["类型保护：typeof / instanceof / in / 字面量相等判断，以及自定义类型谓词 `function isString(x: unknown): x is string { return typeof x === 'string' }`；配合控制流分析自动收窄。","断言：`as T` / 尖括号（JSX 里不能用）、非空断言 `!`、`as const`（把字面量收窄为只读字面量类型）、双重断言 `as unknown as T`（危险信号）。断言只是告诉编译器，不做运行时检查，真实边界要用 zod / io-ts 做运行时校验。","声明文件 .d.ts：declare 声明全局类型/模块，为无类型的 JS 库补类型（@types/*）；declare module '*.svg' 处理非代码资源；/// <reference> 引用；tsconfig 关键项：strict、noImplicitAny、strictNullChecks、target/module/moduleResolution、paths/baseUrl、jsx、skipLibCheck、isolatedModules、noEmit。"],"bullets":[],"code":[],"note":"","text":"类型保护、断言与声明文件？ 类型保护：typeof / instanceof / in / 字面量相等判断，以及自定义类型谓词 `function isString(x: unknown): x is string { return typeof x === 'string' }`；配合控制流分析自动收窄。 断言：`as T` / 尖括号（JSX 里不能用）、非空断言 `!`、`as const`（把字面量收窄为只读字面量类型）、双重断言 `as unknown as T`（危险信号）。断言只是告诉编译器，不做运行时检查，真实边界要用 zod / io-ts 做运行时校验。 声明文件 .d.ts：declare 声明全局类型/模块，为无类型的 JS 库补类型（@types/*）；declare module '*.svg' 处理非代码资源；/// <reference> 引用；tsconfig 关键项：strict、noImplicitAny、strictNullChecks、target/module/moduleResolution、paths/baseUrl、jsx、skipLibCheck、isolatedModules、noEmit。"},{"id":186,"num":"Q186","tag":"对比","title":"协变、逆变、双变与 TS 的严格函数类型？","answers":["协变（covariant）：子类型可以赋给父类型（返回值位置，Dog → Animal 可赋给 () => Animal）；逆变（contravariant）：参数位置方向相反（处理 Animal 的函数可以赋给「处理 Dog 的函数」类型），双变（bivariant）两者皆可（不安全）。","strictFunctionTypes 开启后，函数参数按逆变检查（方法声明仍是双变以保持兼容），这正是「函数参数位置 infer 能得到交叉类型」的原理。","实践意义：理解它才能解释「为什么 (x: Dog) => void 不能随便赋给 (x: Animal) => void」以及事件回调、比较函数的类型报错。"],"bullets":[],"code":[],"note":"","text":"协变、逆变、双变与 TS 的严格函数类型？ 协变（covariant）：子类型可以赋给父类型（返回值位置，Dog → Animal 可赋给 () => Animal）；逆变（contravariant）：参数位置方向相反（处理 Animal 的函数可以赋给「处理 Dog 的函数」类型），双变（bivariant）两者皆可（不安全）。 strictFunctionTypes 开启后，函数参数按逆变检查（方法声明仍是双变以保持兼容），这正是「函数参数位置 infer 能得到交叉类型」的原理。 实践意义：理解它才能解释「为什么 (x: Dog) => void 不能随便赋给 (x: Animal) => void」以及事件回调、比较函数的类型报错。"}]},{"id":"day6-s4","day":6,"title":"6.4 性能优化体系","note":"","questions":[{"id":187,"num":"Q187","tag":"必考","title":"首屏加载慢，你从哪里下手？（完整排查思路）","answers":["先测量再优化，顺序是：① 用 Lighthouse / WebPageTest / RUM 拿到真实数据，拆指标：TTFB → FCP → LCP → INP/TBT → CLS，定位瓶颈阶段；② 网络阶段：TTFB 高查服务端/数据库/CDN/HTTP 版本；资源下载慢查体积（bundle 分析）、压缩（br/gzip）、CDN、HTTP/2/3、缓存命中率、DNS/TLS 握手（preconnect）；③ 解析阶段：查 JS 阻塞（defer/async、代码分割）、CSS 阻塞（内联关键 CSS）、字体 FOIT（font-display: swap + preload）、第三方脚本（延迟加载/沙箱）；④ 渲染阶段：查 LCP 元素（通常是大图/标题），做优先级提示（fetchpriority=\"high\"、preload）、SSR/SSG、骨架屏、避免客户端瀑布请求；⑤ 交互阶段：拆长任务、Web Worker、虚拟列表、防抖节流、useTransition；⑥ 稳定性：图片/广告/iframe 设宽高或 aspect-ratio、预留骨架，降低 CLS。","优化后必须用同口径数据验证（实验室 + 线上 RUM P75/P95），并说明取舍（预加载过多会抢带宽、SSR 增加服务器成本、内联 CSS 失去缓存）。"],"bullets":[],"code":[],"note":"高分信号：主动说「不要用 Lighthouse 分数当结论，要看分位数和真实用户指标」「先定量再动手」「每个优化给出预期收益与副作用」。","text":"首屏加载慢，你从哪里下手？（完整排查思路） 先测量再优化，顺序是：① 用 Lighthouse / WebPageTest / RUM 拿到真实数据，拆指标：TTFB → FCP → LCP → INP/TBT → CLS，定位瓶颈阶段；② 网络阶段：TTFB 高查服务端/数据库/CDN/HTTP 版本；资源下载慢查体积（bundle 分析）、压缩（br/gzip）、CDN、HTTP/2/3、缓存命中率、DNS/TLS 握手（preconnect）；③ 解析阶段：查 JS 阻塞（defer/async、代码分割）、CSS 阻塞（内联关键 CSS）、字体 FOIT（font-display: swap + preload）、第三方脚本（延迟加载/沙箱）；④ 渲染阶段：查 LCP 元素（通常是大图/标题），做优先级提示（fetchpriority=\"high\"、preload）、SSR/SSG、骨架屏、避免客户端瀑布请求；⑤ 交互阶段：拆长任务、Web Worker、虚拟列表、防抖节流、useTransition；⑥ 稳定性：图片/广告/iframe 设宽高或 aspect-ratio、预留骨架，降低 CLS。 优化后必须用同口径数据验证（实验室 + 线上 RUM P75/P95），并说明取舍（预加载过多会抢带宽、SSR 增加服务器成本、内联 CSS 失去缓存）。 高分信号：主动说「不要用 Lighthouse 分数当结论，要看分位数和真实用户指标」「先定量再动手」「每个优化给出预期收益与副作用」。"},{"id":188,"num":"Q188","tag":"高频","title":"Core Web Vitals 三项指标怎么优化？","answers":["LCP（最大内容绘制，目标 ≤2.5s）：优化 TTFB（CDN/缓存/SSR）、给 LCP 图片 preload + fetchpriority=\"high\" + 合适尺寸与 WebP/AVIF、避免懒加载首屏图、内联关键 CSS、剔除渲染阻塞 JS、字体 font-display: swap / preload、减少客户端数据瀑布（SSR 或并行请求）。","INP（交互到下一帧，目标 ≤200ms，已取代 FID）：拆分超过 50ms 的长任务（scheduler.yield / setTimeout 分片 / requestIdleCallback）、把计算移到 Web Worker、减少事件回调里的同步 DOM 读写、避免大范围重渲染（memo / 状态下沉 / 虚拟列表）、用 useTransition 让位给输入、减少第三方脚本。","CLS（累积布局偏移，目标 ≤0.1）：所有 img/iframe/video 显式 width/height 或 aspect-ratio、字体加载用 size-adjust / fallback 度量覆盖、不要在已有内容上方动态插入 banner/广告（预留空间）、动画只用 transform/opacity、避免用 setTimeout 做布局位移。","测量：web-vitals 库 / PerformanceObserver 采集 LCP、INP、CLS 条目，按 P75 上报；DevTools Performance 的 Experience / Layout Shifts 轨道定位具体元素。"],"bullets":[],"code":[],"note":"","text":"Core Web Vitals 三项指标怎么优化？ LCP（最大内容绘制，目标 ≤2.5s）：优化 TTFB（CDN/缓存/SSR）、给 LCP 图片 preload + fetchpriority=\"high\" + 合适尺寸与 WebP/AVIF、避免懒加载首屏图、内联关键 CSS、剔除渲染阻塞 JS、字体 font-display: swap / preload、减少客户端数据瀑布（SSR 或并行请求）。 INP（交互到下一帧，目标 ≤200ms，已取代 FID）：拆分超过 50ms 的长任务（scheduler.yield / setTimeout 分片 / requestIdleCallback）、把计算移到 Web Worker、减少事件回调里的同步 DOM 读写、避免大范围重渲染（memo / 状态下沉 / 虚拟列表）、用 useTransition 让位给输入、减少第三方脚本。 CLS（累积布局偏移，目标 ≤0.1）：所有 img/iframe/video 显式 width/height 或 aspect-ratio、字体加载用 size-adjust / fallback 度量覆盖、不要在已有内容上方动态插入 banner/广告（预留空间）、动画只用 transform/opacity、避免用 setTimeout 做布局位移。 测量：web-vitals 库 / PerformanceObserver 采集 LCP、INP、CLS 条目，按 P75 上报；DevTools Performance 的 Experience / Layout Shifts 轨道定位具体元素。"},{"id":189,"num":"Q189","tag":"场景","title":"代码分割与懒加载怎么做？预加载策略？","answers":["分割：路由级 `React.lazy(() => import('./Page'))` / Vue 的 `defineAsyncComponent` 或路由 component: () => import()；组件级按交互懒加载（弹窗、富文本编辑器、图表库）；Webpack splitChunks / Vite manualChunks 抽 vendor 与公共模块；动态 import 支持魔法注释 webpackPrefetch / webpackPreload 或 Vite 的 /* @vite-ignore */。","prefetch vs preload：preload 用于「当前页面马上要用」的高优先级资源（关键字体、LCP 图、首屏 JS），prefetch 用于「下一次导航可能用到」的低优先级资源（闲置时下载）；滥用 prefetch 会浪费用户流量。","注意：分包不是越细越好——过细导致请求瀑布与 HTTP/2 头部开销，过粗导致首屏加载无用代码；按「路由 + 变更频率 + 体积阈值」三个维度决策，并用 bundle analyzer 驗證。"],"bullets":[],"code":[],"note":"","text":"代码分割与懒加载怎么做？预加载策略？ 分割：路由级 `React.lazy(() => import('./Page'))` / Vue 的 `defineAsyncComponent` 或路由 component: () => import()；组件级按交互懒加载（弹窗、富文本编辑器、图表库）；Webpack splitChunks / Vite manualChunks 抽 vendor 与公共模块；动态 import 支持魔法注释 webpackPrefetch / webpackPreload 或 Vite 的 /* @vite-ignore */。 prefetch vs preload：preload 用于「当前页面马上要用」的高优先级资源（关键字体、LCP 图、首屏 JS），prefetch 用于「下一次导航可能用到」的低优先级资源（闲置时下载）；滥用 prefetch 会浪费用户流量。 注意：分包不是越细越好——过细导致请求瀑布与 HTTP/2 头部开销，过粗导致首屏加载无用代码；按「路由 + 变更频率 + 体积阈值」三个维度决策，并用 bundle analyzer 驗證。"},{"id":190,"num":"Q190","tag":"场景","title":"图片与字体优化清单？","answers":["图片：选对格式（WebP/AVIF，照片用有损、图标用 SVG）、按 DPR 提供 srcset/sizes 响应式图片、压缩与质量调优、懒加载 loading=\"lazy\"（首屏 LCP 图不要懒加载并加 fetchpriority=\"high\"）、显式宽高防 CLS、CDN 图片处理（裁剪/缩放/格式协商 Accept）、雪碧图在 HTTP/2 后基本不再需要、关键小图内联 base64（<4KB）。","字体：font-display: swap / optional 避免 FOIT、preload 关键字体、子集化（中文按需分包，unicode-range）、用 woff2、减少字重数量、用 size-adjust / ascent-override 让 fallback 字体度量接近，减少切换时的 CLS、系统字体栈兜底。"],"bullets":[],"code":[],"note":"","text":"图片与字体优化清单？ 图片：选对格式（WebP/AVIF，照片用有损、图标用 SVG）、按 DPR 提供 srcset/sizes 响应式图片、压缩与质量调优、懒加载 loading=\"lazy\"（首屏 LCP 图不要懒加载并加 fetchpriority=\"high\"）、显式宽高防 CLS、CDN 图片处理（裁剪/缩放/格式协商 Accept）、雪碧图在 HTTP/2 后基本不再需要、关键小图内联 base64（<4KB）。 字体：font-display: swap / optional 避免 FOIT、preload 关键字体、子集化（中文按需分包，unicode-range）、用 woff2、减少字重数量、用 size-adjust / ascent-override 让 fallback 字体度量接近，减少切换时的 CLS、系统字体栈兜底。"},{"id":191,"num":"Q191","tag":"场景","title":"大文件上传怎么做？（高频场景题 + 追问）","answers":["基础方案：切片（Blob.prototype.slice，常用 1~5MB）→ 计算文件 hash（Web Worker + spark-md5 抽样 hash，避免阻塞主线程）→ 并发上传（限制 3~6 路，Promise 池）→ 服务端按 hash + index 存分片 → 全部完成后发合并请求 → 秒传（服务端已存在同 hash 直接返回）→ 断点续传（上传前先查已上传分片列表，只传缺失的）。","必答追问：① 分片大小怎么定？太小请求数多、触发限流与连接开销；太大单次失败重传代价高、内存占用大；一般 1~5MB，按网络类型与服务端限制动态调；② 失败重试：指数退避 + 最大次数，区分可重试错误（网络/5xx）与不可重试（4xx 参数错）；③ 断网恢复：本地持久化 uploadId 与已传分片，恢复后先校验再补传；④ 并发数：按浏览器同域连接上限与服务端负载压测给出数字（常见 3~6）；⑤ 服务端怎么知道传完：显式 merge 请求 + 分片计数/位图校验，或有分片落库后由定时任务扫描；⑥ 内存：用切片流式读取，别一次性 readAsArrayBuffer 整个大文件；hash 放 Worker；⑦ 安全：校验文件类型（魔数而非后缀）、大小限制、鉴权、分片归属用户、防重放。"],"bullets":[],"code":[],"note":"加分：能主动谈「可靠性与性能的平衡」并给出具体数字和理由，是这道题从及格到高分的分水岭。","text":"大文件上传怎么做？（高频场景题 + 追问） 基础方案：切片（Blob.prototype.slice，常用 1~5MB）→ 计算文件 hash（Web Worker + spark-md5 抽样 hash，避免阻塞主线程）→ 并发上传（限制 3~6 路，Promise 池）→ 服务端按 hash + index 存分片 → 全部完成后发合并请求 → 秒传（服务端已存在同 hash 直接返回）→ 断点续传（上传前先查已上传分片列表，只传缺失的）。 必答追问：① 分片大小怎么定？太小请求数多、触发限流与连接开销；太大单次失败重传代价高、内存占用大；一般 1~5MB，按网络类型与服务端限制动态调；② 失败重试：指数退避 + 最大次数，区分可重试错误（网络/5xx）与不可重试（4xx 参数错）；③ 断网恢复：本地持久化 uploadId 与已传分片，恢复后先校验再补传；④ 并发数：按浏览器同域连接上限与服务端负载压测给出数字（常见 3~6）；⑤ 服务端怎么知道传完：显式 merge 请求 + 分片计数/位图校验，或有分片落库后由定时任务扫描；⑥ 内存：用切片流式读取，别一次性 readAsArrayBuffer 整个大文件；hash 放 Worker；⑦ 安全：校验文件类型（魔数而非后缀）、大小限制、鉴权、分片归属用户、防重放。 加分：能主动谈「可靠性与性能的平衡」并给出具体数字和理由，是这道题从及格到高分的分水岭。"},{"id":192,"num":"Q192","tag":"场景","title":"如何排查页面卡顿 / 内存泄漏？","answers":["卡顿：DevTools Performance 录制 → 看 Main 线程长任务（>50ms 标红）、Layout / Recalculate Style 频繁触发（布局抖动）、GC 频繁、帧率掉到 60fps 以下 → 定位到具体函数 → 按「拆任务 / 减 DOM / 用 transform / Worker / 缓存布局读取」处理。也可监听 PerformanceObserver('longtask') 线上采集。","内存：Memory 面板 → 三次 GC 后拍 Heap Snapshot 对比 → 看 Retainers 引用链找「Detached HTMLDivElement」（脱离 DOM 但被引用）、不断增长的数组/Map、闭包持有大对象；Allocation instrumentation 看分配来源；Performance 勾选 Memory 看 JS Heap 是否阶梯上升不回落。","典型根因：未清理定时器/事件监听/订阅、全局缓存无淘汰、闭包引用 DOM、console.log 保留对象、第三方 SDK 未 destroy。"],"bullets":[],"code":[],"note":"","text":"如何排查页面卡顿 / 内存泄漏？ 卡顿：DevTools Performance 录制 → 看 Main 线程长任务（>50ms 标红）、Layout / Recalculate Style 频繁触发（布局抖动）、GC 频繁、帧率掉到 60fps 以下 → 定位到具体函数 → 按「拆任务 / 减 DOM / 用 transform / Worker / 缓存布局读取」处理。也可监听 PerformanceObserver('longtask') 线上采集。 内存：Memory 面板 → 三次 GC 后拍 Heap Snapshot 对比 → 看 Retainers 引用链找「Detached HTMLDivElement」（脱离 DOM 但被引用）、不断增长的数组/Map、闭包持有大对象；Allocation instrumentation 看分配来源；Performance 勾选 Memory 看 JS Heap 是否阶梯上升不回落。 典型根因：未清理定时器/事件监听/订阅、全局缓存无淘汰、闭包引用 DOM、console.log 保留对象、第三方 SDK 未 destroy。"},{"id":193,"num":"Q193","tag":"概念","title":"前端缓存体系有哪些层？","answers":["从近到远：① 内存/变量缓存（memoize、组件状态、Map，最快但刷新即失）；② 浏览器缓存（强缓存/协商缓存，CDN 静态资源长缓存）；③ Service Worker Cache Storage（离线、可编程策略）；④ 本地存储（localStorage / IndexedDB，接口数据、草稿、离线队列）；⑤ HTTP 缓存 / CDN 边缘缓存（s-maxage、stale-while-revalidate）；⑥ 服务端缓存（Redis、页面静态化、SSR 缓存）；⑦ 数据层缓存（TanStack Query / SWR 的 staleTime、gcTime、失效与重验证）。","一致性关键：缓存键设计（URL + 参数 + 用户维度 + Vary）、失效策略（版本化文件名、主动 purge、staleTime、TTL）、穿透/击穿/雪崩的防护（空值缓存、互斥重建、随机 TTL 抖动）。"],"bullets":[],"code":[],"note":"","text":"前端缓存体系有哪些层？ 从近到远：① 内存/变量缓存（memoize、组件状态、Map，最快但刷新即失）；② 浏览器缓存（强缓存/协商缓存，CDN 静态资源长缓存）；③ Service Worker Cache Storage（离线、可编程策略）；④ 本地存储（localStorage / IndexedDB，接口数据、草稿、离线队列）；⑤ HTTP 缓存 / CDN 边缘缓存（s-maxage、stale-while-revalidate）；⑥ 服务端缓存（Redis、页面静态化、SSR 缓存）；⑦ 数据层缓存（TanStack Query / SWR 的 staleTime、gcTime、失效与重验证）。 一致性关键：缓存键设计（URL + 参数 + 用户维度 + Vary）、失效策略（版本化文件名、主动 purge、staleTime、TTL）、穿透/击穿/雪崩的防护（空值缓存、互斥重建、随机 TTL 抖动）。"}]},{"id":"day6-s5","day":6,"title":"6.5 Node.js、测试与其他常考基础","note":"","questions":[{"id":194,"num":"Q194","tag":"基础","title":"Node.js 的特点与适用场景？","answers":["基于 V8 + libuv，单线程事件循环 + 非阻塞 I/O（底层用线程池处理文件/加密/DNS 等），擅长 I/O 密集型高并发（BFF、网关、实时通信、SSR、工具链），不适合 CPU 密集计算（用 Worker Threads / 子进程 / 原生扩展）。","前端要掌握的 Node 能力：CommonJS/ESM 互操作、package.json（exports/main/module/types、scripts、engines、sideEffects）、npm 生命周期、BFF 聚合接口、SSR、CLI 工具、流（Stream）与背压、进程管理（cluster / PM2）、环境变量与配置。","加分：能说出 libuv 的线程池默认 4 线程（UV_THREADPOOL_SIZE 可调），以及为什么「Node 是单线程」准确说法是「JS 执行主线程单线程」。"],"bullets":[],"code":[],"note":"","text":"Node.js 的特点与适用场景？ 基于 V8 + libuv，单线程事件循环 + 非阻塞 I/O（底层用线程池处理文件/加密/DNS 等），擅长 I/O 密集型高并发（BFF、网关、实时通信、SSR、工具链），不适合 CPU 密集计算（用 Worker Threads / 子进程 / 原生扩展）。 前端要掌握的 Node 能力：CommonJS/ESM 互操作、package.json（exports/main/module/types、scripts、engines、sideEffects）、npm 生命周期、BFF 聚合接口、SSR、CLI 工具、流（Stream）与背压、进程管理（cluster / PM2）、环境变量与配置。 加分：能说出 libuv 的线程池默认 4 线程（UV_THREADPOOL_SIZE 可调），以及为什么「Node 是单线程」准确说法是「JS 执行主线程单线程」。"},{"id":195,"num":"Q195","tag":"概念","title":"CommonJS 与 ESM 在 Node 里如何互操作？","answers":["判断依据：文件扩展名 .mjs / .cjs、package.json 的 \"type\": \"module\"、以及 exports 的 import/require 条件导出。","ESM 可以 import CJS（拿到 module.exports 作为默认导出，具名导出靠静态分析有限的 cjs-module-lexer）；CJS 不能 require ESM（因为 require 是同步而 ESM 可含顶层 await），但 Node 22+ 已实验性支持 require(esm)。","ESM 里没有 __dirname / __filename / require，用 import.meta.url + fileURLToPath 替代；包入口用 exports 字段做条件导出，避免 main 被绕过导致的「双包风险」（同一库同时被 CJS 与 ESM 加载产生两份实例）。"],"bullets":[],"code":[],"note":"","text":"CommonJS 与 ESM 在 Node 里如何互操作？ 判断依据：文件扩展名 .mjs / .cjs、package.json 的 \"type\": \"module\"、以及 exports 的 import/require 条件导出。 ESM 可以 import CJS（拿到 module.exports 作为默认导出，具名导出靠静态分析有限的 cjs-module-lexer）；CJS 不能 require ESM（因为 require 是同步而 ESM 可含顶层 await），但 Node 22+ 已实验性支持 require(esm)。 ESM 里没有 __dirname / __filename / require，用 import.meta.url + fileURLToPath 替代；包入口用 exports 字段做条件导出，避免 main 被绕过导致的「双包风险」（同一库同时被 CJS 与 ESM 加载产生两份实例）。"},{"id":196,"num":"Q196","tag":"对比","title":"进程、线程、协程与 Web Worker？","answers":["进程是资源分配的最小单位，有独立地址空间，隔离好、切换开销大；线程是 CPU 调度的最小单位，共享进程内存，切换开销小但需要处理同步与竞态；协程是用户态的轻量「可暂停/恢复」执行单元（JS 的生成器、async/await 可看作协程思维），切换不需要内核参与。","浏览器里 Web Worker 是真正的独立线程（不能访问 DOM、postMessage 通信、结构化克隆），主线程负责 UI；Node 的 worker_threads 同理，适合 CPU 密集任务；cluster / child_process 是多进程方案。","加分：能说出「JS 单线程 + 事件循环」解决的是 I/O 并发而非并行计算，以及为什么 UI 线程不能被阻塞（会导致掉帧与无响应）。"],"bullets":[],"code":[],"note":"","text":"进程、线程、协程与 Web Worker？ 进程是资源分配的最小单位，有独立地址空间，隔离好、切换开销大；线程是 CPU 调度的最小单位，共享进程内存，切换开销小但需要处理同步与竞态；协程是用户态的轻量「可暂停/恢复」执行单元（JS 的生成器、async/await 可看作协程思维），切换不需要内核参与。 浏览器里 Web Worker 是真正的独立线程（不能访问 DOM、postMessage 通信、结构化克隆），主线程负责 UI；Node 的 worker_threads 同理，适合 CPU 密集任务；cluster / child_process 是多进程方案。 加分：能说出「JS 单线程 + 事件循环」解决的是 I/O 并发而非并行计算，以及为什么 UI 线程不能被阻塞（会导致掉帧与无响应）。"},{"id":197,"num":"Q197","tag":"概念","title":"设计模式里前端常考哪些？","answers":["单例（全局 store、Modal 管理器、登录态）、工厂 / 抽象工厂（根据类型创建组件或请求适配器）、策略（表单校验规则、支付方式、折扣计算，消除 if/else）、代理（Proxy 实现缓存/懒加载/权限校验，Vue3 响应式）、观察者（Observer 直接通知）与发布订阅（EventEmitter / mitt，通过事件中心解耦，区别在是否有中间人）、装饰器（@ 装饰器、高阶组件 HOC、中间件）、适配器（统一不同后端接口/第三方 SDK）、组合（组件树、compose）、享元（大量相似对象的共享元数据）、责任链（中间件 koa/express、审批流）。","加分：把设计模式和框架实现对应起来讲（Redux middleware 是责任链 + 装饰器，React HOC 是装饰器，Vue 响应式是观察者 + 代理，EventEmitter 是发布订阅）。"],"bullets":[],"code":[],"note":"","text":"设计模式里前端常考哪些？ 单例（全局 store、Modal 管理器、登录态）、工厂 / 抽象工厂（根据类型创建组件或请求适配器）、策略（表单校验规则、支付方式、折扣计算，消除 if/else）、代理（Proxy 实现缓存/懒加载/权限校验，Vue3 响应式）、观察者（Observer 直接通知）与发布订阅（EventEmitter / mitt，通过事件中心解耦，区别在是否有中间人）、装饰器（@ 装饰器、高阶组件 HOC、中间件）、适配器（统一不同后端接口/第三方 SDK）、组合（组件树、compose）、享元（大量相似对象的共享元数据）、责任链（中间件 koa/express、审批流）。 加分：把设计模式和框架实现对应起来讲（Redux middleware 是责任链 + 装饰器，React HOC 是装饰器，Vue 响应式是观察者 + 代理，EventEmitter 是发布订阅）。"},{"id":198,"num":"Q198","tag":"基础","title":"数据结构与算法，前端要掌握到什么程度？","answers":["必须熟练：数组/字符串双指针与滑动窗口、哈希表计数、栈（括号匹配、单调栈）、队列、链表反转与快慢指针、二叉树递归/层序/BST、排序（快排、归并、堆排序思想与复杂度）、二分查找、DFS/BFS、前缀和、简单动态规划（爬楼梯、背包思想、最长递增子序列 LIS）、贪心。","复杂度：常见操作的 O(1)/O(log n)/O(n)/O(n log n)/O(n²)，能分析时间/空间复杂度与稳定性；能解释为什么 Vue3 diff 用 LIS、为什么虚拟列表用二分定位。","前端特色题：数组扁平化、去重、深拷贝、LRU 缓存（Map + 双向链表或利用 Map 插入顺序）、大数相加、模板字符串解析、虚拟 DOM diff、事件总线、并发控制、JSONP、Promise 系列。完整手写见第 7 天。"],"bullets":[],"code":[],"note":"","text":"数据结构与算法，前端要掌握到什么程度？ 必须熟练：数组/字符串双指针与滑动窗口、哈希表计数、栈（括号匹配、单调栈）、队列、链表反转与快慢指针、二叉树递归/层序/BST、排序（快排、归并、堆排序思想与复杂度）、二分查找、DFS/BFS、前缀和、简单动态规划（爬楼梯、背包思想、最长递增子序列 LIS）、贪心。 复杂度：常见操作的 O(1)/O(log n)/O(n)/O(n log n)/O(n²)，能分析时间/空间复杂度与稳定性；能解释为什么 Vue3 diff 用 LIS、为什么虚拟列表用二分定位。 前端特色题：数组扁平化、去重、深拷贝、LRU 缓存（Map + 双向链表或利用 Map 插入顺序）、大数相加、模板字符串解析、虚拟 DOM diff、事件总线、并发控制、JSONP、Promise 系列。完整手写见第 7 天。"}]}]},{"id":"day7","day":7,"title":"第 7 天｜手写代码全集 + 场景题 + 模拟面试","short":"手写代码全集 + 场景题 + 模拟面试","note":"目标：前六天是「会说」，今天是「会写」。手写题的评分点不是背出代码，而是：边界条件（this、参数、循环引用、空数组）、复杂度、以及能主动说出面试官会追问什么。建议每题先自己写一遍，再对照下面实现。","sections":[{"id":"day7-s1","day":7,"title":"7.1 必背手写题（基础篇）","note":"","questions":[{"id":199,"num":"Q199","tag":"手写","title":"实现防抖 debounce（支持立即执行、cancel、this 与参数透传）。","answers":["思路：闭包保存 timer；每次触发先 clearTimeout 再重新计时；用 apply 保留 this 与参数；immediate 模式靠「timer 是否存在」判断是否首次触发；cancel 清定时器并置空。","易漏点：忘记返回函数、忘记透传 this、immediate 模式下 timer 置空时机、cancel 后状态复位。应用：搜索联想、输入校验、resize 结束、按钮防重复提交。"],"bullets":[],"code":[["function debounce(fn, wait = 300, immediate = false) {","  let timer = null","  function debounced(...args) {","    const ctx = this","    if (timer) clearTimeout(timer)","    if (immediate && !timer) fn.apply(ctx, args)","    timer = setTimeout(() => {","      timer = null","      if (!immediate) fn.apply(ctx, args)","    }, wait)","  }","  debounced.cancel = () => { clearTimeout(timer); timer = null }","  return debounced","}"]],"note":"","text":"实现防抖 debounce（支持立即执行、cancel、this 与参数透传）。 思路：闭包保存 timer；每次触发先 clearTimeout 再重新计时；用 apply 保留 this 与参数；immediate 模式靠「timer 是否存在」判断是否首次触发；cancel 清定时器并置空。 易漏点：忘记返回函数、忘记透传 this、immediate 模式下 timer 置空时机、cancel 后状态复位。应用：搜索联想、输入校验、resize 结束、按钮防重复提交。 function debounce(fn, wait = 300, immediate = false) {   let timer = null   function debounced(...args) {     const ctx = this     if (timer) clearTimeout(timer)     if (immediate && !timer) fn.apply(ctx, args)     timer = setTimeout(() => {       timer = null       if (!immediate) fn.apply(ctx, args)     }, wait)   }   debounced.cancel = () => { clearTimeout(timer); timer = null }   return debounced }"},{"id":200,"num":"Q200","tag":"手写","title":"实现节流 throttle（支持 leading / trailing / cancel）。","answers":["思路：用时间戳判断距离上次执行是否超过 wait；不足则把「末次调用」放到定时器里补发；leading=false 时首次也要等一个 wait。","易错点：时间戳与定时器混用时要互斥（执行了一个就清掉另一个）、trailing 补发时 last 的更新、cancel 后状态复位。复杂度 O(1)。"],"bullets":[],"code":[["function throttle(fn, wait = 300, { leading = true, trailing = true } = {}) {","  let last = 0, timer = null","  function throttled(...args) {","    const now = Date.now(), ctx = this","    if (!last && !leading) last = now","    const remain = wait - (now - last)","    if (remain <= 0 || remain > wait) {","      if (timer) { clearTimeout(timer); timer = null }","      last = now","      fn.apply(ctx, args)","    } else if (trailing && !timer) {","      timer = setTimeout(() => {","        last = leading ? Date.now() : 0","        timer = null","        fn.apply(ctx, args)","      }, remain)","    }","  }","  throttled.cancel = () => { clearTimeout(timer); timer = null; last = 0 }","  return throttled","}"]],"note":"","text":"实现节流 throttle（支持 leading / trailing / cancel）。 思路：用时间戳判断距离上次执行是否超过 wait；不足则把「末次调用」放到定时器里补发；leading=false 时首次也要等一个 wait。 易错点：时间戳与定时器混用时要互斥（执行了一个就清掉另一个）、trailing 补发时 last 的更新、cancel 后状态复位。复杂度 O(1)。 function throttle(fn, wait = 300, { leading = true, trailing = true } = {}) {   let last = 0, timer = null   function throttled(...args) {     const now = Date.now(), ctx = this     if (!last && !leading) last = now     const remain = wait - (now - last)     if (remain <= 0 || remain > wait) {       if (timer) { clearTimeout(timer); timer = null }       last = now       fn.apply(ctx, args)     } else if (trailing && !timer) {       timer = setTimeout(() => {         last = leading ? Date.now() : 0         timer = null         fn.apply(ctx, args)       }, remain)     }   }   throttled.cancel = () => { clearTimeout(timer); timer = null; last = 0 }   return throttled }"},{"id":201,"num":"Q201","tag":"手写","title":"实现深拷贝 deepClone（处理循环引用、Symbol、Date/RegExp/Map/Set、原型链）。","answers":["思路：WeakMap 缓存已拷贝对象解决循环引用；基本类型与函数直接返回；特殊内置对象单独构造；用 Object.create(Object.getPrototypeOf(src)) 保留原型；用 Reflect.ownKeys 覆盖不可枚举属性与 Symbol 键。","易漏点：循环引用（不处理会爆栈）、Symbol 键（Object.keys 取不到）、Date/RegExp/Map/Set（普通递归会变成空对象）、原型丢失、函数如何处理（通常直接复用引用）。"],"bullets":[],"code":[["function deepClone(src, cache = new WeakMap()) {","  if (src === null || typeof src !== 'object') return src   // 基本类型 / 函数","  if (src instanceof Date) return new Date(src.getTime())","  if (src instanceof RegExp) return new RegExp(src.source, src.flags)","  if (cache.has(src)) return cache.get(src)","  if (src instanceof Map) {","    const m = new Map(); cache.set(src, m)","    src.forEach((v, k) => m.set(deepClone(k, cache), deepClone(v, cache)))","    return m","  }","  if (src instanceof Set) {","    const s = new Set(); cache.set(src, s)","    src.forEach(v => s.add(deepClone(v, cache)))","    return s","  }","  const out = Array.isArray(src) ? [] : Object.create(Object.getPrototypeOf(src))","  cache.set(src, out)","  Reflect.ownKeys(src).forEach(k => { out[k] = deepClone(src[k], cache) })","  return out","}"]],"note":"追问：structuredClone 与它的差异？原生支持循环引用、Map/Set/Date/ArrayBuffer，但不支持函数、DOM 节点、Proxy 与自定义原型（会变成普通对象）。","text":"实现深拷贝 deepClone（处理循环引用、Symbol、Date/RegExp/Map/Set、原型链）。 思路：WeakMap 缓存已拷贝对象解决循环引用；基本类型与函数直接返回；特殊内置对象单独构造；用 Object.create(Object.getPrototypeOf(src)) 保留原型；用 Reflect.ownKeys 覆盖不可枚举属性与 Symbol 键。 易漏点：循环引用（不处理会爆栈）、Symbol 键（Object.keys 取不到）、Date/RegExp/Map/Set（普通递归会变成空对象）、原型丢失、函数如何处理（通常直接复用引用）。 function deepClone(src, cache = new WeakMap()) {   if (src === null || typeof src !== 'object') return src   // 基本类型 / 函数   if (src instanceof Date) return new Date(src.getTime())   if (src instanceof RegExp) return new RegExp(src.source, src.flags)   if (cache.has(src)) return cache.get(src)   if (src instanceof Map) {     const m = new Map(); cache.set(src, m)     src.forEach((v, k) => m.set(deepClone(k, cache), deepClone(v, cache)))     return m   }   if (src instanceof Set) {     const s = new Set(); cache.set(src, s)     src.forEach(v => s.add(deepClone(v, cache)))     return s   }   const out = Array.isArray(src) ? [] : Object.create(Object.getPrototypeOf(src))   cache.set(src, out)   Reflect.ownKeys(src).forEach(k => { out[k] = deepClone(src[k], cache) })   return out } 追问：structuredClone 与它的差异？原生支持循环引用、Map/Set/Date/ArrayBuffer，但不支持函数、DOM 节点、Proxy 与自定义原型（会变成普通对象）。"},{"id":202,"num":"Q202","tag":"手写","title":"实现 call / apply / bind。","answers":["call/apply：把函数临时挂到 context 上，通过 `ctx.fn()` 触发隐式绑定得到正确 this，用完 delete；用 Symbol 作键避免覆盖同名属性；context 为 null/undefined 时用 globalThis 并做 Object() 包装（原始值转包装对象）。","bind：返回新函数；要处理 ① 预设参数 + 调用参数拼接；② 被 new 调用时 this 应指向新实例而不是绑定的 ctx（用 this instanceof bound 判断）；③ 原型链继承（否则 new 出来的实例拿不到原函数原型方法）。"],"bullets":[],"code":[["Function.prototype.myCall = function (ctx, ...args) {","  ctx = ctx == null ? globalThis : Object(ctx)","  const key = Symbol('fn')","  ctx[key] = this","  const res = ctx[key](...args)","  delete ctx[key]","  return res","}","Function.prototype.myApply = function (ctx, args = []) {","  ctx = ctx == null ? globalThis : Object(ctx)","  const key = Symbol('fn')","  ctx[key] = this","  const res = ctx[key](...args)","  delete ctx[key]","  return res","}","Function.prototype.myBind = function (ctx, ...preset) {","  const self = this","  function bound(...args) {","    const realCtx = this instanceof bound ? this : ctx","    return self.apply(realCtx, [...preset, ...args])","  }","  if (self.prototype) bound.prototype = Object.create(self.prototype)","  return bound","}"]],"note":"","text":"实现 call / apply / bind。 call/apply：把函数临时挂到 context 上，通过 `ctx.fn()` 触发隐式绑定得到正确 this，用完 delete；用 Symbol 作键避免覆盖同名属性；context 为 null/undefined 时用 globalThis 并做 Object() 包装（原始值转包装对象）。 bind：返回新函数；要处理 ① 预设参数 + 调用参数拼接；② 被 new 调用时 this 应指向新实例而不是绑定的 ctx（用 this instanceof bound 判断）；③ 原型链继承（否则 new 出来的实例拿不到原函数原型方法）。 Function.prototype.myCall = function (ctx, ...args) {   ctx = ctx == null ? globalThis : Object(ctx)   const key = Symbol('fn')   ctx[key] = this   const res = ctx[key](...args)   delete ctx[key]   return res } Function.prototype.myApply = function (ctx, args = []) {   ctx = ctx == null ? globalThis : Object(ctx)   const key = Symbol('fn')   ctx[key] = this   const res = ctx[key](...args)   delete ctx[key]   return res } Function.prototype.myBind = function (ctx, ...preset) {   const self = this   function bound(...args) {     const realCtx = this instanceof bound ? this : ctx     return self.apply(realCtx, [...preset, ...args])   }   if (self.prototype) bound.prototype = Object.create(self.prototype)   return bound }"},{"id":203,"num":"Q203","tag":"手写","title":"实现 new 操作符与 instanceof。","answers":["new 四步：创建空对象并 linking 原型 → apply 执行构造函数 → 判断返回值是否为对象/函数 → 返回实例或该返回值。最常见漏点是「构造函数返回对象时覆盖」。","instanceof：沿原型链比对；先校验右侧是函数、左侧是对象/函数；用 Object.getPrototypeOf 逐层上溯直到 null。"],"bullets":[],"code":[["function myNew(Ctor, ...args) {","  const obj = Object.create(Ctor.prototype)","  const ret = Ctor.apply(obj, args)","  return (ret !== null && (typeof ret === 'object' || typeof ret === 'function')) ? ret : obj","}","function myInstanceof(left, right) {","  if (typeof right !== 'function') throw new TypeError('Right side must be callable')","  if (left === null || (typeof left !== 'object' && typeof left !== 'function')) return false","  let p = Object.getPrototypeOf(left)","  while (p) {","    if (p === right.prototype) return true","    p = Object.getPrototypeOf(p)","  }","  return false","}"]],"note":"","text":"实现 new 操作符与 instanceof。 new 四步：创建空对象并 linking 原型 → apply 执行构造函数 → 判断返回值是否为对象/函数 → 返回实例或该返回值。最常见漏点是「构造函数返回对象时覆盖」。 instanceof：沿原型链比对；先校验右侧是函数、左侧是对象/函数；用 Object.getPrototypeOf 逐层上溯直到 null。 function myNew(Ctor, ...args) {   const obj = Object.create(Ctor.prototype)   const ret = Ctor.apply(obj, args)   return (ret !== null && (typeof ret === 'object' || typeof ret === 'function')) ? ret : obj } function myInstanceof(left, right) {   if (typeof right !== 'function') throw new TypeError('Right side must be callable')   if (left === null || (typeof left !== 'object' && typeof left !== 'function')) return false   let p = Object.getPrototypeOf(left)   while (p) {     if (p === right.prototype) return true     p = Object.getPrototypeOf(p)   }   return false }"},{"id":204,"num":"Q204","tag":"手写","title":"实现寄生组合继承与 Object.create。","answers":["关键点：用 Object.create(Parent.prototype) 代替 new Parent() 挂原型（避免父构造函数执行两次、原型上残留实例属性），并修正 constructor 指向。子类里用 Parent.call(this) 继承实例属性。"],"bullets":[],"code":[["function Parent(name) { this.name = name; this.list = [1, 2] }","Parent.prototype.say = function () { return this.name }","function Child(name, age) { Parent.call(this, name); this.age = age }","Child.prototype = Object.create(Parent.prototype)","Child.prototype.constructor = Child","function myCreate(proto, props) {","  function F() {}","  F.prototype = proto","  const o = new F()","  if (props) Object.defineProperties(o, props)","  return o","}"]],"note":"","text":"实现寄生组合继承与 Object.create。 关键点：用 Object.create(Parent.prototype) 代替 new Parent() 挂原型（避免父构造函数执行两次、原型上残留实例属性），并修正 constructor 指向。子类里用 Parent.call(this) 继承实例属性。 function Parent(name) { this.name = name; this.list = [1, 2] } Parent.prototype.say = function () { return this.name } function Child(name, age) { Parent.call(this, name); this.age = age } Child.prototype = Object.create(Parent.prototype) Child.prototype.constructor = Child function myCreate(proto, props) {   function F() {}   F.prototype = proto   const o = new F()   if (props) Object.defineProperties(o, props)   return o }"},{"id":205,"num":"Q205","tag":"手写","title":"实现 Promise.all / race / allSettled / any / finally。","answers":["通用要点：① 用 Promise.resolve 包装非 Promise 值；② 结果数组按下标写入以保序；③ all 空数组要立即 resolve([])；④ 计数用独立变量而不是 res.length（稀疏数组会误判）；⑤ allSettled 永不 reject；⑥ any 全失败时抛 AggregateError。"],"bullets":[],"code":[["Promise.myAll = tasks => new Promise((resolve, reject) => {","  const res = [], n = tasks.length","  if (!n) return resolve(res)","  let count = 0","  tasks.forEach((t, i) => Promise.resolve(t).then(v => {","    res[i] = v","    if (++count === n) resolve(res)","  }, reject))","})","Promise.myRace = tasks => new Promise((resolve, reject) =>","  tasks.forEach(t => Promise.resolve(t).then(resolve, reject)))","Promise.myAllSettled = tasks => Promise.all(tasks.map(t =>","  Promise.resolve(t).then(","    value => ({ status: 'fulfilled', value }),","    reason => ({ status: 'rejected', reason })","  )))","Promise.myAny = tasks => new Promise((resolve, reject) => {","  const errs = []; let n = 0","  if (!tasks.length) return reject(new AggregateError([], 'All promises rejected'))","  tasks.forEach((t, i) => Promise.resolve(t).then(resolve, e => {","    errs[i] = e","    if (++n === tasks.length) reject(new AggregateError(errs, 'All promises rejected'))","  }))","})","Promise.prototype.myFinally = function (fn) {","  return this.then(","    v => Promise.resolve(fn()).then(() => v),","    e => Promise.resolve(fn()).then(() => { throw e })","  )","}"]],"note":"","text":"实现 Promise.all / race / allSettled / any / finally。 通用要点：① 用 Promise.resolve 包装非 Promise 值；② 结果数组按下标写入以保序；③ all 空数组要立即 resolve([])；④ 计数用独立变量而不是 res.length（稀疏数组会误判）；⑤ allSettled 永不 reject；⑥ any 全失败时抛 AggregateError。 Promise.myAll = tasks => new Promise((resolve, reject) => {   const res = [], n = tasks.length   if (!n) return resolve(res)   let count = 0   tasks.forEach((t, i) => Promise.resolve(t).then(v => {     res[i] = v     if (++count === n) resolve(res)   }, reject)) }) Promise.myRace = tasks => new Promise((resolve, reject) =>   tasks.forEach(t => Promise.resolve(t).then(resolve, reject))) Promise.myAllSettled = tasks => Promise.all(tasks.map(t =>   Promise.resolve(t).then(     value => ({ status: 'fulfilled', value }),     reason => ({ status: 'rejected', reason })   ))) Promise.myAny = tasks => new Promise((resolve, reject) => {   const errs = []; let n = 0   if (!tasks.length) return reject(new AggregateError([], 'All promises rejected'))   tasks.forEach((t, i) => Promise.resolve(t).then(resolve, e => {     errs[i] = e     if (++n === tasks.length) reject(new AggregateError(errs, 'All promises rejected'))   })) }) Promise.prototype.myFinally = function (fn) {   return this.then(     v => Promise.resolve(fn()).then(() => v),     e => Promise.resolve(fn()).then(() => { throw e })   ) }"},{"id":206,"num":"Q206","tag":"手写","title":"实现符合 Promises/A+ 核心的 MyPromise（面试版）。","answers":["必答要点：① 三态且不可逆；② then 返回新 Promise（链式）；③ 回调异步执行（queueMicrotask 模拟微任务）；④ resolvePromise 决议过程：处理 x === p2 循环、thenable 吸收、只调用一次（called 锁）、错误捕获；⑤ 值穿透（缺省回调补默认值）；⑥ executor 抛错要 reject。","追问高频：为什么 then 回调要异步？规范保证执行顺序一致、避免 Zalgo（有时同步有时异步）；为什么需要 called 锁？防止恶意 thenable 既 resolve 又 reject。"],"bullets":[],"code":[["class MyPromise {","  constructor(executor) {","    this.status = 'pending'; this.value = undefined","    this.onFulfilled = []; this.onRejected = []","    const resolve = v => {","      if (v instanceof MyPromise) return v.then(resolve, reject)","      queueMicrotask(() => {","        if (this.status !== 'pending') return","        this.status = 'fulfilled'; this.value = v","        this.onFulfilled.forEach(fn => fn(v))","      })","    }","    const reject = r => queueMicrotask(() => {","      if (this.status !== 'pending') return","      this.status = 'rejected'; this.value = r","      this.onRejected.forEach(fn => fn(r))","    })","    try { executor(resolve, reject) } catch (e) { reject(e) }","  }","  then(onF = v => v, onR = e => { throw e }) {","    const p2 = new MyPromise((resolve, reject) => {","      const run = (fn, val) => queueMicrotask(() => {","        try { resolvePromise(p2, fn(val), resolve, reject) } catch (e) { reject(e) }","      })","      if (this.status === 'fulfilled') run(onF, this.value)","      else if (this.status === 'rejected') run(onR, this.value)","      else {","        this.onFulfilled.push(v => run(onF, v))","        this.onRejected.push(r => run(onR, r))","      }","    })","    return p2","  }","  catch(fn) { return this.then(null, fn) }","  static resolve(v) { return v instanceof MyPromise ? v : new MyPromise(r => r(v)) }","  static reject(r) { return new MyPromise((_, j) => j(r)) }","}","function resolvePromise(p2, x, resolve, reject) {","  if (x === p2) return reject(new TypeError('Chaining cycle detected'))","  if (x instanceof MyPromise) return x.then(resolve, reject)","  if (x !== null && (typeof x === 'object' || typeof x === 'function')) {","    let called = false","    try {","      const then = x.then","      if (typeof then === 'function') {","        then.call(x,","          y => { if (called) return; called = true; resolvePromise(p2, y, resolve, reject) },","          r => { if (called) return; called = true; reject(r) })","      } else resolve(x)","    } catch (e) { if (!called) { called = true; reject(e) } }","  } else resolve(x)","}"]],"note":"","text":"实现符合 Promises/A+ 核心的 MyPromise（面试版）。 必答要点：① 三态且不可逆；② then 返回新 Promise（链式）；③ 回调异步执行（queueMicrotask 模拟微任务）；④ resolvePromise 决议过程：处理 x === p2 循环、thenable 吸收、只调用一次（called 锁）、错误捕获；⑤ 值穿透（缺省回调补默认值）；⑥ executor 抛错要 reject。 追问高频：为什么 then 回调要异步？规范保证执行顺序一致、避免 Zalgo（有时同步有时异步）；为什么需要 called 锁？防止恶意 thenable 既 resolve 又 reject。 class MyPromise {   constructor(executor) {     this.status = 'pending'; this.value = undefined     this.onFulfilled = []; this.onRejected = []     const resolve = v => {       if (v instanceof MyPromise) return v.then(resolve, reject)       queueMicrotask(() => {         if (this.status !== 'pending') return         this.status = 'fulfilled'; this.value = v         this.onFulfilled.forEach(fn => fn(v))       })     }     const reject = r => queueMicrotask(() => {       if (this.status !== 'pending') return       this.status = 'rejected'; this.value = r       this.onRejected.forEach(fn => fn(r))     })     try { executor(resolve, reject) } catch (e) { reject(e) }   }   then(onF = v => v, onR = e => { throw e }) {     const p2 = new MyPromise((resolve, reject) => {       const run = (fn, val) => queueMicrotask(() => {         try { resolvePromise(p2, fn(val), resolve, reject) } catch (e) { reject(e) }       })       if (this.status === 'fulfilled') run(onF, this.value)       else if (this.status === 'rejected') run(onR, this.value)       else {         this.onFulfilled.push(v => run(onF, v))         this.onRejected.push(r => run(onR, r))       }     })     return p2   }   catch(fn) { return this.then(null, fn) }   static resolve(v) { return v instanceof MyPromise ? v : new MyPromise(r => r(v)) }   static reject(r) { return new MyPromise((_, j) => j(r)) } } function resolvePromise(p2, x, resolve, reject) {   if (x === p2) return reject(new TypeError('Chaining cycle detected'))   if (x instanceof MyPromise) return x.then(resolve, reject)   if (x !== null && (typeof x === 'object' || typeof x === 'function')) {     let called = false     try {       const then = x.then       if (typeof then === 'function') {         then.call(x,           y => { if (called) return; called = true; resolvePromise(p2, y, resolve, reject) },           r => { if (called) return; called = true; reject(r) })       } else resolve(x)     } catch (e) { if (!called) { called = true; reject(e) } }   } else resolve(x) }"},{"id":207,"num":"Q207","tag":"手写","title":"实现并发控制（Promise 调度池）。","answers":["思路：维护 `i`（下一个待执行任务下标）与 `done`（已完成数），启动 min(limit, total) 个 worker，每个 worker 完成后自动领取下一个任务（递归补位），全部完成 resolve 结果数组。","必答追问：limit 怎么定？浏览器同域并发上限、服务端限流、内存占用三者权衡，一般 3~6；失败策略？快速失败（reject）还是全部完成后用 allSettled 语义收集；任务必须是「返回 Promise 的函数」而不是已启动的 Promise（否则无法真正限流）。"],"bullets":[],"code":[["function limit(tasks, limit = 3) {","  return new Promise((resolve, reject) => {","    const total = tasks.length, results = []","    let i = 0, done = 0","    if (!total) return resolve(results)","    const run = () => {","      if (i >= total) return","      const idx = i++","      Promise.resolve(tasks[idx]()).then(v => {","        results[idx] = v","        if (++done === total) resolve(results)","        else run()","      }).catch(reject)","    }","    Array.from({ length: Math.min(limit, total) }, run)","  })","}"]],"note":"","text":"实现并发控制（Promise 调度池）。 思路：维护 `i`（下一个待执行任务下标）与 `done`（已完成数），启动 min(limit, total) 个 worker，每个 worker 完成后自动领取下一个任务（递归补位），全部完成 resolve 结果数组。 必答追问：limit 怎么定？浏览器同域并发上限、服务端限流、内存占用三者权衡，一般 3~6；失败策略？快速失败（reject）还是全部完成后用 allSettled 语义收集；任务必须是「返回 Promise 的函数」而不是已启动的 Promise（否则无法真正限流）。 function limit(tasks, limit = 3) {   return new Promise((resolve, reject) => {     const total = tasks.length, results = []     let i = 0, done = 0     if (!total) return resolve(results)     const run = () => {       if (i >= total) return       const idx = i++       Promise.resolve(tasks[idx]()).then(v => {         results[idx] = v         if (++done === total) resolve(results)         else run()       }).catch(reject)     }     Array.from({ length: Math.min(limit, total) }, run)   }) }"},{"id":208,"num":"Q208","tag":"手写","title":"实现函数柯里化 curry 与 compose / pipe。","answers":["curry：收集参数直到数量 >= fn.length 再执行，否则返回新的 curry；局限：fn.length 不计算 rest 参数与默认值参数，且无法处理占位符（可拓展支持 `_` 占位）。","compose 从右到左、pipe 从左到右，都用 reduce 实现；注意 compose 参数为 0 时应返回恒等函数 x => x。"],"bullets":[],"code":[["function curry(fn, ...preset) {","  return function curried(...args) {","    const all = [...preset, ...args]","    return all.length >= fn.length ? fn.apply(this, all) : curry(fn, ...all)","  }","}","const compose = (...fns) => fns.length === 0 ? (x => x)","  : fns.reduce((a, b) => (...args) => a(b(...args)))","const pipe = (...fns) => fns.length === 0 ? (x => x)","  : fns.reduce((a, b) => (...args) => b(a(...args)))"]],"note":"","text":"实现函数柯里化 curry 与 compose / pipe。 curry：收集参数直到数量 >= fn.length 再执行，否则返回新的 curry；局限：fn.length 不计算 rest 参数与默认值参数，且无法处理占位符（可拓展支持 `_` 占位）。 compose 从右到左、pipe 从左到右，都用 reduce 实现；注意 compose 参数为 0 时应返回恒等函数 x => x。 function curry(fn, ...preset) {   return function curried(...args) {     const all = [...preset, ...args]     return all.length >= fn.length ? fn.apply(this, all) : curry(fn, ...all)   } } const compose = (...fns) => fns.length === 0 ? (x => x)   : fns.reduce((a, b) => (...args) => a(b(...args))) const pipe = (...fns) => fns.length === 0 ? (x => x)   : fns.reduce((a, b) => (...args) => b(a(...args)))"},{"id":209,"num":"Q209","tag":"手写","title":"数组扁平化 flatten、去重 unique、按字段去重。","answers":["flatten 用 reduce + concat + 递归并控制 depth；注意 depth 为 0 时返回浅拷贝、flat 会跳过稀疏数组空位。去重优先 [...new Set(arr)]（NaN 也等价，基于 SameValueZero）；对象数组用 Map 按 key 去重，保持首次出现顺序。"],"bullets":[],"code":[["function flatten(arr, depth = Infinity) {","  return depth > 0 ? arr.reduce((acc, v) =>","    acc.concat(Array.isArray(v) ? flatten(v, depth - 1) : v), []) : arr.slice()","}","const unique = arr => [...new Set(arr)]","function uniqueBy(arr, key) {","  const seen = new Map(), res = []","  for (const x of arr) {","    const k = typeof key === 'function' ? key(x) : x[key]","    if (!seen.has(k)) { seen.set(k, true); res.push(x) }","  }","  return res","}"]],"note":"","text":"数组扁平化 flatten、去重 unique、按字段去重。 flatten 用 reduce + concat + 递归并控制 depth；注意 depth 为 0 时返回浅拷贝、flat 会跳过稀疏数组空位。去重优先 [...new Set(arr)]（NaN 也等价，基于 SameValueZero）；对象数组用 Map 按 key 去重，保持首次出现顺序。 function flatten(arr, depth = Infinity) {   return depth > 0 ? arr.reduce((acc, v) =>     acc.concat(Array.isArray(v) ? flatten(v, depth - 1) : v), []) : arr.slice() } const unique = arr => [...new Set(arr)] function uniqueBy(arr, key) {   const seen = new Map(), res = []   for (const x of arr) {     const k = typeof key === 'function' ? key(x) : x[key]     if (!seen.has(k)) { seen.set(k, true); res.push(x) }   }   return res }"},{"id":210,"num":"Q210","tag":"手写","title":"实现 LRU 缓存（get / put 都是 O(1)）。","answers":["利用 Map 的插入顺序：命中后先 delete 再 set，把它移到队尾（最近使用）；put 超容量时删 `map.keys().next().value`（最久未使用）。复杂度 O(1)，空间 O(capacity)。","追问：为什么不用普通对象？需要有序且频繁删除头部，Map 更合适；Vue 的 keep-alive 用 keys 数组 + cache 对象实现同样的 LRU 思想。"],"bullets":[],"code":[["class LRU {","  constructor(cap) { this.cap = cap; this.map = new Map() }","  get(key) {","    if (!this.map.has(key)) return -1","    const v = this.map.get(key)","    this.map.delete(key); this.map.set(key, v)","    return v","  }","  put(key, value) {","    if (this.map.has(key)) this.map.delete(key)","    this.map.set(key, value)","    if (this.map.size > this.cap) this.map.delete(this.map.keys().next().value)","  }","}"]],"note":"","text":"实现 LRU 缓存（get / put 都是 O(1)）。 利用 Map 的插入顺序：命中后先 delete 再 set，把它移到队尾（最近使用）；put 超容量时删 `map.keys().next().value`（最久未使用）。复杂度 O(1)，空间 O(capacity)。 追问：为什么不用普通对象？需要有序且频繁删除头部，Map 更合适；Vue 的 keep-alive 用 keys 数组 + cache 对象实现同样的 LRU 思想。 class LRU {   constructor(cap) { this.cap = cap; this.map = new Map() }   get(key) {     if (!this.map.has(key)) return -1     const v = this.map.get(key)     this.map.delete(key); this.map.set(key, v)     return v   }   put(key, value) {     if (this.map.has(key)) this.map.delete(key)     this.map.set(key, value)     if (this.map.size > this.cap) this.map.delete(this.map.keys().next().value)   } }"},{"id":211,"num":"Q211","tag":"手写","title":"实现发布订阅 EventEmitter（on / once / off / emit / clear）。","answers":["要点：用 Map<string, Function[]> 存事件；once 用包装函数并在执行时自动解绑；emit 时先拷贝一份数组再遍历（防止回调里增删监听器影响本次遍历）；emit 的 this 指向 emitter；off 要能移除 once 包装后的引用（可返回 unsubscribe，或保存 origin 映射）。"],"bullets":[],"code":[["class EventEmitter {","  constructor() { this.events = new Map() }","  on(name, fn) {","    const list = this.events.get(name) || []","    list.push(fn); this.events.set(name, list)","    return () => this.off(name, fn)","  }","  once(name, fn) {","    const wrap = (...args) => { this.off(name, wrap); fn.apply(this, args) }","    wrap.origin = fn","    return this.on(name, wrap)","  }","  off(name, fn) {","    const list = this.events.get(name) || []","    this.events.set(name, list.filter(f => f !== fn && f.origin !== fn))","  }","  emit(name, ...args) {","    ;[...(this.events.get(name) || [])].forEach(fn => fn.apply(this, args))","  }","  clear(name) { name ? this.events.delete(name) : this.events.clear() }","}"]],"note":"","text":"实现发布订阅 EventEmitter（on / once / off / emit / clear）。 要点：用 Map<string, Function[]> 存事件；once 用包装函数并在执行时自动解绑；emit 时先拷贝一份数组再遍历（防止回调里增删监听器影响本次遍历）；emit 的 this 指向 emitter；off 要能移除 once 包装后的引用（可返回 unsubscribe，或保存 origin 映射）。 class EventEmitter {   constructor() { this.events = new Map() }   on(name, fn) {     const list = this.events.get(name) || []     list.push(fn); this.events.set(name, list)     return () => this.off(name, fn)   }   once(name, fn) {     const wrap = (...args) => { this.off(name, wrap); fn.apply(this, args) }     wrap.origin = fn     return this.on(name, wrap)   }   off(name, fn) {     const list = this.events.get(name) || []     this.events.set(name, list.filter(f => f !== fn && f.origin !== fn))   }   emit(name, ...args) {     ;[...(this.events.get(name) || [])].forEach(fn => fn.apply(this, args))   }   clear(name) { name ? this.events.delete(name) : this.events.clear() } }"}]},{"id":"day7-s2","day":7,"title":"7.2 必背手写题（进阶篇）","note":"","questions":[{"id":212,"num":"Q212","tag":"手写","title":"实现 JSONP（含超时与清理）。","answers":["原理：script 标签不受同源策略限制，服务端返回 `callback(data)` 形式的可执行 JS。要点：① 回调名随机且唯一，避免并发冲突；② 挂载到 window 并在结束后 delete；③ 超时与 onerror 都要 reject 并清理；④ 服务端必须白名单校验 callback 名（只允许字母数字下划线点），否则会被注入成 XSS；⑤ 只支持 GET、无 HTTP 状态码、已淘汰。"],"bullets":[],"code":[["function jsonp({ url, params = {}, timeout = 5000 }) {","  return new Promise((resolve, reject) => {","    const name = '__jsonp_' + Date.now() + '_' + Math.random().toString(36).slice(2)","    const script = document.createElement('script')","    const cleanup = () => {","      clearTimeout(timer)","      delete window[name]","      script.remove()","    }","    const timer = setTimeout(() => {","      cleanup(); reject(new Error('JSONP timeout'))","    }, timeout)","    window[name] = data => { resolve(data); cleanup() }","    script.src = url + '?' + new URLSearchParams({ ...params, callback: name }).toString()","    script.onerror = () => { cleanup(); reject(new Error('JSONP network error')) }","    document.body.appendChild(script)","  })","}"]],"note":"","text":"实现 JSONP（含超时与清理）。 原理：script 标签不受同源策略限制，服务端返回 `callback(data)` 形式的可执行 JS。要点：① 回调名随机且唯一，避免并发冲突；② 挂载到 window 并在结束后 delete；③ 超时与 onerror 都要 reject 并清理；④ 服务端必须白名单校验 callback 名（只允许字母数字下划线点），否则会被注入成 XSS；⑤ 只支持 GET、无 HTTP 状态码、已淘汰。 function jsonp({ url, params = {}, timeout = 5000 }) {   return new Promise((resolve, reject) => {     const name = '__jsonp_' + Date.now() + '_' + Math.random().toString(36).slice(2)     const script = document.createElement('script')     const cleanup = () => {       clearTimeout(timer)       delete window[name]       script.remove()     }     const timer = setTimeout(() => {       cleanup(); reject(new Error('JSONP timeout'))     }, timeout)     window[name] = data => { resolve(data); cleanup() }     script.src = url + '?' + new URLSearchParams({ ...params, callback: name }).toString()     script.onerror = () => { cleanup(); reject(new Error('JSONP network error')) }     document.body.appendChild(script)   }) }"},{"id":213,"num":"Q213","tag":"手写","title":"封装 fetch：超时、错误统一处理、AbortController 取消。","answers":["必答坑：fetch 只有在网络错误时 reject，4xx/5xx 会 resolve，必须检查 res.ok；超时要用 AbortController 真正中止请求（Promise.race 只是忽略结果，请求仍在跑）；finally 里清定时器；响应体只能读一次，需要复用要 res.clone()。"],"bullets":[],"code":[["async function request(url, { timeout = 8000, ...options } = {}) {","  const controller = new AbortController()","  const id = setTimeout(() => controller.abort(), timeout)","  try {","    const res = await fetch(url, { ...options, signal: controller.signal })","    if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + url)","    return await res.json()","  } finally {","    clearTimeout(id)","  }","}","// 超时竞速版（不取消请求，仅忽略结果）","const withTimeout = (p, ms) => Promise.race([","  p,","  new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms))","])"]],"note":"","text":"封装 fetch：超时、错误统一处理、AbortController 取消。 必答坑：fetch 只有在网络错误时 reject，4xx/5xx 会 resolve，必须检查 res.ok；超时要用 AbortController 真正中止请求（Promise.race 只是忽略结果，请求仍在跑）；finally 里清定时器；响应体只能读一次，需要复用要 res.clone()。 async function request(url, { timeout = 8000, ...options } = {}) {   const controller = new AbortController()   const id = setTimeout(() => controller.abort(), timeout)   try {     const res = await fetch(url, { ...options, signal: controller.signal })     if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + url)     return await res.json()   } finally {     clearTimeout(id)   } } // 超时竞速版（不取消请求，仅忽略结果） const withTimeout = (p, ms) => Promise.race([   p,   new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms)) ])"},{"id":214,"num":"Q214","tag":"手写","title":"实现 once、memoize、retry、sleep 与轮询。","answers":["once 用闭包锁 + 缓存结果；memoize 用 Map 缓存，注意缓存键要能覆盖多参数（默认只取第一个参数，可传 resolver）；retry 用指数退避 + 抖动，且要区分可重试错误；sleep 是 Promise 化的定时器，配合 async 可做串行与轮询。"],"bullets":[],"code":[["function once(fn) {","  let called = false, result","  return function (...args) {","    if (!called) { called = true; result = fn.apply(this, args) }","    return result","  }","}","function memoize(fn, resolver = (...a) => a[0]) {","  const cache = new Map()","  return function (...args) {","    const key = resolver(...args)","    if (cache.has(key)) return cache.get(key)","    const res = fn.apply(this, args)","    cache.set(key, res)","    return res","  }","}","const sleep = ms => new Promise(r => setTimeout(r, ms))","async function retry(task, { times = 3, delay = 300 } = {}) {","  let lastErr","  for (let i = 0; i < times; i++) {","    try { return await task() }","    catch (e) {","      lastErr = e","      if (i < times - 1) await sleep(delay * 2 ** i + Math.random() * 100)","    }","  }","  throw lastErr","}","async function poll(fn, { interval = 1000, times = Infinity, shouldStop } = {}) {","  for (let i = 0; i < times; i++) {","    const res = await fn()","    if (shouldStop?.(res)) return res","    await sleep(interval)","  }","}"]],"note":"","text":"实现 once、memoize、retry、sleep 与轮询。 once 用闭包锁 + 缓存结果；memoize 用 Map 缓存，注意缓存键要能覆盖多参数（默认只取第一个参数，可传 resolver）；retry 用指数退避 + 抖动，且要区分可重试错误；sleep 是 Promise 化的定时器，配合 async 可做串行与轮询。 function once(fn) {   let called = false, result   return function (...args) {     if (!called) { called = true; result = fn.apply(this, args) }     return result   } } function memoize(fn, resolver = (...a) => a[0]) {   const cache = new Map()   return function (...args) {     const key = resolver(...args)     if (cache.has(key)) return cache.get(key)     const res = fn.apply(this, args)     cache.set(key, res)     return res   } } const sleep = ms => new Promise(r => setTimeout(r, ms)) async function retry(task, { times = 3, delay = 300 } = {}) {   let lastErr   for (let i = 0; i < times; i++) {     try { return await task() }     catch (e) {       lastErr = e       if (i < times - 1) await sleep(delay * 2 ** i + Math.random() * 100)     }   }   throw lastErr } async function poll(fn, { interval = 1000, times = Infinity, shouldStop } = {}) {   for (let i = 0; i < times; i++) {     const res = await fn()     if (shouldStop?.(res)) return res     await sleep(interval)   } }"},{"id":215,"num":"Q215","tag":"手写","title":"实现千分位格式化、大数相加、随机洗牌。","answers":["千分位用正则 `\\B(?=(\\d{3})+$)` 匹配「后面跟着 3 的倍数位数字」的非单词边界；要处理小数部分，不要直接对带小数点的字符串做正则。大数相加用字符串逐位从后往前加并维护进位。洗牌必须用 Fisher-Yates（从后往前与随机位置交换），`sort(() => Math.random() - 0.5)` 分布不均匀，是经典错误答案。"],"bullets":[],"code":[["function thousands(num) {","  const [int, dec] = String(num).split('.')","  return int.replace(/\\B(?=(\\d{3})+$)/g, ',') + (dec ? '.' + dec : '')","}","function addBig(a, b) {","  let i = a.length - 1, j = b.length - 1, carry = 0, res = ''","  while (i >= 0 || j >= 0 || carry) {","    const x = i >= 0 ? +a[i--] : 0","    const y = j >= 0 ? +b[j--] : 0","    const s = x + y + carry","    res = (s % 10) + res","    carry = Math.floor(s / 10)","  }","  return res.replace(/^0+/, '') || '0'","}","function shuffle(arr) {","  const a = [...arr]","  for (let i = a.length - 1; i > 0; i--) {","    const j = Math.floor(Math.random() * (i + 1))","    ;[a[i], a[j]] = [a[j], a[i]]","  }","  return a","}"]],"note":"","text":"实现千分位格式化、大数相加、随机洗牌。 千分位用正则 `\\B(?=(\\d{3})+$)` 匹配「后面跟着 3 的倍数位数字」的非单词边界；要处理小数部分，不要直接对带小数点的字符串做正则。大数相加用字符串逐位从后往前加并维护进位。洗牌必须用 Fisher-Yates（从后往前与随机位置交换），`sort(() => Math.random() - 0.5)` 分布不均匀，是经典错误答案。 function thousands(num) {   const [int, dec] = String(num).split('.')   return int.replace(/\\B(?=(\\d{3})+$)/g, ',') + (dec ? '.' + dec : '') } function addBig(a, b) {   let i = a.length - 1, j = b.length - 1, carry = 0, res = ''   while (i >= 0 || j >= 0 || carry) {     const x = i >= 0 ? +a[i--] : 0     const y = j >= 0 ? +b[j--] : 0     const s = x + y + carry     res = (s % 10) + res     carry = Math.floor(s / 10)   }   return res.replace(/^0+/, '') || '0' } function shuffle(arr) {   const a = [...arr]   for (let i = a.length - 1; i > 0; i--) {     const j = Math.floor(Math.random() * (i + 1))     ;[a[i], a[j]] = [a[j], a[i]]   }   return a }"},{"id":216,"num":"Q216","tag":"手写","title":"二分查找、快速排序、深比较 isEqual。","answers":["二分注意循环条件 `l <= r` 与中点溢出（JS 里可用 `(l + r) >> 1`，超大数据用 `l + ((r - l) >> 1)`）；快排给「易懂版」（非原地、空间 O(n)），能说出原地分区版与三数取中优化更好；isEqual 用 Object.is 起手、WeakMap 处理循环引用、比较原型与 Reflect.ownKeys 数量，递归比较每个键。"],"bullets":[],"code":[["function binarySearch(arr, target) {","  let l = 0, r = arr.length - 1","  while (l <= r) {","    const m = l + ((r - l) >> 1)","    if (arr[m] === target) return m","    arr[m] < target ? l = m + 1 : r = m - 1","  }","  return -1","}","function quickSort(arr) {","  if (arr.length <= 1) return arr","  const pivot = arr[0], left = [], right = []","  for (let i = 1; i < arr.length; i++) (arr[i] < pivot ? left : right).push(arr[i])","  return [...quickSort(left), pivot, ...quickSort(right)]","}","function isEqual(a, b, seen = new WeakMap()) {","  if (Object.is(a, b)) return true","  if (a === null || b === null || typeof a !== 'object' || typeof b !== 'object') return false","  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false","  if (seen.has(a)) return seen.get(a) === b","  seen.set(a, b)","  if (a instanceof Date) return a.getTime() === b.getTime()","  if (a instanceof RegExp) return String(a) === String(b)","  const ka = Reflect.ownKeys(a), kb = Reflect.ownKeys(b)","  return ka.length === kb.length &&","    ka.every(k => Object.prototype.hasOwnProperty.call(b, k) && isEqual(a[k], b[k], seen))","}"]],"note":"","text":"二分查找、快速排序、深比较 isEqual。 二分注意循环条件 `l <= r` 与中点溢出（JS 里可用 `(l + r) >> 1`，超大数据用 `l + ((r - l) >> 1)`）；快排给「易懂版」（非原地、空间 O(n)），能说出原地分区版与三数取中优化更好；isEqual 用 Object.is 起手、WeakMap 处理循环引用、比较原型与 Reflect.ownKeys 数量，递归比较每个键。 function binarySearch(arr, target) {   let l = 0, r = arr.length - 1   while (l <= r) {     const m = l + ((r - l) >> 1)     if (arr[m] === target) return m     arr[m] < target ? l = m + 1 : r = m - 1   }   return -1 } function quickSort(arr) {   if (arr.length <= 1) return arr   const pivot = arr[0], left = [], right = []   for (let i = 1; i < arr.length; i++) (arr[i] < pivot ? left : right).push(arr[i])   return [...quickSort(left), pivot, ...quickSort(right)] } function isEqual(a, b, seen = new WeakMap()) {   if (Object.is(a, b)) return true   if (a === null || b === null || typeof a !== 'object' || typeof b !== 'object') return false   if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false   if (seen.has(a)) return seen.get(a) === b   seen.set(a, b)   if (a instanceof Date) return a.getTime() === b.getTime()   if (a instanceof RegExp) return String(a) === String(b)   const ka = Reflect.ownKeys(a), kb = Reflect.ownKeys(b)   return ka.length === kb.length &&     ka.every(k => Object.prototype.hasOwnProperty.call(b, k) && isEqual(a[k], b[k], seen)) }"},{"id":217,"num":"Q217","tag":"手写","title":"实现极简 useState / useEffect（讲清 Hooks 原理即可）。","answers":["演示目的：状态不在函数里，而在外部数组中按「调用顺序」存放；每次 render 前把索引归零；这就是为什么 Hook 不能写在条件/循环里。真实 React 用 Fiber.memoizedState 的链表 + Scheduler 调度，这里只是心智模型。"],"bullets":[],"code":[["const hooks = []; let idx = 0","function useState(initial) {","  const i = idx++","  if (!(i in hooks)) hooks[i] = typeof initial === 'function' ? initial() : initial","  const setState = next => { hooks[i] = typeof next === 'function' ? next(hooks[i]) : next }","  return [hooks[i], setState]","}","function useEffect(cb, deps) {","  const i = idx++","  const prev = hooks[i]","  const changed = !prev || !deps || deps.some((d, k) => !Object.is(d, prev.deps[k]))","  if (changed) {","    prev?.cleanup?.()","    const record = { deps, cleanup: null }","    hooks[i] = record","    queueMicrotask(() => { record.cleanup = cb() })","  }","}","function render(Component) { idx = 0; Component() }"]],"note":"","text":"实现极简 useState / useEffect（讲清 Hooks 原理即可）。 演示目的：状态不在函数里，而在外部数组中按「调用顺序」存放；每次 render 前把索引归零；这就是为什么 Hook 不能写在条件/循环里。真实 React 用 Fiber.memoizedState 的链表 + Scheduler 调度，这里只是心智模型。 const hooks = []; let idx = 0 function useState(initial) {   const i = idx++   if (!(i in hooks)) hooks[i] = typeof initial === 'function' ? initial() : initial   const setState = next => { hooks[i] = typeof next === 'function' ? next(hooks[i]) : next }   return [hooks[i], setState] } function useEffect(cb, deps) {   const i = idx++   const prev = hooks[i]   const changed = !prev || !deps || deps.some((d, k) => !Object.is(d, prev.deps[k]))   if (changed) {     prev?.cleanup?.()     const record = { deps, cleanup: null }     hooks[i] = record     queueMicrotask(() => { record.cleanup = cb() })   } } function render(Component) { idx = 0; Component() }"},{"id":218,"num":"Q218","tag":"手写","title":"虚拟列表的核心区间计算（固定行高版）。","answers":["思路：可视区只渲染 start~end 条，用 translateY(start * itemH) 把渲染块推到正确位置，用 paddingBottom/占位元素撑起总高度让滚动条正确；buffer 缓冲减少快速滚动白屏。","追问：不定高怎么办？维护每项高度与前缀和数组（缓存测量值 + 用预估高度先渲染），用二分查找前缀和定位 startIndex，滚动后异步测量真实高度并修正总高与偏移。"],"bullets":[],"code":[["function getRange(scrollTop, viewportH, itemH, total, buffer = 5) {","  const start = Math.max(0, Math.floor(scrollTop / itemH) - buffer)","  const count = Math.ceil(viewportH / itemH) + buffer * 2","  const end = Math.min(total, start + count)","  return {","    start, end,","    offsetY: start * itemH,","    paddingBottom: (total - end) * itemH","  }","}"]],"note":"","text":"虚拟列表的核心区间计算（固定行高版）。 思路：可视区只渲染 start~end 条，用 translateY(start * itemH) 把渲染块推到正确位置，用 paddingBottom/占位元素撑起总高度让滚动条正确；buffer 缓冲减少快速滚动白屏。 追问：不定高怎么办？维护每项高度与前缀和数组（缓存测量值 + 用预估高度先渲染），用二分查找前缀和定位 startIndex，滚动后异步测量真实高度并修正总高与偏移。 function getRange(scrollTop, viewportH, itemH, total, buffer = 5) {   const start = Math.max(0, Math.floor(scrollTop / itemH) - buffer)   const count = Math.ceil(viewportH / itemH) + buffer * 2   const end = Math.min(total, start + count)   return {     start, end,     offsetY: start * itemH,     paddingBottom: (total - end) * itemH   } }"},{"id":219,"num":"Q219","tag":"手写","title":"图片懒加载（IntersectionObserver 版）与 URL 参数解析。","answers":["懒加载：给 img 用 data-src，IntersectionObserver 进入视口（可配 rootMargin 提前加载）时赋 src 并 unobserve；比监听 scroll + getBoundingClientRect 性能好得多（不在主线程做布局计算）。注意首屏 LCP 图不要懒加载。","参数解析：URLSearchParams 处理重复键、编码与空值；Object.fromEntries 把 entries 转对象，重复键会保留最后一个。"],"bullets":[],"code":[["const io = new IntersectionObserver(entries => {","  for (const e of entries) {","    if (!e.isIntersecting) continue","    const img = e.target","    img.src = img.dataset.src","    io.unobserve(img)","  }","}, { rootMargin: '200px' })","document.querySelectorAll('img[data-src]').forEach(img => io.observe(img))","const getParams = (url = location.href) =>","  Object.fromEntries(new URL(url).searchParams.entries())"]],"note":"","text":"图片懒加载（IntersectionObserver 版）与 URL 参数解析。 懒加载：给 img 用 data-src，IntersectionObserver 进入视口（可配 rootMargin 提前加载）时赋 src 并 unobserve；比监听 scroll + getBoundingClientRect 性能好得多（不在主线程做布局计算）。注意首屏 LCP 图不要懒加载。 参数解析：URLSearchParams 处理重复键、编码与空值；Object.fromEntries 把 entries 转对象，重复键会保留最后一个。 const io = new IntersectionObserver(entries => {   for (const e of entries) {     if (!e.isIntersecting) continue     const img = e.target     img.src = img.dataset.src     io.unobserve(img)   } }, { rootMargin: '200px' }) document.querySelectorAll('img[data-src]').forEach(img => io.observe(img)) const getParams = (url = location.href) =>   Object.fromEntries(new URL(url).searchParams.entries())"},{"id":220,"num":"Q220","tag":"手写","title":"实现每隔一秒打印 1,2,3,4（闭包 / let / 递归 / async 四种解法）。","answers":["考点是「闭包保存变量」与「异步循环」。推荐递归 + setTimeout 或 async + sleep（最清晰）；用 var + setTimeout 直接写会全部打印 5。"],"bullets":[],"code":[["// 解法 1：let 块级绑定","for (let i = 1; i <= 4; i++) setTimeout(() => console.log(i), i * 1000)","// 解法 2：IIFE 闭包（var 时代标准答案）","for (var i = 1; i <= 4; i++) {","  (function (j) { setTimeout(() => console.log(j), j * 1000) })(i)","}","// 解法 3：递归（无定时器堆积）","function print(n, max) {","  if (n > max) return","  setTimeout(() => { console.log(n); print(n + 1, max) }, 1000)","}","print(1, 4)","// 解法 4：async + sleep","const sleep = ms => new Promise(r => setTimeout(r, ms))",";(async () => { for (let i = 1; i <= 4; i++) { await sleep(1000); console.log(i) } })()"]],"note":"","text":"实现每隔一秒打印 1,2,3,4（闭包 / let / 递归 / async 四种解法）。 考点是「闭包保存变量」与「异步循环」。推荐递归 + setTimeout 或 async + sleep（最清晰）；用 var + setTimeout 直接写会全部打印 5。 // 解法 1：let 块级绑定 for (let i = 1; i <= 4; i++) setTimeout(() => console.log(i), i * 1000) // 解法 2：IIFE 闭包（var 时代标准答案） for (var i = 1; i <= 4; i++) {   (function (j) { setTimeout(() => console.log(j), j * 1000) })(i) } // 解法 3：递归（无定时器堆积） function print(n, max) {   if (n > max) return   setTimeout(() => { console.log(n); print(n + 1, max) }, 1000) } print(1, 4) // 解法 4：async + sleep const sleep = ms => new Promise(r => setTimeout(r, ms)) ;(async () => { for (let i = 1; i <= 4; i++) { await sleep(1000); console.log(i) } })()"},{"id":221,"num":"Q221","tag":"手写","title":"用 setTimeout 模拟 setInterval（并解释为什么）。","answers":["原因：setInterval 不管上一次回调是否执行完就按固定周期往队列里塞任务，回调耗时超过间隔时会产生任务堆积、间隔失真甚至连续执行；用递归 setTimeout 能保证「上一次执行完再等 interval」，间隔更稳定，也便于动态改间隔与停止。"],"bullets":[],"code":[["function myInterval(fn, ms) {","  let timer = null, stopped = false","  const tick = () => {","    if (stopped) return","    fn()","    timer = setTimeout(tick, ms)","  }","  timer = setTimeout(tick, ms)","  return () => { stopped = true; clearTimeout(timer) }","}","// 支持异步回调的版本：await fn() 之后再 setTimeout 更好"]],"note":"","text":"用 setTimeout 模拟 setInterval（并解释为什么）。 原因：setInterval 不管上一次回调是否执行完就按固定周期往队列里塞任务，回调耗时超过间隔时会产生任务堆积、间隔失真甚至连续执行；用递归 setTimeout 能保证「上一次执行完再等 interval」，间隔更稳定，也便于动态改间隔与停止。 function myInterval(fn, ms) {   let timer = null, stopped = false   const tick = () => {     if (stopped) return     fn()     timer = setTimeout(tick, ms)   }   timer = setTimeout(tick, ms)   return () => { stopped = true; clearTimeout(timer) } } // 支持异步回调的版本：await fn() 之后再 setTimeout 更好"},{"id":222,"num":"Q222","tag":"手写","title":"倒计时纠偏（为什么 setTimeout 做倒计时会不准）。","answers":["原因：JS 定时器受事件循环、主线程长任务、后台标签页节流（最小 1s 甚至更久）、系统休眠影响，`setInterval(1000)` 累计误差会越来越大。做法：记录「目标结束时间戳」，每次用 `endTime - Date.now()` 重新计算剩余时间，而不是在本地累减；页面从后台回来时用 visibilitychange 立即重算；服务端下发结束时间避免客户端时钟被篡改。"],"bullets":[],"code":[["function countdown(endTime, onTick, onDone) {","  let timer = null","  const tick = () => {","    const left = endTime - Date.now()","    if (left <= 0) { onDone(); return }","    onTick(Math.max(0, left))","    timer = setTimeout(tick, Math.min(1000, left % 1000 || 1000))","  }","  tick()","  document.addEventListener('visibilitychange', () => {","    if (!document.hidden) { clearTimeout(timer); tick() }","  })","  return () => clearTimeout(timer)","}"]],"note":"","text":"倒计时纠偏（为什么 setTimeout 做倒计时会不准）。 原因：JS 定时器受事件循环、主线程长任务、后台标签页节流（最小 1s 甚至更久）、系统休眠影响，`setInterval(1000)` 累计误差会越来越大。做法：记录「目标结束时间戳」，每次用 `endTime - Date.now()` 重新计算剩余时间，而不是在本地累减；页面从后台回来时用 visibilitychange 立即重算；服务端下发结束时间避免客户端时钟被篡改。 function countdown(endTime, onTick, onDone) {   let timer = null   const tick = () => {     const left = endTime - Date.now()     if (left <= 0) { onDone(); return }     onTick(Math.max(0, left))     timer = setTimeout(tick, Math.min(1000, left % 1000 || 1000))   }   tick()   document.addEventListener('visibilitychange', () => {     if (!document.hidden) { clearTimeout(timer); tick() }   })   return () => clearTimeout(timer) }"},{"id":223,"num":"Q223","tag":"手写","title":"实现一个简单的前端埋点 / 错误监控采集器。","answers":["考察点：全局错误与未处理 Promise 拒绝、资源加载错误要在捕获阶段监听（资源错误不冒泡）、上报用 sendBeacon / fetch keepalive 保证页面卸载时也能发出、批量合并与采样、避免监控自身报错造成递归。"],"bullets":[],"code":[[";(function () {","  const queue = []","  window.addEventListener('error', e => {","    if (e.target && e.target !== window && e.target.src) {","      queue.push({ type: 'resource', src: e.target.src })","    } else {","      queue.push({ type: 'js', msg: e.message, stack: e.error?.stack })","    }","  }, true)  // 捕获阶段才能拿到资源错误","  window.addEventListener('unhandledrejection', e =>","    queue.push({ type: 'promise', reason: String(e.reason) }))","  const flush = () => {","    if (!queue.length) return","    const body = JSON.stringify(queue.splice(0))","    navigator.sendBeacon?.('/api/log', body) ||","      fetch('/api/log', { method: 'POST', body, keepalive: true })","  }","  setInterval(flush, 5000)","  window.addEventListener('pagehide', flush)","})()"]],"note":"","text":"实现一个简单的前端埋点 / 错误监控采集器。 考察点：全局错误与未处理 Promise 拒绝、资源加载错误要在捕获阶段监听（资源错误不冒泡）、上报用 sendBeacon / fetch keepalive 保证页面卸载时也能发出、批量合并与采样、避免监控自身报错造成递归。 ;(function () {   const queue = []   window.addEventListener('error', e => {     if (e.target && e.target !== window && e.target.src) {       queue.push({ type: 'resource', src: e.target.src })     } else {       queue.push({ type: 'js', msg: e.message, stack: e.error?.stack })     }   }, true)  // 捕获阶段才能拿到资源错误   window.addEventListener('unhandledrejection', e =>     queue.push({ type: 'promise', reason: String(e.reason) }))   const flush = () => {     if (!queue.length) return     const body = JSON.stringify(queue.splice(0))     navigator.sendBeacon?.('/api/log', body) ||       fetch('/api/log', { method: 'POST', body, keepalive: true })   }   setInterval(flush, 5000)   window.addEventListener('pagehide', flush) })()"},{"id":224,"num":"Q224","tag":"手写","title":"实现一个简单的模板字符串解析 / 大数金额转中文？（选考）","answers":["这类「造轮子」题考的是正则 + 状态机 + 边界处理，不要慌：先问清输入范围与非法输入怎么处理，再拆「词法分析 → 语法/语义 → 输出」三步。以简易模板为例："],"bullets":[],"code":[["function render(tpl, data) {","  return tpl.replace(/\\{\\{\\s*([\\w.]+)\\s*\\}\\}/g, (_, path) => {","    const v = path.split('.').reduce((o, k) => o?.[k], data)","    return v == null ? '' : String(v)","  })","}","render('Hi {{user.name}}, {{user.age}}', { user: { name: 'Tom', age: 18 } })"]],"note":"面试官真正看的是：有没有先澄清需求、有没有考虑非法输入 / 转义 / XSS、复杂度与可维护性，而不是一次写对。","text":"实现一个简单的模板字符串解析 / 大数金额转中文？（选考） 这类「造轮子」题考的是正则 + 状态机 + 边界处理，不要慌：先问清输入范围与非法输入怎么处理，再拆「词法分析 → 语法/语义 → 输出」三步。以简易模板为例： function render(tpl, data) {   return tpl.replace(/\\{\\{\\s*([\\w.]+)\\s*\\}\\}/g, (_, path) => {     const v = path.split('.').reduce((o, k) => o?.[k], data)     return v == null ? '' : String(v)   }) } render('Hi {{user.name}}, {{user.age}}', { user: { name: 'Tom', age: 18 } }) 面试官真正看的是：有没有先澄清需求、有没有考虑非法输入 / 转义 / XSS、复杂度与可维护性，而不是一次写对。"}]},{"id":"day7-s3","day":7,"title":"7.3 场景题与设计题（中大厂必问）","note":"","questions":[{"id":225,"num":"Q225","tag":"场景","title":"设计一套登录鉴权方案（Token 存哪、如何刷新、如何退出、多端控制）？","answers":["推荐方案：Access Token 短时（15 分钟）+ Refresh Token 长时（7 天，存 HttpOnly + Secure + SameSite=Lax Cookie）；Access Token 放内存（JS 变量 / 状态库）或 HttpOnly Cookie，不放 localStorage（XSS 可直接读走）。","流程：登录成功服务端下发双 token → 请求拦截器自动带 Access Token → 401 时用 Refresh Token 静默换新，并用一个「共享的刷新 Promise」让并发的多个 401 只刷新一次（refresh 期间的请求排队，刷新完统一重放）→ Refresh 也失效则跳登录并清除状态。","退出与多端：服务端维护 token 版本/黑名单或 session 表，退出即失效 Refresh Token 并广播（WebSocket / 轮询），其他标签页通过 storage / BroadcastChannel 事件同步登出；关键操作可二次校验。","为什么这么选：Cookie 天然抗 XSS 窃取（HttpOnly）但要防 CSRF（SameSite + CSRF Token），内存 token 抗 CSRF 但刷新页面丢失（需静默恢复），localStorage 两者都不抗；讲清楚 trade-off 比背方案更重要。"],"bullets":[],"code":[],"note":"","text":"设计一套登录鉴权方案（Token 存哪、如何刷新、如何退出、多端控制）？ 推荐方案：Access Token 短时（15 分钟）+ Refresh Token 长时（7 天，存 HttpOnly + Secure + SameSite=Lax Cookie）；Access Token 放内存（JS 变量 / 状态库）或 HttpOnly Cookie，不放 localStorage（XSS 可直接读走）。 流程：登录成功服务端下发双 token → 请求拦截器自动带 Access Token → 401 时用 Refresh Token 静默换新，并用一个「共享的刷新 Promise」让并发的多个 401 只刷新一次（refresh 期间的请求排队，刷新完统一重放）→ Refresh 也失效则跳登录并清除状态。 退出与多端：服务端维护 token 版本/黑名单或 session 表，退出即失效 Refresh Token 并广播（WebSocket / 轮询），其他标签页通过 storage / BroadcastChannel 事件同步登出；关键操作可二次校验。 为什么这么选：Cookie 天然抗 XSS 窃取（HttpOnly）但要防 CSRF（SameSite + CSRF Token），内存 token 抗 CSRF 但刷新页面丢失（需静默恢复），localStorage 两者都不抗；讲清楚 trade-off 比背方案更重要。"},{"id":226,"num":"Q226","tag":"场景","title":"设计一个权限系统（路由级 + 按钮级）？","answers":["模型：RBAC（用户 → 角色 → 权限点），权限点用「资源:操作」字符串（如 order:export）或位图；后端返回当前用户权限列表，前端不硬编码。","路由级：静态路由表 + meta.requiresAuth/permissions，登录后按权限动态 addRoute / 生成路由（Vue Router addRoute / React Router 配置过滤），并在全局守卫做兜底校验（防止手敲 URL）；注意 404 路由要最后添加，否则动态路由被 404 吞掉。","按钮级：自定义指令 v-permission / 组件 <Auth code=\"...\"> / Hook usePermission；只读隐藏不够，后端接口必须再次鉴权（前端只是体验层）。","加分：菜单与路由分离、权限变更后如何刷新（重新拉取 or 重新登录）、缓存与权限变更不一致、无权限页面的友好提示、审计日志。"],"bullets":[],"code":[],"note":"","text":"设计一个权限系统（路由级 + 按钮级）？ 模型：RBAC（用户 → 角色 → 权限点），权限点用「资源:操作」字符串（如 order:export）或位图；后端返回当前用户权限列表，前端不硬编码。 路由级：静态路由表 + meta.requiresAuth/permissions，登录后按权限动态 addRoute / 生成路由（Vue Router addRoute / React Router 配置过滤），并在全局守卫做兜底校验（防止手敲 URL）；注意 404 路由要最后添加，否则动态路由被 404 吞掉。 按钮级：自定义指令 v-permission / 组件 <Auth code=\"...\"> / Hook usePermission；只读隐藏不够，后端接口必须再次鉴权（前端只是体验层）。 加分：菜单与路由分离、权限变更后如何刷新（重新拉取 or 重新登录）、缓存与权限变更不一致、无权限页面的友好提示、审计日志。"},{"id":227,"num":"Q227","tag":"场景","title":"封装一个公司级请求库，你会设计哪些能力？","answers":["基础：baseURL / 超时 / 统一 headers / 请求响应拦截器 / 统一错误码与错误提示 / 自动 JSON 转换 / 取消（AbortController）。","进阶：① 401 静默刷新 + 并发请求排队重放；② 请求去重（相同 key 的并发 GET 复用同一个 Promise）；③ 失败重试（只对幂等请求、指数退避、可配置）；④ 缓存与陈旧再验证（staleTime、按 key 失效）；⑤ 竞态保护（新请求覆盖旧请求）；⑥ 取消路由切换时的未完成请求；⑦ 上传下载进度、断点续传；⑧ 埋点与耗时上报、链路追踪 traceId；⑨ mock 与类型（泛型推导响应类型）。","加分：讲出「什么时候不该封装」（小项目直接用 fetch 或 TanStack Query 更省）、以及「请求库与服务端状态库的分工」。"],"bullets":[],"code":[],"note":"","text":"封装一个公司级请求库，你会设计哪些能力？ 基础：baseURL / 超时 / 统一 headers / 请求响应拦截器 / 统一错误码与错误提示 / 自动 JSON 转换 / 取消（AbortController）。 进阶：① 401 静默刷新 + 并发请求排队重放；② 请求去重（相同 key 的并发 GET 复用同一个 Promise）；③ 失败重试（只对幂等请求、指数退避、可配置）；④ 缓存与陈旧再验证（staleTime、按 key 失效）；⑤ 竞态保护（新请求覆盖旧请求）；⑥ 取消路由切换时的未完成请求；⑦ 上传下载进度、断点续传；⑧ 埋点与耗时上报、链路追踪 traceId；⑨ mock 与类型（泛型推导响应类型）。 加分：讲出「什么时候不该封装」（小项目直接用 fetch 或 TanStack Query 更省）、以及「请求库与服务端状态库的分工」。"},{"id":228,"num":"Q228","tag":"场景","title":"线上页面白屏 / 报错，你的排查路径是什么？","answers":["① 先确认影响面：监控大盘看错误率、版本、浏览器/机型/地域分布，判断是发版引入还是个例；② 看错误类型：JS 运行时错误（配合 sourcemap 还原到具体文件行）、资源 404/加载失败（CDN、文件名 hash 与 HTML 引用不一致）、接口 500/超时、CSP 拦截；③ 复现：同版本同环境 + 无痕/禁用插件，看控制台与 Network，检查是否有 document.write、JSONP 失败、hydration 不一致；④ 定位到代码后看是否与最近一次提交相关，用 bisect / 回滚验证；⑤ 止血：先回滚到上一版本或关 feature flag，再修；⑥ 沉淀：加 E2E 冒烟、构建产物校验、灰度发布与告警阈值。","常见根因：发版后 HTML 缓存导致引用了不存在的 hash 文件（HTML 必须 no-cache）、依赖升级破坏、环境变量配置错、CDN 节点异常、SSR 双端渲染不一致、第三方脚本阻塞。"],"bullets":[],"code":[],"note":"","text":"线上页面白屏 / 报错，你的排查路径是什么？ ① 先确认影响面：监控大盘看错误率、版本、浏览器/机型/地域分布，判断是发版引入还是个例；② 看错误类型：JS 运行时错误（配合 sourcemap 还原到具体文件行）、资源 404/加载失败（CDN、文件名 hash 与 HTML 引用不一致）、接口 500/超时、CSP 拦截；③ 复现：同版本同环境 + 无痕/禁用插件，看控制台与 Network，检查是否有 document.write、JSONP 失败、hydration 不一致；④ 定位到代码后看是否与最近一次提交相关，用 bisect / 回滚验证；⑤ 止血：先回滚到上一版本或关 feature flag，再修；⑥ 沉淀：加 E2E 冒烟、构建产物校验、灰度发布与告警阈值。 常见根因：发版后 HTML 缓存导致引用了不存在的 hash 文件（HTML 必须 no-cache）、依赖升级破坏、环境变量配置错、CDN 节点异常、SSR 双端渲染不一致、第三方脚本阻塞。"},{"id":229,"num":"Q229","tag":"场景","title":"设计一个组件库，需要考虑什么？","answers":["API 设计：受控/非受控双模式（value/defaultValue + onChange）、组合式（插槽 / children / compound components）、稳定的 props 命名与向后兼容、TypeScript 类型完备（泛型、ref 转发、事件类型）。","质量：无障碍（ARIA 属性、键盘导航、焦点管理、色彩对比度）、样式隔离与主题（CSS 变量 / Design Token / 暗色模式）、按需加载与 Tree Shaking（ESM + sideEffects）、单元测试 + 视觉回归 + E2E、文档站点与示例。","工程：Monorepo + Changesets 发版、语义化版本、SSR 兼容（不直接访问 window）、国际化、RTL 布局、弹层类组件的 Portal / z-index 管理、SSR 下 id 生成稳定（useId）。","加分：能说出「组件库最难的是 API 稳定性与破坏性变更管理」，而不是「写个 Button 很快」。"],"bullets":[],"code":[],"note":"","text":"设计一个组件库，需要考虑什么？ API 设计：受控/非受控双模式（value/defaultValue + onChange）、组合式（插槽 / children / compound components）、稳定的 props 命名与向后兼容、TypeScript 类型完备（泛型、ref 转发、事件类型）。 质量：无障碍（ARIA 属性、键盘导航、焦点管理、色彩对比度）、样式隔离与主题（CSS 变量 / Design Token / 暗色模式）、按需加载与 Tree Shaking（ESM + sideEffects）、单元测试 + 视觉回归 + E2E、文档站点与示例。 工程：Monorepo + Changesets 发版、语义化版本、SSR 兼容（不直接访问 window）、国际化、RTL 布局、弹层类组件的 Portal / z-index 管理、SSR 下 id 生成稳定（useId）。 加分：能说出「组件库最难的是 API 稳定性与破坏性变更管理」，而不是「写个 Button 很快」。"},{"id":230,"num":"Q230","tag":"场景","title":"如何实现前端灰度发布 / A/B 实验？","answers":["分流：按用户 ID / 设备 ID 哈希取模（保证同一用户稳定命中），或白名单、地域、比例、人群标签；分流逻辑放边缘（CDN / 网关 / SSR）或前端 SDK，流量与服务层要共用一个分桶标识。","实施：① 静态资源双版本 + HTML 入口按分桶切换（最简单）；② feature flag 配置中心动态下发开关（不发版即可关停）；③ 微前端/模块联邦按版本加载不同 remote；④ 客户端 SDK 在运行时决定渲染哪套 UI。","度量：埋点带实验组标识，看核心指标（错误率、性能、转化），用统计显著性判断而非「看着好像变好」；配套：快速回滚、灰度放量节奏（1% → 5% → 20% → 100%）、实验互斥与分层。","坑：用户跨设备命中不一致、缓存导致分组串味、实验代码长期不清理变成技术债。"],"bullets":[],"code":[],"note":"","text":"如何实现前端灰度发布 / A/B 实验？ 分流：按用户 ID / 设备 ID 哈希取模（保证同一用户稳定命中），或白名单、地域、比例、人群标签；分流逻辑放边缘（CDN / 网关 / SSR）或前端 SDK，流量与服务层要共用一个分桶标识。 实施：① 静态资源双版本 + HTML 入口按分桶切换（最简单）；② feature flag 配置中心动态下发开关（不发版即可关停）；③ 微前端/模块联邦按版本加载不同 remote；④ 客户端 SDK 在运行时决定渲染哪套 UI。 度量：埋点带实验组标识，看核心指标（错误率、性能、转化），用统计显著性判断而非「看着好像变好」；配套：快速回滚、灰度放量节奏（1% → 5% → 20% → 100%）、实验互斥与分层。 坑：用户跨设备命中不一致、缓存导致分组串味、实验代码长期不清理变成技术债。"},{"id":231,"num":"Q231","tag":"场景","title":"乐观更新（Optimistic UI）怎么做？失败如何回滚？","answers":["流程：用户操作后立刻更新本地 UI（不等接口）→ 发请求 → 成功则用服务端返回的真实数据校正（如数据库生成的 ID、时间戳）→ 失败则回滚到操作前快照并提示重试。","要点：① 保存快照（深拷贝或记录反向操作）；② 用唯一事务 ID 关联请求与回滚，避免并发操作互相覆盖；③ 失败后要处理「其它操作已 modify 同一份数据」的情况（用版本号 / CAS 而不是整体覆盖）；④ 给 pending 状态视觉反馈，禁用重复提交；⑤ 网络离线时进入本地队列，恢复后重放。","React 19 的 useOptimistic / useActionState 就是把这个模式标准化，答出来是加分项。"],"bullets":[],"code":[],"note":"","text":"乐观更新（Optimistic UI）怎么做？失败如何回滚？ 流程：用户操作后立刻更新本地 UI（不等接口）→ 发请求 → 成功则用服务端返回的真实数据校正（如数据库生成的 ID、时间戳）→ 失败则回滚到操作前快照并提示重试。 要点：① 保存快照（深拷贝或记录反向操作）；② 用唯一事务 ID 关联请求与回滚，避免并发操作互相覆盖；③ 失败后要处理「其它操作已 modify 同一份数据」的情况（用版本号 / CAS 而不是整体覆盖）；④ 给 pending 状态视觉反馈，禁用重复提交；⑤ 网络离线时进入本地队列，恢复后重放。 React 19 的 useOptimistic / useActionState 就是把这个模式标准化，答出来是加分项。"},{"id":232,"num":"Q232","tag":"场景","title":"国际化（i18n）与本地化要注意什么？","answers":["不只是翻译：文案抽取（不硬编码、用 key + 命名空间）、复数规则（不同语言复数形式不同，用 ICU MessageFormat）、变量插值与语序、日期/时间/数字/货币格式化（Intl.DateTimeFormat / Intl.NumberFormat）、时区处理（存 UTC、展示按用户时区）、RTL 布局（direction / 逻辑属性 margin-inline）、字体与断行、图片与图标的文化差异、本地化测试与伪语言（pseudo-locale，用超长字符串测溢出）。","工程：按需加载语言包、缺失 key 回退策略、与后端错误码文案的协同、翻译平台与 CI 校验。"],"bullets":[],"code":[],"note":"","text":"国际化（i18n）与本地化要注意什么？ 不只是翻译：文案抽取（不硬编码、用 key + 命名空间）、复数规则（不同语言复数形式不同，用 ICU MessageFormat）、变量插值与语序、日期/时间/数字/货币格式化（Intl.DateTimeFormat / Intl.NumberFormat）、时区处理（存 UTC、展示按用户时区）、RTL 布局（direction / 逻辑属性 margin-inline）、字体与断行、图片与图标的文化差异、本地化测试与伪语言（pseudo-locale，用超长字符串测溢出）。 工程：按需加载语言包、缺失 key 回退策略、与后端错误码文案的协同、翻译平台与 CI 校验。"},{"id":233,"num":"Q233","tag":"开放题","title":"「你做过最有挑战的项目 / 最大的坑」怎么答？","answers":["模板：一句话背景（业务、量级、你的角色）→ 明确问题与量化现状（如「首屏 8.2s，LCP P75 4.1s，列表 1 万条卡顿」）→ 约束条件（不能改后端 / 要兼容老浏览器 / 工期）→ 你提出的 2~3 个方案与取舍（为什么选它）→ 落地细节与关键代码思路 → 结果数据（优化前后对比 + 线上 RUM 验证）→ 复盘沉淀（规范化、工具化、文档、可复用方案）。","雷区：只讲「我用了某某框架」不讲决策；把团队成果说成个人；给不出数字；被追问细节就答不上来；选一个自己没真正做过的技术难点。"],"bullets":[],"code":[],"note":"","text":"「你做过最有挑战的项目 / 最大的坑」怎么答？ 模板：一句话背景（业务、量级、你的角色）→ 明确问题与量化现状（如「首屏 8.2s，LCP P75 4.1s，列表 1 万条卡顿」）→ 约束条件（不能改后端 / 要兼容老浏览器 / 工期）→ 你提出的 2~3 个方案与取舍（为什么选它）→ 落地细节与关键代码思路 → 结果数据（优化前后对比 + 线上 RUM 验证）→ 复盘沉淀（规范化、工具化、文档、可复用方案）。 雷区：只讲「我用了某某框架」不讲决策；把团队成果说成个人；给不出数字；被追问细节就答不上来；选一个自己没真正做过的技术难点。"},{"id":234,"num":"Q234","tag":"开放题","title":"「你平时怎么学前端 / 怎么判断一个技术方案该不该引入」？","answers":["学习：官方文档优先（MDN、React/Vue 官方、TC39 提案、规范原文）→ 动手做最小验证 → 读源码/设计文档理解取舍 → 输出（笔记、分享、PR）；对「八股文」的态度是理解原理而非死记。","技术选型四问：① 解决什么问题、现状量化指标是什么；② 收益与成本（学习成本、包体积、维护成本、迁移风险、锁死风险）；③ 生态与团队（维护活跃度、TS 支持、团队熟悉度、招人难度）；④ 退出策略（能否渐进引入、能否回滚、有没有替代）。先做 POC 与压测，再小范围灰度，用数据决定。"],"bullets":[],"code":[],"note":"","text":"「你平时怎么学前端 / 怎么判断一个技术方案该不该引入」？ 学习：官方文档优先（MDN、React/Vue 官方、TC39 提案、规范原文）→ 动手做最小验证 → 读源码/设计文档理解取舍 → 输出（笔记、分享、PR）；对「八股文」的态度是理解原理而非死记。 技术选型四问：① 解决什么问题、现状量化指标是什么；② 收益与成本（学习成本、包体积、维护成本、迁移风险、锁死风险）；③ 生态与团队（维护活跃度、TS 支持、团队熟悉度、招人难度）；④ 退出策略（能否渐进引入、能否回滚、有没有替代）。先做 POC 与压测，再小范围灰度，用数据决定。"}]},{"id":"day7-s4","day":7,"title":"7.4 面试冲刺：30 秒速答表","note":"最后半天不要再啃新知识点。用这张表做「随机抽题 → 口头作答」训练，说不顺的立刻回前面章节重看。能流畅讲出来，才算真的背会。","questions":[]},{"id":"day7-s5","day":7,"title":"7.5 七天回顾与面试前 Checklist","note":"","questions":[{"id":235,"num":"Q235","tag":"自检","title":"面试前一晚，按这份清单逐条打勾。","answers":[],"bullets":["能不看资料讲清 10 个核心原理：原型链、闭包、Event Loop、Promise、Vue3 响应式、React Fiber、Hooks、diff/key、HTTP 缓存、TLS 握手。","能徒手写出的 12 道题：防抖、节流、深拷贝、call/apply/bind、new、instanceof、Promise.all、MyPromise、并发控制、柯里化、LRU、EventEmitter。","能完整推演 3 道混合输出题（同步 + 微任务 + 宏任务 + async/await），并解释为什么。","能讲清 3 个「自己项目里的真实问题」，每个都带数字、工具名、方案取舍与验证结果。","能说清 5 组对比的区别与取舍：Vue2/Vue3、Vue/React、CJS/ESM、Webpack/Vite、Cookie/JWT。","准备好 3 个反问面试官的问题（团队技术栈与演进、这个岗位要解决的核心问题、性能/工程化现状与规划）。","简历上每个技术名词都要能接住两轮追问；不熟的不要在简历里写。"],"code":[],"note":"","text":"面试前一晚，按这份清单逐条打勾。 能不看资料讲清 10 个核心原理：原型链、闭包、Event Loop、Promise、Vue3 响应式、React Fiber、Hooks、diff/key、HTTP 缓存、TLS 握手。 能徒手写出的 12 道题：防抖、节流、深拷贝、call/apply/bind、new、instanceof、Promise.all、MyPromise、并发控制、柯里化、LRU、EventEmitter。 能完整推演 3 道混合输出题（同步 + 微任务 + 宏任务 + async/await），并解释为什么。 能讲清 3 个「自己项目里的真实问题」，每个都带数字、工具名、方案取舍与验证结果。 能说清 5 组对比的区别与取舍：Vue2/Vue3、Vue/React、CJS/ESM、Webpack/Vite、Cookie/JWT。 准备好 3 个反问面试官的问题（团队技术栈与演进、这个岗位要解决的核心问题、性能/工程化现状与规划）。 简历上每个技术名词都要能接住两轮追问；不熟的不要在简历里写。"}]},{"id":"day7-s6","day":7,"title":"7.6 资料来源与说明","note":"本宝典的题目框架与知识模块，参考了 GitHub 上多个高星前端面试仓库的目录结构与高频题型，并结合 2025—2026 年大厂真题趋势（React 19 / Vue3 编译优化 / 工程化决策 / Web Vitals / 场景设计题）整理、重写与补全答案。所有答案均为可直接口述的表达，代码示例可直接在浏览器控制台或 Node 中运行。","questions":[{"id":236,"num":"Q236","tag":"说明","title":"怎么使用这份资料效果最好？","answers":["① 不要逐字背答案：先盖住答案自己讲一遍（出声，用手机的语音备忘录录下来），讲不顺的地方就是薄弱点；② 每道题都要能接住一轮「为什么」，比如被问到 Proxy 就准备好「缺点是什么」；③ 手写题务必在编辑器里真敲一遍，边界条件（空数组、循环引用、this、取消）比主干代码更常被追问；④ 第 7 天的速答表用来做随机抽题自测，连续三天都能流畅讲完，才叫「背完」。","⑤ 八股文是入场券不是终点：面试官从「答出原理」到「讲出落地问题与优化方案」打分，把每个知识点挂到一个自己做过的真实场景上，分数会明显不同。"],"bullets":[],"code":[],"note":"","text":"怎么使用这份资料效果最好？ ① 不要逐字背答案：先盖住答案自己讲一遍（出声，用手机的语音备忘录录下来），讲不顺的地方就是薄弱点；② 每道题都要能接住一轮「为什么」，比如被问到 Proxy 就准备好「缺点是什么」；③ 手写题务必在编辑器里真敲一遍，边界条件（空数组、循环引用、this、取消）比主干代码更常被追问；④ 第 7 天的速答表用来做随机抽题自测，连续三天都能流畅讲完，才叫「背完」。 ⑤ 八股文是入场券不是终点：面试官从「答出原理」到「讲出落地问题与优化方案」打分，把每个知识点挂到一个自己做过的真实场景上，分数会明显不同。"}]}]}],"tables":[{"title":"高频问题·30 秒速答（按主题速查）","rows":[["主题","一句话答案","必带关键词"],["闭包","函数 + 定义时词法环境，外层变量被内部函数引用而常驻堆内存","词法作用域、[[Environment]]、内存泄漏"],["原型链","对象沿 [[Prototype]] 向上找属性，终点 Object.prototype → null","prototype、__proto__、constructor"],["this 绑定","new > 显式 > 隐式 > 默认；箭头函数沿作用域链继承","优先级、箭头函数不可改 this"],["Event Loop","一个宏任务 → 清空全部微任务 → 渲染 → 下一个宏任务","宏任务、微任务、queueMicrotask"],["Promise","A+ 三态不可逆、then 返回新 Promise、决议过程吸收 thenable","thenable、值穿透、微任务"],["Vue3 响应式","Proxy 拦截 get/set 做 track/trigger，依赖存 WeakMap","Reflect receiver、惰性递归、PatchFlag"],["Vue2 缺陷","defineProperty 只能劫持已有属性，数组要重写 7 个方法","$set、递归遍历、数组下标"],["React Fiber","双缓存 workInProgress 树 + 可中断时间切片 + lane 优先级","beginWork、commit、并发渲染"],["Hooks 规则","状态按调用顺序挂在 Fiber 链表上，顺序变了就串位","顶层调用、闭包陷阱、deps"],["setState","React 18 全场景 automatic batching，需同步用 flushSync","批处理、函数式更新"],["虚拟 DOM","声明式抽象 + 批处理 + 最小更新，不是绝对更快","diff、key、PatchFlag、跨平台"],["HTTP 缓存","强缓存 max-age 不发请求，协商 ETag 命中返 304","no-cache 不是不缓存、immutable"],["跨域","同源 = 协议+域+端口；CORS 预检 / 代理 / JSONP","OPTIONS、Allow-Credentials"],["HTTPS","非对称做认证与密钥交换，对称加密数据，CA 证书防冒充","ECDHE 前向安全、TLS 1.3"],["XSS","注入脚本执行，转义 + CSP + HttpOnly","存储/反射/DOM 型、DOMPurify"],["CSRF","冒用已登录凭证发请求，SameSite + Token + Origin 校验","拿不到 Cookie 内容"],["Vite 为什么快","原生 ESM 免打包 + esbuild 预构建依赖 + 模块级 HMR","Rollup 生产构建、.vite 缓存"],["Tree Shaking","依赖 ESM 静态分析 + sideEffects 标记","CommonJS 无法静态推断"],["LCP / INP / CLS","加载 / 交互 / 视觉稳定性三大指标，按 P75 看真实数据","Web Vitals、PerformanceObserver"],["BFC","独立渲染区域，清浮动、防 margin 塌陷、两栏自适应","flow-root、overflow"],["防抖 / 节流","最后一次后执行 / 单位时间最多一次","搜索联想 / 滚动上报"],["大文件上传","切片 + hash 秒传 + 并发池 + 断点续传 + merge","Worker 算 hash、重试退避"]],"kind":"speed","day":7},{"title":"一周背诵节奏总表","rows":[["天数","主题","核心产出","自检标准"],["第 1 天","JS 语言核心","数据类型、原型继承、闭包、this、GC","能默画原型链图、能讲清 0.1+0.2"],["第 2 天","异步与 ES6+","Event Loop、Promise、模块化、Proxy","能推演任意混合输出题、能手撕 Promise"],["第 3 天","HTML/CSS/渲染","渲染流水线、BFC、层叠上下文、布局","能写出 6 种居中、说清重排重绘"],["第 4 天","浏览器与网络","URL 全过程、HTTP 缓存、跨域、安全","能一口气讲完 URL 到渲染的 8 步"],["第 5 天","Vue / React","响应式、diff、Fiber、Hooks、并发","能对比两大框架的更新粒度"],["第 6 天","工程化/TS/性能","Webpack/Vite、类型体操、Web Vitals","能给出首屏优化的完整排查路径"],["第 7 天","手写 + 场景","30+ 手写实现、系统设计、模拟面试","不看答案能写出 15 道手写题"]],"kind":"plan","day":7},{"title":"主要参考的 GitHub 题库与知识模块来源","rows":[["仓库 / 资源","定位","借鉴的知识模块"],["CavsZhouyou/Front-End-Interview-Notebook","校招前端复习笔记，HTML/CSS/JS/网络/算法/工具分模块","JS 175 题、CSS 105 题、HTML 69 题、网络 14 题的题型清单"],["Advanced-Frontend/Daily-Interview-Question","每日一道大厂面试题，深度解析","高频原理题与手写题的追问深度"],["haizlin/fe-interview","前端每日 3+1，题库驱动学习","基础题覆盖面与出题角度"],["wangwenjie1314/webQd","按模块整理的高频面试题索引","HTML/CSS/JS/Vue/React/工程化/网络/手写/算法九大分类"],["InterviewMap/CS-Interview-Knowledge-Map","面试知识地图","JS、网络、浏览器、性能、安全、框架、算法的知识图谱"],["febobo/web-interview、poetries/FE-Interview-Questions","分类题库与在线阅读版","按知识体系查漏补缺"],["yangshun/front-end-interview-handbook、javascript-questions","英文面试指南 / JS 细节题","代码输出题与语言细节（lydiahallie/javascript-questions）"],["lucifer.ren/fe-interview、xiumubai/coding","前端面试指南 / 八股与手写结合","手写题解题思路"]],"kind":"source","day":7}],"stats":{"chapters":7,"sections":29,"codeLines":520,"tables":3}};
